    [0,150,300,450,600,750].forEach(v=>grid+=`<line class="chart-grid" x1="48" y1="${y(v)}" x2="724" y2="${y(v)}"/><text class="chart-axis" x="5" y="${y(v)+3}">${v}k</text>`);
