  function moduleMenuHtml(){
    const modules=[
      ['hub','Employee Hub','People, work and self-service','users'],
      ['payroll','Payroll & HR','Payroll, people and compliance','expense'],
      ['accounting','Accounting','Cash, control and reporting','ledger'],
      ['procurement','Procurement','Sourcing, vendors and contracts','payable'],
      ['portfolio','Portfolio Management','Funds, mandates and analytics','invest'],
      ['risk','Risk & Compliance','Enterprise controls and assurance','shield'],
      ['workshop','Workshop OS','Vehicle service operations','settings'],
      ['settings','Platform Settings','Identity, integrations and tenant','plug']
    ];
    return `<div class="module-menu-head"><strong>Matanho enterprise suite</strong><span>Switch workspace or open platform settings</span></div>${modules.map(m=>`<button class="module-option ${m[0]==='accounting'?'active':''}" data-action="module-switch-v2" data-id="${m[0]}"><span class="module-option-icon">${icon(m[3])}</span><span><strong>${m[1]}</strong><span>${m[2]}</span></span>${m[0]==='accounting'?'<em>Current</em>':icon('chevron')}</button>`).join('')}`;
  }

  function enhanceV2(){
    const app=q('#app'); if(!app) return;
    const brand=q('.brand');
    if(brand){brand.setAttribute('role','button');brand.setAttribute('tabindex','0');brand.setAttribute('aria-label','Open Matanho module menu');brand.dataset.action='toggle-module-menu-v2'}
    let menu=q('#moduleMenuV2');
    if(!menu && brand){menu=document.createElement('div');menu.id='moduleMenuV2';menu.className='module-menu';menu.innerHTML=moduleMenuHtml();brand.insertAdjacentElement('afterend',menu)}
    const toggle=q('#menuBtn');
    if(toggle){const collapsed=app.classList.contains('collapsed');toggle.innerHTML=`${icon(collapsed?'chevron':'collapse')}<span class="toggle-label">${collapsed?'Expand menu':'Collapse menu'}</span>`;toggle.title=collapsed?'Expand navigation':'Collapse navigation';toggle.setAttribute('aria-label',toggle.title)}
    qa('.nav-item').forEach(item=>item.setAttribute('aria-label',item.title||item.textContent.trim()));
    q('#brandLogo')?.setAttribute('draggable','false');
    const content=q('.content'); if(content) content.style.overflowY='auto';
  }

  function currentQuoteApprovalAllowed(){
    const user=users.find(x=>x.name==='Tariro Moyo');
    return can('quotations.approve') && !!user?.quoteApproval;
  }

