    openDrawer(v.name,`${v.id} · governed vendor master`,`<div style="display:flex;gap:12px;align-items:center"><div class="vendor-logo" style="width:58px;height:58px;border-radius:12px;font-size:15px">${v.initials}</div><div><div class="eyebrow">${v.category}</div><h2 style="font-size:20px;font-weight:620;margin:0">${v.name}</h2><div class="sub" style="margin-top:4px">${v.country} · ${badge(v.status)}</div></div></div><div class="profile-summary-strip" style="margin-top:13px"><div class="fact"><span>Compliance score</span><strong>${v.compliance}%</strong></div><div class="fact"><span>Service rating</span><strong>${v.rating} / 5</strong></div><div class="fact"><span>12-month spend</span><strong>${fmt(v.spend)}</strong></div><div class="fact"><span>Next renewal</span><strong>${v.renewal}</strong></div></div><div class="grid two" style="margin-top:11px">${card('Vendor profile','Identity, contact and service relationship',`<div class="form-grid two-col">${[['Primary contact',v.contact],['Email',v.email],['Phone',v.phone],['Category',v.category],['BP number',v.bp],['VAT number',v.vat],['Default currency',v.currency],['Bank',v.bank]].map(x=>`<div class="fact"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div>`)}${card('Compliance readiness','Evidence and payment eligibility',`${progressRow('Tax clearance',/Expired/i.test(v.taxExpiry)?30:v.compliance,`Expiry: ${v.taxExpiry}`,/Expired/i.test(v.taxExpiry)?'red':v.compliance<90?'amber':'')}${progressRow('Bank verification',100,'Account ownership confirmed')}${progressRow('Beneficial ownership',v.compliance,'Ownership: '+v.ownership,v.compliance<90?'amber':'')}${progressRow('Conflict declaration',100,'Current declaration on file')}`)}</div><div style="margin-top:11px">${card('Recent sourcing and accounting activity','Invitations, bids, invoices and control events',`<div class="timeline"><div class="timeline-item"><div class="timeline-dot">1</div><div><strong>Bid submitted</strong><span>RFQ-FIN-2026-014 · structured response and six attachments</span></div></div><div class="timeline-item"><div class="timeline-dot">2</div><div><strong>Secure invitation opened</strong><span>Identity token verified and vendor form accessed</span></div></div><div class="timeline-item"><div class="timeline-dot">3</div><div><strong>Invoice matched</strong><span>Three-way controls passed and payment eligibility confirmed</span></div></div><div class="timeline-item"><div class="timeline-dot">4</div><div><strong>Compliance record refreshed</strong><span>Tax, bank and ownership evidence reviewed</span></div></div></div>`)}</div>`,btn('Vendor documents','vendor-docs-v2','')+btn('Send secure email','email-vendor-v2','primary',v.id));
