  const allJournalsV4=()=>[...engineV4.seed,...engineV4.added];
  const allLinesV4=()=>allJournalsV4().flatMap(j=>j.lines.map((l,i)=>({...l,journalId:j.id,lineNo:i+1,date:j.date,source:j.source,sourceId:j.sourceId,description:j.description,currency:j.currency,rate:j.rate,cashFlow:j.cashFlow,maker:j.maker,checker:j.checker,status:'Posted',hash:j.hash||hashV4(JSON.stringify(j))})));
  function hashV4(str){let h=2166136261;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}return 'FNV-'+(h>>>0).toString(16).padStart(8,'0').toUpperCase()}
  function validateLinesV4(lines,source='Manual'){
    if(!Array.isArray(lines)||lines.length<2)return {ok:false,message:'At least two journal lines are required.'};
    let d=0,c=0;
    for(const l of lines){
      if(!accountMapV4[l.account])return {ok:false,message:`Unknown account ${l.account}.`};
      const dr=round2(l.debit),cr=round2(l.credit);
      if(dr<0||cr<0||(!dr&&!cr)||(dr&&cr))return {ok:false,message:`Each line must contain either a debit or a credit, not both.`};
      if(source==='Manual'&&accountMapV4[l.account].control)return {ok:false,message:`${l.account} ${accountMapV4[l.account].name} is a control account and may only be posted through its sub-ledger.`};
      d+=dr;c+=cr;
    }
    if(Math.abs(round2(d-c))>.009)return {ok:false,message:`Debits ${moneyV4(d)} do not equal credits ${moneyV4(c)}.`};
    return {ok:true,debit:round2(d),credit:round2(c)};
  }
  function nextJournalIdV4(prefix='JE'){
    const n=allJournalsV4().length+engineV4.pending.length+1;
    return `${prefix}-${new Date().getFullYear()}-${String(n).padStart(5,'0')}`;
  }
  function postJournalV4(input){
    const currency=input.currency||'USD',rate=Number(input.rate||1);
    if(!(rate>0))throw new Error('A positive exchange rate is required.');
    const lines=(input.lines||[]).map(l=>lineV4(l.account,l.debit,l.credit,l.narration||input.description||''));
    const result=validateLinesV4(lines,input.source||'Manual');if(!result.ok)throw new Error(result.message);
    const payload={id:input.id||nextJournalIdV4('JE'),date:input.date||new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}),source:input.source||'Manual',sourceId:input.sourceId||'MANUAL',description:input.description||'Journal entry',currency,rate,cashFlow:input.cashFlow||null,maker:input.maker||currentUserV4(),checker:input.checker||'System controls',lines};
    payload.hash=hashV4(JSON.stringify(payload));
    const journal=immutableV4(payload);engineV4.added.unshift(journal);persistV4();
    logEvent('JOURNAL_POSTED',journal.id,`${journal.source} posted ${result.debit.toFixed(2)} ${currency}; hash ${journal.hash}`,'Posting');
    return journal;
  }
  function submitManualV4(input){
    const lines=(input.lines||[]).map(l=>lineV4(l.account,l.debit,l.credit,l.narration||input.description||''));
    const result=validateLinesV4(lines,'Manual');if(!result.ok)throw new Error(result.message);
    const pending=Object.freeze({id:nextJournalIdV4('MJE'),date:input.date,source:'Manual',sourceId:input.reference,description:input.description,currency:input.currency,rate:input.rate,cashFlow:null,maker:currentUserV4(),checker:'Unassigned',status:'In review',lines:Object.freeze(lines.map(Object.freeze)),hash:hashV4(JSON.stringify(input))});
    engineV4.pending.unshift(pending);persistV4();
    if(!approvals.some(a=>a.record===pending.id))approvals.unshift({id:`APR-${Date.now().toString().slice(-6)}`,type:'Journal',record:pending.id,subject:pending.description,amount:result.debit,currency:pending.currency,maker:pending.maker,submitted:'Just now',risk:result.debit>25000?'High':'Medium',status:'Pending'});
    logEvent('JOURNAL_SUBMITTED',pending.id,'Balanced manual journal submitted for independent checker approval','Approval');return pending;
  }
  function approvePendingV4(id){
    const idx=engineV4.pending.findIndex(x=>x.id===id);if(idx<0)throw new Error('Pending journal not found.');
    const p=engineV4.pending[idx];if(!can('journal.approve'))throw new Error(`${state.role} cannot approve journals.`);if(p.maker===currentUserV4())throw new Error('Maker-checker control blocks a user from approving their own journal. Switch to an independent approver role.');
    const j=postJournalV4({...p,id:p.id,checker:currentUserV4()});engineV4.pending.splice(idx,1);const a=approvals.find(x=>x.record===p.id);if(a)a.status='Approved';persistV4();return j;
  }
  function trialBalanceV4(){
    const map={};accountsV4.forEach(a=>map[a.code]={...a,debits:0,credits:0});
    allLinesV4().forEach(l=>{map[l.account].debits=round2(map[l.account].debits+l.baseDebit);map[l.account].credits=round2(map[l.account].credits+l.baseCredit)});
    const rows=Object.values(map).map(a=>{const net=round2(a.debits-a.credits);return {...a,debit:net>0?net:0,credit:net<0?-net:0,balance:Math.abs(net)}}).filter(a=>a.debit||a.credit);
    return {rows,totalDebit:round2(rows.reduce((s,r)=>s+r.debit,0)),totalCredit:round2(rows.reduce((s,r)=>s+r.credit,0))};
  }
  function incomeStatementV4(){const tb=trialBalanceV4().rows;const revenue=tb.filter(r=>r.type==='Revenue').map(r=>({...r,amount:r.credit-r.debit}));const expenses=tb.filter(r=>r.type==='Expense').map(r=>({...r,amount:r.debit-r.credit}));const totalRevenue=round2(revenue.reduce((s,r)=>s+r.amount,0)),totalExpenses=round2(expenses.reduce((s,r)=>s+r.amount,0));return {revenue,expenses,totalRevenue,totalExpenses,netIncome:round2(totalRevenue-totalExpenses)}}
  function balanceSheetV4(){const tb=trialBalanceV4().rows,is=incomeStatementV4();const assets=tb.filter(r=>['Asset','Contra-Asset'].includes(r.type)).map(r=>({...r,amount:r.type==='Contra-Asset'?-(r.credit-r.debit):(r.debit-r.credit)}));const liabilities=tb.filter(r=>r.type==='Liability').map(r=>({...r,amount:r.credit-r.debit}));const equity=tb.filter(r=>r.type==='Equity').map(r=>({...r,amount:r.credit-r.debit}));const totalAssets=round2(assets.reduce((s,r)=>s+r.amount,0)),totalLiabilities=round2(liabilities.reduce((s,r)=>s+r.amount,0)),baseEquity=round2(equity.reduce((s,r)=>s+r.amount,0)),totalEquity=round2(baseEquity+is.netIncome);return {assets,liabilities,equity,baseEquity,currentEarnings:is.netIncome,totalAssets,totalLiabilities,totalEquity,difference:round2(totalAssets-totalLiabilities-totalEquity)}}
  function cashFlowV4(){const sums={Operating:0,Investing:0,Financing:0};allJournalsV4().forEach(j=>{if(!j.cashFlow)return;const cash=j.lines.filter(l=>l.account==='1100').reduce((s,l)=>s+l.baseDebit-l.baseCredit,0);sums[j.cashFlow]=round2(sums[j.cashFlow]+cash)});const opening=allJournalsV4().filter(j=>j.source==='Opening Balance').flatMap(j=>j.lines).filter(l=>l.account==='1100').reduce((s,l)=>s+l.baseDebit-l.baseCredit,0);const change=round2(sums.Operating+sums.Investing+sums.Financing);return {...sums,opening:round2(opening),change,closing:round2(opening+change)}}
  function reportRowsV4(kind){
    const tb=trialBalanceV4(),is=incomeStatementV4(),bs=balanceSheetV4(),cf=cashFlowV4();
    if(kind==='trial')return [...tb.rows.map(r=>({label:`${r.code} · ${r.name}`,code:r.code,debit:r.debit,credit:r.credit})),{label:'TOTAL',debit:tb.totalDebit,credit:tb.totalCredit,total:true}];
    if(kind==='income')return [{label:'REVENUE',section:true},...is.revenue.map(r=>({label:r.name,code:r.code,amount:r.amount})),{label:'Total revenue',amount:is.totalRevenue,total:true},{label:'EXPENSES',section:true},...is.expenses.map(r=>({label:r.name,code:r.code,amount:-r.amount})),{label:'Total expenses',amount:-is.totalExpenses,total:true},{label:'NET INCOME',amount:is.netIncome,grand:true}];
    if(kind==='balance')return [{label:'ASSETS',section:true},...bs.assets.map(r=>({label:r.name,code:r.code,amount:r.amount})),{label:'Total assets',amount:bs.totalAssets,total:true},{label:'LIABILITIES',section:true},...bs.liabilities.map(r=>({label:r.name,code:r.code,amount:r.amount})),{label:'Total liabilities',amount:bs.totalLiabilities,total:true},{label:'EQUITY',section:true},...bs.equity.map(r=>({label:r.name,code:r.code,amount:r.amount})),{label:'Current period earnings',amount:bs.currentEarnings},{label:'Total equity',amount:bs.totalEquity,total:true},{label:'LIABILITIES + EQUITY',amount:round2(bs.totalLiabilities+bs.totalEquity),grand:true}];
    if(kind==='cashflow')return [{label:'Cash flows from operating activities',amount:cf.Operating},{label:'Cash flows from investing activities',amount:cf.Investing},{label:'Cash flows from financing activities',amount:cf.Financing},{label:'Net movement in cash',amount:cf.change,total:true},{label:'Cash at beginning of period',amount:cf.opening},{label:'Cash at end of period',amount:cf.closing,grand:true}];
    return [{label:'Opening equity',amount:bs.baseEquity},{label:'Current period net income',amount:bs.currentEarnings},{label:'Distributions',amount:0},{label:'Closing equity',amount:bs.totalEquity,grand:true}];
  }
  const reportMetaV4={trial:['Trial Balance','Integrity check: total debits must equal total credits.'],income:['Income Statement','Revenue less expenses for the selected period.'],balance:['Balance Sheet','Financial position: Assets = Liabilities + Equity.'],cashflow:['Cash Flow Statement','Operating, investing and financing cash movements.'],equity:['Statement of Changes in Equity','Opening equity, current earnings and distributions.']};
  function integrityV4(){const tb=trialBalanceV4(),bs=balanceSheetV4();return {tbDifference:round2(tb.totalDebit-tb.totalCredit),equationDifference:bs.difference,journals:allJournalsV4().length,lines:allLinesV4().length,pending:engineV4.pending.length}}
  function accountOptionsV4(includeControls=true,selected=''){return accountsV4.filter(a=>includeControls||!a.control).map(a=>`<option value="${a.code}" ${a.code===selected?'selected':''}>${a.code} · ${a.name}${a.control?' · sub-ledger':''}</option>`).join('')}
  function reportTableHtmlV4(kind,interactive=true){const rows=reportRowsV4(kind);if(kind==='trial')return `<table class="data-table report-table-v4"><thead><tr><th>Account</th><th class="num">Debit</th><th class="num">Credit</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.total?'report-total-v4':''}" ${r.code&&interactive?`data-action="account-drill-v4" data-id="${r.code}"`:''}><td class="${r.code?'link':''}">${r.label}</td><td class="num">${r.debit?moneyV4(r.debit):'-'}</td><td class="num">${r.credit?moneyV4(r.credit):'-'}</td></tr>`).join('')}</tbody></table>`;return `<table class="data-table report-table-v4"><thead><tr><th>Line item</th><th class="num">Amount · USD</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.section?'report-section-v4':''} ${r.total?'report-total-v4':''} ${r.grand?'report-grand-v4':''}" ${r.code&&interactive?`data-action="account-drill-v4" data-id="${r.code}"`:''}><td class="${r.code?'link':''}">${r.label}</td><td class="num">${r.section?'':moneyV4(r.amount||0)}</td></tr>`).join('')}</tbody></table>`}
  function financialDocumentV4(kind){const meta=reportMetaV4[kind],i=integrityV4();return `<div class="doc-page financial-doc-v4"><div class="financial-doc-head-v4"><div><div class="doc-brand-v4">matanho</div><span>ACCOUNTING · GOVERNED FINANCIAL OUTPUT</span></div><div><strong>${esc(meta[0])}</strong><small>${esc(state.period)} · ${esc(entities.find(x=>x[0]===state.entity)?.[1]||state.entity)}</small></div></div><div class="doc-meta"><div><span>Presentation currency</span><strong>USD</strong></div><div><span>Ledger snapshot</span><strong>${allJournalsV4().length} immutable journals</strong></div><div><span>Generated by</span><strong>${esc(currentUserV4())}</strong></div></div><h1>${esc(meta[0])}</h1><p>${esc(meta[1])}</p><div class="table-wrap report-document-table-v4">${reportTableHtmlV4(kind,false)}</div><div class="report-cert-v4"><strong>Integrity certification</strong><span>Trial balance difference: ${moneyV4(i.tbDifference)} · Accounting equation difference: ${moneyV4(i.equationDifference)} · Source lines: ${i.lines}</span></div><div class="doc-sign-v4"><div><span>Prepared by</span><strong>${esc(currentUserV4())}</strong><small>Digitally recorded</small></div><div><span>Reviewed by</span><strong>Independent checker</strong><small>Pending / recorded in workflow</small></div><div><span>Document status</span><strong>Preview</strong><small>Versioned on generation</small></div></div></div>`}
  function openReportPreviewV4(kind){const meta=reportMetaV4[kind]||reportMetaV4.trial;openModal(meta[0],`${state.period} · live general-ledger aggregation`,`<div class="document-preview">${financialDocumentV4(kind)}</div>`,btn('Edit commentary','edit-report-v4','',kind)+btn(`${icon('download')} Download CSV`,'export-report-v4','',kind)+btn('Send for approval','submit-report-v4','primary',kind),true)}
  function accountDrillV4(code){const a=accountMapV4[code],lines=allLinesV4().filter(l=>l.account===code);const totalD=lines.reduce((s,l)=>s+l.baseDebit,0),totalC=lines.reduce((s,l)=>s+l.baseCredit,0);openDrawer(`${code} · ${a.name}`,`${a.type} · ${a.natural} natural balance`,`<div class="grid three">${kpi('Debits',moneyV4(totalD),'posted base value','ledger')}${kpi('Credits',moneyV4(totalC),'posted base value','ledger')}${kpi('Net balance',moneyV4(Math.abs(totalD-totalC)),a.natural+' balance','report')}</div><div style="margin-top:12px">${card('Contributing transactions','Select a journal to inspect the immutable double-entry record',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Journal</th><th>Source</th><th>Description</th><th class="num">Debit</th><th class="num">Credit</th><th>Currency / rate</th></tr></thead><tbody>${lines.map(l=>`<tr data-action="journal-drill-v4" data-id="${l.journalId}"><td>${l.date}</td><td class="link">${l.journalId}</td><td>${l.source}</td><td>${l.description}</td><td class="num">${l.baseDebit?moneyV4(l.baseDebit):'-'}</td><td class="num">${l.baseCredit?moneyV4(l.baseCredit):'-'}</td><td>${l.currency} · ${l.rate.toFixed(4)}</td></tr>`).join('')}</tbody></table></div>`)}</div>`,btn('Open General Ledger','go-ledger','primary'))}
  function journalDrillV4(id){const j=[...allJournalsV4(),...engineV4.pending].find(x=>x.id===id);if(!j)return;const isPending=j.status==='In review';const total=j.lines.reduce((s,l)=>s+(l.debit||0),0);openDrawer(`${j.id} · ${isPending?'In review':'Posted'}`,`${j.source} · ${j.sourceId}`,`<div class="journal-proof-v4"><div>${personV4(j.maker,'Maker','md')}</div><div class="journal-proof-arrow-v4">→</div><div>${personV4(j.checker||'Unassigned','Checker','md')}</div></div><div class="profile-summary-strip" style="margin-top:12px"><div class="fact"><span>Transaction currency</span><strong>${j.currency}</strong></div><div class="fact"><span>Exchange rate</span><strong>${Number(j.rate||1).toFixed(4)}</strong></div><div class="fact"><span>Total value</span><strong>${moneyV4(total,j.currency)}</strong></div><div class="fact"><span>Integrity hash</span><strong>${j.hash||hashV4(JSON.stringify(j))}</strong></div></div><div style="margin-top:12px">${card('Immutable journal lines','Every debit and credit is retained as the atomic accounting record',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Account</th><th>Narration</th><th class="num">Debit · ${j.currency}</th><th class="num">Credit · ${j.currency}</th><th class="num">Base debit</th><th class="num">Base credit</th></tr></thead><tbody>${j.lines.map(l=>`<tr data-action="account-drill-v4" data-id="${l.account}"><td class="link">${l.account} · ${accountMapV4[l.account]?.name||''}</td><td>${l.narration||j.description}</td><td class="num">${l.debit?moneyV4(l.debit,j.currency):'-'}</td><td class="num">${l.credit?moneyV4(l.credit,j.currency):'-'}</td><td class="num">${l.baseDebit?moneyV4(l.baseDebit):l.debit?moneyV4(l.debit*(j.rate||1)):'-'}</td><td class="num">${l.baseCredit?moneyV4(l.baseCredit):l.credit?moneyV4(l.credit*(j.rate||1)):'-'}</td></tr>`).join('')}</tbody></table></div>`)}</div><div class="note" style="margin-top:12px">Posted journals cannot be edited or deleted. Corrections are made through a separately approved reversal journal, preserving the complete audit trail.</div>`,isPending&&can('journal.approve')?btn('Approve and post','approve-pending-v4','primary',j.id):btn('Request reversal','reverse-journal-v4','danger',j.id))}

  function ledgerPageV4(){const i=integrityV4(),q=engineV4.search.toLowerCase(),lines=allLinesV4().filter(l=>(engineV4.account==='All accounts'||l.account===engineV4.account)&&(!q||Object.values(l).join(' ').toLowerCase().includes(q)));return `${pageHead('Core accounting record','General Ledger Explorer','The real-time consolidated source of truth. Every sub-ledger transaction resolves to an immutable, balanced journal entry.',btn(`${icon('plus')} Manual journal`,'new-manual-v4','primary')+btn(`${icon('report')} Trial balance`,'go-trial-v4')+btn(`${icon('download')} Export`,'export-ledger-v4'))}<div class="integrity-strip-v4"><div><span>Double-entry integrity</span><strong>${moneyV4(i.tbDifference)}</strong><small>trial balance difference</small></div><div><span>Accounting equation</span><strong>${moneyV4(i.equationDifference)}</strong><small>Assets − Liabilities − Equity</small></div><div><span>Immutable journals</span><strong>${i.journals}</strong><small>${i.lines} atomic lines</small></div><div><span>Maker-checker queue</span><strong>${i.pending}</strong><small>manual journals awaiting review</small></div></div>${card('Ledger lines','Drill from any line to the complete journal and source record',`<div class="filterbar"><input class="input" id="engineSearchV4" value="${esc(engineV4.search)}" placeholder="Search journal, source, account, description or owner"><select class="select" id="engineAccountV4"><option>All accounts</option>${accountsV4.map(a=>`<option value="${a.code}" ${engineV4.account===a.code?'selected':''}>${a.code} · ${a.name}</option>`).join('')}</select><span class="pill">Base currency · USD</span></div><div class="table-wrap"><table class="data-table dense-ledger-v4"><thead><tr><th>Date</th><th>Journal / source</th><th>Account</th><th>Description</th><th class="num">Debit</th><th class="num">Credit</th><th>Currency / rate</th><th>Maker</th><th>Status</th></tr></thead><tbody>${lines.map(l=>`<tr data-action="journal-drill-v4" data-id="${l.journalId}"><td>${l.date}</td><td><strong class="link">${l.journalId}</strong><span class="sub">${l.source} · ${l.sourceId}</span></td><td>${l.account} · ${accountMapV4[l.account].name}</td><td>${l.description}</td><td class="num">${l.baseDebit?moneyV4(l.baseDebit):'-'}</td><td class="num">${l.baseCredit?moneyV4(l.baseCredit):'-'}</td><td>${l.currency}<span class="sub">rate ${l.rate.toFixed(4)}</span></td><td>${personV4(l.maker,'','xs')}</td><td>${badge('Posted')}</td></tr>`).join('')}</tbody></table></div>`)}`}

  let manualDraftV4={description:'Month-end adjustment',reference:'MAN-'+Date.now().toString().slice(-5),date:'31 Jul 2026',currency:'USD',rate:1,lines:[lineV4('5104',0,0,'Adjustment line'),lineV4('2205',0,0,'Balancing line')]};
  function journalsPageV4(){const val=validateLinesV4(manualDraftV4.lines,'Manual'),d=manualDraftV4.lines.reduce((s,l)=>s+Number(l.debit||0),0),c=manualDraftV4.lines.reduce((s,l)=>s+Number(l.credit||0),0);return `${pageHead('Governed process','Journal Entry Maker-Checker','Manual journals enforce line-level validation, balanced debits and credits, control-account restrictions and independent approval.',btn('Reset draft','reset-manual-v4')+btn('Journal register','journal-register-v4')+btn('Submit for review','submit-manual-v4','primary'))}<div class="journal-layout-v4"><div class="stack">${card('Journal header','Transaction identity and multi-currency values',`<div class="form-grid two-col"><div class="field full"><label>Description</label><input class="input" id="manualDescV4" value="${esc(manualDraftV4.description)}"></div><div class="field"><label>Reference number</label><input class="input" id="manualRefV4" value="${esc(manualDraftV4.reference)}"></div><div class="field"><label>Journal date</label><input class="input" id="manualDateV4" value="${esc(manualDraftV4.date)}"></div><div class="field"><label>Transaction currency</label><select class="select" id="manualCurrencyV4"><option ${manualDraftV4.currency==='USD'?'selected':''}>USD</option><option ${manualDraftV4.currency==='ZiG'?'selected':''}>ZiG</option><option ${manualDraftV4.currency==='ZAR'?'selected':''}>ZAR</option></select></div><div class="field"><label>Rate to USD</label><input class="input" id="manualRateV4" type="number" step="0.0001" value="${manualDraftV4.rate}"></div></div>`) }${card('Journal lines','Control accounts are posted only by their underlying sub-ledgers',`<div class="table-wrap"><table class="data-table journal-lines-v4"><thead><tr><th>#</th><th>Account</th><th>Narration</th><th class="num">Debit</th><th class="num">Credit</th><th></th></tr></thead><tbody>${manualDraftV4.lines.map((l,i)=>`<tr><td>${i+1}</td><td><select class="select manual-line-v4" data-index="${i}" data-field="account">${accountOptionsV4(true,l.account)}</select></td><td><input class="input manual-line-v4" data-index="${i}" data-field="narration" value="${esc(l.narration||'')}"></td><td><input class="input manual-line-v4 num" data-index="${i}" data-field="debit" type="number" step="0.01" value="${l.debit||''}"></td><td><input class="input manual-line-v4 num" data-index="${i}" data-field="credit" type="number" step="0.01" value="${l.credit||''}"></td><td><button class="row-icon-v4" data-action="remove-manual-line-v4" data-id="${i}" title="Remove line">×</button></td></tr>`).join('')}</tbody></table></div><div class="journal-total-v4"><button class="btn small" data-action="add-manual-line-v4">${icon('plus')} Add line</button><span>Debits <strong>${moneyV4(d,manualDraftV4.currency)}</strong></span><span>Credits <strong>${moneyV4(c,manualDraftV4.currency)}</strong></span><span class="${val.ok?'ok-v4':'bad-v4'}">${val.ok?'Balanced':'Difference '+moneyV4(Math.abs(d-c),manualDraftV4.currency)}</span></div>`)}</div><aside class="stack sticky">${card('Validation & controls','Immediate checks before submission',statusRows([['Debit = credit',val.ok?'Balanced':'Out of balance',val.ok?'Complete':'Exception'],['Control-account posting','Sub-ledger only','Enforced'],['Exchange rate',manualDraftV4.rate>0?'Valid':'Missing',manualDraftV4.rate>0?'Complete':'Exception'],['Accounting period','July 2026 open','Complete'],['Maker',currentUserV4(),'Recorded'],['Checker','Independent role required','Pending']]))}${card('Pending manual journals','Independent checker queue',engineV4.pending.length?`<div class="stack">${engineV4.pending.map(p=>`<div class="status-line" data-action="journal-drill-v4" data-id="${p.id}"><div>${personV4(p.maker,p.id,'xs')}<span class="sub">${p.description}</span></div>${badge('In review')}</div>`).join('')}</div>`:`<div class="empty-v4">No manual journals awaiting review.</div>`,can('journal.approve')&&engineV4.pending.length?btn('Review first journal','journal-drill-v4','primary small',engineV4.pending[0].id):'')}</aside></div>`}

  function cashPageV4(){const lines=allLinesV4().filter(l=>l.account==='1100'),balance=lines.reduce((s,l)=>s+l.baseDebit-l.baseCredit,0),recent=[...allJournalsV4()].filter(j=>j.lines.some(l=>l.account==='1100')&&j.source!=='Opening Balance').reverse();const cf=cashFlowV4();return `${pageHead('Sub-ledger','Cashbook & Daily Liquidity','All receipts, payments and transfers create a fully balanced journal entry and update Bank Account 1100 in real time.',btn(`${icon('plus')} New receipt`,'open-cash-entry-v4','primary','receipt')+btn('New payment','open-cash-entry-v4','','payment')+btn('Transfer','open-cash-entry-v4','','transfer'))}<div class="grid kpis">${kpi('Bank / cash balance',moneyV4(balance),'GL account 1100','cash')}${kpi('Operating cash flow',moneyV4(cf.Operating),'current period','report')}${kpi('Investing cash flow',moneyV4(cf.Investing),'current period','invest')}${kpi('Financing cash flow',moneyV4(cf.Financing),'current period','group')}${kpi('Unreconciled lines','2','bank workbench','warning','2','warn')}${kpi('Ledger integrity',moneyV4(integrityV4().tbDifference),'debit-credit difference','shield')}</div><div class="split-2"><div>${card('Cashbook register','Each row links to the atomic double-entry journal',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Reference</th><th>Counterparty / description</th><th>Classification</th><th class="num">Cash inflow</th><th class="num">Cash outflow</th><th>Journal</th><th>Status</th></tr></thead><tbody>${recent.map(j=>{const cash=j.lines.find(l=>l.account==='1100'),movement=cash.baseDebit-cash.baseCredit;return `<tr data-action="journal-drill-v4" data-id="${j.id}"><td>${j.date}</td><td>${j.sourceId}</td><td>${j.description}</td><td>${j.cashFlow||'Unclassified'}</td><td class="num">${movement>0?moneyV4(movement):'-'}</td><td class="num">${movement<0?moneyV4(-movement):'-'}</td><td class="link">${j.id}</td><td>${badge('Posted')}</td></tr>`}).join('')}</tbody></table></div>`)}</div><aside class="stack sticky">${card('Cash-flow bridge','Cashbook classification feeds the Cash Flow Statement',`${progressRow('Operating',Math.min(100,Math.abs(cf.Operating)/10000),moneyV4(cf.Operating))}${progressRow('Investing',Math.min(100,Math.abs(cf.Investing)/10000),moneyV4(cf.Investing),'amber')}${progressRow('Financing',Math.min(100,Math.abs(cf.Financing)/10000),moneyV4(cf.Financing),'violet')}<div class="mini-sheet" style="margin-top:10px"><div><span>Opening cash</span><strong>${moneyV4(cf.opening)}</strong></div><div><span>Net movement</span><strong>${moneyV4(cf.change)}</strong></div><div><span>Closing cash</span><strong>${moneyV4(cf.closing)}</strong></div></div>`,btn('Preview cash flow','preview-report-v4','soft small','cashflow'))}${card('Cashbook controls','Validation before posting',statusRows([['Counter-account required','Every entry','Enforced'],['Positive amount and rate','Before posting','Enforced'],['Source reference','Audit and reconciliation','Required'],['Bank reconciliation','Daily / weekly','Configured'],['Immutable correction','Reversal journal only','Enforced']]))}</aside></div>`}

  function receivablesPageV4(){const total=receivables.reduce((s,r)=>s+r.outstanding,0),overdue=receivables.filter(r=>r.age>30).reduce((s,r)=>s+r.outstanding,0);return `${pageHead('Sub-ledger','Debtors · Accounts Receivable','Create invoices, record receipts and drill from customer balances to automatically generated journals.',btn(`${icon('plus')} Create invoice`,'open-sales-invoice-v4','primary')+btn('Record receipt','open-customer-receipt-v4')+btn('Customer registry','customer-registry-v4'))}<div class="grid kpis">${kpi('Outstanding',moneyV4(total),'customer sub-ledger','receivable')}${kpi('Overdue',moneyV4(overdue),'older than 30 days','warning')}${kpi('Invoices',String(receivables.length),'open and settled records','file')}${kpi('Control account',moneyV4(Math.abs(trialBalanceV4().rows.find(r=>r.code==='1300')?.debit||0)),'GL account 1300','ledger')}${kpi('Unallocated receipts','0','all receipts allocated','cash')}${kpi('Journal linkage','100%','invoice to GL traceability','link')}</div>${card('Customer invoice register','Invoice, receipt allocation and ledger status',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Invoice</th><th>Invoice date</th><th>Due</th><th>Currency</th><th class="num">Original</th><th class="num">Outstanding</th><th>Age</th><th>Status</th></tr></thead><tbody>${receivables.map(r=>`<tr data-action="receivable-v4" data-id="${r.invoice}"><td>${r.customer}</td><td class="link">${r.invoice}</td><td>${r.date}</td><td>${r.due}</td><td>${r.currency}</td><td class="num">${moneyV4(r.original,r.currency)}</td><td class="num">${moneyV4(r.outstanding,r.currency)}</td><td>${r.age} days</td><td>${badge(r.status)}</td></tr>`).join('')}</tbody></table></div>`)}`}

  function payablesPageV4(){const total=supplierInvoices.reduce((s,r)=>s+r.amount,0);return `${pageHead('Sub-ledger','Creditors · Accounts Payable','Capture supplier bills and payments through the creditors sub-ledger; the system posts balanced journals to control account 2000.',btn(`${icon('plus')} Supplier invoice`,'open-supplier-invoice-v4','primary')+btn('Record payment','open-supplier-payment-v4')+btn('Vendor registry','go-vendors-v4')+btn('Compare quotations','go-quotations-v4'))}<div class="grid kpis">${kpi('Invoice register',moneyV4(total),'current displayed invoices','payable')}${kpi('GL control balance',moneyV4(Math.abs((trialBalanceV4().rows.find(r=>r.code==='2000')?.credit||0)-(trialBalanceV4().rows.find(r=>r.code==='2000')?.debit||0))),'account 2000','ledger')}${kpi('Ready to pay','18','validated beneficiaries','check')}${kpi('Match exceptions','2','PO / GRN / invoice','warning','2','bad')}${kpi('Tax evidence','94%','invoice coverage','tax')}${kpi('Vendor holds','1','payment eligibility','lock')}</div>${card('Supplier invoice register','Bills, three-way match and journal traceability',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Invoice</th><th>Supplier</th><th>Supplier reference</th><th>Date</th><th>Due</th><th>PO / evidence</th><th class="num">Amount</th><th>Owner</th><th>Status</th></tr></thead><tbody>${supplierInvoices.map(x=>`<tr data-action="payable-v4" data-id="${x.id}"><td class="link">${x.id}</td><td>${x.supplier}</td><td>${x.invoice}</td><td>${x.date}</td><td>${x.due}</td><td>${x.po}<span class="sub">${x.grn}</span></td><td class="num">${moneyV4(x.amount,x.currency)}</td><td>${personV4(x.owner,'','xs')}</td><td>${badge(x.status)}</td></tr>`).join('')}</tbody></table></div>`)}`}

  function inventoryPageV4(){const value=inventory.reduce((s,x)=>s+x.qty*x.unitCost,0),exceptions=inventory.filter(x=>/Review|Exception/.test(x.status)).length;return `${pageHead('Integrated sub-ledger','Inventory Accounting','Perpetual quantities, weighted cost, count adjustments and automatic cost-of-sales journals remain linked to the General Ledger.',btn(`${icon('plus')} Stock adjustment`,'open-stock-adjustment-v4','primary')+btn('Record purchase','open-inventory-purchase-v4')+btn('Run valuation','run-valuation-v4'))}<div class="grid kpis">${kpi('Inventory value',moneyV4(value),'live quantity × cost','inventory')}${kpi('GL inventory balance',moneyV4(trialBalanceV4().rows.find(r=>r.code==='1400')?.debit||0),'account 1400','ledger')}${kpi('Items',String(inventory.length),'active SKUs','file')}${kpi('Count exceptions',String(exceptions),'require evidence','warning',String(exceptions),'bad')}${kpi('COGS posted',moneyV4(trialBalanceV4().rows.find(r=>r.code==='5005')?.debit||0),'current period','report')}${kpi('Valuation method','Weighted average','effective rule','settings')}</div>${card('Inventory valuation register','Select an item for movement, valuation and journal detail',`<div class="table-wrap"><table class="data-table"><thead><tr><th>SKU</th><th>Item</th><th>Category</th><th>Warehouse</th><th class="num">Quantity</th><th class="num">Unit cost</th><th class="num">Value</th><th>Count variance</th><th>Obsolete</th><th>Status</th></tr></thead><tbody>${inventory.map(x=>`<tr data-action="inventory-item-v4" data-id="${x.sku}"><td class="link">${x.sku}</td><td>${x.item}</td><td>${x.category}</td><td>${x.warehouse}</td><td class="num">${x.qty}</td><td class="num">${moneyV4(x.unitCost)}</td><td class="num">${moneyV4(x.qty*x.unitCost)}</td><td>${x.countVar}</td><td>${x.obsolete}</td><td>${badge(x.status)}</td></tr>`).join('')}</tbody></table></div>`)}`}

  function assetsPageV4(){const posted=allJournalsV4().some(j=>j.sourceId==='DEP-AUTO-JUL-2026'),dep=31860;return `${pageHead('Fixed asset sub-ledger','Fixed Assets & Depreciation','Maintain asset evidence and generate a scheduled non-cash journal: debit depreciation expense and credit accumulated depreciation.',btn(`${icon('plus')} Add asset`,'add-asset-v4')+btn('Preview depreciation','preview-depreciation-v4')+`<button class="btn primary" data-action="post-depreciation-v4" ${posted?'disabled':''}>${posted?'Run posted':'Post depreciation run'}</button>`)}<div class="grid kpis">${kpi('Asset cost',moneyV4(assets.reduce((s,a)=>s+a.cost,0)),'register value','asset')}${kpi('Accumulated depreciation',moneyV4(assets.reduce((s,a)=>s+a.accum,0)),'register value','report')}${kpi('Net book value',moneyV4(assets.reduce((s,a)=>s+a.nbv,0)),'cost less accumulated','invest')}${kpi('July depreciation',moneyV4(dep),'scheduled journal','journal')}${kpi('Evidence coverage','98%','purchase documents','vault')}${kpi('Posting status',posted?'Posted':'Ready','maker-checker run','check')}</div><div class="split-2"><div>${card('Asset register','Cost, custodian, useful life and current book value',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Asset ID</th><th>Description</th><th>Category</th><th>Location</th><th>Custodian</th><th class="num">Cost</th><th class="num">Accum.</th><th class="num">NBV</th><th>Status</th></tr></thead><tbody>${assets.map(x=>`<tr data-action="asset-detail" data-id="${x.id}"><td class="link">${x.id}</td><td>${x.desc}</td><td>${x.category}</td><td>${x.location}</td><td>${personV4(x.custodian,'','xs')}</td><td class="num">${moneyV4(x.cost)}</td><td class="num">${moneyV4(x.accum)}</td><td class="num">${moneyV4(x.nbv)}</td><td>${badge(x.status)}</td></tr>`).join('')}</tbody></table></div>`)}</div><aside class="stack sticky">${card('Scheduled posting preview','Non-cash adjustment generated from the asset register',`<div class="mini-sheet"><div class="head"><strong>Account</strong><strong>Debit</strong><strong>Credit</strong><strong>Rule</strong></div><div><span>5130 Depreciation Expense</span><span>${moneyV4(dep)}</span><span>-</span><span>Scheduled</span></div><div><span>1550 Accumulated Depreciation</span><span>-</span><span>${moneyV4(dep)}</span><span>Straight-line</span></div></div><div class="note" style="margin-top:10px">The posting is immutable after approval. A correction requires a reversal and a replacement run.</div>`,btn('Preview journal','preview-depreciation-v4','soft small'))}${card('Run controls','Register completeness and posting conditions',statusRows([['Useful lives','All active assets','Complete'],['Missing evidence','2 records','Review'],['Transfer pending','1 record','Pending'],['Debit = credit',moneyV4(0),'Complete'],['Independent checker','Required','Enforced']]))}</aside></div>`}

  function reportsPageV4(){const kind=state.selectedReportV4||'trial',meta=reportMetaV4[kind],i=integrityV4();return `${pageHead('Financial reporting','Financial Statements & Trial Balance','Reports aggregate directly from immutable journal lines. Every account and figure drills back to contributing transactions.',btn(`${icon('file')} Preview report`,'preview-report-v4','primary',kind)+btn(`${icon('download')} Export`,'export-report-v4','',kind)+btn('Send for approval','submit-report-v4','',kind))}<div class="report-workspace-v4"><aside class="report-rail-v4">${Object.entries(reportMetaV4).map(([id,m])=>`<button class="report-choice-v4 ${id===kind?'active':''}" data-action="select-report-v4" data-id="${id}"><span>${icon(id==='trial'?'ledger':id==='cashflow'?'cash':'report')}</span><div><strong>${m[0]}</strong><small>${m[1]}</small></div></button>`).join('')}</aside><section class="card"><div class="card-head"><div class="card-title"><strong>${meta[0]}</strong><span>${state.period} · Live ledger snapshot · Base currency USD</span></div><div class="card-tools"><span class="badge">${i.tbDifference===0?'Balanced':'Exception'}</span></div></div><div class="card-body"><div class="report-integrity-v4"><span>Trial balance difference <strong>${moneyV4(i.tbDifference)}</strong></span><span>Equation difference <strong>${moneyV4(i.equationDifference)}</strong></span><span>Source journals <strong>${i.journals}</strong></span><span>Atomic lines <strong>${i.lines}</strong></span></div><div class="table-wrap">${reportTableHtmlV4(kind,true)}</div></div></section><aside class="stack">${card('Report controls','Scope, currency and governed output',statusRows([['Entity',entities.find(x=>x[0]===state.entity)?.[1]||state.entity,'Recorded'],['Period',state.period,'Recorded'],['Presentation currency','USD','Recorded'],['Trial balance','Balanced','Complete'],['Variance commentary','Editable document','Ready'],['Approval chain','Controller → Director','Enforced']]),btn('Preview','preview-report-v4','primary small',kind))}${card('Report lineage','End-to-end drill-down',`<div class="workflow-strip"><div><i>1</i><strong>Sub-ledger</strong><span>Business task</span></div><div><i>2</i><strong>Journal</strong><span>Debit = credit</span></div><div><i>3</i><strong>General Ledger</strong><span>Real-time balance</span></div><div><i>4</i><strong>Trial Balance</strong><span>Integrity check</span></div><div><i>5</i><strong>Statement</strong><span>Governed output</span></div></div>`)} </aside></div>`}

  function accessPageV4(){const current=state.role;return `${pageHead('Security & governance','Dynamic Role-Based Access Control','Page, action, data, amount, entity, document and maker-checker permissions are evaluated using the selected role and named user.',btn(`${icon('plus')} Invite user`,'invite-user')+btn('Create role','create-role','primary'))}<div class="grid kpis">${kpi('Finance users',String(users.length),'named identities','users')}${kpi('Roles',String(roles.length),'least-privilege profiles','access')}${kpi('MFA coverage','100%','finance users','shield')}${kpi('Journal approvers',String(users.filter(u=>['Finance Director','Financial Controller'].includes(u.role)).length),'independent checkers','approve')}${kpi('Pending journals',String(engineV4.pending.length),'maker-checker queue','journal')}${kpi('SoD conflicts','0','continuous policy evaluation','check')}</div><div class="split-2"><div>${card('Named-user access register','Profile, role, data scope and approval capability',`<div class="table-wrap"><table class="data-table"><thead><tr><th>User</th><th>Role</th><th>Entity scope</th><th>MFA</th><th>Last active</th><th>Journal approval</th><th>Status</th></tr></thead><tbody>${users.map(u=>`<tr data-action="user-detail" data-id="${u.email}"><td>${personV4(u.name,u.email,'sm')}</td><td>${u.role}</td><td>${u.scope}</td><td>${badge(u.mfa)}</td><td>${u.last}</td><td>${badge(['Finance Director','Financial Controller'].includes(u.role)?'Granted':'Restricted')}</td><td>${badge(u.status)}</td></tr>`).join('')}</tbody></table></div>`)}</div><aside class="stack sticky">${card('Policy simulator','Test a role against action, amount and entity constraints',`<div class="form-grid"><div class="field"><label>Role</label><select class="select" id="simRole">${roles.map(r=>`<option ${r===current?'selected':''}>${r}</option>`).join('')}</select></div><div class="field"><label>Permission</label><select class="select" id="simPermission">${permissions.map(p=>`<option value="${p[0]}">${p[0]}</option>`).join('')}</select></div><div class="field"><label>Transaction amount</label><input class="input" id="simAmount" type="number" value="25000"></div><div class="field"><label>Entity</label><select class="select"><option>Matanho Capital Partners</option><option>Matanho Operations</option></select></div></div><div class="note" id="simResult" style="margin-top:10px">Run a simulation to evaluate the effective policy.</div>`,btn('Test access','test-access','primary small'))}${card('Segregation of duties','Non-negotiable conflict rules',statusRows([['Journal maker vs checker','Same identity blocked','Enforced'],['Vendor bank editor vs payment approver','Incompatible permissions','Enforced'],['Tax preparer vs final filer','Independent approval','Enforced'],['Control account direct posting','Sub-ledger only','Enforced'],['Posted journal modification','Update and delete blocked','Enforced']]))}</aside></div><div style="margin-top:14px">${card('Permission matrix','Authorised administrators can toggle effective role permissions; all changes are versioned.',`<div class="permission-grid"><table class="data-table"><thead><tr><th>Permission</th><th>Description</th>${roles.slice(0,6).map(r=>`<th>${r.replace(' Officer','').replace('Financial ','Fin. ')}</th>`).join('')}</tr></thead><tbody>${permissions.map(p=>`<tr><td><code>${p[0]}</code></td><td>${p[1]}</td>${roles.slice(0,6).map(r=>`<td><span class="permission-toggle ${(rolePermissions[r]||[]).includes(p[0])?'on':''} ${!can('rbac.manage')?'locked':''}" data-action="toggle-permission" data-role="${r}" data-id="${p[0]}"><i></i></span></td>`).join('')}</tr>`).join('')}</tbody></table></div>`)}</div>`}

  function approvalsPageV4(){const pendingManual=engineV4.pending.map(p=>({id:'P-'+p.id,type:'Journal',record:p.id,subject:p.description,amount:p.lines.reduce((s,l)=>s+l.debit,0),currency:p.currency,maker:p.maker,submitted:'Just now',risk:'Medium',status:'Pending'}));const list=[...pendingManual,...approvals.filter(a=>!pendingManual.some(p=>p.record===a.record))];return `${pageHead('Governed actions','Approval Queue','Independent decisions for journals, payment runs, reports, tax packs and master-data changes.',btn('Refresh controls','refresh-approvals')+btn('Approval policy','approval-policy','primary'))}${card('Risk-ranked requests','Select a request for evidence, thresholds and decision controls',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Request</th><th>Type / record</th><th>Subject</th><th>Maker</th><th>Submitted</th><th class="num">Amount</th><th>Risk</th><th>Status</th></tr></thead><tbody>${list.map(a=>`<tr data-action="${a.record.startsWith('MJE-')?'journal-drill-v4':'approval-detail'}" data-id="${a.record.startsWith('MJE-')?a.record:a.id}"><td class="link">${a.id}</td><td>${a.type}<span class="sub">${a.record}</span></td><td>${a.subject}</td><td>${personV4(a.maker,'','xs')}</td><td>${a.submitted}</td><td class="num">${moneyV4(a.amount,a.currency)}</td><td>${badge(a.risk)}</td><td>${badge(a.status)}</td></tr>`).join('')}</tbody></table></div>`)}`}

  function expensesPageV4(){return `${pageHead('Employee sub-ledger','Expenses & Employee Claims','Itemised claims, receipt evidence and policy controls feed approved expense and payable journals.',btn(`${icon('plus')} New claim`,'new-claim','primary')+btn('Import corporate card','import-card'))}<div class="grid kpis">${kpi('Submitted',moneyV4(36480),'45 claims','expense')}${kpi('Awaiting review',moneyV4(12744.5),'14 claims','warning')}${kpi('Policy exceptions',moneyV4(6320.45),'4 claims','warning')}${kpi('Approved unpaid',moneyV4(18520),'employee payable','payable')}${kpi('Missing receipts','4','reimbursement blocked','file')}${kpi('Journal linkage','100%','approved claims','link')}</div>${card('Claims queue','Employee identity, itemised spend and control status',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Claim</th><th>Employee</th><th>Purpose</th><th>Submitted</th><th class="num">Amount</th><th>Receipts</th><th>Budget</th><th>Policy</th><th>Status</th></tr></thead><tbody>${claims.map(x=>`<tr data-action="claim-detail" data-id="${x.id}"><td class="link">${x.id}</td><td>${personV4(x.employee,'','sm')}</td><td>${x.purpose}</td><td>${x.submitted}</td><td class="num">${moneyV4(x.amount,x.currency)}</td><td>${x.receipts}</td><td>${x.budget}</td><td>${badge(x.policy)}</td><td>${badge(x.status)}</td></tr>`).join('')}</tbody></table></div>`)}`}

  const oldOverviewV4=pages.overview;
  pages.ledger=ledgerPageV4;pages.journals=journalsPageV4;pages.cash=cashPageV4;pages.receivables=receivablesPageV4;pages.payables=payablesPageV4;pages.inventory=inventoryPageV4;pages.assets=assetsPageV4;pages.reports=reportsPageV4;pages.access=accessPageV4;pages.approvals=approvalsPageV4;pages.expenses=expensesPageV4;
