  document.addEventListener('input',e=>{
    if(e.target.id==='engineSearchV4'){engineV4.search=e.target.value;clearTimeout(window.__engineSearchV4);window.__engineSearchV4=setTimeout(render,180)}
    if(e.target.classList.contains('manual-line-v4')){const i=Number(e.target.dataset.index),f=e.target.dataset.field;if(!manualDraftV4.lines[i])return;manualDraftV4.lines[i][f]=['debit','credit'].includes(f)?Number(e.target.value||0):e.target.value;clearTimeout(window.__manualRenderV4);window.__manualRenderV4=setTimeout(()=>{const active=document.activeElement?.dataset?.field;render();if(active){const next=$v4(`.manual-line-v4[data-index="${i}"][data-field="${active}"]`);next?.focus();next?.select?.()}},260)}
    if(['manualDescV4','manualRefV4','manualDateV4','manualRateV4'].includes(e.target.id)){const map={manualDescV4:'description',manualRefV4:'reference',manualDateV4:'date',manualRateV4:'rate'};manualDraftV4[map[e.target.id]]=e.target.id==='manualRateV4'?Number(e.target.value||0):e.target.value}
  }, __ac52Sig);
