  function enhanceV4(){
    const mark=$v4('.brand-mark');if(mark){mark.textContent='m';mark.setAttribute('aria-label','Matanho compact logo')}
    const avatar=$v4('.profile .avatar');if(avatar&&!avatar.querySelector('img'))avatar.innerHTML=`<img class="top-profile-v4" src="${photoFor('Tariro Moyo')}" alt="Tariro Moyo profile">`;
    const profile=$v4('.profile');if(profile){profile.dataset.action='profile-menu-v4';profile.setAttribute('role','button');profile.title='Open user profile and session controls'}
    $v4('.content')?.style.setProperty('overflow-y','auto');
  }
