function miniSpark(values,w=170,h=45){const max=Math.max(...values),min=Math.min(...values),range=max-min||1,pts=values.map((v,i)=>`${i*(w/(values.length-1))},${h-4-(v-min)/range*(h-8)}`).join(' ');return `<svg viewBox="0 0 ${w} ${h}" style="width:100%;height:45px"><polyline points="${pts}" fill="none" stroke="#1768ee" stroke-width="2.5"/><line x1="0" x2="${w}" y1="${h-4}" y2="${h-4}" stroke="var(--line)"/></svg>`}

