 document.querySelectorAll('img[alt*="profile"],.person-v4 img,.top-profile-v4').forEach(img=>{const alt=(img.alt||'').replace(/ profile$/i,'').trim();const row=img.closest('.person-v4');const name=alt||row?.querySelector('strong')?.textContent?.trim()||'Tariro Moyo';const src=v5Photo(name);if(img.src!==src)img.src=src;img.loading='eager';img.referrerPolicy='no-referrer'});
 const av=document.querySelector('.profile .avatar');if(av){const name=state.role==='CEO'?'Tinashe Matanho':'Tariro Moyo';let img=av.querySelector('img');if(!img){img=document.createElement('img');av.replaceChildren(img)}const src=v5Photo(name);if(img.src!==src)img.src=src;img.alt=`${name} profile`}
 const p=document.querySelector('.profile strong');if(p)p.textContent=state.role==='CEO'?'Tinashe Matanho':'Tariro Moyo';
