function installRatePill(){const top=document.querySelector('.topbar');if(!top||document.querySelector('#v5RatePill'))return;const live=top.querySelector('.live-pill');const el=document.createElement('button');el.className='v5-rate-pill';el.id='v5RatePill';el.dataset.action='v5-rate-detail';el.innerHTML=`<i class="dot"></i><div><strong>USD/ZWG <span id="v5RateValue">${v5Rates.avg.toFixed(4)}</span></strong><span id="v5RateDate">RBZ · ${v5Rates.date}</span></div>`;top.insertBefore(el,live)}

