function ageingBand8(due,outstanding){if(outstanding<=.001)return'Paid';const days=Math.floor((new Date('2026-08-01')-new Date(due))/86400000);return days<=0?'Current':days<=30?'1–30 days':days<=60?'31–60 days':days<=90?'61–90 days':'90+ days'}
function arAgeing8(){const bands={'Current':0,'1–30 days':0,'31–60 days':0,'61–90 days':0,'90+ days':0};S.invoices.forEach(x=>{const b=ageingBand8(x.due,x.outstanding);if(bands[b]!==undefined)bands[b]+=x.outstanding});return bands}
function apAgeing8(){const bands={'Current':0,'1–30 days':0,'31–60 days':0,'61–90 days':0,'90+ days':0};S.bills.forEach(x=>{const b=ageingBand8(x.due,x.outstanding);if(bands[b]!==undefined)bands[b]+=x.outstanding});return bands}
function miniAgeing8(bands){const max=Math.max(1,...Object.values(bands));return `<div style="display:grid;gap:8px">${Object.entries(bands).map(([k,v])=>`<div style="display:grid;grid-template-columns:78px 1fr 88px;gap:8px;align-items:center"><span style="font-size:10px;color:var(--muted)">${k}</span><div style="height:8px;background:var(--surface-2);border-radius:999px;overflow:hidden"><div style="height:100%;width:${Math.max(1,v/max*100)}%;background:${k==='90+ days'?'#d92d45':k==='61–90 days'?'#d9892d':k==='31–60 days'?'#f2ae28':'#087cff'};border-radius:999px"></div></div><strong style="font-size:10px;text-align:right">${money8(v)}</strong></div>`).join('')}</div>`}
function arTabBody8(){const tab=S.ui.arTab,age=arAgeing8();if(tab==='transactions'){const rows=S.invoices.map(x=>{const c=customer8(x.customerId);return `<tr data-action="v8-invoice-detail" data-id="${x.id}"><td class="v8-link">${x.id}</td><td data-action="v8-customer-detail" data-id="${c?.id}" class="v8-link">${esc8(c?.name)}</td><td>${date8(x.date)}</td><td>${date8(x.due)}</td><td>${esc8(x.project)}</td><td>${x.currency}</td><td class="num">${money8(x.total,x.currency)}</td><td class="num">${money8(x.outstanding,x.currency)}</td><td>${badge8(ageingBand8(x.due,x.outstanding))}</td><td>${badge8(x.status)}</td></tr>`}).join('');return panel8('Invoice and receipt register','Every invoice links to its automatic journal and receipt allocations',table8(['Invoice','Customer','Invoice date','Due date','Project / fund','Currency','Gross','Outstanding','Ageing','Status'],rows,'1120px'),btn8('Create invoice','v8-new-invoice','small primary')+btn8('Record receipt','v8-new-receipt-allocation','small'))}
 if(tab==='documents'){const rows=S.documents.filter(d=>/invoice/i.test(d.type)).map(d=>`<tr data-action="v8-document-preview" data-id="${d.id}"><td class="v8-link">${d.id}</td><td>${esc8(d.type)}</td><td>${esc8(d.record)}</td><td>${esc8(d.name)}</td><td>v${d.version}</td><td>${esc8(d.updated)}</td><td>${badge8(d.status)}</td><td>${btn8('Preview','v8-document-preview','small',d.id)} ${btn8('Email','v8-email-document','small soft',d.id)}</td></tr>`).join('');return panel8('Receivable documents','Invoices, credit notes, receipts and collection correspondence',table8(['Document','Type','Record','Name','Version','Updated','Status','Actions'],rows||'<tr><td colspan="8">No documents.</td></tr>','900px'),btn8('Document vault','v8-go-page','small','vault'))}
 if(tab==='communications'){const rows=[...S.communications.filter(x=>x.type==='Customer'),{id:'COM-AR-001',date:'2026-07-31',counterparty:'Mambo Foods',channel:'Email',subject:'Overdue invoice reminder',owner:'Rudo Kaseke',status:'Delivered'},{id:'COM-AR-002',date:'2026-07-29',counterparty:'Mukuru Microfinance',channel:'Call',subject:'Promise to pay confirmed',owner:'Nyasha Dube',status:'Recorded'}].map(x=>`<tr><td>${esc8(x.date||date8(x.time))}</td><td>${esc8(x.counterparty)}</td><td>${esc8(x.channel)}</td><td>${esc8(x.subject)}</td><td>${esc8(x.owner)}</td><td>${badge8(x.status)}</td></tr>`).join('');return panel8('Collection communications','A complete, time-stamped customer engagement record',table8(['Date','Customer','Channel','Subject / outcome','Owner','Status'],rows,'820px'),btn8('New communication','v8-new-ar-communication','small primary'))}
 if(tab==='audit'){const rows=S.audit.filter(x=>/INVOICE|RECEIPT|CUSTOMER/i.test(x.action)).map(x=>`<tr><td>${new Date(x.time).toLocaleString()}</td><td>${esc8(x.user)}</td><td>${esc8(x.action)}</td><td class="v8-link">${esc8(x.record)}</td><td>${esc8(x.detail)}</td><td>${badge8(x.status)}</td></tr>`).join('');return panel8('Receivables audit trail','User, system and integration events cannot be edited',table8(['Timestamp','Actor','Event','Record','Details','Status'],rows||'<tr><td colspan="6">No receivables events yet.</td></tr>','920px'))}
 const customerRows=S.customers.map(c=>{const inv=S.invoices.filter(x=>x.customerId===c.id),out=inv.reduce((s,x)=>s+x.outstanding,0),over=inv.filter(x=>new Date(x.due)<new Date('2026-08-01')&&x.outstanding>0).reduce((s,x)=>s+x.outstanding,0);return `<tr data-action="v8-customer-detail" data-id="${c.id}"><td><div class="v8-person" style="display:flex;align-items:center;gap:8px"><img src="${photo8(c.owner)}" alt="${esc8(c.owner)}"><div><strong>${esc8(c.name)}</strong><span class="v8-sub">${esc8(c.id)} · ${esc8(c.email)}</span></div></div></td><td>${esc8(c.owner)}</td><td>${c.currency}</td><td class="num">${money8(c.limit,c.currency)}</td><td class="num">${money8(out,c.currency)}</td><td class="num">${money8(over,c.currency)}</td><td>${badge8(c.risk)}</td><td>${badge8(c.status)}</td></tr>`}).join('');return `<div class="v8-split"><div>${panel8('Customer portfolio','Credit limits, outstanding balances and collection ownership',table8(['Customer','Account owner','Currency','Credit limit','Outstanding','Overdue','Risk','Status'],customerRows,'980px'),btn8('Add customer','v8-add-customer','small soft'))}</div><aside class="v8-stack">${panel8('Ageing of outstanding invoices','Click through to the underlying customer and invoices',miniAgeing8(age),btn8('Open transactions','v8-ar-tab','small','transactions'))}${panel8('Collection priorities','Risk-ranked actions and promises to pay',`<div class="status-line"><div><strong>Mambo Foods</strong><span>$49,000 overdue · last reminder 31 Jul</span></div>${badge8('Overdue')}</div><div class="status-line"><div><strong>Mukuru Microfinance</strong><span>$56,000 outstanding · promise due 05 Aug</span></div>${badge8('Review')}</div><div class="status-line"><div><strong>Horizon Mining</strong><span>$84,500 current · no dispute</span></div>${badge8('Current')}</div>`)}</aside></div>`}
function receivablesPage8(){const age=arAgeing8(),overdue=Object.entries(age).filter(([k])=>k!=='Current').reduce((s,[,v])=>s+v,0),dso=38;return `<div class="v8-page">${head8('Customer sub-ledger','Accounts Receivable & Collections','Create invoices, automatically post receivable, revenue and VAT journals, allocate receipts and preserve a complete customer-to-ledger audit trail.',btn8('New invoice','v8-new-invoice','primary')+btn8('Record receipt','v8-new-receipt-allocation','soft')+btn8('Send statements','v8-send-statements'))}<div class="v8-filterbar">${field8('Entity / fund',select8('v8ArEntity',['All entities','Matanho Capital Partners','Growth Fund I','MFI Entity'],'All entities'))}${field8('Customer',select8('v8ArCustomer',[['all','All customers'],...S.customers.map(c=>[c.id,c.name])],'all'))}${field8('Ageing bucket',select8('v8ArAge',['All ageing','Current','1–30 days','31–60 days','61–90 days','90+ days'],'All ageing'))}${field8('Currency',select8('v8ArCurrency',['All currencies','USD','ZWG'],'All currencies'))}${field8('Owner',select8('v8ArOwner',['All owners','Nyasha Dube','Rudo Kaseke','Tariro Moyo'],'All owners'))}${field8('Search',input8('v8ArSearch','','search','Customer, invoice, project or journal'))}</div><div class="v8-grid v8-kpis">${kpi8('Total outstanding',money8(outstandingAR8()),`${S.invoices.filter(x=>x.outstanding>0).length} open invoices`,'Live')}${kpi8('Overdue value',money8(overdue),'Past due at 01 Aug 2026','Collections')}${kpi8('DSO',`${dso} days`,'Rolling 90-day average','Target 35')}${kpi8('Receipts this period',money8(S.cashbook.filter(x=>x.type==='Receipt').reduce((s,x)=>s+x.baseAmount,0)),'Allocated to invoices','Jul 2026')}${kpi8('Credit utilisation','42%','Across approved limits','Controlled')}${kpi8('Disputes','1','Open commercial dispute','Review')}</div><div class="v8-tabs">${[['overview','Overview'],['transactions','Transactions'],['documents','Documents'],['communications','Communications'],['audit','Audit trail']].map(x=>`<button class="v8-tab ${S.ui.arTab===x[0]?'active':''}" data-action="v8-ar-tab" data-id="${x[0]}">${x[1]}</button>`).join('')}</div><div id="v8ArBody">${arTabBody8()}</div></div>`}
function invoiceModal8(){openModal('Create customer invoice','Business document entry with automatic receivable, revenue and VAT journal generation',`<div class="v8-filterbar" style="grid-template-columns:repeat(3,minmax(0,1fr))">${field8('Customer',select8('v8InvCustomer',S.customers.map(c=>[c.id,c.name]),S.customers[0].id))}${field8('Invoice date',input8('v8InvDate',new Date().toISOString().slice(0,10),'date'))}${field8('Due date',input8('v8InvDue','2026-08-31','date'))}${field8('Currency',select8('v8InvCurrency',['USD','ZWG','ZAR'],'USD'))}${field8('Rate to USD',input8('v8InvRate','1','number','','step="0.0001"'))}${field8('Project / fund',select8('v8InvProject',['Corporate','Growth Fund I','MFI Portfolio Audit','Pension Liquidity'],'Corporate'))}${field8('Revenue account',select8('v8InvRevenue',S.accounts.filter(a=>a.posting&&['Revenue','Other Income'].includes(a.type)).map(a=>[a.code,`${a.code} · ${a.name}`]),'4100'))}${field8('Net amount',input8('v8InvNet','0','number','','min="0" step="0.01"'))}${field8('VAT treatment',select8('v8InvVat',[['0.15','VAT 15%'],['0','Zero rated / exempt']],'0.15'))}<div class="v8-field" style="grid-column:1/-1"><label>Invoice description</label><textarea class="v8-textarea" id="v8InvDescription">Professional services and implementation support</textarea></div></div><div class="v8-split-even">${panel8('Expected accounting','The system posts this journal atomically when the invoice is approved',`<div class="v8-callout"><strong>Debit</strong>Trade receivables control for the gross invoice value.</div><div class="v8-callout" style="margin-top:7px"><strong>Credit</strong>Selected revenue account and output VAT where applicable.</div>`)}${panel8('Document controls','Invoice generation and distribution',`<div class="v8-validation-list"><div class="v8-validation">Premium letterhead and controlled invoice number</div><div class="v8-validation">Customer tax, currency and payment terms inherited</div><div class="v8-validation">PDF preview available before email delivery</div><div class="v8-validation">Journal and document linked bidirectionally</div></div>`)}</div>`,btn8('Cancel','v8-close-modal')+btn8('Preview invoice','v8-preview-new-invoice','soft')+btn8('Review & create','v8-review-invoice','primary'),true)}
function receiptAllocationModal8(){const open=S.invoices.filter(x=>x.outstanding>0);openModal('Record and allocate customer receipt','Select the invoice, bank and allocation amount. Posting debits bank and credits receivables control.',`<div class="v8-filterbar" style="grid-template-columns:repeat(3,minmax(0,1fr))">${field8('Open invoice',select8('v8ReceiptInvoice',open.map(x=>[x.id,`${x.id} · ${customer8(x.customerId)?.name} · ${money8(x.outstanding,x.currency)}`]),open[0]?.id||''))}${field8('Receiving bank',select8('v8ReceiptBank',S.banks.map(b=>[b.id,b.name]),S.banks[0].id))}${field8('Receipt date',input8('v8ReceiptDate',new Date().toISOString().slice(0,10),'date'))}${field8('Reference',input8('v8ReceiptRef',`RCPT-${String(S.seq.cash+1).padStart(4,'0')}`))}${field8('Amount',input8('v8ReceiptAmount',open[0]?.outstanding||0,'number','','min="0" step="0.01"'))}${field8('Rate to USD',input8('v8ReceiptRate','1','number','','step="0.0001"'))}</div><div class="v8-callout"><strong>Allocation result</strong>The invoice balance and status update only after the balanced cash and receivables journal posts successfully.</div>`,btn8('Cancel','v8-close-modal')+btn8('Review & allocate','v8-review-receipt','primary'),true)}
function customerDrawerBody8(c){const inv=S.invoices.filter(x=>x.customerId===c.id),out=inv.reduce((s,x)=>s+x.outstanding,0),tab=S.ui.customerTab;let body='';if(tab==='transactions')body=table8(['Invoice','Date','Due','Project','Gross','Outstanding','Status'],inv.map(x=>`<tr data-action="v8-invoice-detail" data-id="${x.id}"><td class="v8-link">${x.id}</td><td>${date8(x.date)}</td><td>${date8(x.due)}</td><td>${esc8(x.project)}</td><td>${money8(x.total,x.currency)}</td><td>${money8(x.outstanding,x.currency)}</td><td>${badge8(x.status)}</td></tr>`).join('')||'<tr><td colspan="7">No transactions.</td></tr>','760px');else if(tab==='documents')body=S.documents.filter(d=>inv.some(x=>x.id===d.record)).map(d=>`<div class="status-line" data-action="v8-document-preview" data-id="${d.id}" style="cursor:pointer"><div><strong>${esc8(d.name)}</strong><span>${d.type} · v${d.version} · ${d.updated}</span></div>${badge8(d.status)}</div>`).join('')||'<div class="v8-callout">No linked documents.</div>';else if(tab==='communications')body=`<div class="status-line"><div><strong>Overdue reminder delivered</strong><span>31 Jul 2026 · Email · Rudo Kaseke</span></div>${badge8('Delivered')}</div><div class="status-line"><div><strong>Promise to pay recorded</strong><span>29 Jul 2026 · Call · Nyasha Dube</span></div>${badge8('Recorded')}</div>`;else if(tab==='audit')body=S.audit.filter(x=>x.record===c.id||inv.some(i=>i.id===x.record)).map(x=>`<div class="status-line"><div><strong>${esc8(x.action)}</strong><span>${new Date(x.time).toLocaleString()} · ${esc8(x.user)} · ${esc8(x.detail)}</span></div>${badge8(x.status)}</div>`).join('')||'<div class="v8-callout">No audit events.</div>';else body=`<div class="v8-split-even">${panel8('Customer profile','Commercial and credit master data',`<div class="v8-facts"><div class="v8-fact"><span>Email</span><strong>${esc8(c.email)}</strong></div><div class="v8-fact"><span>Phone</span><strong>${esc8(c.phone)}</strong></div><div class="v8-fact"><span>Terms</span><strong>${c.terms} days</strong></div><div class="v8-fact"><span>Currency</span><strong>${c.currency}</strong></div><div class="v8-fact"><span>Credit limit</span><strong>${money8(c.limit,c.currency)}</strong></div><div class="v8-fact"><span>Outstanding</span><strong>${money8(out,c.currency)}</strong></div><div class="v8-fact"><span>Risk</span><strong>${c.risk}</strong></div><div class="v8-fact"><span>Status</span><strong>${c.status}</strong></div></div>`)}${panel8('Account controls','Customer-specific collection and posting controls',`<div class="v8-validation-list"><div class="v8-validation">Debtors control account: 1200</div><div class="v8-validation">Invoice journal generation: automatic</div><div class="v8-validation">Receipt allocation: invoice-specific</div><div class="v8-validation ${out>c.limit?'bad':''}">Credit utilisation: ${Math.round(out/c.limit*100)}%</div></div>`)}</div>`;return `<div class="v8-drawer-hero"><div class="v8-drawer-person"><img src="${photo8(c.owner)}" alt="${esc8(c.owner)}"><div><div class="v8-eyebrow">Customer sub-ledger</div><h2>${esc8(c.name)}</h2><p>${esc8(c.id)} · Account owner ${esc8(c.owner)}</p></div></div>${badge8(c.status)}</div><div class="v8-facts" style="margin-bottom:12px"><div class="v8-fact"><span>Outstanding</span><strong>${money8(out,c.currency)}</strong></div><div class="v8-fact"><span>Open invoices</span><strong>${inv.filter(x=>x.outstanding>0).length}</strong></div><div class="v8-fact"><span>Credit utilisation</span><strong>${Math.round(out/c.limit*100)}%</strong></div><div class="v8-fact"><span>Risk</span><strong>${c.risk}</strong></div></div><div class="v8-tabs">${[['overview','Overview'],['transactions','Transactions'],['documents','Documents'],['communications','Communications'],['audit','Audit trail']].map(x=>`<button class="v8-tab ${tab===x[0]?'active':''}" data-action="v8-customer-tab" data-id="${x[0]}">${x[1]}</button>`).join('')}</div><div id="v8CustomerDrawerBody">${body}</div>`}
function openCustomer8(id){const c=customer8(id);if(!c)return;S.ui.currentCustomer=id;save8();openDrawer(c.name,`${c.id} · governed customer record`,customerDrawerBody8(c),btn8('Edit profile','v8-edit-customer','',c.id)+btn8('Create invoice','v8-new-invoice','primary',c.id));setDrawer8('wide')}
function editCustomerModal8(id){const c=customer8(id);if(!c)return;openModal('Edit customer profile','Permitted commercial fields are versioned; control-account history is never rewritten',`<div class="v8-filterbar" style="grid-template-columns:repeat(2,minmax(0,1fr))">${field8('Customer name',input8('v8EditCustomerName',c.name))}${field8('Email',input8('v8EditCustomerEmail',c.email,'email'))}${field8('Phone',input8('v8EditCustomerPhone',c.phone))}${field8('Payment terms',input8('v8EditCustomerTerms',c.terms,'number'))}${field8('Credit limit',input8('v8EditCustomerLimit',c.limit,'number'))}${field8('Risk rating',select8('v8EditCustomerRisk',['Low','Medium','High'],c.risk))}</div>`,btn8('Cancel','v8-close-modal')+btn8('Review changes','v8-review-edit-customer','primary',id),true)}

function apTabBody8(){const tab=S.ui.apTab,age=apAgeing8();if(tab==='transactions'){const rows=S.bills.map(x=>{const v=vendor8(x.vendorId);return `<tr data-action="v8-bill-detail" data-id="${x.id}"><td class="v8-link">${x.id}</td><td data-action="v8-vendor-detail" data-id="${v?.id}" class="v8-link">${esc8(v?.name)}</td><td>${esc8(x.invoice)}</td><td>${date8(x.date)}</td><td>${date8(x.due)}</td><td>${esc8(x.project)}</td><td class="num">${money8(x.total,x.currency)}</td><td class="num">${money8(x.outstanding,x.currency)}</td><td>${badge8(x.match)}</td><td>${badge8(x.status)}</td></tr>`}).join('');return panel8('Supplier bill and payment register','Bills create expense/VAT/payable journals; payments clear the payable against bank',table8(['Bill','Vendor','Vendor invoice','Bill date','Due date','Project / fund','Gross','Outstanding','Match','Status'],rows,'1150px'),btn8('Create supplier bill','v8-new-bill','small primary')+btn8('Pay supplier','v8-pay-bill','small'))}
 if(tab==='documents'){const rows=S.documents.filter(d=>/supplier/i.test(d.type)).map(d=>`<tr data-action="v8-document-preview" data-id="${d.id}"><td class="v8-link">${d.id}</td><td>${d.type}</td><td>${d.record}</td><td>${d.name}</td><td>v${d.version}</td><td>${d.updated}</td><td>${badge8(d.status)}</td></tr>`).join('');return panel8('Payables documents','Supplier invoices, purchase evidence, approvals and payment confirmations',table8(['Document','Type','Record','Name','Version','Updated','Status'],rows||'<tr><td colspan="7">No documents.</td></tr>','820px'))}
 if(tab==='communications')return panel8('Vendor communications','Payment advice, query resolution and compliance outreach',table8(['Date','Vendor','Channel','Subject / outcome','Owner','Status'],`<tr><td>31 Jul 2026</td><td>CBZ Custody</td><td>Email</td><td>Payment advice PAY-001</td><td>Chipo Ndlovu</td><td>${badge8('Delivered')}</td></tr><tr><td>29 Jul 2026</td><td>Dube & Partners</td><td>Portal</td><td>Rate variance query</td><td>Farai Mapfumo</td><td>${badge8('Review')}</td></tr>`,'820px'),btn8('New communication','v8-new-ap-communication','small primary'))
 if(tab==='audit'){const rows=S.audit.filter(x=>/BILL|SUPPLIER|VENDOR|PAYMENT/i.test(x.action)).map(x=>`<tr><td>${new Date(x.time).toLocaleString()}</td><td>${esc8(x.user)}</td><td>${esc8(x.action)}</td><td>${esc8(x.record)}</td><td>${esc8(x.detail)}</td><td>${badge8(x.status)}</td></tr>`).join('');return panel8('Payables audit trail','Immutable vendor, bill, payment and approval events',table8(['Timestamp','Actor','Event','Record','Details','Status'],rows||'<tr><td colspan="6">No payables events yet.</td></tr>','920px'))}
 const vendorRows=S.vendors.map(v=>{const bills=S.bills.filter(x=>x.vendorId===v.id),out=bills.reduce((s,x)=>s+x.outstanding,0),due=bills.filter(x=>new Date(x.due)<=new Date('2026-08-07')&&x.outstanding>0).reduce((s,x)=>s+x.outstanding,0);return `<tr data-action="v8-vendor-detail" data-id="${v.id}"><td><div class="v8-person" style="display:flex;align-items:center;gap:8px"><img src="${photo8(v.owner)}" alt="${esc8(v.owner)}"><div><strong>${esc8(v.name)}</strong><span class="v8-sub">${v.id} · ${esc8(v.email)}</span></div></div></td><td>${esc8(v.owner)}</td><td>${v.currency}</td><td>${v.terms} days</td><td class="num">${money8(out,v.currency)}</td><td class="num">${money8(due,v.currency)}</td><td>${badge8(v.risk)}</td><td>${badge8(v.status)}</td></tr>`}).join('');return `<div class="v8-split"><div>${panel8('Vendor registry','Payment eligibility, ownership, tax, bank and balance context',table8(['Vendor','Owner','Currency','Terms','Outstanding','Due next 7 days','Risk','Status'],vendorRows,'980px'),btn8('Add vendor','v8-add-vendor','small soft'))}</div><aside class="v8-stack">${panel8('Payables ageing','Outstanding supplier obligations by age',miniAgeing8(age),btn8('Open transactions','v8-ap-tab','small','transactions'))}${panel8('Payment control queue','Bills requiring matching, funding or approval',`<div class="status-line"><div><strong>Dube & Partners</strong><span>Rate variance · $28,476</span></div>${badge8('Exception')}</div><div class="status-line"><div><strong>Westend Properties</strong><span>Due 01 Aug · $12,500</span></div>${badge8('Due')}</div><div class="status-line"><div><strong>CBZ Custody</strong><span>Approved and scheduled</span></div>${badge8('Approved')}</div>`)}</aside></div>`}
function payablesPage8(){const age=apAgeing8(),due7=S.bills.filter(x=>new Date(x.due)<=new Date('2026-08-07')&&x.outstanding>0).reduce((s,x)=>s+x.outstanding,0);return `<div class="v8-page">${head8('Supplier sub-ledger','Accounts Payable & Vendor Control','Register supplier bills, validate tax and three-way evidence, approve payments and preserve a complete vendor-to-ledger audit trail.',btn8('New supplier bill','v8-new-bill','primary')+btn8('Pay supplier','v8-pay-bill','soft')+btn8('Payment run','v8-payment-run'))}<div class="v8-filterbar">${field8('Entity / fund',select8('v8ApEntity',['All entities','Matanho Capital Partners','Growth Fund I','MFI Entity'],'All entities'))}${field8('Vendor',select8('v8ApVendor',[['all','All vendors'],...S.vendors.map(v=>[v.id,v.name])],'all'))}${field8('Ageing bucket',select8('v8ApAge',['All ageing','Current','1–30 days','31–60 days','61–90 days','90+ days'],'All ageing'))}${field8('Currency',select8('v8ApCurrency',['All currencies','USD','ZWG'],'All currencies'))}${field8('Match status',select8('v8ApMatch',['All matches','Matched','Rate variance','Contract match','Direct expense'],'All matches'))}${field8('Search',input8('v8ApSearch','','search','Vendor, bill, project or journal'))}</div><div class="v8-grid v8-kpis">${kpi8('Total outstanding',money8(outstandingAP8()),`${S.bills.filter(x=>x.outstanding>0).length} open bills`,'Live')}${kpi8('Due next 7 days',money8(due7),'Funding required','Liquidity')}${kpi8('Approved for payment',money8(S.bills.filter(x=>x.status==='Approved').reduce((s,x)=>s+x.outstanding,0)),'Payment-ready population','Controlled')}${kpi8('Match exceptions',String(S.bills.filter(x=>/Exception|variance/i.test(`${x.status} ${x.match}`)).length),'PO, receipt, rate or tax','Review')}${kpi8('Average payment days','19 days','Rolling 90-day result','Target 21')}${kpi8('Payment holds','1','Master data or compliance','Controlled')}</div><div class="v8-tabs">${[['overview','Overview'],['transactions','Transactions'],['documents','Documents'],['communications','Communications'],['audit','Audit trail']].map(x=>`<button class="v8-tab ${S.ui.apTab===x[0]?'active':''}" data-action="v8-ap-tab" data-id="${x[0]}">${x[1]}</button>`).join('')}</div><div id="v8ApBody">${apTabBody8()}</div></div>`}
function billModal8(){openModal('Create supplier bill','Supplier invoice entry with recoverable VAT, expense allocation and automatic creditors journal',`<div class="v8-filterbar" style="grid-template-columns:repeat(3,minmax(0,1fr))">${field8('Vendor',select8('v8BillVendor',S.vendors.map(v=>[v.id,v.name]),S.vendors[0].id))}${field8('Vendor invoice number',input8('v8BillVendorInvoice','SUP-INV-'))}${field8('Bill date',input8('v8BillDate',new Date().toISOString().slice(0,10),'date'))}${field8('Due date',input8('v8BillDue','2026-08-31','date'))}${field8('Currency',select8('v8BillCurrency',['USD','ZWG','ZAR'],'USD'))}${field8('Rate to USD',input8('v8BillRate','1','number','','step="0.0001"'))}${field8('Expense / asset account',select8('v8BillExpense',S.accounts.filter(a=>a.posting&&!a.control&&['Expense','Current Asset','Non-current Asset'].includes(a.type)).map(a=>[a.code,`${a.code} · ${a.name}`]),'5140'))}${field8('Net amount',input8('v8BillNet','0','number','','min="0" step="0.01"'))}${field8('VAT treatment',select8('v8BillVat',[['0.15','VAT 15% recoverable'],['0','No VAT / exempt']],'0.15'))}${field8('Project / fund',select8('v8BillProject',['Corporate','Growth Fund I','MFI Portfolio','Pension Liquidity','Technology'],'Corporate'))}${field8('Match basis',select8('v8BillMatch',['Three-way matched','Contract match','Direct expense','Rate variance'],'Direct expense'))}<div class="v8-field" style="grid-column:1/-1"><label>Description</label><textarea class="v8-textarea" id="v8BillDescription">Professional services and supplier charges</textarea></div></div><div class="v8-callout"><strong>Expected journal</strong>Debit the selected expense or asset, debit recoverable VAT where applicable, and credit trade payables control for the gross bill value.</div>`,btn8('Cancel','v8-close-modal')+btn8('Review & create','v8-review-bill','primary'),true)}
function paymentModal8(){const open=S.bills.filter(x=>x.outstanding>0);openModal('Pay supplier bill','Allocate a bank payment to a selected approved supplier bill',`<div class="v8-filterbar" style="grid-template-columns:repeat(3,minmax(0,1fr))">${field8('Open supplier bill',select8('v8PayBill',open.map(x=>[x.id,`${x.id} · ${vendor8(x.vendorId)?.name} · ${money8(x.outstanding,x.currency)}`]),open[0]?.id||''))}${field8('Paying bank',select8('v8PayBank',S.banks.map(b=>[b.id,b.name]),S.banks[0].id))}${field8('Payment date',input8('v8PayDate',new Date().toISOString().slice(0,10),'date'))}${field8('Payment reference',input8('v8PayRef',`PAY-${String(S.seq.cash+1).padStart(4,'0')}`))}${field8('Amount',input8('v8PayAmount',open[0]?.outstanding||0,'number','','min="0" step="0.01"'))}${field8('Rate to USD',input8('v8PayRate','1','number','','step="0.0001"'))}</div><div class="v8-callout warn"><strong>Approval and bank result</strong>The payable will be debited and the selected bank credited. Amounts above the configured authority limit may be submitted to a payment checker instead of posting immediately.</div>`,btn8('Cancel','v8-close-modal')+btn8('Review payment','v8-review-payment','primary'),true)}
function vendorDrawerBody8(v){const bills=S.bills.filter(x=>x.vendorId===v.id),out=bills.reduce((s,x)=>s+x.outstanding,0),tab=S.ui.vendorTab;let body='';if(tab==='transactions')body=table8(['Bill','Vendor invoice','Date','Due','Project','Gross','Outstanding','Match','Status'],bills.map(x=>`<tr data-action="v8-bill-detail" data-id="${x.id}"><td class="v8-link">${x.id}</td><td>${esc8(x.invoice)}</td><td>${date8(x.date)}</td><td>${date8(x.due)}</td><td>${esc8(x.project)}</td><td>${money8(x.total,x.currency)}</td><td>${money8(x.outstanding,x.currency)}</td><td>${badge8(x.match)}</td><td>${badge8(x.status)}</td></tr>`).join('')||'<tr><td colspan="9">No transactions.</td></tr>','820px');else if(tab==='documents')body=`<div class="status-line"><div><strong>Tax clearance certificate</strong><span>Verified · expires 31 Dec 2026</span></div>${badge8('Verified')}</div><div class="status-line"><div><strong>Bank ownership confirmation</strong><span>${esc8(v.bank)} · sensitive field</span></div>${badge8('Verified')}</div><div class="status-line"><div><strong>Supplier agreement</strong><span>Version 3 · approved by Legal</span></div>${badge8('Approved')}</div>`;else if(tab==='communications')body=`<div class="status-line"><div><strong>Payment advice delivered</strong><span>31 Jul 2026 · secure email</span></div>${badge8('Delivered')}</div><div class="status-line"><div><strong>Invoice query opened</strong><span>29 Jul 2026 · Accounts Payable</span></div>${badge8('Review')}</div>`;else if(tab==='audit')body=S.audit.filter(x=>x.record===v.id||bills.some(b=>b.id===x.record)).map(x=>`<div class="status-line"><div><strong>${esc8(x.action)}</strong><span>${new Date(x.time).toLocaleString()} · ${esc8(x.user)} · ${esc8(x.detail)}</span></div>${badge8(x.status)}</div>`).join('')||'<div class="v8-callout">No audit events.</div>';else body=`<div class="v8-split-even">${panel8('Vendor profile','Editable commercial master data',`<div class="v8-facts"><div class="v8-fact"><span>Email</span><strong>${esc8(v.email)}</strong></div><div class="v8-fact"><span>Phone</span><strong>${esc8(v.phone)}</strong></div><div class="v8-fact"><span>Terms</span><strong>${v.terms} days</strong></div><div class="v8-fact"><span>Currency</span><strong>${v.currency}</strong></div><div class="v8-fact"><span>Tax</span><strong>${esc8(v.tax)}</strong></div><div class="v8-fact"><span>Bank</span><strong>${esc8(v.bank)}</strong></div><div class="v8-fact"><span>Risk</span><strong>${v.risk}</strong></div><div class="v8-fact"><span>Outstanding</span><strong>${money8(out,v.currency)}</strong></div></div>`)}${panel8('Payment eligibility','Master-data and segregation controls',`<div class="v8-validation-list"><div class="v8-validation">Creditors control account: 2000</div><div class="v8-validation">Tax and bank ownership evidence verified</div><div class="v8-validation">Bank changes require independent checker</div><div class="v8-validation ${/eligible|active/i.test(v.status)?'':'warn'}">Current status: ${esc8(v.status)}</div></div>`)}</div>`;return `<div class="v8-drawer-hero"><div class="v8-drawer-person"><img src="${photo8(v.owner)}" alt="${esc8(v.owner)}"><div><div class="v8-eyebrow">Governed vendor master</div><h2>${esc8(v.name)}</h2><p>${v.id} · Owner ${esc8(v.owner)}</p></div></div>${badge8(v.status)}</div><div class="v8-facts" style="margin-bottom:12px"><div class="v8-fact"><span>Outstanding</span><strong>${money8(out,v.currency)}</strong></div><div class="v8-fact"><span>Open bills</span><strong>${bills.filter(x=>x.outstanding>0).length}</strong></div><div class="v8-fact"><span>Payment terms</span><strong>${v.terms} days</strong></div><div class="v8-fact"><span>Risk</span><strong>${v.risk}</strong></div></div><div class="v8-tabs">${[['overview','Overview'],['transactions','Transactions'],['documents','Documents'],['communications','Communications'],['audit','Audit trail']].map(x=>`<button class="v8-tab ${tab===x[0]?'active':''}" data-action="v8-vendor-tab" data-id="${x[0]}">${x[1]}</button>`).join('')}</div><div id="v8VendorDrawerBody">${body}</div>`}
function openVendor8(id){const v=vendor8(id);if(!v)return;S.ui.currentVendor=id;save8();openDrawer(v.name,`${v.id} · vendor profile, transactions and evidence`,vendorDrawerBody8(v),btn8('Edit permitted fields','v8-edit-vendor','',v.id)+btn8('Create supplier bill','v8-new-bill','primary',v.id));setDrawer8('wide')}
function editVendorModal8(id){const v=vendor8(id);if(!v)return;openModal('Edit vendor profile','Commercial fields are editable. Bank details remain protected and route through maker-checker.',`<div class="v8-filterbar" style="grid-template-columns:repeat(2,minmax(0,1fr))">${field8('Vendor name',input8('v8EditVendorName',v.name))}${field8('Email',input8('v8EditVendorEmail',v.email,'email'))}${field8('Phone',input8('v8EditVendorPhone',v.phone))}${field8('Payment terms',input8('v8EditVendorTerms',v.terms,'number'))}${field8('Default currency',select8('v8EditVendorCurrency',['USD','ZWG','ZAR'],v.currency))}${field8('Risk rating',select8('v8EditVendorRisk',['Low','Medium','High'],v.risk))}${field8('Tax identifier',input8('v8EditVendorTax',v.tax))}${field8('Bank details',input8('v8EditVendorBank',v.bank,'text','','disabled'))}</div><div class="v8-callout warn"><strong>Sensitive field protection</strong>Changing vendor bank details requires a separate controlled request, document evidence and an independent checker.</div>`,btn8('Cancel','v8-close-modal')+btn8('Review profile changes','v8-review-edit-vendor','primary',id),true)}

/* --------------------------------------------------------------------------
   Inventory, timesheets, recurring automation, CoA and approvals
   -------------------------------------------------------------------------- */
function inventoryPage8(){const total=S.inventory.reduce((s,x)=>s+x.qty*x.unitCost,0),review=S.inventory.filter(x=>x.status==='Review').length,rows=S.inventory.map(x=>`<tr data-action="v8-inventory-detail" data-id="${x.sku}"><td class="v8-link">${x.sku}</td><td>${esc8(x.name)}</td><td>${esc8(x.category)}</td><td>${esc8(x.warehouse)}</td><td class="num">${x.qty.toLocaleString()}</td><td class="num">${money8(x.unitCost)}</td><td class="num">${money8(x.qty*x.unitCost)}</td><td>${badge8(x.status)}</td></tr>`).join('');return `<div class="v8-page">${head8('Perpetual inventory','Inventory Valuation & Controls','Quantity movements, cost layers, physical counts and accounting adjustments remain synchronised with inventory asset and cost-of-sales journals.',btn8('Stock adjustment','v8-stock-adjustment','primary')+btn8('New stock count','v8-stock-count','soft')+btn8('Valuation report','v8-preview-inventory-report'))}<div class="v8-filterbar">${field8('Warehouse',select8('v8InvWarehouse',['All warehouses','Harare Main','Bulawayo','Mutare'],'All warehouses'))}${field8('Category',select8('v8InvCategory',['All categories','Technology','Tyres','Stationery','Workshop parts'],'All categories'))}${field8('Valuation basis',select8('v8InvBasis',['Weighted average','FIFO','Standard cost'],'Weighted average'))}${field8('Status',select8('v8InvStatus',['All statuses','Controlled','Review'],'All statuses'))}${field8('Period',select8('v8InvPeriod',['Jul 2026','Aug 2026','Custom'],'Jul 2026'))}${field8('Search',input8('v8InvSearch','','search','SKU, item or warehouse'))}</div><div class="v8-grid v8-kpis">${kpi8('Inventory carrying value',money8(total),'Weighted-average cost','Live')}${kpi8('Active SKUs',String(S.inventory.length),'Across three warehouses','Controlled')}${kpi8('Units on hand',S.inventory.reduce((s,x)=>s+x.qty,0).toLocaleString(),'Perpetual quantity','Live')}${kpi8('Count exceptions',String(review),'Physical count review','Attention')}${kpi8('Obsolete stock',money8(1426),'Policy-based provision','Review')}${kpi8('Inventory GL',money8(accountDisplayBalance8('1300')),'Account 1300','Reconciled')}</div><div class="v8-split"><div>${panel8('Inventory register','Select any item for movement, valuation and adjustment history',table8(['SKU','Item','Category','Warehouse','Quantity','Unit cost','Carrying value','Status'],rows,'900px'),btn8('Export register','v8-export','small'))}</div><aside class="v8-stack">${panel8('Valuation reconciliation','Inventory sub-ledger to control account',`<div class="v8-facts"><div class="v8-fact"><span>Sub-ledger value</span><strong>${money8(total)}</strong></div><div class="v8-fact"><span>GL control balance</span><strong>${money8(accountDisplayBalance8('1300'))}</strong></div><div class="v8-fact"><span>Difference</span><strong>${money8(total-accountDisplayBalance8('1300'))}</strong></div><div class="v8-fact"><span>Method</span><strong>Weighted average</strong></div></div><div class="v8-callout ${Math.abs(total-accountDisplayBalance8('1300'))>.01?'warn':''}" style="margin-top:10px"><strong>Control conclusion</strong>Quantity and valuation changes must generate or reference balanced journals before the period can close.</div>`)}${panel8('Stock control queue','Count, damage, loss and obsolescence actions',`<div class="status-line"><div><strong>Legacy printer toner</strong><span>Slow-moving stock · 31 units</span></div>${badge8('Review')}</div><div class="status-line"><div><strong>Harare cycle count</strong><span>Due 03 Aug 2026 · owner Nigel Moyo</span></div>${badge8('Pending')}</div><div class="status-line"><div><strong>Cost layer validation</strong><span>All July receipts costed</span></div>${badge8('Complete')}</div>`)}</aside></div></div>`}
function stockAdjustmentModal8(sku=S.inventory[0]?.sku){const item=S.inventory.find(x=>x.sku===sku)||S.inventory[0];openModal('Stock adjustment','Granular quantity, valuation, reason and evidence capture with automatic inventory journal generation',`<div class="v8-filterbar" style="grid-template-columns:repeat(3,minmax(0,1fr))">${field8('Inventory item',select8('v8StockSku',S.inventory.map(x=>[x.sku,`${x.sku} · ${x.name}`]),item.sku))}${field8('Warehouse',select8('v8StockWarehouse',['Harare Main','Bulawayo','Mutare'],item.warehouse))}${field8('Adjustment type',select8('v8StockReason',['Physical count gain','Physical count loss','Damage / write-off','Obsolescence','Unit-cost correction','Opening balance correction'],'Physical count loss'))}${field8('Adjustment date',input8('v8StockDate',new Date().toISOString().slice(0,10),'date'))}${field8('Quantity change',input8('v8StockQty','-1','number','','step="1"'))}${field8('Unit cost',input8('v8StockCost',item.unitCost,'number','','min="0" step="0.01"'))}${field8('Project / branch',select8('v8StockProject',['Corporate','Harare Main','Bulawayo','Mutare','Workshop Operations'],item.warehouse))}${field8('Reference',input8('v8StockRef',`ADJ-${item.sku}-${new Date().toISOString().slice(5,10).replace('-','')}`))}${field8('Count sheet / evidence',input8('v8StockEvidence','Count sheet CS-2026-081'))}<div class="v8-field" style="grid-column:1/-1"><label>Adjustment explanation</label><textarea class="v8-textarea" id="v8StockNote">Physical count variance investigated and approved by the warehouse supervisor.</textarea></div></div><div class="v8-split-even">${panel8('Current item position','Before the adjustment',`<div class="v8-facts"><div class="v8-fact"><span>On hand</span><strong>${item.qty}</strong></div><div class="v8-fact"><span>Unit cost</span><strong>${money8(item.unitCost)}</strong></div><div class="v8-fact"><span>Carrying value</span><strong>${money8(item.qty*item.unitCost)}</strong></div><div class="v8-fact"><span>Status</span><strong>${item.status}</strong></div></div>`)}${panel8('Expected accounting','Final values recalculate at review',`<div class="v8-callout warn"><strong>Loss / write-off</strong>Debit inventory losses and credit inventory asset.</div><div class="v8-callout" style="margin-top:7px"><strong>Gain</strong>Debit inventory asset and credit inventory adjustment gain.</div>`)}</div>`,btn8('Cancel','v8-close-modal')+btn8('Review adjustment','v8-review-stock-adjustment','primary'),true)}
function openInventoryItem8(sku){const item=S.inventory.find(x=>x.sku===sku);if(!item)return;const tx=S.journals.filter(j=>j.source==='Inventory').flatMap(j=>j.lines.filter(l=>l.account==='1300').map(l=>({...l,journal:j.id,date:j.date,description:j.description,status:j.status})));openDrawer(item.name,`${item.sku} · ${item.warehouse} · weighted-average valuation`,`<div class="v8-drawer-hero"><div><div class="v8-eyebrow">Inventory item</div><h2>${esc8(item.name)}</h2><p>${esc8(item.category)} · ${esc8(item.warehouse)}</p></div>${badge8(item.status)}</div><div class="v8-facts"><div class="v8-fact"><span>Quantity on hand</span><strong>${item.qty}</strong></div><div class="v8-fact"><span>Unit cost</span><strong>${money8(item.unitCost)}</strong></div><div class="v8-fact"><span>Carrying value</span><strong>${money8(item.qty*item.unitCost)}</strong></div><div class="v8-fact"><span>Inventory GL</span><strong>1300</strong></div></div><div style="margin-top:12px">${panel8('Movement and journal history','Inventory control-account lines linked to source transactions',table8(['Date','Journal','Description','Debit','Credit','Status'],tx.map(x=>`<tr data-action="v8-journal-detail" data-id="${x.journal}"><td>${date8(x.date)}</td><td class="v8-link">${x.journal}</td><td>${esc8(x.description)}</td><td>${x.baseDebit?money8(x.baseDebit):'—'}</td><td>${x.baseCredit?money8(x.baseCredit):'—'}</td><td>${badge8(x.status)}</td></tr>`).join('')||'<tr><td colspan="6">No item-specific journal lines yet.</td></tr>','720px'))}</div>`,btn8('Adjust stock','v8-stock-adjustment','primary',item.sku));setDrawer8('wide')}

function timesheetsPage8(){const rows=S.timesheets.map(x=>`<tr data-action="v8-timesheet-detail" data-id="${x.id}"><td class="v8-link">${x.id}</td><td><div class="v8-person" style="display:flex;gap:8px;align-items:center"><img src="${photo8(x.employee)}"><div><strong>${esc8(x.employee)}</strong><span class="v8-sub">${esc8(x.week)}</span></div></div></td><td>${esc8(x.project)}</td><td>${esc8(x.client)}</td><td class="num">${x.hours}</td><td class="num">${x.billable}</td><td class="num">${Math.round(x.billable/x.hours*100)}%</td><td class="num">${money8(x.cost)}</td><td>${esc8(x.owner)}</td><td>${badge8(x.status)}</td></tr>`).join('');const total=S.timesheets.reduce((s,x)=>s+x.hours,0),bill=S.timesheets.reduce((s,x)=>s+x.billable,0);return `<div class="v8-page">${head8('Project accounting','Timesheets & Cost Allocation','Review submitted time by employee, project, client and fund; approve hours and convert validated allocations into payroll, project-cost or billable-revenue workflows.',btn8('Import timesheets','v8-import-timesheets')+btn8('Approve selected','v8-approve-timesheet','primary')+btn8('Export allocation','v8-export'))}<div class="v8-filterbar">${field8('Week',select8('v8TimesheetWeek',['27 Jul – 02 Aug 2026','20 – 26 Jul 2026','Custom'],'27 Jul – 02 Aug 2026'))}${field8('Employee',select8('v8TimesheetEmployee',['All employees',...S.timesheets.map(x=>x.employee)],'All employees'))}${field8('Project / fund',select8('v8TimesheetProject',['All projects',...new Set(S.timesheets.map(x=>x.project))],'All projects'))}${field8('Client',select8('v8TimesheetClient',['All clients',...new Set(S.timesheets.map(x=>x.client))],'All clients'))}${field8('Status',select8('v8TimesheetStatus',['All statuses','Submitted','Review','Approved'],'All statuses'))}${field8('Search',input8('v8TimesheetSearch','','search','Employee, project or timesheet'))}</div><div class="v8-grid v8-kpis">${kpi8('Submitted hours',`${total} h`,'Current review population','Week')}${kpi8('Billable hours',`${bill} h`,`${Math.round(bill/total*100)}% utilisation`,'Commercial')}${kpi8('Labour cost',money8(S.timesheets.reduce((s,x)=>s+x.cost,0)),'Pending project allocation','Accrual')}${kpi8('Projects',String(new Set(S.timesheets.map(x=>x.project)).size),'Fund and client assignments','Active')}${kpi8('Submitted',String(S.timesheets.filter(x=>x.status==='Submitted').length),'Awaiting review','Queue')}${kpi8('Approved',String(S.timesheets.filter(x=>x.status==='Approved').length),'Ready for cost allocation','Controlled')}</div>${panel8('Submitted timesheets','Select a timesheet to inspect daily hours, project codes and approval history',table8(['Timesheet','Employee / week','Project / fund','Client','Hours','Billable','Utilisation','Cost','Approver','Status'],rows,'1120px'),btn8('Project profitability','v8-go-page','small soft','reports'))}</div>`}
function openTimesheet8(id){const t=S.timesheets.find(x=>x.id===id);if(!t)return;const days=[['Mon',8,7],['Tue',8,7],['Wed',9,8],['Thu',8,7],['Fri',8,5],['Sat',1,1]].map((x,i)=>`<tr><td>${x[0]}</td><td>${esc8(t.project)}</td><td>FIN-${100+i}</td><td class="num">${x[1]}</td><td class="num">${x[2]}</td><td>${i===2?'Client workshop and control review':'Analysis and delivery activities'}</td></tr>`).join('');openDrawer(t.id,`${t.employee} · ${t.week}`,`<div class="v8-drawer-hero"><div class="v8-drawer-person"><img src="${photo8(t.employee)}"><div><div class="v8-eyebrow">Submitted timesheet</div><h2>${esc8(t.employee)}</h2><p>${esc8(t.project)} · ${esc8(t.client)}</p></div></div>${badge8(t.status)}</div><div class="v8-facts"><div class="v8-fact"><span>Total hours</span><strong>${t.hours}</strong></div><div class="v8-fact"><span>Billable</span><strong>${t.billable}</strong></div><div class="v8-fact"><span>Estimated cost</span><strong>${money8(t.cost)}</strong></div><div class="v8-fact"><span>Approver</span><strong>${esc8(t.owner)}</strong></div></div><div style="margin-top:12px">${panel8('Daily detail','Project, task code and business narration',table8(['Day','Project','Task','Hours','Billable','Narration'],days,'720px'))}</div><div class="v8-callout" style="margin-top:12px"><strong>Expected accounting result</strong>Approval makes the hours available for project labour-cost accrual and, where applicable, customer billing. No journal is posted until the configured allocation run is approved.</div>`,btn8('Return for correction','v8-reject-timesheet','danger',id)+btn8('Approve timesheet','v8-approve-timesheet','primary',id));setDrawer8('wide')}

function recurringPage8(){const rows=S.recurring.map(x=>`<tr data-action="v8-recurring-detail" data-id="${x.id}"><td class="v8-link">${x.id}</td><td>${esc8(x.type)}</td><td>${esc8(x.counterparty)}</td><td>${esc8(x.description)}</td><td>${esc8(x.frequency)}</td><td>${date8(x.nextRun)}</td><td class="num">${money8(x.amount,x.currency)}</td><td>${x.debit} / ${x.credit}</td><td>${esc8(x.project)}</td><td>${badge8(x.status)}</td></tr>`).join('');return `<div class="v8-page">${head8('Accounting automation','Recurring Schedules','Reusable expense, supplier bill, revenue and accrual automations with counterparty, tax, dimensional and maker-checker controls.',btn8('New recurring schedule','v8-new-recurring','primary')+btn8('Run due schedules','v8-run-due-recurring','soft'))}<div class="v8-filterbar">${field8('Schedule type',select8('v8RecurringType',['All types','Expense','Bill','Revenue','Accrual'],'All types'))}${field8('Counterparty',select8('v8RecurringCounterparty',['All counterparties',...S.customers.map(x=>x.name),...S.vendors.map(x=>x.name)],'All counterparties'))}${field8('Frequency',select8('v8RecurringFrequency',['All frequencies','Weekly','Monthly','Quarterly','Annual'],'All frequencies'))}${field8('Entity / fund',select8('v8RecurringEntity',['All entities','Corporate','Growth Fund I','MFI Portfolio','Pension Liquidity'],'All entities'))}${field8('Status',select8('v8RecurringStatus',['All statuses','Active','Review','Paused'],'All statuses'))}${field8('Search',input8('v8RecurringSearch','','search','Schedule, counterparty or narration'))}</div><div class="v8-grid v8-kpis">${kpi8('Active schedules',String(S.recurring.filter(x=>x.status==='Active').length),'Automated templates','Live')}${kpi8('Next 30-day value',money8(S.recurring.reduce((s,x)=>s+x.amount,0)),'Forecasted documents','Cash planning')}${kpi8('Bills',String(S.recurring.filter(x=>x.type==='Bill').length),'Vendor obligations','AP')}${kpi8('Revenue',money8(S.recurring.filter(x=>x.type==='Revenue').reduce((s,x)=>s+x.amount,0)),'Expected invoicing','AR')}${kpi8('Accrual templates','2','Month-end automation','Close')}${kpi8('Control exceptions','1','Counterparty or mapping review','Attention')}</div>${panel8('Recurring schedule register','Select a schedule for generated occurrences, journal mapping and version history',table8(['Schedule','Type','Counterparty','Description','Frequency','Next run','Amount','DR / CR mapping','Project / fund','Status'],rows,'1180px'))}</div>`}
function recurringModal8(){openModal('New recurring schedule','Create a reusable expense, bill, revenue or accrual automation',`<div class="v8-filterbar" style="grid-template-columns:repeat(3,minmax(0,1fr))">${field8('Schedule type',select8('v8RecType',['Expense','Bill','Revenue','Accrual'],'Bill'))}${field8('Counterparty',select8('v8RecCounterparty',['Select counterparty',...S.customers.map(x=>x.name),...S.vendors.map(x=>x.name)],'Select counterparty'))}<div class="v8-field"><label>Missing counterparty?</label>${btn8('+ Add counterparty','v8-add-counterparty','soft')}</div>${field8('Frequency',select8('v8RecFrequency',['Weekly','Monthly','Quarterly','Annual'],'Monthly'))}${field8('Next run date',input8('v8RecNext',new Date().toISOString().slice(0,10),'date'))}${field8('Amount',input8('v8RecAmount','0','number','','min="0" step="0.01"'))}${field8('Currency',select8('v8RecCurrency',['USD','ZWG','ZAR'],'USD'))}${field8('Debit account',select8('v8RecDebit',S.accounts.filter(a=>a.posting).map(a=>[a.code,`${a.code} · ${a.name}`]),'5140'))}${field8('Credit account',select8('v8RecCredit',S.accounts.filter(a=>a.posting).map(a=>[a.code,`${a.code} · ${a.name}`]),'2000'))}${field8('Tax treatment',select8('v8RecTax',[['0','No VAT'],['0.15','VAT 15%']],'0.15'))}${field8('Project / fund',select8('v8RecProject',['Corporate','Growth Fund I','MFI Portfolio','Pension Liquidity'],'Corporate'))}${field8('Posting policy',select8('v8RecPolicy',['Create draft for approval','Auto-post below authority threshold'],'Create draft for approval'))}<div class="v8-field" style="grid-column:1/-1"><label>Description</label><textarea class="v8-textarea" id="v8RecDescription">Recurring supplier or customer transaction</textarea></div></div>`,btn8('Cancel','v8-close-modal')+btn8('Review schedule','v8-review-recurring','primary'),true)}
function openRecurring8(id){const x=S.recurring.find(r=>r.id===id);if(!x)return;openDrawer(x.description,`${x.id} · ${x.frequency} · ${x.type}`,`<div class="v8-drawer-hero"><div><div class="v8-eyebrow">Recurring automation</div><h2>${esc8(x.description)}</h2><p>${esc8(x.counterparty)} · next run ${date8(x.nextRun)}</p></div>${badge8(x.status)}</div><div class="v8-facts"><div class="v8-fact"><span>Amount</span><strong>${money8(x.amount,x.currency)}</strong></div><div class="v8-fact"><span>Frequency</span><strong>${x.frequency}</strong></div><div class="v8-fact"><span>Debit account</span><strong>${x.debit}</strong></div><div class="v8-fact"><span>Credit account</span><strong>${x.credit}</strong></div></div><div style="margin-top:12px">${panel8('Next occurrence','Document and journal preview',journalPreview8([line8(x.debit,x.amount,0,x.description,x.project,x.currency,fx8(x.currency)),line8(x.credit,0,x.amount,x.description,x.project,x.currency,fx8(x.currency))],x.currency))}</div><div style="margin-top:12px">${panel8('Generated history','Prior controlled occurrences',table8(['Run date','Document','Journal','Amount','Status'],`<tr><td>31 Jul 2026</td><td>REC-DOC-0731</td><td class="v8-link">JE-2026-0113</td><td>${money8(x.amount,x.currency)}</td><td>${badge8('Posted')}</td></tr>`,'620px'))}</div>`,btn8('Pause schedule','v8-pause-recurring','danger',id)+btn8('Run now','v8-run-recurring','primary',id));setDrawer8('wide')}

function coaPage8(){const rows=S.accounts.map(a=>`<tr data-action="v8-account-detail" data-id="${a.code}"><td class="v8-link">${a.code}</td><td>${esc8(a.name)}</td><td>${esc8(a.type)}</td><td>${a.natural||a.normal}</td><td>${a.control?badge8('Control account'):badge8(a.posting?'Posting':'Header')}</td><td>${esc8(a.scope)}</td><td class="num">${a.posting||a.control?money8(accountDisplayBalance8(a.code)):'—'}</td><td>${badge8(a.active?'Active':'Inactive')}</td><td>${btn8('Edit','v8-edit-account','small',a.code)}</td></tr>`).join('');return `<div class="v8-page">${head8('Master-data governance','Chart of Accounts','A complete, editable accounting map with natural balances, control-account protection, dimensional scope and impact-assessed changes.',btn8('Add account','v8-add-account','primary')+btn8('Import CoA','v8-import-coa','soft')+btn8('Change history','v8-coa-history'))}<div class="v8-filterbar">${field8('Account type',select8('v8CoaType',['All types',...new Set(S.accounts.map(a=>a.type))],'All types'))}${field8('Posting class',select8('v8CoaPosting',['All classes','Posting','Control account','Header'],'All classes'))}${field8('Natural balance',select8('v8CoaNatural',['All balances','Debit','Credit'],'All balances'))}${field8('Scope / industry',select8('v8CoaScope',['All scopes',...new Set(S.accounts.map(a=>a.scope))],'All scopes'))}${field8('Status',select8('v8CoaStatus',['All statuses','Active','Inactive'],'All statuses'))}${field8('Search',input8('v8CoaSearch','','search','Account number or name'))}</div><div class="v8-grid v8-kpis">${kpi8('Accounts',String(S.accounts.length),'Headers, controls and postings','Master')}${kpi8('Posting accounts',String(S.accounts.filter(a=>a.posting).length),'Transaction eligible','Active')}${kpi8('Control accounts',String(S.accounts.filter(a=>a.control).length),'Sub-ledger only','Protected')}${kpi8('Industry scopes',String(new Set(S.accounts.map(a=>a.scope)).size),'Group, MFI, funds and pension','Dimensions')}${kpi8('Pending changes','0','Maker-checker queue','Current')}${kpi8('Last review','31 Jul 2026','Financial Controller','Governed')}</div>${panel8('Chart of Accounts register','Select an account for ledger analysis; edit permitted master-data fields through a governed change',table8(['Account','Name','Type','Natural balance','Class','Scope','Balance','Status','Action'],rows,'1080px'))}</div>`}
function accountModal8(code=''){const a=account8(code)||{code:'',name:'',type:'Expense',normal:'Debit',control:false,posting:true,scope:'Group',active:true};openModal(code?'Edit account':'Add Chart of Accounts entry','Account changes are versioned and impact-assessed before becoming active',`<div class="v8-filterbar" style="grid-template-columns:repeat(2,minmax(0,1fr))">${field8('Account number',input8('v8CoaCode',a.code,'text','','maxlength="6"'))}${field8('Account name',input8('v8CoaName',a.name))}${field8('Account type',select8('v8CoaEditType',['Current Asset','Non-current Asset','Contra Asset','Current Liability','Non-current Liability','Equity','Revenue','Other Income','Expense','Bank'],a.type))}${field8('Natural balance',select8('v8CoaEditNatural',['Debit','Credit'],(a.natural||a.normal||'Debit')))}${field8('Class',select8('v8CoaEditClass',[['posting','Posting account'],['control','Control account'],['header','Header / group']],a.control?'control':a.posting?'posting':'header'))}${field8('Industry / entity scope',select8('v8CoaEditScope',['Group','Operations','Treasury','Microfinance','Asset Management','Investments','Pension'],a.scope))}${field8('Status',select8('v8CoaEditStatus',['Active','Inactive'],a.active?'Active':'Inactive'))}${field8('Reporting mapping',select8('v8CoaEditReport',['Balance Sheet','Income Statement','Cash Flow only','Disclosure / memo'],'Income Statement'))}</div><div class="v8-callout warn"><strong>Impact assessment</strong>Changing an active account's type or natural balance can affect the trial balance and financial statements. Existing posted journal lines are never rewritten.</div>`,btn8('Cancel','v8-close-modal')+btn8('Review account change','v8-review-account','primary',code),true)}

function approvalsPage8(){const pending=S.approvals.filter(x=>x.status==='Pending'),rows=S.approvals.map(x=>`<tr data-action="v8-approval-detail" data-id="${x.id}"><td class="v8-link">${x.id}</td><td>${esc8(x.type)}</td><td class="v8-link">${esc8(x.record)}</td><td>${esc8(x.title)}</td><td class="num">${money8(x.amount,x.currency)}</td><td><div class="v8-person" style="display:flex;align-items:center;gap:7px"><img src="${photo8(x.maker)}"><div><strong>${esc8(x.maker)}</strong><span class="v8-sub">Maker</span></div></div></td><td>${esc8(x.requiredRole)}</td><td>${badge8(x.status)}</td></tr>`).join('');return `<div class="v8-page">${head8('Maker–checker governance','Approval Centre','Review accounting, payment, investment and master-data actions independently. Approval is blocked when the checker is also the maker.',btn8('Refresh policy','v8-refresh-approvals')+btn8('Policy simulator','v8-go-page','soft','access'))}<div class="v8-filterbar">${field8('Approval type',select8('v8ApprovalType',['All approvals','Journal','Payment','Investment','Master data'],'All approvals'))}${field8('Entity / fund',select8('v8ApprovalEntity',['All entities','Corporate','Growth Fund I','MFI Entity','Pension Liquidity'],'All entities'))}${field8('Value band',select8('v8ApprovalValue',['All values','Below $10k','$10k–$50k','Above $50k'],'All values'))}${field8('Maker',select8('v8ApprovalMaker',['All makers',...new Set(S.approvals.map(x=>x.maker))],'All makers'))}${field8('Status',select8('v8ApprovalStatus',['All statuses','Pending','Approved','Rejected'],'Pending'))}${field8('Search',input8('v8ApprovalSearch','','search','Approval, journal or description'))}</div><div class="v8-grid v8-kpis">${kpi8('Pending approvals',String(pending.length),'Independent review required','Queue')}${kpi8('Pending value',money8(pending.reduce((s,x)=>s+x.amount,0)),'Base-currency exposure','Controlled')}${kpi8('Journals',String(pending.filter(x=>x.type==='Journal').length),'Balanced records awaiting post','Accounting')}${kpi8('Payments','2','Bank and beneficiary checks','Treasury')}${kpi8('SOD blocks','0','Maker / checker conflicts','Current')}${kpi8('Median turnaround','1.4 h','Last 30 days','SLA 4 h')}</div>${panel8('Approval queue','Select a record to inspect journals, evidence, policy and expected result',table8(['Approval','Type','Record','Description','Value','Maker','Required authority','Status'],rows||'<tr><td colspan="8">No approvals.</td></tr>','1050px'))}</div>`}
function openApproval8(id){const a=S.approvals.find(x=>x.id===id),j=S.journals.find(x=>x.id===a?.record);if(!a)return;openDrawer(a.title,`${a.id} · ${a.type} approval`,`${j?`<div class="v8-drawer-hero"><div><div class="v8-eyebrow">Maker–checker review</div><h2>${esc8(j.id)}</h2><p>${esc8(j.description)} · ${date8(j.date)}</p></div>${badge8(a.status)}</div><div class="v8-facts"><div class="v8-fact"><span>Maker</span><strong>${esc8(a.maker)}</strong></div><div class="v8-fact"><span>Required role</span><strong>${esc8(a.requiredRole)}</strong></div><div class="v8-fact"><span>Value</span><strong>${money8(a.amount,a.currency)}</strong></div><div class="v8-fact"><span>Source</span><strong>${esc8(j.source)}</strong></div></div><div style="margin-top:12px">${panel8('Balanced journal','Review all immutable debit and credit lines before approval',journalPreview8(j.lines,j.currency))}</div>`:`<div class="v8-callout">Approval record does not contain a journal preview.</div>`}<div style="margin-top:12px">${panel8('Policy evaluation','Dynamic role, value and segregation checks',`<div class="v8-validation-list"><div class="v8-validation">Current role: ${esc8(state.role)}</div><div class="v8-validation ${a.maker===currentUser8()?'bad':''}">${a.maker===currentUser8()?'Segregation block: maker and checker are the same user.':'Maker and checker are independent.'}</div><div class="v8-validation">Required authority: ${esc8(a.requiredRole)}</div><div class="v8-validation">Journal balance and open-period checks passed.</div></div>`)}</div>`,a.status==='Pending'?btn8('Reject / return','v8-reject-approval','danger',a.id)+btn8('Approve & post','v8-approve-approval','primary',a.id):btn8('Close','v8-close-drawer'));setDrawer8('wide')}
function approveApproval8(id){const a=S.approvals.find(x=>x.id===id),j=S.journals.find(x=>x.id===a?.record);if(!a||a.status!=='Pending')throw new Error('Approval is no longer pending.');if(a.maker===currentUser8()&&state.role!=='CEO')throw new Error('Segregation of duties prevents the maker from approving the same record. Switch to an independent authorised user or CEO view.');if(j){const v=validateJournal8(j.lines,j.source);if(!v.valid)throw new Error(v.errors.join(' '));j.status='Posted';j.checker=currentUser8();j.postedAt=now8();j.immutable=true}const pr=S.paymentRuns?.find(x=>x.id===a.record);if(pr&&pr.status==='Pending approval'){for(const billId of pr.billIds){const bill=S.bills.find(x=>x.id===billId);if(!bill||bill.outstanding<=.001)continue;const pj=payBill8({billId,bankId:pr.bankId,amount:bill.outstanding,date:pr.date,reference:`${pr.id}-${billId}`,rate:fx8(bill.currency,pr.date)});pr.journals.push(pj.id)}pr.status='Approved and posted';pr.checker=currentUser8();pr.completedAt=now8()}a.status='Approved';a.checker=currentUser8();a.completedAt=now8();audit8('APPROVAL_COMPLETED',a.record,`${a.id} approved by ${currentUser8()}`,'Approved');save8();return a}
function rejectApproval8(id,reason='Returned for correction'){const a=S.approvals.find(x=>x.id===id),j=S.journals.find(x=>x.id===a?.record);if(!a||a.status!=='Pending')throw new Error('Approval is no longer pending.');a.status='Rejected';a.checker=currentUser8();a.reason=reason;a.completedAt=now8();if(j)j.status='Rejected';audit8('APPROVAL_REJECTED',a.record,`${a.id} · ${reason}`,'Rejected');save8();return a}

/* --------------------------------------------------------------------------
   Short-term investments: continuous accrual, liquidity and CFO analytics
   -------------------------------------------------------------------------- */
function investmentBaseValue8(inv){return r8((inv.principal+inv.accrued)*fx8(inv.currency))}
function weightedApy8(){const total=S.investments.reduce((s,x)=>s+investmentBaseValue8(x),0);return total?S.investments.reduce((s,x)=>s+investmentBaseValue8(x)*x.apy,0)/total:0}
function investmentSeries8(inv,days=20){const out=[],den=dayDenominator8(inv.dayCount,'2026-08-01'),rate=investmentRate8(inv,'2026-08-01');let bal=Math.max(0,inv.accrued-(inv.principal*(rate/100)/den)*days);for(let i=days-1;i>=0;i--){const d=new Date(Date.UTC(2026,7,1-i)).toISOString().slice(0,10),daily=inv.principal*(rate/100)/den;bal+=daily;out.push({date:d,amount:r8(daily),balance:r8(bal),apy:rate})}return out}
function investmentLineChart8(inv){const data=(inv.daily?.length?inv.daily.slice(-20):investmentSeries8(inv,20)),w=820,h=250,p={l:54,r:20,t:20,b:36},vals=data.map(x=>x.balance),min=Math.min(...vals,0),max=Math.max(...vals,1),range=Math.max(1,max-min),pts=data.map((x,i)=>({x:p.l+i*(w-p.l-p.r)/Math.max(1,data.length-1),y:p.t+(max-x.balance)/range*(h-p.t-p.b),v:x}));const path=pts.map((x,i)=>`${i?'L':'M'} ${x.x.toFixed(1)} ${x.y.toFixed(1)}`).join(' ');return `<svg class="v8-chart" viewBox="0 0 ${w} ${h}"><defs><linearGradient id="v8area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#087cff" stop-opacity=".26"/><stop offset="1" stop-color="#087cff" stop-opacity=".02"/></linearGradient></defs>${[0,.25,.5,.75,1].map(f=>{const y=p.t+f*(h-p.t-p.b),v=max-f*range;return `<line class="gridline" x1="${p.l}" x2="${w-p.r}" y1="${y}" y2="${y}"/><text x="4" y="${y+3}">${money8(v,inv.currency)}</text>`}).join('')}<path class="area" d="${path} L ${pts.at(-1)?.x||p.l} ${h-p.b} L ${p.l} ${h-p.b} Z"/><path class="line" d="${path}"/>${pts.filter((_,i)=>i%Math.max(1,Math.floor(data.length/6))===0||i===data.length-1).map(x=>`<circle class="dot" data-action="v8-investment-point" data-id="${inv.id}|${x.v.date}" cx="${x.x}" cy="${x.y}" r="4"><title>${x.v.date}: ${money8(x.v.balance,inv.currency)}</title></circle><text x="${x.x}" y="${h-12}" text-anchor="middle">${x.v.date.slice(5)}</text>`).join('')}<text x="${p.l}" y="12">Cumulative accrued interest (${inv.currency})</text></svg>`}
function heatClass8(apy,risk){if(/High/i.test(risk)||apy<0)return'r2';if(/Review/i.test(risk))return'r1';if(apy>=10)return'g3';if(apy>=9)return'g2';if(apy>=8)return'g1';if(apy>=5)return'a1';return'a2'}
function investmentHeatmap8(){const weeks=['W1','W2','W3','W4','W5'];return `<div class="v8-heatmap">${S.investments.flatMap(inv=>weeks.map((w,i)=>{const yieldRate=inv.apy+(i-2)*.08,cls=heatClass8(yieldRate,inv.risk);return `<div class="v8-heatcell ${cls}" data-action="v8-investment-heat" data-id="${inv.id}|${w}"><strong>${esc8(inv.issuer)}</strong><span>${yieldRate.toFixed(2)}%</span><em>${w} · ${esc8(inv.currency)} · ${esc8(inv.entity)}</em></div>`})).join('')}</div>`}
function investmentsPage8(){const total=S.investments.reduce((s,x)=>s+investmentBaseValue8(x),0),accrued=S.investments.reduce((s,x)=>s+x.accrued*fx8(x.currency),0),daily=S.investments.reduce((s,x)=>{const den=dayDenominator8(x.dayCount,'2026-08-01');return s+(x.principal+x.accrued)*(x.apy/100)/den*fx8(x.currency)},0),maturing=S.investments.filter(x=>x.maturity!=='On demand'&&new Date(x.maturity)<=new Date('2026-10-31')).reduce((s,x)=>s+investmentBaseValue8(x),0),rows=S.investments.map(x=>`<tr data-action="v8-investment-detail" data-id="${x.id}"><td class="v8-link">${x.id}</td><td>${esc8(x.issuer)}<span class="v8-sub">${esc8(x.type)} · ${esc8(x.entity)}</span></td><td>${x.currency}</td><td class="num">${money8(x.principal,x.currency)}</td><td class="num">${x.apy.toFixed(2)}%</td><td>${esc8(x.method)}</td><td>${esc8(x.dayCount)}</td><td class="num">${money8(x.accrued,x.currency)}</td><td>${x.maturity==='On demand'?x.maturity:date8(x.maturity)}</td><td>${badge8(x.risk)}</td><td>${badge8(x.status)}</td></tr>`).join('');return `<div class="v8-page">${head8('Treasury and liquidity','Short-Term Investments','CFO-grade portfolio valuation, daily appreciation, effective-dated rates, maturity liquidity, dimensional reporting, FX translation and automated journal posting.',btn8('New placement','v8-new-investment','primary')+btn8('Run daily accrual','v8-run-accrual-batch','soft')+btn8('Export portfolio','v8-export'))}<div class="v8-filterbar">${field8('Entity / fund',select8('v8InvestEntity',['All entities',...new Set(S.investments.map(x=>x.entity))],'All entities'))}${field8('Instrument type',select8('v8InvestType',['All instruments',...new Set(S.investments.map(x=>x.type))],'All instruments'))}${field8('Issuer / broker',select8('v8InvestIssuer',['All issuers',...new Set(S.investments.map(x=>x.issuer))],'All issuers'))}${field8('Currency',select8('v8InvestCurrency',['All currencies','USD','ZWG','ZAR'],'All currencies'))}${field8('Maturity horizon',select8('v8InvestMaturity',['All maturities','On demand','Next 30 days','31–60 days','61–90 days','90+ days'],'All maturities'))}${field8('Risk',select8('v8InvestRisk',['All risk','Low','Review','High'],'All risk'))}</div><div class="v8-grid v8-kpis">${kpi8('Total portfolio value',money8(total),'Principal + unsettled accrued interest','Live')}${kpi8('Accrued interest',money8(accrued),'Translated to base currency','Current')}${kpi8('Estimated daily yield',money8(daily),'Current effective rates','23:59 batch')}${kpi8('Weighted APY',`${weightedApy8().toFixed(2)}%`,'Base-value weighted','Portfolio')}${kpi8('Next 90-day liquidity',money8(maturing),'Principal + accrued interest','Forecast')}${kpi8('FX-exposed value',money8(S.investments.filter(x=>x.currency!=='USD').reduce((s,x)=>s+investmentBaseValue8(x),0)),'Non-USD instruments','Revalue')}</div><div class="v8-invest-grid"><div class="v8-stack">${panel8('Portfolio yield heat map','Compact weekly yield and risk view · select any cell for full-page granular analytics',investmentHeatmap8(),btn8('Open yield report','v8-select-report','small soft','yield'))}${panel8('Investment register','Principal, APY, day count, accrued income and maturity status',table8(['Instrument','Issuer / dimensions','Currency','Principal','APY','Calculation','Day count','Accrued','Maturity','Risk','Status'],rows,'1200px'),btn8('Daily yield report','v8-select-report','small','yield'))}</div><aside class="v8-stack">${panel8('Liquidity ladder','Expected principal and interest cash inflows',`<div class="status-line"><div><strong>On demand</strong><span>CBZ Money Market</span></div><strong>${money8(investmentBaseValue8(S.investments[0]))}</strong></div><div class="status-line"><div><strong>0–30 days</strong><span>RBZ Treasury Bill</span></div><strong>${money8(investmentBaseValue8(S.investments[1]))}</strong></div><div class="status-line"><div><strong>31–90 days</strong><span>Stanbic FD and FBC CP</span></div><strong>${money8(investmentBaseValue8(S.investments[2])+investmentBaseValue8(S.investments[3]))}</strong></div><div class="status-line"><div><strong>90+ days</strong><span>NBS ZWG Deposit</span></div><strong>${money8(investmentBaseValue8(S.investments[4]))}</strong></div>`,btn8('Liquidity forecast','v8-investment-analytics','small','STI-2026-013'))}${panel8('Continuous accounting engine','Daily batch and posting policy',`<div class="v8-validation-list"><div class="v8-validation">Scheduled run: 23:59 tenant time</div><div class="v8-validation">Posting mode: ${esc8(S.settings.investmentPostingMode)}</div><div class="v8-validation">Effective-dated rates and leap-year logic enabled</div><div class="v8-validation">DR accrued interest / CR interest income</div><div class="v8-validation warn">${S.approvals.filter(x=>x.type==='Journal'&&S.journals.find(j=>j.id===x.record)?.source==='Investments'&&x.status==='Pending').length} investment journal(s) await approval</div></div>`,btn8('Posting policy','v8-investment-policy','small soft'))}${panel8('Concentration and risk','Issuer, currency and capital protection',`<div class="status-line"><div><strong>Largest issuer</strong><span>RBZ Treasury Bill</span></div><strong>29.8%</strong></div><div class="status-line"><div><strong>ZWG exposure</strong><span>Daily FX translation required</span></div><strong>${money8(investmentBaseValue8(S.investments[4]))}</strong></div><div class="status-line"><div><strong>Capital erosion</strong><span>Negative-yield instruments</span></div>${badge8('0 instruments')}</div>`)}</aside></div></div>`}
function investmentModal8(){openModal('New short-term investment','Create an instrument with dimensions, effective rate, day count, settlement account and GL mappings',`<div class="v8-filterbar" style="grid-template-columns:repeat(3,minmax(0,1fr))">${field8('Instrument name / issuer',input8('v8NewInvIssuer',''))}${field8('Category',select8('v8NewInvType',['Money Market','Treasury Bill','Commercial Paper','Certificate of Deposit','Fixed Deposit'],'Money Market'))}${field8('Entity / fund',select8('v8NewInvEntity',['Group Treasury','Growth Fund I','MFI Entity','Pension Liquidity'],'Group Treasury'))}${field8('Currency',select8('v8NewInvCurrency',['USD','ZWG','ZAR'],'USD'))}${field8('Principal amount',input8('v8NewInvPrincipal','0','number','','min="0" step="0.01"'))}${field8('Annual percentage yield',input8('v8NewInvApy','0','number','','step="0.01"'))}${field8('Interest calculation',select8('v8NewInvMethod',['Simple','Compound Daily','Compound Monthly'],'Simple'))}${field8('Day-count convention',select8('v8NewInvDayCount',['Actual/360','Actual/365','30/360'],'Actual/365'))}${field8('Settlement account',select8('v8NewInvBank',S.banks.map(b=>[b.id,b.name]),S.banks[0].id))}${field8('Start date',input8('v8NewInvStart',new Date().toISOString().slice(0,10),'date'))}${field8('Maturity date',input8('v8NewInvMaturity','2026-11-30','date'))}${field8('Posting policy',select8('v8NewInvPosting',['Draft for CFO review','Approved to GL'],'Draft for CFO review'))}${field8('Principal asset account',select8('v8NewInvPrincipalAccount',[['1500','1500 · Short-term investments']],'1500'))}${field8('Accrued interest account',select8('v8NewInvAccrualAccount',[['1510','1510 · Accrued investment income']],'1510'))}${field8('Interest income account',select8('v8NewInvIncomeAccount',[['4200','4200 · Investment interest income']],'4200'))}</div><div class="v8-callout warn"><strong>Mandatory settlement readiness</strong>The instrument cannot be saved without a linked cash account and all three GL mappings. Active instruments cannot be deleted; errors are corrected through a controlled void and reversal.</div>`,btn8('Cancel','v8-close-modal')+btn8('Review instrument','v8-review-new-investment','primary'),true)}
function openInvestment8(id){const inv=S.investments.find(x=>x.id===id);if(!inv)return;S.ui.currentInvestment=id;save8();const series=inv.daily?.length?inv.daily.slice(-30):investmentSeries8(inv,30),journals=S.journals.filter(j=>j.sourceId===inv.id),rows=series.slice().reverse().map(x=>`<tr><td>${date8(x.date)}</td><td>${x.apy.toFixed(3)}%</td><td class="num">${money8(x.amount,inv.currency)}</td><td class="num">${money8(x.balance,inv.currency)}</td><td>${n8(x.rate||fx8(inv.currency)).toFixed(4)}</td></tr>`).join('');openDrawer(inv.issuer,`${inv.id} · ${inv.type} · ${inv.entity}`,`<div class="v8-drawer-hero"><div><div class="v8-eyebrow">Investment instrument</div><h2>${esc8(inv.issuer)}</h2><p>${esc8(inv.type)} · ${esc8(inv.entity)} · ${esc8(inv.currency)}</p></div>${badge8(inv.status)}</div><div class="v8-facts"><div class="v8-fact"><span>Principal</span><strong>${money8(inv.principal,inv.currency)}</strong></div><div class="v8-fact"><span>Accrued interest</span><strong>${money8(inv.accrued,inv.currency)}</strong></div><div class="v8-fact"><span>Current APY</span><strong>${inv.apy.toFixed(2)}%</strong></div><div class="v8-fact"><span>Portfolio value</span><strong>${money8(inv.principal+inv.accrued,inv.currency)}</strong></div></div><div class="v8-tabs" style="margin-top:12px"><button class="v8-tab active">Accrual analytics</button><button class="v8-tab" data-action="v8-investment-analytics" data-id="${inv.id}">Full analysis</button><button class="v8-tab" data-action="v8-rate-change" data-id="${inv.id}">Rate history</button><button class="v8-tab" data-action="v8-journal-detail" data-id="${journals[0]?.id||''}">Journals</button></div><div class="v8-split-even"><div>${panel8('Daily accrual trend','Cumulative interest under the active effective-dated rate',investmentLineChart8(inv))}</div><div>${panel8('Instrument master and GL mappings','Treasury dimensions and accounting policy',`<div class="v8-facts"><div class="v8-fact"><span>Calculation</span><strong>${inv.method}</strong></div><div class="v8-fact"><span>Day count</span><strong>${inv.dayCount}</strong></div><div class="v8-fact"><span>Maturity</span><strong>${inv.maturity==='On demand'?inv.maturity:date8(inv.maturity)}</strong></div><div class="v8-fact"><span>Settlement bank</span><strong>${bank8(inv.settlementBank)?.name}</strong></div><div class="v8-fact"><span>Principal GL</span><strong>${inv.principalAccount}</strong></div><div class="v8-fact"><span>Accrual GL</span><strong>${inv.accrualAccount}</strong></div><div class="v8-fact"><span>Income GL</span><strong>${inv.incomeAccount}</strong></div><div class="v8-fact"><span>Risk</span><strong>${inv.risk}</strong></div></div>`)}</div><div style="margin-top:12px">${panel8('Daily accrual register','Interest, cumulative accrued value and translation rate',table8(['Date','APY','Daily accrual','Accrued balance','FX rate'],rows,'700px'))}</div>`,btn8('Effective-dated rate','v8-rate-change','',inv.id)+btn8('Run accrual today','v8-run-single-accrual','soft',inv.id)+btn8('Liquidate / mature','v8-mature-investment','primary',inv.id));setDrawer8('investment')}
function investmentAnalyticsPage8(){const inv=S.investments.find(x=>x.id===S.ui.currentInvestment)||S.investments[0],series=inv.daily?.length?inv.daily.slice(-60):investmentSeries8(inv,60),journalRows=S.journals.filter(j=>j.sourceId===inv.id).map(j=>`<tr data-action="v8-journal-detail" data-id="${j.id}"><td>${date8(j.date)}</td><td class="v8-link">${j.id}</td><td>${esc8(j.description)}</td><td class="num">${money8(j.total)}</td><td>${badge8(j.status)}</td></tr>`).join('');return `<div class="v8-page">${head8('Instrument analytics',`${inv.id} · ${inv.issuer}`,'Granular daily accrual, rate, FX, liquidity and journal analysis for the selected short-term investment.',btn8('Back to portfolio','v8-go-page','','investments')+btn8('Change rate','v8-rate-change','soft',inv.id)+btn8('Run accrual','v8-run-single-accrual','primary',inv.id))}<div class="v8-grid v8-kpis">${kpi8('Principal',money8(inv.principal,inv.currency),inv.currency,'Original')}${kpi8('Accrued interest',money8(inv.accrued,inv.currency),`${series.length} analysed days`,'Current')}${kpi8('Current APY',`${inv.apy.toFixed(2)}%`,inv.method,'Effective')}${kpi8('Daily accrual',money8(series.at(-1)?.amount||0,inv.currency),inv.dayCount,'Estimate')}${kpi8('Base-currency value',money8(investmentBaseValue8(inv)),'Using approved FX rate','Translated')}${kpi8('Maturity',inv.maturity==='On demand'?'On demand':date8(inv.maturity),bank8(inv.settlementBank)?.name,'Liquidity')}</div><div class="v8-split"><div class="v8-stack">${panel8('Accrual time series','Daily and cumulative interest under the effective rate table',investmentLineChart8(inv),btn8('Download daily accruals','v8-export','small'))}${panel8('Accrual register','Detailed interest and translation evidence',table8(['Date','APY','Daily accrual','Cumulative accrued','FX rate','Base equivalent'],series.slice().reverse().map(x=>`<tr><td>${date8(x.date)}</td><td>${x.apy.toFixed(3)}%</td><td class="num">${money8(x.amount,inv.currency)}</td><td class="num">${money8(x.balance,inv.currency)}</td><td>${n8(x.rate||fx8(inv.currency)).toFixed(4)}</td><td class="num">${money8(x.amount*n8(x.rate||fx8(inv.currency)))}</td></tr>`).join(''),'840px'))}</div><aside class="v8-stack">${panel8('Rate table','Effective-dated APY changes',inv.rates.map(r=>`<div class="status-line"><div><strong>${r.apy.toFixed(2)}%</strong><span>Effective ${date8(r.effective)}</span></div>${badge8(r.effective===inv.rates.at(-1).effective?'Current':'Historical')}</div>`).join(''),btn8('Add rate change','v8-rate-change','small soft',inv.id))}${panel8('Journal automation','Daily DR accrued interest / CR investment income',table8(['Date','Journal','Description','Value','Status'],journalRows||'<tr><td colspan="5">No generated journals yet.</td></tr>','560px'))}${panel8('Stress and boundary analysis','Capital, yield and FX sensitivity',`<div class="status-line"><div><strong>APY –100 bps</strong><span>Annual income sensitivity</span></div><strong>${money8(-inv.principal*.01,inv.currency)}</strong></div><div class="status-line"><div><strong>FX –10%</strong><span>Base carrying-value sensitivity</span></div><strong>${money8(-investmentBaseValue8(inv)*.10)}</strong></div><div class="status-line"><div><strong>Early liquidation</strong><span>Estimated principal + accrued</span></div><strong>${money8(inv.principal+inv.accrued,inv.currency)}</strong></div>`)}</aside></div></div>`}
function rateChangeModal8(id){const inv=S.investments.find(x=>x.id===id);if(!inv)return;openModal('Effective-dated APY change',`${inv.id} · ${inv.issuer}`,`<div class="v8-filterbar" style="grid-template-columns:repeat(2,minmax(0,1fr))">${field8('Current APY',input8('v8RateCurrent',inv.apy,'number','','disabled'))}${field8('New APY',input8('v8RateNew',inv.apy,'number','','step="0.01"'))}${field8('Effective date',input8('v8RateEffective',new Date().toISOString().slice(0,10),'date'))}${field8('Change reason',select8('v8RateReason',['Issuer rate notice','Treasury renegotiation','Variable yield reset','Correction'],'Issuer rate notice'))}<div class="v8-field" style="grid-column:1/-1"><label>Evidence and approval note</label><textarea class="v8-textarea" id="v8RateNote">Issuer rate notice received and independently verified.</textarea></div></div><div class="v8-callout warn"><strong>Time-stamp integrity</strong>The new rate applies only from the selected effective date. Prior accruals remain unchanged and the old/new values, user and timestamp are retained.</div>`,btn8('Cancel','v8-close-modal')+btn8('Review rate change','v8-review-rate-change','primary',id),true)}
function addInvestment8(data){if(!data.issuer||n8(data.principal)<=0||!data.bank)throw new Error('Issuer, principal and settlement account are required.');const id=`STI-2026-${String(S.investments.length+15).padStart(3,'0')}`,inv={id,issuer:data.issuer,type:data.type,entity:data.entity,currency:data.currency,principal:n8(data.principal),apy:n8(data.apy),method:data.method,dayCount:data.dayCount,settlementBank:data.bank,principalAccount:'1500',accrualAccount:'1510',incomeAccount:'4200',start:data.start,maturity:data.maturity,accrued:0,status:'Active',risk:data.apy<0?'High':'Low',rates:[{effective:data.start,apy:n8(data.apy)}],daily:[]};S.investments.unshift(inv);audit8('INVESTMENT_CREATED',id,`${inv.issuer} · ${money8(inv.principal,inv.currency)} · ${inv.apy}%`,'Recorded');save8();return inv}

/* --------------------------------------------------------------------------
   Enterprise financial reporting, premium letterheads and document preview
   -------------------------------------------------------------------------- */
const reportCatalog8=[['pnl','Statement of Profit or Loss','Performance, budget and prior comparison'],['bs','Statement of Financial Position','Assets, liabilities and equity'],['cf','Statement of Cash Flows','Operating, investing and financing'],['equity','Statement of Changes in Equity','Capital, reserves and retained earnings'],['tb','Trial Balance','Debit and credit integrity'],['ar','Accounts Receivable Ageing','Customer balances and collection risk'],['ap','Accounts Payable Ageing','Supplier obligations and liquidity'],['yield','Daily Investment Yield Report','Daily accrual and issuer analysis']];
function reportDataset8(type){if(['pnl','bs','cf','equity','tb'].includes(type))return reportRows8(type);if(type==='ar')return S.customers.map(c=>{const inv=S.invoices.filter(x=>x.customerId===c.id),current=inv.reduce((s,x)=>s+x.outstanding,0);return{id:c.id,label:c.name,codes:['1200'],current,budget:c.limit,prior:current*.88,meta:`${inv.filter(x=>x.outstanding>0).length} open invoices`,total:false}}).concat([{id:'ar-total',label:'Total accounts receivable',codes:['1200'],current:outstandingAR8(),budget:S.customers.reduce((s,x)=>s+x.limit,0),prior:outstandingAR8()*.88,total:true}]);if(type==='ap')return S.vendors.map(v=>{const bills=S.bills.filter(x=>x.vendorId===v.id),current=bills.reduce((s,x)=>s+x.outstanding,0);return{id:v.id,label:v.name,codes:['2000'],current,budget:current*.95,prior:current*.92,meta:`${bills.filter(x=>x.outstanding>0).length} open bills`}}).concat([{id:'ap-total',label:'Total accounts payable',codes:['2000'],current:outstandingAP8(),budget:outstandingAP8()*.95,prior:outstandingAP8()*.92,total:true}]);return S.investments.map(inv=>({id:inv.id,label:inv.issuer,codes:['1510','4200'],current:inv.accrued,budget:inv.principal*inv.apy/100/12,prior:inv.accrued*.91,meta:`${inv.apy.toFixed(2)}% · ${inv.currency} · ${inv.entity}`})).concat([{id:'yield-total',label:'Total accrued investment income',codes:['1510','4200'],current:S.investments.reduce((s,x)=>s+x.accrued*fx8(x.currency),0),budget:S.investments.reduce((s,x)=>s+x.principal*x.apy/100/12*fx8(x.currency),0),prior:S.investments.reduce((s,x)=>s+x.accrued*fx8(x.currency),0)*.91,total:true}])}
function reportLineTransactions8(type,row){if(type==='ar'){const c=customer8(row.id);return c?S.invoices.filter(x=>x.customerId===c.id).map(x=>({date:x.date,journal:x.journal,reference:x.id,description:`Invoice · ${x.project}`,source:'Receivables',project:x.project,debit:x.total,credit:x.total-x.outstanding,status:x.status})):S.invoices.map(x=>({date:x.date,journal:x.journal,reference:x.id,description:`${customer8(x.customerId)?.name} · ${x.project}`,source:'Receivables',project:x.project,debit:x.total,credit:x.total-x.outstanding,status:x.status}))}if(type==='ap'){const v=vendor8(row.id);return v?S.bills.filter(x=>x.vendorId===v.id).map(x=>({date:x.date,journal:x.journal,reference:x.id,description:`${x.invoice} · ${x.project}`,source:'Payables',project:x.project,debit:x.total-x.outstanding,credit:x.total,status:x.status})):S.bills.map(x=>({date:x.date,journal:x.journal,reference:x.id,description:`${vendor8(x.vendorId)?.name} · ${x.invoice}`,source:'Payables',project:x.project,debit:x.total-x.outstanding,credit:x.total,status:x.status}))}if(type==='yield'){const inv=S.investments.find(x=>x.id===row.id);return inv?(inv.daily?.length?inv.daily.slice(-12):investmentSeries8(inv,12)).map((x,i)=>({date:x.date,journal:S.journals.find(j=>j.sourceId===inv.id&&j.date===x.date)?.id||`ACCR-DRAFT-${i+1}`,reference:inv.id,description:`Daily accrual · ${inv.issuer}`,source:'Investments',project:inv.entity,debit:x.amount,credit:x.amount,status:'Calculated'})):S.investments.map(x=>({date:'2026-08-01',journal:S.journals.find(j=>j.sourceId===x.id)?.id||'Pending',reference:x.id,description:x.issuer,source:'Investments',project:x.entity,debit:x.accrued,credit:x.accrued,status:x.status}))}return journalTransactionsForAccounts8(row.codes)}
function reportKpis8(type){const data=reportDataset8(type),total=data.find(x=>x.total)?.current??data.reduce((s,x)=>s+n8(x.current),0),prior=data.find(x=>x.total)?.prior??data.reduce((s,x)=>s+n8(x.prior),0),budget=data.find(x=>x.total)?.budget??data.reduce((s,x)=>s+n8(x.budget),0),variance=r8(total-budget),tb=trialBalance8(),diff=r8(tb.reduce((s,x)=>s+x.debit-x.credit,0));return [kpi8('Report total',money8(total),reportNames8[type]||reportCatalog8.find(x=>x[0]===type)?.[1],'Selected'),kpi8('Prior period',money8(prior),'Comparative period','Prior'),kpi8('Budget / benchmark',money8(budget),'Current approved basis','Plan'),kpi8('Variance',money8(variance),'Actual less budget',variance>=0?'Favourable':'Review'),kpi8('Ledger integrity',money8(diff),'Debit less credit',Math.abs(diff)<.01?'Balanced':'Exception'),kpi8('Publication status','Draft v10','Prepared from approved ledger','Review')].join('')}
function reportLetterhead8(){const l=S.settings.letterhead;return `<header class="v8-letterhead"><div class="brandname">matanho<small>${esc8(l.descriptor)}</small></div><div class="meta"><strong>${esc8(l.legalName)}</strong>${esc8(l.address)}<br>${esc8(l.email)}<br>${esc8(l.registration)} · ${esc8(l.tax)}</div></header>`}
function statementRows8(type){const data=reportDataset8(type),expanded=new Set(S.ui.reportExpanded||[]);if(type==='tb')return data.map(r=>`<tr class="report-line ${r.total?'total':''}" data-action="v8-toggle-report-line" data-id="${r.id}"><td><span class="v8-link">${expanded.has(r.id)?'−':'+'}</span> ${esc8(r.label)}</td><td>${r.debit?money8(r.debit):'—'}</td><td>${r.credit?money8(r.credit):'—'}</td><td>${money8(r.debit-r.credit)}</td><td>—</td><td>${badge8('Posted')}</td></tr>${expanded.has(r.id)?reportDrillRow8(type,r):''}`).join('');return data.map(r=>{const variance=r8(n8(r.current)-n8(r.budget)),pct=Math.abs(r.budget)>.01?variance/Math.abs(r.budget)*100:0;return `<tr class="report-line ${r.total?'total':''}" data-action="v8-toggle-report-line" data-id="${r.id}"><td><span class="v8-link">${expanded.has(r.id)?'−':'+'}</span> ${esc8(r.label)}${r.meta?`<span class="v8-sub">${esc8(r.meta)}</span>`:''}</td><td>${money8(r.current)}</td><td>${money8(r.prior)}</td><td>${money8(r.budget)}</td><td>${money8(variance)}</td><td>${pct.toFixed(1)}%</td></tr>${expanded.has(r.id)?reportDrillRow8(type,r):''}`}).join('')}
function reportDrillRow8(type,row){const tx=reportLineTransactions8(type,row).slice(0,18),rows=tx.map(x=>`<tr data-action="${x.journal&&x.journal.startsWith('JE-')?'v8-journal-detail':'v8-report-transaction'}" data-id="${x.journal||x.reference}"><td>${date8(x.date)}</td><td class="v8-link">${esc8(x.journal||'—')}</td><td>${esc8(x.reference||'')}</td><td>${esc8(x.description)}</td><td>${esc8(x.source)}</td><td>${esc8(x.project)}</td><td>${x.debit?money8(x.debit):'—'}</td><td>${x.credit?money8(x.credit):'—'}</td><td>${badge8(x.status||'Posted')}</td></tr>`).join('');return `<tr class="drill"><td colspan="6"><div style="padding:11px 12px"><div style="display:flex;justify-content:space-between;gap:10px;margin-bottom:8px"><div><strong>Contributing transactions</strong><span class="v8-sub">Click any journal to continue the report-to-ledger-to-source audit trail.</span></div>${btn8('Open full ledger','v8-go-page','small soft','ledger')}</div>${table8(['Date','Journal','Reference','Description','Source','Dimension','Debit','Credit','Status'],rows||'<tr><td colspan="9">No underlying transactions.</td></tr>','900px')}</div></td></tr>`}
function reportSheet8(type=S.ui.report){const title=reportNames8[type]||reportCatalog8.find(x=>x[0]===type)?.[1]||'Financial Report',isTb=type==='tb';return `<article class="v8-report-sheet" id="v8ReportSheet">${reportLetterhead8()}<div class="v8-report-title"><div><div class="v8-eyebrow">Governed financial statement</div><h2>${esc8(title)}</h2><p>${esc8(S.ui.reportEntity)} · ${esc8(S.ui.reportPeriod)} · ${esc8(S.ui.reportCurrency)} presentation · ${esc8(S.ui.reportBasis)} basis</p></div><div class="version"><strong>Draft ledger snapshot</strong><br>Version 10 · ${new Date().toLocaleString()}<br>Report ID FIN-${type.toUpperCase()}-2026-07</div></div><table class="v8-statement"><thead><tr><th>Account / line item</th>${isTb?'<th>Debit</th><th>Credit</th><th>Net</th><th>Reference</th><th>Status</th>':'<th>Actual</th><th>Prior</th><th>Budget</th><th>Variance</th><th>Variance %</th>'}</tr></thead><tbody>${statementRows8(type)}</tbody></table><div class="v8-report-note"><strong>Basis of preparation and control conclusion.</strong> Prepared from approved and posted general-ledger balances under the selected entity, period, currency and dimensional filters. Transaction-currency values are translated using the rate stored with each journal. Report lines are drillable to immutable journal lines and source sub-ledgers. The trial balance must remain balanced before publication.</div><div class="v8-report-signoff"><div class="v8-sign"><strong>Farai Mapfumo</strong><span>Prepared by · Financial Controller</span></div><div class="v8-sign"><strong>Tariro Moyo</strong><span>Reviewed by · Finance Director</span></div><div class="v8-sign"><strong>${state.role==='CEO'?'Tinashe Matanho':'Pending executive approval'}</strong><span>Approved by · Executive authority</span></div></div><footer style="display:flex;justify-content:space-between;border-top:1px solid #dbe4ee;padding:12px 36px 18px;font-size:10px;color:#708096"><span>Confidential · Controlled copy · Generated from Matanho Accounting</span><span>Page 1 of 1</span></footer></article>`}
function reportsPage8(){return `<div class="v8-page">${head8('Governed reporting','Financial Reports & Statement Builder','Professional, letterheaded and fully drillable financial, sub-ledger and treasury reports with dimensional filters, comparative analysis and controlled distribution.',btn8('Edit letterhead','v8-edit-letterhead')+btn8('Email secure link','v8-email-report','soft')+btn8('Preview report','v8-preview-report','primary',S.ui.report))}<div class="v8-filterbar">${field8('Entity / fund',select8('v8ReportEntity',['All entities','Group consolidated','Matanho Capital Partners','Growth Fund I','MFI Entity','Pension Liquidity'],S.ui.reportEntity))}${field8('Period',select8('v8ReportPeriod',['Jul 2026','Q2 2026','FY 2026 YTD','Custom range'],S.ui.reportPeriod))}${field8('Currency',select8('v8ReportCurrency',['USD','ZWG','Functional currency','Presentation currency'],S.ui.reportCurrency))}${field8('Basis',select8('v8ReportBasis',['Accrual','Cash','Regulatory','Tax'],S.ui.reportBasis))}${field8('Scenario',select8('v8ReportScenario',['Actual vs prior and budget','Actual vs forecast','All comparisons'],'Actual vs prior and budget'))}${field8('Dimension',select8('v8ReportDimension',['All dimensions','Branch','Department','Fund','Project','Product'],'All dimensions'))}</div><div class="v8-grid v8-kpis">${reportKpis8(S.ui.report)}</div><div class="v8-report-layout"><aside class="v8-report-rail">${reportCatalog8.map(x=>`<button class="v8-report-item ${S.ui.report===x[0]?'active':''}" data-action="v8-select-report" data-id="${x[0]}"><strong>${x[1]}</strong><span>${x[2]}</span></button>`).join('')}</aside><div class="v8-report-document">${reportSheet8(S.ui.report)}</div><aside class="v8-stack">${panel8('Report controls','Versioned presentation and commentary settings',`${field8('Template',select8('v8ReportTemplate',['Matanho executive standard','Board pack','Regulatory filing','Audit working paper'],'Matanho executive standard'))}${field8('Rounding',select8('v8ReportRounding',['Exact','Nearest 1,000','Nearest million'],'Exact'))}${field8('Comparatives',select8('v8ReportComparatives',['Prior + budget','Prior only','Budget only','Custom'],'Prior + budget'))}<div class="v8-field"><label>Management commentary</label><textarea class="v8-textarea" id="v8ReportCommentary">Operating performance remained above plan while finance attention remains focused on overdue receivables, bank exceptions and investment maturity liquidity.</textarea></div>`,btn8('Save version','v8-save-report','small')+btn8('Submit for approval','v8-submit-report','small primary'))}${panel8('Publication controls','All conditions required before distribution',`<div class="v8-validation-list"><div class="v8-validation">Trial balance balanced to ${money8(trialBalance8().reduce((s,x)=>s+x.debit-x.credit,0))}</div><div class="v8-validation ${S.reconciliation.signedOff?'':'warn'}">Bank reconciliation: ${S.reconciliation.signedOff?'signed off':'sign-off outstanding'}</div><div class="v8-validation">FX rates retained with source and date</div><div class="v8-validation">Letterhead and report version controlled</div><div class="v8-validation warn">Executive approval pending</div></div>`)}${panel8('Output and delivery','Preview, export and secure email',btn8('PDF preview','v8-preview-report','small soft',S.ui.report)+' '+btn8('Excel workbook','v8-export','small')+' '+btn8('Email report','v8-email-report','small primary'))}</aside></div></div>`}
function previewReport8(type=S.ui.report){S.ui.previewScale=1;save8();openModal(reportNames8[type]||'Report preview','Controlled preview · maximise, minimise and zoom without changing the report version',`<div class="v8-preview-toolbar" style="justify-content:flex-end;margin-bottom:10px">${btn8('− Zoom out','v8-preview-zoom-out','small')}${btn8('Reset','v8-preview-reset','small')}${btn8('+ Zoom in','v8-preview-zoom-in','small')}${btn8('Maximise','v8-preview-max','small soft')}${btn8('Minimise','v8-preview-min','small soft')}</div><div style="overflow:auto;background:#edf2f7;padding:14px;border-radius:12px;min-height:480px"><div class="v8-preview-stage" id="v8PreviewStage">${reportSheet8(type)}</div></div>`,btn8('Close','v8-close-modal')+btn8('Email secure link','v8-email-report','soft')+btn8('Download controlled PDF','v8-export','primary'),true);setTimeout(applyPreviewScale8,0)}
function applyPreviewScale8(){const s=q('#v8PreviewStage');if(s)s.style.transform=`scale(${S.ui.previewScale||1})`;if(s)s.style.marginBottom=`${Math.max(0,((S.ui.previewScale||1)-1)*s.getBoundingClientRect().height)}px`}
function letterheadModal8(){const l=S.settings.letterhead;openModal('Edit report letterhead','Minimal institutional identity used across financial statements, invoices, quotations and controlled documents',`<div class="v8-filterbar" style="grid-template-columns:repeat(2,minmax(0,1fr))">${field8('Legal entity name',input8('v8LetterLegal',l.legalName))}${field8('Descriptor',input8('v8LetterDescriptor',l.descriptor))}${field8('Address',input8('v8LetterAddress',l.address))}${field8('Registration',input8('v8LetterRegistration',l.registration))}${field8('Tax identifier',input8('v8LetterTax',l.tax))}${field8('Finance email',input8('v8LetterEmail',l.email,'email'))}</div><div class="v8-report-document" style="margin-top:12px"><article class="v8-report-sheet" style="min-width:650px">${reportLetterhead8()}<div class="v8-report-title"><div><div class="v8-eyebrow">Preview</div><h2>Controlled document title</h2><p>Period, entity and document metadata</p></div><div class="version">Version 1<br>Controlled copy</div></div></article></div>`,btn8('Cancel','v8-close-modal')+btn8('Review letterhead','v8-review-letterhead','primary'),true)}
function documentBody8(doc){const inv=S.invoices.find(x=>x.id===doc?.record),bill=S.bills.find(x=>x.id===doc?.record);if(inv){const c=customer8(inv.customerId);return `${reportLetterhead8()}<div class="v8-report-title"><div><div class="v8-eyebrow">Tax invoice</div><h2>${inv.id}</h2><p>Invoice date ${date8(inv.date)} · Due ${date8(inv.due)} · ${inv.currency}</p></div><div class="version"><strong>${esc8(c?.name)}</strong><br>${esc8(c?.email)}<br>Payment terms ${c?.terms} days</div></div><table class="v8-statement"><thead><tr><th>Description</th><th>Project</th><th>Net</th><th>VAT</th><th>Total</th><th>Outstanding</th></tr></thead><tbody><tr><td>Professional services and implementation support</td><td>${esc8(inv.project)}</td><td>${money8(inv.net,inv.currency)}</td><td>${money8(inv.vat,inv.currency)}</td><td>${money8(inv.total,inv.currency)}</td><td>${money8(inv.outstanding,inv.currency)}</td></tr><tr class="total"><td colspan="4">Amount due</td><td colspan="2">${money8(inv.outstanding,inv.currency)}</td></tr></tbody></table><div class="v8-report-note">Please quote ${inv.id} on payment. Bank details are issued through the secure customer portal and controlled invoice PDF.</div>`}if(bill){const v=vendor8(bill.vendorId);return `${reportLetterhead8()}<div class="v8-report-title"><div><div class="v8-eyebrow">Supplier invoice review</div><h2>${bill.id}</h2><p>${esc8(v?.name)} · Vendor invoice ${esc8(bill.invoice)}</p></div><div class="version">Match: ${esc8(bill.match)}<br>Journal ${esc8(bill.journal)}<br>${esc8(bill.status)}</div></div><table class="v8-statement"><thead><tr><th>Description</th><th>Project</th><th>Net</th><th>Input VAT</th><th>Gross</th><th>Outstanding</th></tr></thead><tbody><tr><td>Supplier goods or services</td><td>${esc8(bill.project)}</td><td>${money8(bill.net,bill.currency)}</td><td>${money8(bill.vat,bill.currency)}</td><td>${money8(bill.total,bill.currency)}</td><td>${money8(bill.outstanding,bill.currency)}</td></tr></tbody></table>`}return `${reportLetterhead8()}<div class="v8-report-title"><div><div class="v8-eyebrow">Controlled document</div><h2>${esc8(doc?.name||'Document preview')}</h2><p>${esc8(doc?.type||'Document')} · ${esc8(doc?.record||'')}</p></div><div class="version">Version ${doc?.version||1}<br>${esc8(doc?.status||'Draft')}<br>${esc8(doc?.updated||'')}</div></div><div class="v8-report-note">This preview retains document metadata, version history, approval evidence and secure distribution controls.</div>`}
function previewDocument8(id){const doc=S.documents.find(x=>x.id===id)||{id,type:'Document',record:id,name:id,status:'Draft',version:1,updated:new Date().toLocaleString()};S.ui.previewScale=1;save8();openModal(doc.name,`${doc.type} · ${doc.record} · version ${doc.version}`,`<div class="v8-preview-toolbar" style="justify-content:flex-end;margin-bottom:10px">${btn8('− Zoom out','v8-preview-zoom-out','small')}${btn8('Reset','v8-preview-reset','small')}${btn8('+ Zoom in','v8-preview-zoom-in','small')}${btn8('Maximise','v8-preview-max','small soft')}${btn8('Minimise','v8-preview-min','small soft')}</div><div style="overflow:auto;background:#edf2f7;padding:14px;border-radius:12px"><div class="v8-preview-stage" id="v8PreviewStage"><article class="v8-report-sheet">${documentBody8(doc)}<footer style="display:flex;justify-content:space-between;border-top:1px solid #dbe4ee;padding:12px 36px 18px;font-size:10px;color:#708096"><span>Controlled document · ${esc8(doc.id)}</span><span>Page 1 of 1</span></footer></article></div></div>`,btn8('Close','v8-close-modal')+btn8('Email document','v8-email-document','soft',doc.id)+btn8('Download PDF','v8-export','primary'),true);setTimeout(applyPreviewScale8,0)}

