function paymentRunPage8(){const eligible=S.bills.filter(x=>x.outstanding>0),selected=eligible.filter(x=>S.ui.paymentSelection.includes(x.id)),total=selected.reduce((s,x)=>s+x.outstanding,0),rows=eligible.map(x=>{const v=vendor8(x.vendorId),sel=S.ui.paymentSelection.includes(x.id),blocked=/Exception/i.test(x.status);return `<tr data-id="${x.id}"><td><button class="v8-btn small" data-action="v8-payment-select" data-id="${x.id}" ${blocked?'disabled':''}>${sel?'Selected':'Select'}</button></td><td class="v8-link" data-action="v8-bill-detail" data-id="${x.id}">${x.id}</td><td class="v8-link" data-action="v8-vendor-detail" data-id="${v?.id}">${esc8(v?.name)}</td><td>${esc8(x.invoice)}</td><td>${date8(x.due)}</td><td>${esc8(x.project)}</td><td>${x.currency}</td><td class="num">${money8(x.outstanding,x.currency)}</td><td>${badge8(v?.bank?'Verified':'Blocked')}</td><td>${badge8(x.match)}</td><td>${badge8(blocked?'Hold':'Eligible')}</td></tr>`}).join('');return `<div class="v8-page">${head8('Treasury execution','Supplier Payment Run','Select approved obligations, validate beneficiary and tax controls, obtain independent authority and generate auditable cashbook and bank-file records.',btn8('Back to payables','v8-go-page','','payables')+btn8('Validate population','v8-payment-validate','soft')+btn8('Preview bank file','v8-payment-bankfile')+btn8('Submit for approval','v8-payment-submit','primary'))}<div class="v8-workflow-banner"><div><b>1 · Select</b><span>Approved, due and unblocked bills</span></div><div><b>2 · Validate</b><span>Beneficiary, duplicate, WHT and funding</span></div><div><b>3 · Approve</b><span>Independent treasury authority</span></div><div><b>4 · Post</b><span>DR payables · CR bank per bill</span></div></div><div class="v8-filterbar">${field8('Settlement bank',select8('v8PaymentBank',S.banks.map(b=>[b.id,`${b.name} · ${b.currency}`]),S.banks[0].id))}${field8('Payment date',input8('v8PaymentDate',new Date().toISOString().slice(0,10),'date'))}${field8('Currency',select8('v8PaymentCurrency',['USD','ZWG','ZAR'],'USD'))}${field8('Due horizon',select8('v8PaymentDue',['All due dates','Due now','Next 7 days','Next 30 days'],'All due dates'))}${field8('Vendor',select8('v8PaymentVendor',['All vendors',...S.vendors.map(x=>x.name)],'All vendors'))}${field8('Search',input8('v8PaymentSearch','','search','Bill, vendor, invoice or project'))}</div><div class="v8-payment-summary"><div><span>Selected bills</span><strong>${selected.length}</strong></div><div><span>Selected value</span><strong>${money8(total)}</strong></div><div><span>Funding after run</span><strong>${money8(currentBankBalance8(value8('v8PaymentBank')||S.banks[0].id)-total)}</strong></div><div><span>Validation</span><strong>${S.ui.paymentValidated?'Passed':'Required'}</strong></div></div><div style="margin-top:12px" class="v8-split"><div>${panel8('Payment population','Select a bill or inspect its vendor and source-document history',table8(['Select','Bill','Vendor','Invoice','Due','Project / fund','Currency','Outstanding','Bank','Match','Control'],rows,'1240px'),btn8(S.ui.paymentSelection.length===eligible.filter(x=>!/Exception/i.test(x.status)).length?'Clear eligible':'Select all eligible','v8-payment-select-all','small soft'))}</div><aside class="v8-stack">${panel8('Validation controls','All checks must pass before submission',`<div class="v8-validation-list"><div class="v8-validation">Beneficiary bank ownership verified against vendor master</div><div class="v8-validation">Duplicate bill and payment reference checks</div><div class="v8-validation">Withholding-tax and VAT treatment evaluated</div><div class="v8-validation">Cashbook currency and funding sufficiency checked</div><div class="v8-validation ${S.ui.paymentValidated?'':'warn'}">Population validation: ${S.ui.paymentValidated?'passed':'not yet run'}</div></div>`)}${panel8('Approval result','What happens after independent approval',`<div class="v8-callout"><strong>Per approved bill</strong>DR Trade payables control; CR selected bank. Outstanding balances, cashbook rows and linked journals update atomically.</div><div class="v8-callout warn" style="margin-top:8px"><strong>Bank file</strong>The ISO 20022 / CSV payment instruction remains a controlled preview until approval.</div>`)}</aside></div></div>`}
function previewPaymentBankFile8(){const bills=S.bills.filter(x=>S.ui.paymentSelection.includes(x.id));if(!bills.length)throw new Error('Select at least one supplier bill.');openModal('Payment instruction preview',`${bills.length} beneficiary instruction(s) · controlled draft`,`<div class="v8-preview-toolbar" style="justify-content:flex-end;margin-bottom:10px">${btn8('− Zoom out','v8-preview-zoom-out','small')}${btn8('Reset','v8-preview-reset','small')}${btn8('+ Zoom in','v8-preview-zoom-in','small')}${btn8('Maximise','v8-preview-max','small soft')}${btn8('Minimise','v8-preview-min','small soft')}</div><div style="overflow:auto;background:#edf2f7;padding:14px;border-radius:12px"><div class="v8-preview-stage" id="v8PreviewStage"><article class="v8-report-sheet">${reportLetterhead8()}<div class="v8-report-title"><div><div class="v8-eyebrow">Supplier payment instruction</div><h2>Bank File Control Preview</h2><p>Unapproved draft · ${date8(new Date().toISOString().slice(0,10))}</p></div><div class="version">Draft<br>Controlled</div></div><table class="v8-statement"><thead><tr><th>Vendor</th><th>Bill</th><th>Beneficiary bank</th><th class="num">Amount</th></tr></thead><tbody>${bills.map(b=>`<tr><td>${esc8(vendor8(b.vendorId)?.name)}</td><td>${b.id}</td><td>${esc8(vendor8(b.vendorId)?.bank)}</td><td class="num">${money8(b.outstanding,b.currency)}</td></tr>`).join('')}<tr class="total"><td colspan="3">Total instruction</td><td class="num">${money8(bills.reduce((s,b)=>s+b.outstanding,0))}</td></tr></tbody></table><div class="v8-report-note"><strong>Control state</strong>No bank instruction is released until maker-checker approval is complete.</div></article></div></div>`,btn8('Close','v8-close-modal')+btn8('Submit for approval','v8-payment-submit','primary'),true);setTimeout(applyPreviewScale8,0)}

