 const daily=navGroups.find(x=>x[0]==='Daily accounting');if(daily){if(!daily[1].some(x=>x[0]==='timesheets'))daily[1].push(['timesheets','Project Timesheets','calendar']);if(!daily[1].some(x=>x[0]==='recurring'))daily[1].push(['recurring','Recurring Schedules','calendar'])}
