let C;try{C=JSON.parse(localStorage.getItem('matanho-close-v11')||'null')||seed()}catch{C=seed()}if(C.version!=='11.0.0')C=seed();const save=()=>{try{localStorage.setItem('matanho-close-v11',JSON.stringify(C))}catch{}};
const ws=id=>C.ws.find(x=>x.id===id),task=id=>C.tasks.find(x=>x.id===id),ex=id=>C.ex.find(x=>x.id===id),user=()=>typeof state!=='undefined'&&state.role==='CEO'?'Tinashe Matanho':'Tariro Moyo';
const sclass=s=>/Complete|Approved|Resolved|Passed|Locked/i.test(s)?'ok':/Blocked|Critical|Failed/i.test(s)?'bad':/Pending|Review|progress|started|Investigating|Open|High/i.test(s)?'review':'blue';const badge=s=>`<span class="v11-status ${sclass(s)}">${esc(s)}</span>`;const owner=n=>`<div class="v11-owner"><img src="${pic(n)}"><div><strong>${esc(n)}</strong><span>Finance team</span></div></div>`;const btn=(l,a,k='',id='',x='')=>`<button class="v11-btn ${k}" data-v11="${a}" ${id?`data-id="${esc(id)}"`:''} ${x}>${l}</button>`;const field=(l,h)=>`<div class="v11-field"><label>${l}</label>${h}</div>`;
const done=()=>C.tasks.filter(t=>t.status==='Complete').length,openEx=()=>C.ex.filter(x=>x.status!=='Resolved'),evidence=()=>{const a=C.tasks.filter(t=>t.id!=='GV-03');return Math.round(a.reduce((s,t)=>s+Math.min(t.evidence,t.required),0)/Math.max(1,a.reduce((s,t)=>s+t.required,0))*100)},progress=t=>t.status==='Complete'?100:Math.round(t.checklist.filter(Boolean).length/Math.max(1,t.checklist.length)*82+t.evidence/Math.max(1,t.required)*18),stats=id=>{const a=C.tasks.filter(t=>t.ws===id);return{a,done:a.filter(t=>t.status==='Complete').length,blocked:a.filter(t=>t.status==='Blocked').length,p:Math.round(a.reduce((s,t)=>s+progress(t),0)/a.length),ev:Math.round(a.reduce((s,t)=>s+Math.min(t.evidence,t.required),0)/a.reduce((s,t)=>s+t.required,0)*100)}};const readiness=()=>Math.round(done()/C.tasks.length*65+evidence()*.2+C.sign.filter(x=>x.status==='Approved').length/C.sign.length*15);
const crumb=a=>`<div class="v11-crumb"><button data-v11="home">Period Close</button>${a.map((x,i)=>`<span>›</span>${i===a.length-1?`<b>${esc(x.l)}</b>`:`<button data-v11="${x.a}" data-id="${x.id||''}">${esc(x.l)}</button>`}`).join('')}</div>`;const head=(e,t,d,a='',c='')=>`${c}<div class="v11-head"><div><div class="v11-eye">${e}</div><h1>${t}</h1><p>${d}</p></div><div class="v11-actions">${a}</div></div>`;const panel=(t,s,b,a='')=>`<section class="v11-panel"><header class="v11-panel-head"><div><h2>${t}</h2><p>${s}</p></div>${a}</header><div class="v11-panel-body">${b}</div></section>`;const kpi=(l,v,m,p,a,id='')=>`<div class="v11-kpi" data-v11="${a}" ${id?`data-id="${id}"`:''}><span>${l}</span><strong>${v}</strong><em>${m}</em><div class="v11-meter"><i style="width:${Math.max(0,Math.min(100,p))}%"></i></div></div>`;
const stages=()=>{const crit=openEx().filter(x=>x.severity==='Critical').length,a=[['Prepare',100],['Reconcile',83],['Adjust',crit?62:100],['Review',readiness()>80?82:48],['Report',stats('reporting').p],['Lock',C.locked?100:18]];return `<div class="v11-stage">${a.map((x,i)=>`<div class="v11-step ${x[1]===100?'done':i===3?'active':crit&&i===2?'blocked':''}"><i>${x[1]===100?'✓':i+1}</i><strong>${x[0]}</strong><span>${x[1]}% complete</span></div>`).join('')}</div>`};
const filtered=()=>C.tasks.filter(t=>(!C.filters.search||`${t.id} ${t.name} ${t.owner} ${t.source}`.toLowerCase().includes(C.filters.search.toLowerCase()))&&(C.filters.ws==='All workstreams'||ws(t.ws).name===C.filters.ws)&&(C.filters.status==='All statuses'||t.status===C.filters.status)&&(C.filters.owner==='All owners'||t.owner===C.filters.owner)&&(C.filters.priority==='All priorities'||t.priority===C.filters.priority));
const table=(a=filtered())=>`<div class="v11-table-wrap"><table class="v11-table"><thead><tr><th>Task</th><th>Workstream</th><th>Owner</th><th>Due</th><th>Dependency</th><th>Evidence</th><th>Progress</th><th>Priority</th><th>Status</th></tr></thead><tbody>${a.map(t=>`<tr data-v11="task" data-id="${t.id}"><td class="v11-link">${t.id}<span class="v11-sub">${esc(t.name)}</span></td><td>${ws(t.ws).name}</td><td>${owner(t.owner)}</td><td>${t.due}</td><td>${t.dependency}</td><td>${t.evidence}/${t.required}</td><td><div class="v11-progress" style="width:85px;margin:0"><i style="width:${progress(t)}%"></i></div><span class="v11-sub">${progress(t)}%</span></td><td>${badge(t.priority)}</td><td>${badge(t.status)}</td></tr>`).join('')}</tbody></table></div>`;
const chart=()=>`<div class="v11-chart" data-v11="analytics"><svg viewBox="0 0 110 68" preserveAspectRatio="none"><defs><linearGradient id="v11Area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#0074ff" stop-opacity=".28"/><stop offset="1" stop-color="#00c8ff" stop-opacity="0"/></linearGradient></defs>${[16,32,48].map(y=>`<line class="gridline" x1="8" y1="${y}" x2="108" y2="${y}"/>`).join('')}<polygon class="area" points="10,66 10,22 27,30 44,36 61,33 78,42 95,46 95,66"/><polyline class="line" points="10,22 27,30 44,36 61,33 78,42 95,46"/>${[22,30,36,33,42,46].map((y,i)=>`<circle class="dot" cx="${10+i*17}" cy="${y}" r="2.3"/>`).join('')}<line x1="8" y1="50" x2="108" y2="50" stroke="#ff9f0a" stroke-dasharray="3 3"/></svg><div class="v11-axis" style="grid-template-columns:repeat(6,1fr)">${['Feb','Mar','Apr','May','Jun','Jul'].map(x=>`<span>${x}</span>`).join('')}</div></div>`;
function home(){const pc=Math.round(done()/C.tasks.length*100),crit=openEx().filter(x=>x.severity==='Critical').length,next=C.tasks.find(t=>t.status==='Blocked')||C.tasks.find(t=>t.status==='In review');return `<div class="v11">${head('Governed financial close','Month-End Close Control Centre','A decision-oriented workspace that answers what is complete, what is blocking publication, who owns the next action and whether July 2026 can be safely locked.',btn('Close calendar','calendar','soft')+btn('CFO brief','brief')+btn('Run control scan','scan')+btn('Submit close','submit','primary'))}${stages()}<div class="v11-kpis">${kpi('Close completion',`${pc}%`,`${done()} of ${C.tasks.length} tasks`,pc,'analytics')}${kpi('Critical blockers',crit,`${openEx().length} open exceptions`,crit?42:100,'exceptions')}${kpi('Evidence coverage',`${evidence()}%`,`${C.docs.length} governed files`,evidence(),'evidence')}${kpi('Control readiness',`${readiness()}%`,`Last scan ${C.scan}`,readiness(),'analytics')}${kpi('Review chain',`${C.sign.filter(x=>x.status==='Approved').length}/${C.sign.length}`,`${C.sign.filter(x=>x.status==='Pending').length} pending`,C.sign.filter(x=>x.status==='Approved').length/C.sign.length*100,'signoffs')}${kpi('Period lock',C.locked?'Locked':'Unavailable',`${C.tasks.filter(t=>t.priority==='Critical'&&t.id!=='GV-03'&&t.status!=='Complete').length} critical tasks remain`,C.locked?100:readiness(),'lock')}</div><div class="v11-answer-grid"><div class="v11-answer" data-v11="ws" data-id="gl"><div class="v11-answer-top"><div><h3>Are the books balanced?</h3><p>Trial balance and journal integrity.</p></div>${badge('Passed')}</div><div class="value">USD 0.00 difference</div><div class="next">2 GL actions remain</div></div><div class="v11-answer" data-v11="ws" data-id="cash"><div class="v11-answer-top"><div><h3>Is cash fully proven?</h3><p>External statements and ledger balances.</p></div>${badge(task('CA-01').status==='Complete'?'Passed':'Review')}</div><div class="value">2 of 3 accounts signed</div><div class="next">USD 185 adjustment required</div></div><div class="v11-answer" data-v11="ws" data-id="tax"><div class="v11-answer-top"><div><h3>Are taxes ready?</h3><p>VAT, WHT and source evidence.</p></div>${badge(task('TX-01').status==='Complete'?'Passed':'Review')}</div><div class="value">96% VAT readiness</div><div class="next">One supplier document blocks filing</div></div><div class="v11-answer" data-v11="lock"><div class="v11-answer-top"><div><h3>Can we lock July?</h3><p>Mandatory gates and approvals.</p></div>${badge(C.locked?'Locked':'Blocked')}</div><div class="value">${C.locked?'Yes · locked':'No · not yet'}</div><div class="next">Open exact lock gates</div></div></div><div class="v11-layout"><div class="v11-stack">${panel('Workstream control map','Open a secondary workspace for task status, dependencies, evidence and reviewer conclusion.',`<div class="v11-workstreams">${C.ws.map(w=>{const s=stats(w.id);return `<div class="v11-ws" data-v11="ws" data-id="${w.id}" style="--ws:${w.color}"><div class="v11-ws-top"><div><h3>${w.name}</h3><p>${w.purpose}</p></div>${badge(s.blocked?`${s.blocked} blocked`:`${s.done}/${s.a.length} done`)}</div><div class="v11-progress"><i style="width:${s.p}%"></i></div><div class="v11-ws-meta"><div><span>Progress</span><strong>${s.p}%</strong></div><div><span>Evidence</span><strong>${s.ev}%</strong></div><div><span>Owner</span><strong>${w.owner.split(' ')[0]}</strong></div></div></div>`}).join('')}</div>`)}${panel('Close task register','Filters persist. Every row opens a unique third-level task workspace.',`<div class="v11-filter">${field('Search',`<input class="v11-input" data-v11-filter="search" value="${esc(C.filters.search)}" placeholder="Task, owner or source">`)}${field('Workstream',`<select class="v11-select" data-v11-filter="ws">${['All workstreams',...C.ws.map(x=>x.name)].map(x=>`<option ${C.filters.ws===x?'selected':''}>${x}</option>`).join('')}</select>`)}${field('Status',`<select class="v11-select" data-v11-filter="status">${['All statuses','Complete','In review','In progress','Blocked','Not started'].map(x=>`<option ${C.filters.status===x?'selected':''}>${x}</option>`).join('')}</select>`)}${field('Owner',`<select class="v11-select" data-v11-filter="owner">${['All owners',...new Set(C.tasks.map(x=>x.owner))].map(x=>`<option ${C.filters.owner===x?'selected':''}>${x}</option>`).join('')}</select>`)}${field('Priority',`<select class="v11-select" data-v11-filter="priority">${['All priorities','Critical','High','Medium'].map(x=>`<option ${C.filters.priority===x?'selected':''}>${x}</option>`).join('')}</select>`)}</div>${table()}`)}</div><aside class="v11-stack"><div class="v11-next"><div class="label">Recommended next action</div><h3>${next?.name||'Review final close pack'}</h3><p>${next?`${next.id} · ${ws(next.ws).name} · ${next.owner}. ${next.note}`:'All tasks complete.'}</p><div class="buttons">${next?btn('Open task','task','primary small',next.id):btn('Open sign-offs','signoffs','primary small')}${btn('Explain priority','why','small')}</div></div>${panel('Close duration trend','Elapsed business days from cut-off to lock.',chart(),btn('Analytics','analytics','small soft'))}${panel('Immediate control attention','Risk-ranked items that prevent a clean close.',`<div class="v11-control">${openEx().map(x=>`<div class="v11-control-row" data-v11="exception" data-id="${x.id}" style="cursor:pointer"><div><strong>${x.id} · ${x.title}</strong><span>${x.owner} · ${x.age} · ${x.source}</span></div>${badge(x.severity)}</div>`).join('')}</div>`,btn('All exceptions','exceptions','small soft'))}${panel('Recent activity','Tasks, documents, controls and approvals.',`<div class="v11-timeline">${C.activity.map((a,i)=>`<div class="v11-event"><i>${i+1}</i><div><strong>${a.event}</strong><span>${a.time} · ${a.detail}</span></div></div>`).join('')}</div>`)}</aside></div></div>`}
function workstream(){const w=ws(C.selectedWs),s=stats(w.id),open=s.a.filter(t=>t.status!=='Complete');return `<div class="v11">${head('Secondary close workspace',w.name,`${w.purpose} This page combines task status, dependencies, source evidence and the conclusion a reviewer needs before sign-off.`,btn('Back to close','home')+btn('Evidence','evidence','soft')+btn('Send reminder','remind')+btn('Complete eligible','bulk','primary',w.id),crumb([{l:w.name}]))}<div class="v11-kpis">${kpi('Progress',`${s.p}%`,`${s.done}/${s.a.length} tasks`,s.p,'analytics')}${kpi('Open tasks',open.length,`${s.blocked} blocked`,70,'noop')}${kpi('Evidence',`${s.ev}%`,'Required support',s.ev,'evidence')}${kpi('High-risk',s.a.filter(t=>t.priority==='Critical'&&t.status!=='Complete').length,'Priority review',45,'exceptions')}${kpi('Owner capacity','72%',w.owner,72,'owner',w.owner)}${kpi('Conclusion',s.p===100?'Ready':'Not ready','Reviewer sign-off',s.p,'signoffs')}</div><div class="v11-two"><div class="v11-stack">${panel('Workstream tasks','Select a task for checklist, source records, evidence, comments and audit events.',table(s.a))}${panel('Control completion by task','Live progress derived from checklist and evidence.',`<div class="v11-chart" data-v11="analytics"><svg viewBox="0 0 120 75" preserveAspectRatio="none">${[20,40,60].map(y=>`<line class="gridline" x1="18" y1="${y}" x2="116" y2="${y}"/>`).join('')}${s.a.map((t,i)=>`<rect class="bar ${t.status==='Blocked'?'bad':''}" x="${22+i*(90/s.a.length)}" y="${68-progress(t)*.55}" width="${Math.max(7,65/s.a.length)}" height="${progress(t)*.55}"/>`).join('')}</svg><div class="v11-axis" style="grid-template-columns:repeat(${s.a.length},1fr)">${s.a.map(t=>`<span>${t.id}</span>`).join('')}</div></div>`)}</div><aside class="v11-stack">${panel('Workstream conclusion','Controller-ready answer, not a decorative status.',`<div class="v11-note ${s.blocked?'bad':s.p<100?'warn':''}">${s.p===100?`${w.name} is complete with sufficient evidence.`:`${w.name} is ${s.p}% complete. ${open.length} task(s) remain and ${s.blocked} are blocked.`}</div><div class="v11-control" style="margin-top:8px"><div class="v11-control-row"><div><strong>Source integrity</strong><span>Task records linked to source modules</span></div>${badge(s.p>75?'Passed':'Review')}</div><div class="v11-control-row"><div><strong>Evidence sufficiency</strong><span>${s.ev}% complete</span></div>${badge(s.ev===100?'Passed':'Review')}</div><div class="v11-control-row"><div><strong>Independent review</strong><span>${s.p===100?'Available':'Blocked by open tasks'}</span></div>${badge(s.p===100?'Ready':'Blocked')}</div></div>`,open[0]?btn('Open next task','task','primary small',open[0].id):btn('Sign off','signoffs','primary small'))}${panel('Owner and dependencies','Accountability and upstream records.',`${owner(w.owner)}<div class="v11-facts" style="margin-top:9px"><div class="v11-fact"><span>Assigned tasks</span><strong>${s.a.length}</strong></div><div class="v11-fact"><span>Open tasks</span><strong>${open.length}</strong></div><div class="v11-fact"><span>Reviewer</span><strong>Tariro Moyo</strong></div></div><div class="v11-control" style="margin-top:8px">${s.a.slice(0,5).map(t=>`<div class="v11-control-row"><div><strong>${t.id} · ${t.dependency}</strong><span>${t.source}</span></div>${badge(t.status)}</div>`).join('')}</div>`)}</aside></div></div>`}
function taskPage(){const t=task(C.selectedTask),w=ws(t.ws),xs=C.ex.filter(x=>x.task===t.id),ds=C.docs.filter(x=>x.task===t.id),cs=C.comments.filter(x=>x.task===t.id),S=window.MatanhoAccountingV8?.getState?.()||{};const rows=t.source==='Journal Entries'?(S.journals||[]).slice(0,6).map(x=>[x.id,x.description,x.total,x.status]):t.source==='Payables'?(S.bills||[]).slice(0,6).map(x=>[x.id,x.invoice,x.outstanding,x.status]):t.source==='Receivables'?(S.invoices||[]).slice(0,6).map(x=>[x.id,x.project,x.outstanding,x.status]):t.source==='Bank Reconciliation'?(S.reconciliation?.statement||[]).slice(0,6).map(x=>[x.id,x.description,x.amount,x.status]):[];return `<div class="v11">${head('Third-level task workspace',`${t.id} · ${t.name}`,`${w.name} · ${t.control}. The business conclusion, accounting population, evidence and reviewer conversation are kept together.`,btn('Back to workstream','ws','',w.id)+btn('Source module','source','soft',t.source)+btn('Attach evidence','attach')+btn(t.status==='Complete'?'Reopen task':'Mark complete','task-review','primary',t.id),crumb([{l:w.name,a:'ws',id:w.id},{l:t.id}]))}<div class="v11-kpis">${kpi('Progress',`${progress(t)}%`,`${t.checklist.filter(Boolean).length}/${t.checklist.length} steps`,progress(t),'noop')}${kpi('Evidence',`${t.evidence}/${t.required}`,`${ds.length} indexed documents`,t.evidence/t.required*100,'evidence')}${kpi('Priority',t.priority,'Residual control risk',45,'noop')}${kpi('Due',t.due,t.owner,64,'calendar')}${kpi('Exceptions',xs.filter(x=>x.status!=='Resolved').length,xs[0]?.title||'No linked exception',xs.length?42:100,'exceptions')}${kpi('Status',t.status,t.dependency,progress(t),'noop')}</div><div class="v11-two"><div class="v11-stack">${panel('Editable task conclusion','Changes update readiness and the audit history.',`<div class="v11-facts"><div class="v11-fact"><span>Control objective</span><strong>${t.control}</strong></div><div class="v11-fact"><span>Source module</span><strong>${t.source}</strong></div><div class="v11-fact"><span>Dependency</span><strong>${t.dependency}</strong></div></div><div class="v11-filter" style="grid-template-columns:repeat(3,1fr);margin-top:9px">${field('Owner',`<select class="v11-select" id="v11Owner">${[...new Set(C.tasks.map(x=>x.owner))].map(x=>`<option ${x===t.owner?'selected':''}>${x}</option>`).join('')}</select>`)}${field('Status',`<select class="v11-select" id="v11Status">${['Not started','In progress','In review','Blocked','Complete'].map(x=>`<option ${x===t.status?'selected':''}>${x}</option>`).join('')}</select>`)}${field('Due',`<input class="v11-input" id="v11Due" value="${t.due}">`)}</div>${field('Close note',`<textarea class="v11-textarea" id="v11Note">${esc(t.note)}</textarea>`)}<div style="margin-top:8px">${btn('Save changes','task-save','primary small',t.id)}</div>`)}${panel('Control checklist','Each step can be independently completed and reopened.',`<div class="v11-checks">${t.checklist.map((v,i)=>`<div class="v11-check ${v?'done':''}"><button data-v11="check" data-id="${t.id}|${i}">${v?'✓':''}</button><div><strong>${['Population completeness confirmed','Accounting result recalculated','Exceptions investigated and owned','Independent review completed'][i]||`Control step ${i+1}`}</strong><span>${['Source population agrees to scope.','Expected journal or balance impact recalculated.','Every difference has an owner and action.','Reviewer conclusion and timestamp recorded.'][i]||'Configured control step.'}</span></div><em>${v?'Complete':'Open'}</em></div>`).join('')}</div>`)}${panel('Underlying accounting population','Read directly from the current prototype state.',rows.length?`<div class="v11-table-wrap"><table class="v11-table" style="min-width:650px"><thead><tr><th>Record</th><th>Description</th><th>Value</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="v11-link">${r[0]}</td><td>${esc(r[1])}</td><td>${Number(r[2]||0).toLocaleString(undefined,{minimumFractionDigits:2})}</td><td>${badge(r[3])}</td></tr>`).join('')}</tbody></table></div>`:`<div class="v11-note">Open the linked source module to inspect the current accounting population.</div>`,btn('Open source','source','small soft',t.source))}</div><aside class="v11-stack">${panel('Evidence and versions','Files linked specifically to this control.',ds.length?`<div class="v11-evidence" style="grid-template-columns:1fr">${ds.map(d=>`<div class="v11-doc" data-v11="doc" data-id="${d.id}"><i>D</i><strong>${d.name}</strong><span>${d.type} · v${d.version} · ${d.owner}</span><em>${d.status} · ${d.updated}</em></div>`).join('')}</div>`:`<div class="v11-note warn">No indexed evidence is linked to this task.</div>`,btn('Attach','attach','small',t.id)+btn('Evidence library','evidence','small soft'))}${panel('Linked exceptions','Root cause and resolution remain separate from task status.',xs.length?xs.map(x=>`<div class="v11-control-row" data-v11="exception" data-id="${x.id}" style="cursor:pointer"><div><strong>${x.id} · ${x.title}</strong><span>${x.root}</span></div>${badge(x.status)}</div>`).join(''):`<div class="v11-note">No exception is linked to this task.</div>`)}${panel('Reviewer conversation','Task-specific comments remain auditable.',`${cs.map(c=>`<div style="display:grid;grid-template-columns:29px 1fr;gap:7px;padding:8px 0;border-bottom:1px solid #e7edf4"><img src="${pic(c.name)}" style="width:28px;height:28px;border-radius:8px;object-fit:cover"><div><strong style="font-size:10px">${c.name}</strong><span style="font-size:10px;color:var(--muted);margin-left:5px">${c.time}</span><p style="font-size:10px;line-height:1.45;margin:3px 0 0">${c.text}</p></div></div>`).join('')||'<div class="v11-note">No comments yet.</div>'}${field('Add comment',`<textarea class="v11-textarea" id="v11Comment"></textarea>`)}<div style="margin-top:7px">${btn('Post comment','comment','primary small',t.id)}</div>`)}</aside></div></div>`}
function exceptions(){return `<div class="v11">${head('Close risk and exceptions','Exception Resolution Centre','Every item has a root cause, accounting value, owner, resolution path, due date and linked close task.',btn('Back to close','home')+btn('Control scan','scan')+btn('Export','export-ex','soft'),crumb([{l:'Exceptions'}]))}<div class="v11-kpis">${kpi('Open exceptions',openEx().length,`${C.ex.length-openEx().length} resolved`,55,'noop')}${kpi('Critical value',`$${openEx().filter(x=>x.severity==='Critical').reduce((s,x)=>s+x.value,0).toLocaleString()}`,'Potential close impact',42,'noop')}${kpi('Past due','0','All have active due dates',100,'noop')}${kpi('Average age','7.2 hrs','Open population',62,'noop')}${kpi('Owned','100%','No unassigned items',100,'noop')}${kpi('Lock impact',openEx().filter(x=>x.severity==='Critical').length,'Critical items block lock',48,'lock')}</div><div class="v11-layout"><div class="v11-stack">${panel('Exception register','Open an item for source evidence, proposed journal and resolution controls.',`<div class="v11-three">${C.ex.map(x=>`<div class="v11-ex" data-v11="exception" data-id="${x.id}"><div class="v11-ex-top"><div><h3>${x.id} · ${x.title}</h3><p>${x.root}</p></div>${badge(x.status)}</div><div class="v11-ex-meta"><div><span>Severity</span><strong>${x.severity}</strong></div><div><span>Value</span><strong>$${x.value.toLocaleString()}</strong></div><div><span>Owner / age</span><strong>${x.owner.split(' ')[0]} · ${x.age}</strong></div></div></div>`).join('')}</div>`)}${panel('Exception value by item','Risk concentration and materiality.',`<div class="v11-chart" data-v11="analytics"><svg viewBox="0 0 120 75" preserveAspectRatio="none">${[20,40,60].map(y=>`<line class="gridline" x1="16" y1="${y}" x2="116" y2="${y}"/>`).join('')}${C.ex.map((x,i)=>`<rect class="bar ${x.severity==='Critical'?'bad':x.severity==='High'?'warn':''}" x="${20+i*18}" y="${65-Math.min(55,x.value/180)}" width="11" height="${Math.min(55,x.value/180)}"/>`).join('')}</svg><div class="v11-axis" style="grid-template-columns:repeat(${C.ex.length},1fr)">${C.ex.map(x=>`<span>${x.id}</span>`).join('')}</div></div>`)}</div><aside class="v11-stack">${panel('Resolution model','Guidance for the end user.',`<div class="v11-control"><div class="v11-control-row"><div><strong>1. Understand</strong><span>Root cause, source and accounting impact.</span></div>${badge('Guided')}</div><div class="v11-control-row"><div><strong>2. Decide</strong><span>Correction, accrual, waiver or escalation.</span></div>${badge('Controlled')}</div><div class="v11-control-row"><div><strong>3. Evidence</strong><span>Document and reviewer conclusion.</span></div>${badge('Auditable')}</div><div class="v11-control-row"><div><strong>4. Close</strong><span>Dependent tasks update automatically.</span></div>${badge('Integrated')}</div></div>`)}${panel('Resolve first','Priority based on lock impact, value, age and dependency.',openEx()[0]?`<div class="v11-next"><div class="label">Highest priority</div><h3>${openEx()[0].id} · ${openEx()[0].title}</h3><p>${openEx()[0].resolution}</p><div class="buttons">${btn('Open exception','exception','primary small',openEx()[0].id)}</div></div>`:'<div class="v11-note">No open exceptions.</div>')}</aside></div></div>`}
function exception(){const x=ex(C.selectedEx),t=task(x.task),w=ws(t.ws),j=x.id==='EX-001'?[['5305 · Bank charges',185,0],['1101 · CBZ USD Operating',0,185]]:[['Close adjustment account',x.value,0],['Offset / control account',0,x.value]];return `<div class="v11">${head('Third-level exception workspace',`${x.id} · ${x.title}`,`${w.name} · linked task ${t.id}. Review the root cause, source evidence, accounting correction and control consequence before resolution.`,btn('Back to exceptions','exceptions')+btn('Linked task','task','soft',t.id)+btn('Escalate','escalate','warn',x.id)+btn(x.status==='Resolved'?'Reopen':'Resolve','resolve-review','primary',x.id),crumb([{l:'Exceptions',a:'exceptions'},{l:x.id}]))}<div class="v11-kpis">${kpi('Accounting value',`$${x.value.toLocaleString()}`,x.source,58,'noop')}${kpi('Severity',x.severity,'Lock impact',42,'noop')}${kpi('Age',x.age,`Due ${x.due}`,66,'calendar')}${kpi('Owner',x.owner.split(' ')[0],x.owner,78,'owner',x.owner)}${kpi('Linked task',t.id,t.name,progress(t),'task',t.id)}${kpi('Status',x.status,x.status==='Resolved'?'Readiness refreshed':'Evidence required',x.status==='Resolved'?100:45,'noop')}</div><div class="v11-two"><div class="v11-stack">${panel('Root-cause analysis','What happened, why and where it was detected.',`<div class="v11-facts"><div class="v11-fact"><span>What happened</span><strong>${x.title}</strong></div><div class="v11-fact"><span>Why</span><strong>${x.root}</strong></div><div class="v11-fact"><span>Detected in</span><strong>${x.source}</strong></div></div><div class="v11-note bad" style="margin-top:9px">${x.severity==='Critical'?'This exception blocks period lock and final approval.':'Documented resolution or risk acceptance is required.'}</div>`)}${panel('Recommended resolution','Guided action with human approval retained.',`<div class="v11-next"><div class="label">Suggested action</div><h3>${x.resolution}</h3><p>The system records who decided, what changed and which evidence supported it.</p></div><div class="v11-checks" style="margin-top:8px"><div class="v11-check done"><button>✓</button><div><strong>Source population identified</strong><span>${x.source} · ${x.id}</span></div><em>Complete</em></div><div class="v11-check ${x.status==='Resolved'?'done':''}"><button>${x.status==='Resolved'?'✓':''}</button><div><strong>Accounting correction approved</strong><span>Balanced journal or non-posting decision.</span></div><em>${x.status==='Resolved'?'Complete':'Open'}</em></div><div class="v11-check ${x.status==='Resolved'?'done':''}"><button>${x.status==='Resolved'?'✓':''}</button><div><strong>Evidence linked and exception closed</strong><span>Owner conclusion and reviewer retained.</span></div><em>${x.status==='Resolved'?'Complete':'Open'}</em></div></div>`)}${panel('Proposed accounting impact','Balanced correction preview.',`<div class="v11-table-wrap"><table class="v11-table" style="min-width:620px"><thead><tr><th>Account</th><th>Debit</th><th>Credit</th><th>Dimension</th></tr></thead><tbody>${j.map(r=>`<tr><td>${r[0]}</td><td>${r[1]||'-'}</td><td>${r[2]||'-'}</td><td>${w.name}</td></tr>`).join('')}<tr><td><strong>Total</strong></td><td><strong>${x.value.toFixed(2)}</strong></td><td><strong>${x.value.toFixed(2)}</strong></td><td>${badge('Balanced')}</td></tr></tbody></table></div>`,btn('Create correction journal','correction','primary small',x.id))}</div><aside class="v11-stack">${panel('Ownership and decision','Save a task-specific resolution conclusion.',`${owner(x.owner)}<div class="v11-facts" style="margin-top:9px"><div class="v11-fact"><span>Due</span><strong>${x.due}</strong></div><div class="v11-fact"><span>Age</span><strong>${x.age}</strong></div><div class="v11-fact"><span>Severity</span><strong>${x.severity}</strong></div></div>${field('Resolution note',`<textarea class="v11-textarea" id="v11Resolution">${x.status==='Resolved'?'Resolved with correction and evidence.':''}</textarea>`)}`)}${panel('Dependency impact','What changes after resolution.',`<div class="v11-control"><div class="v11-control-row"><div><strong>${t.id} · ${t.name}</strong><span>Task status and progress</span></div>${badge(t.status)}</div><div class="v11-control-row"><div><strong>Workstream readiness</strong><span>${w.name}</span></div>${badge(`${stats(w.id).p}%`)}</div><div class="v11-control-row"><div><strong>Period lock</strong><span>Critical exception gate</span></div>${badge(x.status==='Resolved'?'Passed':'Blocked')}</div></div>`)}</aside></div></div>`}
function analytics(){return `<div class="v11">${head('Close intelligence','Close Analytics & Bottleneck Studio','A management layer for CFOs, finance directors and analysts to understand speed, workload, evidence quality and recurring bottlenecks.',btn('Back to close','home')+btn('Export','export-an','soft')+btn('Exceptions','exceptions','primary'),crumb([{l:'Analytics'}]))}<div class="v11-kpis">${kpi('Current duration','5.8 days','1.3 days faster than May',76,'noop')}${kpi('Target duration','5.0 days','Executive SLA',88,'noop')}${kpi('On-time tasks','84%','16 of 19 tasks',84,'noop')}${kpi('Average task age','9.4 hrs','Open population',63,'noop')}${kpi('Rework rate','6.1%','Returned tasks and evidence',78,'noop')}${kpi('Automation','58%','Auto-posted or matched',58,'noop')}</div><div class="v11-two"><div class="v11-stack">${panel('Close duration and forecast','Historical elapsed days and July forecast.',chart())}${panel('Workstream performance matrix','Completion, evidence, blockers and owner concentration.',`<div class="v11-table-wrap"><table class="v11-table" style="min-width:780px"><thead><tr><th>Workstream</th><th>Completion</th><th>Evidence</th><th>Blocked</th><th>Open</th><th>Owner</th></tr></thead><tbody>${C.ws.map(w=>{const s=stats(w.id);return `<tr data-v11="ws" data-id="${w.id}"><td class="v11-link">${w.name}</td><td>${s.p}%</td><td>${s.ev}%</td><td>${s.blocked}</td><td>${s.a.length-s.done}</td><td>${owner(w.owner)}</td></tr>`}).join('')}</tbody></table></div>`)}${panel('Recurring bottlenecks','Actionable patterns rather than vanity analytics.',`<div class="v11-three"><div class="v11-next"><div class="label">Supplier evidence</div><h3>Late tax-document corrections</h3><p>Automate reminders five business days before cut-off.</p></div><div class="v11-next"><div class="label">Reviewer capacity</div><h3>Manual journal congestion</h3><p>Introduce twice-daily review windows.</p></div><div class="v11-next"><div class="label">Cash evidence</div><h3>Recurring bank fees</h3><p>Propose rule-driven adjustments during auto-match.</p></div></div>`)}</div><aside class="v11-stack">${panel('Executive interpretation','Answers management needs.',`<div class="v11-control"><div class="v11-control-row"><div><strong>Will close meet target?</strong><span>Forecast 01 Aug 17:20</span></div>${badge('At risk')}</div><div class="v11-control-row"><div><strong>Largest delay</strong><span>Supplier evidence and VAT dependency</span></div>${badge('AP / Tax')}</div><div class="v11-control-row"><div><strong>Constrained owner</strong><span>Tariro Moyo · 6 reviews</span></div>${badge('72%')}</div><div class="v11-control-row"><div><strong>Best automation</strong><span>Bank fees and recurring accruals</span></div>${badge('High value')}</div></div>`)}${panel('Role-specific answers','One state, different user questions.',`<div class="v11-control"><div class="v11-control-row"><div><strong>Finance officer</strong><span>Next task, records, evidence and due time.</span></div>${badge('Action')}</div><div class="v11-control-row"><div><strong>Risk manager</strong><span>Exceptions and failed controls.</span></div>${badge('Risk')}</div><div class="v11-control-row"><div><strong>CFO / CEO</strong><span>Readiness, forecast and lock decision.</span></div>${badge('Decision')}</div></div>`)}</aside></div></div>`}
function evidencePage(){return `<div class="v11">${head('Close documentation','Close Evidence & Audit Pack','Governed evidence by workstream, task, version, owner and approval status. Every document is previewable and traceable to its control.',btn('Back to close','home')+btn('Attach evidence','attach')+btn('Generate audit index','index','primary'),crumb([{l:'Evidence'}]))}<div class="v11-kpis">${kpi('Coverage',`${evidence()}%`,'Required close evidence',evidence(),'noop')}${kpi('Documents',C.docs.length,'Indexed versions',75,'noop')}${kpi('Approved',C.docs.filter(d=>d.status==='Approved').length,'Controlled copies',67,'noop')}${kpi('In review',C.docs.filter(d=>d.status==='In review').length,'Reviewer action',45,'noop')}${kpi('Missing',C.tasks.reduce((s,t)=>s+Math.max(0,t.required-t.evidence),0),'Task-level gaps',54,'noop')}${kpi('Audit pack','Draft','Generated on demand',62,'index')}</div><div class="v11-layout"><div class="v11-stack">${panel('Evidence folders','Counts map to task requirements.',`<div class="v11-evidence">${C.ws.map(w=>{const d=C.docs.filter(x=>task(x.task)?.ws===w.id);return `<div class="v11-doc" data-v11="ws" data-id="${w.id}"><i>${d.length}</i><strong>${w.name}</strong><span>${d.length} indexed documents</span><em>${stats(w.id).ev}% coverage</em></div>`}).join('')}</div>`)}${panel('Document index','Preview a controlled copy or open the supporting task.',`<div class="v11-table-wrap"><table class="v11-table"><thead><tr><th>Document</th><th>Folder</th><th>Task</th><th>Type</th><th>Version</th><th>Owner</th><th>Updated</th><th>Status</th></tr></thead><tbody>${C.docs.map(d=>`<tr data-v11="doc" data-id="${d.id}"><td class="v11-link">${d.name}</td><td>${d.folder}</td><td>${d.task}</td><td>${d.type}</td><td>v${d.version}</td><td>${owner(d.owner)}</td><td>${d.updated}</td><td>${badge(d.status)}</td></tr>`).join('')}</tbody></table></div>`)}</div><aside class="v11-stack">${panel('Evidence quality','Audit defensibility and completeness.',`<div class="v11-control"><div class="v11-control-row"><div><strong>Task linkage</strong><span>Every file references a close task</span></div>${badge('Passed')}</div><div class="v11-control-row"><div><strong>Version history</strong><span>Prior copies retained</span></div>${badge('Passed')}</div><div class="v11-control-row"><div><strong>Approval metadata</strong><span>One file in review</span></div>${badge('Review')}</div><div class="v11-control-row"><div><strong>Missing evidence</strong><span>Gaps remain visible</span></div>${badge('Review')}</div></div>`)}${panel('Audit readiness','What an auditor can obtain.',`<div class="v11-note">The index includes task ID, control objective, document, version, owner, approval status, source record and retrieval timestamp.</div>`)}</aside></div></div>`}
function signoffs(){return `<div class="v11">${head('Close governance','Close Review & Sign-off Chain','Role-aware review showing scope, evidence, conflicts, decision comments and the exact assertions each approver accepts.',btn('Back to close','home')+btn('Reviewer pack','evidence','soft')+btn('Send reminders','remind-sign')+btn('Review next','sign-next','primary'),crumb([{l:'Sign-offs'}]))}<div class="v11-kpis">${kpi('Approved',C.sign.filter(x=>x.status==='Approved').length,`${C.sign.length} required`,C.sign.filter(x=>x.status==='Approved').length/C.sign.length*100,'noop')}${kpi('Pending',C.sign.filter(x=>x.status==='Pending').length,'Active review',50,'noop')}${kpi('Not started',C.sign.filter(x=>x.status==='Not started').length,'Executive stage',25,'noop')}${kpi('Conflict checks','Passed','Maker and approver separated',100,'noop')}${kpi('Reviewer pack','Version 8','Snapshot indexed',88,'evidence')}${kpi('Lock authority','Executive','Final approval required',45,'lock')}</div><div class="v11-two"><div class="v11-stack">${panel('Approval chain','Inspect scope and record a decision.',`<div class="v11-table-wrap"><table class="v11-table" style="min-width:760px"><thead><tr><th>Stage</th><th>Approver</th><th>Scope</th><th>Time</th><th>Status</th><th>Action</th></tr></thead><tbody>${C.sign.map((s,i)=>`<tr><td>${i+1} · ${s.role}</td><td>${owner(s.name)}</td><td>${s.scope}</td><td>${s.time}</td><td>${badge(s.status)}</td><td>${s.status==='Approved'?btn('View','sign-view','small',s.id):btn('Review','sign-review','primary small',s.id)}</td></tr>`).join('')}</tbody></table></div>`)}${panel('Reviewer conclusion pack','Controlled close summary before approval.',`<div class="v11-facts"><div class="v11-fact"><span>Completion</span><strong>${Math.round(done()/C.tasks.length*100)}%</strong></div><div class="v11-fact"><span>Critical blockers</span><strong>${openEx().filter(x=>x.severity==='Critical').length}</strong></div><div class="v11-fact"><span>Evidence</span><strong>${evidence()}%</strong></div><div class="v11-fact"><span>Trial balance</span><strong>Balanced</strong></div><div class="v11-fact"><span>Cash difference</span><strong>USD ${task('CA-01').status==='Complete'?'0.00':'185.00'}</strong></div><div class="v11-fact"><span>VAT readiness</span><strong>${task('TX-01').status==='Complete'?'100%':'96%'}</strong></div></div><div class="v11-note warn" style="margin-top:9px">${openEx().filter(x=>x.severity==='Critical').length} critical exception(s) remain. Final executive approval is blocked.</div>`)}</div><aside class="v11-stack">${panel('Segregation of duties','Identity and authority checks.',`<div class="v11-control"><div class="v11-control-row"><div><strong>Current user</strong><span>${user()}</span></div>${badge('Authenticated')}</div><div class="v11-control-row"><div><strong>Maker-checker</strong><span>Independent reviewer required</span></div>${badge('Passed')}</div><div class="v11-control-row"><div><strong>Approval authority</strong><span>Close and lock permission</span></div>${badge('Passed')}</div><div class="v11-control-row"><div><strong>Open blockers</strong><span>${openEx().filter(x=>x.severity==='Critical').length} critical</span></div>${badge(openEx().filter(x=>x.severity==='Critical').length?'Blocked':'Passed')}</div></div>`)}${panel('Approver assertions','What approval means.',`<div class="v11-checks"><div class="v11-check done"><button>✓</button><div><strong>Records are complete</strong><span>Material transactions are recorded.</span></div><em>Assertion</em></div><div class="v11-check done"><button>✓</button><div><strong>Balances are supported</strong><span>Reconciliations and evidence indexed.</span></div><em>Assertion</em></div><div class="v11-check"><button></button><div><strong>Exceptions resolved</strong><span>Critical items must close.</span></div><em>Open</em></div></div>`)}</aside></div></div>`}
function lock(){const gates=[['Critical tasks',C.tasks.filter(t=>t.priority==='Critical'&&t.id!=='GV-03').every(t=>t.status==='Complete'),`${C.tasks.filter(t=>t.priority==='Critical'&&t.id!=='GV-03'&&t.status!=='Complete').length} incomplete`],['Critical exceptions',openEx().filter(x=>x.severity==='Critical').length===0,`${openEx().filter(x=>x.severity==='Critical').length} open`],['Evidence coverage',evidence()===100,`${evidence()}% complete`],['Bank reconciliations',task('CA-01').status==='Complete'&&task('CA-02').status==='Complete','All material accounts signed'],['Tax readiness',task('TX-01').status==='Complete','VAT reviewer conclusion'],['Management accounts',task('RP-01').status==='Complete','Final report approval'],['Approval chain',C.sign.every(s=>s.status==='Approved'),`${C.sign.filter(s=>s.status!=='Approved').length} outstanding`],['Evidence archive',task('GV-01').status==='Complete','Close pack archived']],pass=gates.every(x=>x[1]);return `<div class="v11">${head('Irreversible close control','Period Lock Readiness','Every mandatory gate, evidence requirement and responsible owner is visible before the period becomes immutable.',btn('Back to close','home')+btn('Certificate preview','certificate','soft')+btn(C.locked?'Period locked':'Request lock','lock-review','primary','',pass?'':'disabled'),crumb([{l:'Period lock'}]))}<div class="v11-kpis">${kpi('Readiness',`${readiness()}%`,`${gates.filter(x=>x[1]).length}/${gates.length} gates`,readiness(),'noop')}${kpi('Mandatory gates',gates.length,'Configured policy',100,'noop')}${kpi('Gates passed',gates.filter(x=>x[1]).length,'Current validation',gates.filter(x=>x[1]).length/gates.length*100,'noop')}${kpi('Critical exceptions',openEx().filter(x=>x.severity==='Critical').length,'Must equal zero',42,'exceptions')}${kpi('Approvals',`${C.sign.filter(x=>x.status==='Approved').length}/${C.sign.length}`,'Executive required',C.sign.filter(x=>x.status==='Approved').length/C.sign.length*100,'signoffs')}${kpi('Lock state',C.locked?'Locked':'Open',C.locked?'No July postings permitted':'Authorised postings allowed',C.locked?100:40,'noop')}</div><div class="v11-two"><div class="v11-stack">${panel('Lock validation gates','Failed gates link back to operational resolution.',`<div class="v11-gates">${gates.map(g=>`<div class="v11-gate ${g[1]?'pass':'fail'}"><i>${g[1]?'✓':'!'}</i><div><strong>${g[0]}</strong><span>${g[2]}</span></div>${badge(g[1]?'Passed':'Blocked')}</div>`).join('')}</div>`)}${panel('Lock consequence preview','What changes after final approval.',`<div class="v11-three"><div class="v11-next"><div class="label">Posting</div><h3>July journals become immutable</h3><p>Corrections require reopening or a future-period adjustment.</p></div><div class="v11-next"><div class="label">Reporting</div><h3>Reports bind to the lock snapshot</h3><p>The exact ledger and rate version is retained.</p></div><div class="v11-next"><div class="label">Audit</div><h3>A lock certificate is generated</h3><p>Approvers, gates and evidence are recorded.</p></div></div>`)}</div><aside class="v11-stack">${panel('System conclusion','Whether the current close can be locked.',`<div class="v11-next"><div class="label">Decision</div><h3>${C.locked?'July 2026 is locked':pass?'Ready for lock approval':'Not ready to lock'}</h3><p>${C.locked?'The period is immutable.':pass?'All gates passed.':'Open the failed gates before requesting the lock.'}</p><div class="buttons">${C.locked?btn('View lock certificate','certificate','primary small'):pass?btn('Request lock','lock-review','primary small'):btn('Open next blocker','next-blocker','primary small')}</div></div>`)}${panel('Authority and audit','Final control metadata.',`<div class="v11-control"><div class="v11-control-row"><div><strong>Lock authority</strong><span>Finance Director or CEO</span></div>${badge('Configured')}</div><div class="v11-control-row"><div><strong>Current user</strong><span>${user()}</span></div>${badge('Verified')}</div><div class="v11-control-row"><div><strong>Last validation</strong><span>${C.scan}</span></div>${badge('Recorded')}</div><div class="v11-control-row"><div><strong>Certificate</strong><span>${C.locked?'LOCK-2026-07-001':'After approval'}</span></div>${badge(C.locked?'Available':'Pending')}</div></div>`)}</aside></div></div>`}
function calendar(){const days=['31 Jul','01 Aug','02 Aug','03 Aug','04 Aug'],times=['08:00','10:00','12:00','14:00','16:00'];return `<div class="v11">${head('Close planning','Close Calendar & Capacity Board','Time-based tasks, dependencies, owner workload and reviewer capacity. Select a task to open its control workspace.',btn('Back to close','home')+btn('Add task','add-task')+btn('Send reminders','remind','primary'),crumb([{l:'Close calendar'}]))}<div class="v11-kpis">${kpi('Tasks today',C.tasks.filter(t=>t.due.includes('01 Aug')).length,'July execution',82,'noop')}${kpi('Overdue','0','No past-due tasks',100,'noop')}${kpi('Due next 2 hours','5','Priority population',62,'noop')}${kpi('Owner conflicts','2','Overlapping reviews',44,'analytics')}${kpi('Reviewer capacity','68%','Finance Director workload',68,'signoffs')}${kpi('Forecast finish','01 Aug 17:20','2h20 after target',58,'analytics')}</div>${panel('Close schedule','Business-hour calendar for tasks and reviews.',`<div style="overflow:auto"><div class="v11-calendar"><div class="v11-cal head">Time</div>${days.map(d=>`<div class="v11-cal head">${d}</div>`).join('')}${times.map(time=>`<div class="v11-cal time">${time}</div>${days.map(d=>{const a=C.tasks.filter(t=>t.due.startsWith(d)&&Math.abs(parseInt(t.due.split(' ')[2]||'0')-parseInt(time))<2).slice(0,2);return `<div class="v11-cal">${a.map(t=>`<div class="v11-cal-task ${t.status==='Blocked'?'bad':t.status==='In review'?'warn':''}" data-v11="task" data-id="${t.id}"><strong>${t.id} · ${t.name}</strong><span>${t.owner} · ${t.status}</span></div>`).join('')}</div>`}).join('')}`).join('')}</div></div>`)}<div class="v11-two" style="margin-top:11px">${panel('Owner workload','Open task capacity.',`<div class="v11-control">${[...new Set(C.tasks.map(t=>t.owner))].map(n=>`<div class="v11-control-row"><div>${owner(n)}</div><div><strong>${C.tasks.filter(t=>t.owner===n&&t.status!=='Complete').length} open</strong><span>Current workload</span></div></div>`).join('')}</div>`)}${panel('Critical path','Dependencies likely to affect finish.',`<div class="v11-control">${C.tasks.filter(t=>t.status==='Blocked'||(t.priority==='Critical'&&t.status!=='Complete')).slice(0,6).map(t=>`<div class="v11-control-row" data-v11="task" data-id="${t.id}" style="cursor:pointer"><div><strong>${t.id} · ${t.name}</strong><span>${t.dependency}</span></div>${badge(t.status)}</div>`).join('')}</div>`)}</div></div>`}
function modalConfirm(title,summary,impact,action,id=''){openModal(title,'Review the exact workflow and result before confirming.',`<div class="v11-confirm"><h3>${summary}</h3><p>${impact}</p><div class="v11-confirm-grid"><div><span>Period</span><strong>${C.period}</strong></div><div><span>Entity</span><strong>${C.entity}</strong></div><div><span>Acting user</span><strong>${user()}</strong></div></div></div>`,btn('No, go back','modal-close')+btn('Yes, continue',action,'primary',id))}
const route=id=>window.MatanhoAccountingV8?.navigate?.(id),source=s=>route({'Journal Entries':'journals','General Ledger':'ledger','Financial Reports':'reports','Bank Reconciliation':'reconciliation','Cash & Liquidity':'cash','Receivables':'receivables','Payables':'payables','Compliance & Tax':'compliance','Group Consolidation':'consolidation','Document Vault':'vault','Access Control':'access','Period Close':'close'}[s]||'overview');const rerender=()=>typeof render==='function'?render():route(state.page);
function previewDoc(id){const d=C.docs.find(x=>x.id===id);if(!d)return;openModal(d.name,`${d.type} · version ${d.version} · ${d.status}`,`<div style="background:#eaf0f6;padding:18px;border-radius:12px;overflow:auto"><article style="max-width:720px;min-height:620px;margin:auto;background:#fff;color:#172438;box-shadow:0 25px 70px rgba(13,33,60,.18);padding:44px 48px"><div style="display:flex;justify-content:space-between;border-bottom:2px solid #0c274c;padding-bottom:16px"><div><div style="font-size:23px;font-weight:900;color:#08254c">matanho</div><div style="font-size:10px;letter-spacing:.13em;text-transform:uppercase;color:#54708e">Finance & Accounting</div></div><div style="text-align:right;font-size:10px;color:#60728a">${C.entity}<br>${C.period}<br>Controlled evidence</div></div><div style="margin-top:26px"><div style="font-size:10px;color:#006dff;text-transform:uppercase;font-weight:900">Close evidence</div><h1 style="font-size:21px;margin:5px 0">${d.name}</h1><p style="font-size:10px;color:#60728a">Task ${d.task} · ${d.folder}</p></div><div class="v11-confirm-grid" style="margin:20px 0"><div><span>Version</span><strong>${d.version}</strong></div><div><span>Status</span><strong>${d.status}</strong></div><div><span>Owner</span><strong>${d.owner}</strong></div></div><h2 style="font-size:14px">Control conclusion</h2><p style="font-size:10px;line-height:1.7">The supporting population was reviewed against the relevant ledger or sub-ledger. Source records and reviewer metadata are retained with this version.</p></article></div>`,btn('Close','modal-close')+btn('Open task','task','soft',d.task)+btn('Download copy','download','primary',d.id),true)}
try{Object.assign(pages,{close:home,v11ws:workstream,v11task:taskPage,v11exceptions:exceptions,v11exception:exception,v11analytics:analytics,v11evidence:evidencePage,v11signoffs:signoffs,v11lock:lock,v11calendar:calendar});['v11ws','v11task','v11exceptions','v11exception','v11analytics','v11evidence','v11signoffs','v11lock','v11calendar'].forEach(id=>pagePermission[id]='close.manage')}catch(e){console.error(e)}
document.addEventListener('input',e=>{const k=e.target.dataset.v11Filter;if(!k)return;C.filters[k]=e.target.value;save();clearTimeout(window.v11ft);window.v11ft=setTimeout(rerender,120)}, __ac52Sig);document.addEventListener('change',e=>{const k=e.target.dataset.v11Filter;if(!k)return;C.filters[k]=e.target.value;save();rerender()}, __ac52Sig);
document.addEventListener('click',e=>{const el=e.target.closest('[data-v11]');if(!el)return;const a=el.dataset.v11,id=el.dataset.id||'';if(a==='noop')return;e.preventDefault();e.stopImmediatePropagation();switch(a){case'home':route('close');break;case'ws':C.selectedWs=id;save();route('v11ws');break;case'task':C.selectedTask=id;C.selectedWs=task(id)?.ws||C.selectedWs;save();route('v11task');break;case'exceptions':route('v11exceptions');break;case'exception':C.selectedEx=id;save();route('v11exception');break;case'analytics':route('v11analytics');break;case'evidence':route('v11evidence');break;case'signoffs':route('v11signoffs');break;case'lock':route('v11lock');break;case'calendar':route('v11calendar');break;case'source':source(id);break;case'owner':openDrawer(`${id} · close workload`,'Assigned tasks, deadlines and status',`<div class="v11-control">${C.tasks.filter(t=>t.owner===id).map(t=>`<div class="v11-control-row" data-v11="task" data-id="${t.id}" style="cursor:pointer"><div><strong>${t.id} · ${t.name}</strong><span>${t.due} · ${ws(t.ws).name}</span></div>${badge(t.status)}</div>`).join('')}</div>`,btn('Send reminder','remind','primary'));break;case'scan':modalConfirm('Run close control scan','Refresh all tasks, dependencies, evidence, exception and sign-off gates.','No accounting entry is posted. The scan updates readiness and records the acting user.','scan-do');break;case'scan-do':C.scan=now();C.activity.unshift({time:C.scan,event:'Close control scan completed',detail:`${done()} tasks complete; ${openEx().length} exceptions remain.`});save();closeModal();rerender();toast('Control scan completed','Readiness, dependencies and lock gates were refreshed.');break;case'task-review':{const t=task(id);modalConfirm(t.status==='Complete'?'Reopen close task':'Complete close task',`${t.id} · ${t.name}`,t.status==='Complete'?'The task returns to In progress.':'Checklist and evidence will be completed. Critical linked exceptions still block completion.','task-do',id)}break;case'task-do':{const t=task(id),xs=C.ex.filter(x=>x.task===id&&x.status!=='Resolved'&&x.severity==='Critical');if(t.status==='Complete')t.status='In progress';else if(xs.length){closeModal();toast('Task remains blocked',`Resolve ${xs.map(x=>x.id).join(', ')} first.`,'bad');return}else{t.status='Complete';t.checklist=t.checklist.map(()=>1);t.evidence=t.required}save();closeModal();route('v11task');break}case'check':{const [tid,i]=id.split('|'),t=task(tid);t.checklist[+i]=t.checklist[+i]?0:1;if(t.status==='Not started')t.status='In progress';save();route('v11task');break}case'task-save':{const t=task(id);t.owner=$('#v11Owner')?.value||t.owner;t.status=$('#v11Status')?.value||t.status;t.due=$('#v11Due')?.value||t.due;t.note=$('#v11Note')?.value||t.note;C.activity.unshift({time:now(),event:`${t.id} updated`,detail:`${t.owner} · ${t.status}`});save();toast('Task saved','Control metadata and audit history updated.');route('v11task');break}case'comment':{const v=$('#v11Comment')?.value.trim();if(!v)return toast('Comment required','Enter a clear control conclusion.','warn');C.comments.push({task:id,name:user(),time:now(),text:v});save();route('v11task');break}case'attach':openModal('Attach close evidence','Link a governed file to a task.',`<div class="v11-filter" style="grid-template-columns:repeat(2,1fr)">${field('Task',`<select class="v11-select" id="v11Et">${C.tasks.map(t=>`<option value="${t.id}" ${id===t.id?'selected':''}>${t.id} · ${t.name}</option>`).join('')}</select>`)}${field('Type',`<select class="v11-select" id="v11Ey"><option>Reconciliation</option><option>Working paper</option><option>Financial report</option><option>Source document</option></select>`)}${field('Name',`<input class="v11-input" id="v11En" value="Close support · ${C.period}.pdf">`)}${field('File',`<input class="v11-input" type="file" id="v11Ef">`)}</div>`,btn('Cancel','modal-close')+btn('Attach and version','attach-do','primary'));break;case'attach-do':{const tid=$('#v11Et').value,t=task(tid),name=$('#v11En').value||$('#v11Ef').files?.[0]?.name||'Close evidence.pdf';C.docs.push({id:`EV-${Date.now()}`,task:tid,folder:ws(t.ws).name,name,type:$('#v11Ey').value,version:1,owner:user(),status:'Draft',updated:now()});t.evidence=Math.min(t.required,t.evidence+1);save();closeModal();toast('Evidence attached',`${name} was linked to ${tid}.`);rerender();break}case'doc':previewDoc(id);break;case'resolve-review':{const x=ex(id);modalConfirm(x.status==='Resolved'?'Reopen exception':'Resolve exception',`${x.id} · ${x.title}`,x.status==='Resolved'?'The linked task returns to active review.':'The exception closes, the linked task refreshes and lock readiness recalculates.','resolve-do',id)}break;case'resolve-do':{const x=ex(id),t=task(x.task);if(x.status==='Resolved'){x.status='Open';t.status='Blocked'}else{x.status='Resolved';t.status=t.checklist.every(Boolean)&&t.evidence>=t.required?'Complete':'In progress';t.note=`${x.id} resolved by ${user()} on ${now()}.`}save();closeModal();route('v11exception');break}case'escalate':ex(id).status='Escalated';save();rerender();toast('Exception escalated','Owner and Finance Director notified.','warn');break;case'correction':modalConfirm('Create correction journal',`${id} · balanced correction proposal`,'A draft journal is routed through maker-checker. The exception remains open until approval.','correction-do',id);break;case'correction-do':closeModal();toast('Correction journal created',`A balanced draft for ${id} was routed to approvals.`);break;case'bulk':{const a=C.tasks.filter(t=>t.ws===id&&t.id!=='GV-03'&&t.status!=='Complete'&&!C.ex.some(x=>x.task===t.id&&x.status!=='Resolved'&&x.severity==='Critical'));modalConfirm('Complete eligible tasks',`${a.length} eligible tasks in ${ws(id).name}`,'Only tasks without critical exceptions will complete.','bulk-do',id);break}case'bulk-do':C.tasks.filter(t=>t.ws===id&&t.id!=='GV-03'&&t.status!=='Complete'&&!C.ex.some(x=>x.task===t.id&&x.status!=='Resolved'&&x.severity==='Critical')).forEach(t=>{t.status='Complete';t.checklist=t.checklist.map(()=>1);t.evidence=t.required});save();closeModal();route('v11ws');break;case'sign-review':{const s=C.sign.find(x=>x.id===id);openModal(`${s.role} review`,`${s.name} · ${s.scope}`,`<div class="v11-confirm"><h3>Reviewer conclusion</h3><p>You assert that the assigned scope is complete and supported.</p><div class="v11-confirm-grid"><div><span>Readiness</span><strong>${readiness()}%</strong></div><div><span>Critical blockers</span><strong>${openEx().filter(x=>x.severity==='Critical').length}</strong></div><div><span>Evidence</span><strong>${evidence()}%</strong></div></div></div>${field('Decision comment',`<textarea class="v11-textarea"></textarea>`)}`,btn('Cancel','modal-close')+btn('Approve scope','sign-do','primary',id));break}case'sign-do':{const s=C.sign.find(x=>x.id===id);if(s.role==='Executive approver'&&openEx().some(x=>x.severity==='Critical'&&x.status!=='Resolved'))return toast('Approval blocked','Resolve critical exceptions first.','bad');s.status='Approved';s.time=now();s.name=user();save();closeModal();route('v11signoffs');break}case'sign-next':{const s=C.sign.find(x=>x.status!=='Approved');if(s){const b=document.createElement('button');b.dataset.v11='sign-review';b.dataset.id=s.id;b.click()}else toast('All sign-offs complete','Proceed to period lock.');break}case'sign-view':toast('Decision evidence','Approver identity, role, time and snapshot are retained.');break;case'submit':modalConfirm('Submit close for review',`${Math.round(done()/C.tasks.length*100)}% complete · ${openEx().length} exceptions`,'The current snapshot is frozen for reviewer assessment; operational tasks remain editable.','submit-do');break;case'submit-do':C.submitted=true;save();closeModal();toast('Close submitted','Controller and tax reviewer notified.');rerender();break;case'lock-review':modalConfirm('Request irreversible period lock',`${C.entity} · ${C.period}`,'July postings and edits will be blocked; reports bind to the lock snapshot.','lock-do');break;case'lock-do':{const ok=C.tasks.filter(t=>t.priority==='Critical'&&t.id!=='GV-03').every(t=>t.status==='Complete')&&!openEx().some(x=>x.severity==='Critical')&&C.sign.every(s=>s.status==='Approved')&&task('GV-01').status==='Complete';if(!ok){closeModal();toast('Period lock blocked','Mandatory tasks, exceptions, evidence or approvals remain.','bad');route('v11lock')}else{C.locked=true;task('GV-03').status='Complete';save();closeModal();route('v11lock');toast('Period locked','July 2026 is immutable.')}break}case'next-blocker':{const t=C.tasks.find(x=>x.status==='Blocked'||(x.priority==='Critical'&&x.status!=='Complete'));if(t){C.selectedTask=t.id;C.selectedWs=t.ws;save();route('v11task')}else route('v11signoffs');break}case'brief':openModal('CFO close brief',`${C.entity} · ${C.period} · ${now()}`,`<div class="v11-confirm"><h3>${openEx().length?'Close is progressing but not ready to lock.':'Close is ready for approval.'}</h3><p>${done()} of ${C.tasks.length} tasks are complete, evidence is ${evidence()}%, and ${openEx().filter(x=>x.severity==='Critical').length} critical exception(s) remain. Forecast finish: 01 Aug 17:20.</p></div><div class="v11-three" style="margin-top:9px"><div class="v11-next"><div class="label">Top risk</div><h3>${openEx()[0]?.title||'None'}</h3><p>${openEx()[0]?.resolution||'All material risks resolved.'}</p></div><div class="v11-next"><div class="label">Management focus</div><h3>Supplier evidence and reviewer capacity</h3><p>Largest contributors to delay.</p></div><div class="v11-next"><div class="label">Decision</div><h3>${C.locked?'Locked':'Do not lock yet'}</h3><p>Open lock readiness for failed gates.</p></div></div>`,btn('Close','modal-close')+btn('Lock readiness','lock','primary'),true);break;case'why':openModal('Why this action is first','Priority uses lock impact, dependency, age, due time and owner capacity.',`<div class="v11-control"><div class="v11-control-row"><div><strong>Lock impact</strong><span>Critical blockers rank first.</span></div>${badge('High')}</div><div class="v11-control-row"><div><strong>Dependency</strong><span>Tasks unblocking tax and reports rank higher.</span></div>${badge('High')}</div><div class="v11-control-row"><div><strong>Due time</strong><span>Near-due items rise in the queue.</span></div>${badge('Medium')}</div></div>`,btn('Close','modal-close'));break;case'add-task':openModal('Add close task','Create a period-specific control task.',`<div class="v11-filter" style="grid-template-columns:repeat(2,1fr)">${field('Workstream',`<select class="v11-select" id="v11Nw">${C.ws.map(w=>`<option value="${w.id}">${w.name}</option>`).join('')}</select>`)}${field('Owner',`<select class="v11-select" id="v11No">${[...new Set(C.tasks.map(t=>t.owner))].map(n=>`<option>${n}</option>`).join('')}</select>`)}${field('Task name',`<input class="v11-input" id="v11Nn">`)}${field('Due',`<input class="v11-input" id="v11Nd" value="01 Aug 16:30">`)}</div>${field('Control objective',`<textarea class="v11-textarea" id="v11Nc"></textarea>`)}`,btn('Cancel','modal-close')+btn('Create task','add-task-do','primary'));break;case'add-task-do':{const w=$('#v11Nw').value,n=$('#v11Nn').value.trim();if(!n)return toast('Task name required','Describe the close outcome.','warn');const id2=`${w.toUpperCase().slice(0,2)}-${String(C.tasks.filter(t=>t.ws===w).length+1).padStart(2,'0')}`;C.tasks.push({id:id2,ws:w,name:n,owner:$('#v11No').value,due:$('#v11Nd').value,status:'Not started',priority:'High',evidence:0,required:3,dependency:'Configured dependency',control:$('#v11Nc').value||'Configured close control',source:'General Ledger',checklist:[0,0,0],note:'New close task.'});save();closeModal();route('v11calendar');break}case'index':toast('Audit index generated',`${C.docs.length} documents indexed by task, version and owner.`);break;case'remind':case'remind-sign':toast('Reminders sent','Owners received tasks, due times and direct links.');break;case'certificate':toast('Certificate preview','Lock certificate includes gates, evidence and approvers.');break;case'download':toast('Controlled copy prepared',`${id} is ready for download.`);break;case'export-ex':case'export-an':toast('Export prepared','The current governed view was exported.');break;case'modal-close':closeModal();break}}
,true);
