const status12=s=>{const t=String(s||'Recorded'),l=t.toLowerCase(),c=/exception|blocked|overdue|rejected|expired|hold/.test(l)?'bad':/pending|review|draft|prepar|open|maturing/.test(l)?'warn':/approved|posted|complete|active|ready|balanced|verified|eligible|signed/.test(l)?'ok':'blue';return `<span class="v12-status ${c}">${esc12(t)}</span>`};
const btn12=(label,a,cls='',id='')=>`<button class="v12-btn ${cls}" data-v12="${a}" ${id!==''?`data-id="${esc12(id)}"`:''}>${label}</button>`;
const head12=(eye,title,desc,actions='')=>`<div class="v12-head"><div class="v12-head-copy"><div class="v12-eye">${esc12(eye)}</div><h1>${esc12(title)}</h1><p>${esc12(desc)}</p></div><div class="v12-actions">${actions}</div></div>`;
