const select12=(id,options,val)=>`<select class="v12-select" id="${id}">${options.map(o=>{const a=Array.isArray(o)?o:[o,o];return `<option value="${esc12(a[0])}" ${String(a[0])===String(val)?'selected':''}>${esc12(a[1])}</option>`}).join('')}</select>`;
const input12=(id,val='',type='text',ph='')=>`<input class="v12-input" id="${id}" type="${type}" value="${esc12(val)}" placeholder="${esc12(ph)}">`;
