function cashPage12(){const s=core12(),journals=(s.journals||[]).filter(x=>x.source==='Cashbook'),rows=[...V12.cashBatches.flatMap(b=>b.rows.map(r=>({...r,batch:b.id,date:b.date,bank:b.bank,status:'Posted'}))),...journals.map(j=>({batch:j.reference,date:j.date,bank:(s.banks||[]).find(b=>b.gl===(j.lines||[]).find(l=>/^110/.test(l.account))?.account)?.name||'Cashbook',counterparty:j.description,project:j.lines?.[0]?.project||'Corporate',currency:j.currency,receipt:(j.lines||[]).filter(l=>/^110/.test(l.account)).reduce((a,l)=>a+l.debit,0),payment:(j.lines||[]).filter(l=>/^110/.test(l.account)).reduce((a,l)=>a+l.credit,0),journal:j.id,status:j.status,reference:j.reference,description:j.description}))].slice(0,100).map(x=>`<tr data-action="noop" data-v12="journal" data-id="${x.journal||''}"><td>${d12(x.date)}</td><td class="v12-link">${esc12(x.batch||x.reference)}</td><td>${esc12(x.bank)}</td><td>${esc12(x.counterparty||'Direct entry')}</td><td>${esc12(x.project||'Corporate')}</td><td>${esc12(x.currency||'USD')}</td><td class="v12-num">${x.receipt?money12(x.receipt,x.currency):'—'}</td><td class="v12-num">${x.payment?money12(x.payment,x.currency):'—'}</td><td>${esc12(x.journal||'Batch')}</td><td>${status12(x.status)}</td></tr>`).join('');return `<div class="v12-page v39-cash-page">${head12('Cash operations','Cashbook & Daily Liquidity','Spreadsheet-style batch processing with editable rows, bank and currency context, tax, project dimensions and balanced-journal validation.',btn12('Import batch','cash-import','soft')+btn12('New receipt','cash-new','primary','receipt')+btn12('New payment','cash-new','','payment')+btn12('New transfer','cash-new','','transfer'))}<div class="v12-filterbar">${field12('Cashbook',select12('v12CashBank',[['all','All cashbooks'],...(s.banks||[]).map(b=>[b.id,b.name])],'all'))}${field12('Posting period',select12('v12CashPeriod',['Jul 2026','Aug 2026','Custom'],'Jul 2026'))}${field12('Currency',select12('v12CashCurrency',['All currencies','USD','ZWG','ZAR'],'All currencies'))}${field12('Project / fund',select12('v12CashProject',['All projects','Corporate','Growth Fund I','MFI Portfolio','Pension Liquidity'],'All projects'))}${field12('Status',select12('v12CashStatus',['All statuses','Posted','Draft','Exception'],'All statuses'))}${field12('Search',input12('v12CashSearch','','search','Batch, reference, counterparty or journal'))}</div><div class="v12-kpis">${kpi12('Cash at bank',money12((s.journals||[]).filter(j=>j.status==='Posted').flatMap(j=>j.lines||[]).filter(l=>/^110/.test(l.account)).reduce((a,l)=>a+num12(l.baseDebit)-num12(l.baseCredit),0)),'All configured cashbooks')}${kpi12('Receipt batches',String(V12.cashBatches.filter(x=>x.kind==='receipt').length),'User-created batches','#009d68')}${kpi12('Payment batches',String(V12.cashBatches.filter(x=>x.kind==='payment').length),'User-created batches','#e18a00')}${kpi12('Unreconciled lines',String((s.reconciliation?.statement||[]).filter(x=>x.status!=='Matched').length),'Bank workbench','#e52d50')}${kpi12('Bank feeds',`${(s.banks||[]).filter(x=>/api|sftp/i.test(x.feed)).length}/${(s.banks||[]).length}`,'API, SFTP and uploads','#00aeea')}${kpi12('Ledger integrity','Balanced','Cash journals validated','#6b48ff')}</div><div class="v12-grid v12-two v39-cash-layout"><div class="v39-cash-register-col">${panel12('Cashbook register','Posted cashbook batches and their source-to-ledger relationship.',table12(['Date','Batch / reference','Cashbook','Counterparty','Project / fund','Currency','Receipts','Payments','Journal','Status'],rows||'<tr><td colspan="10">No cashbook records.</td></tr>','1180px','560px'))}</div><aside class="v12-stack">${panel12('Batch processing model','Industry-style cashbook workflow.',`<div class="v12-lineage"><div><i>1</i><strong>Batch header</strong><span>Bank, period, currency and owner</span></div><div><i>2</i><strong>Grid entry</strong><span>Edit rows, accounts, tax and dimensions</span></div><div><i>3</i><strong>Validate</strong><span>Duplicates, period and account controls</span></div><div><i>4</i><strong>Post</strong><span>Balanced journal per accepted row</span></div><div><i>5</i><strong>Reconcile</strong><span>Match to external statement</span></div></div>`)}${panel12('Bank reconciliation','Compare bank evidence with cashbook and GL lines.',`<div class="v12-callout"><strong>${(s.reconciliation?.statement||[]).length} statement lines</strong><br>${(s.reconciliation?.statement||[]).filter(x=>x.status==='Matched').length} matched · ${(s.reconciliation?.statement||[]).filter(x=>x.status!=='Matched').length} require action.</div>`,btn12('Open workbench','go','small primary','reconciliation'))}</aside></div></div>`}
function cashBatchModal12(kind='receipt'){const s=core12(),isTransfer=kind==='transfer',title=kind==='receipt'?'Receipt batch entry':kind==='payment'?'Payment batch entry':'Transfer batch entry',defaultBank=s.banks?.[0];openModal(title,'Editable full-width cashbook grid · every accepted row produces a balanced, source-linked journal',`<div class="v12-batch-shell"><div class="v12-batch-head">${field12('Batch number',input12('v12BatchNumber',`CB-${String(Date.now()).slice(-6)}`))}${field12('Cashbook',select12('v12BatchBank',(s.banks||[]).map(b=>[b.id,b.name]),defaultBank?.id))}${field12('Entered by',input12('v12BatchOwner',state.role==='CEO'?'Tinashe Matanho':'Tariro Moyo'))}${field12('Posting date',input12('v12BatchDate',new Date().toISOString().slice(0,10),'date'))}${field12('Currency',select12('v12BatchCurrency',['USD','ZWG','ZAR'],defaultBank?.currency||'USD'))}</div><div class="v12-batch-grid-wrap"><table class="v12-batch-grid"><thead><tr><th>Line</th><th>Date</th><th>Source</th><th>Counterparty</th><th>GL account</th><th>Reference</th><th>Description</th><th>Receipt amount</th><th>Payment amount</th><th>Tax</th><th>Project / fund</th><th></th></tr></thead><tbody id="v12CashRows"></tbody></table></div><div>${btn12('+ Add line','cash-line-add','small soft',kind)}</div><div class="v12-batch-foot"><div class="v12-batch-totals"><div class="v12-batch-total"><span>Entries</span><strong id="v12BatchEntries">0</strong></div><div class="v12-batch-total"><span>Receipts</span><strong id="v12BatchReceipts">$0.00</strong></div><div class="v12-batch-total"><span>Payments</span><strong id="v12BatchPayments">$0.00</strong></div><div class="v12-batch-total"><span>Validation</span><strong id="v12BatchValidation">Incomplete</strong></div></div><div class="v12-callout" id="v12BatchResult"><strong>Expected accounting</strong><br>Receipt rows debit the selected bank and credit revenue or another selected account. Payment rows debit the selected account and credit the bank. VAT creates a separate tax leg.</div></div></div>`,btn12('Cancel','modal-close')+btn12('Save draft','cash-draft','soft',kind)+btn12('Review & post batch','cash-post','primary',kind),true);setTimeout(()=>{addCashRow12(kind);addCashRow12(kind);updateCashTotals12()},40)}
function addCashRow12(kind='receipt'){const s=core12(),tbody=$('#v12CashRows');if(!tbody)return;const i=tbody.children.length+1,accounts=(s.accounts||[]).filter(a=>a.posting&&!a.control),counter=[...(s.customers||[]).map(x=>x.name),...(s.vendors||[]).map(x=>x.name),'Direct entry'];const tr=document.createElement('tr');tr.innerHTML=`<td>${i}</td><td><input type="date" value="${$('#v12BatchDate')?.value||new Date().toISOString().slice(0,10)}"></td><td><select><option>${kind==='receipt'?'CR':'AP'}</option><option>GL</option><option>AR</option><option>AP</option><option>BC</option></select></td><td><select>${counter.map(x=>`<option>${esc12(x)}</option>`).join('')}</select></td><td><select>${accounts.map(a=>`<option value="${a.code}" ${a.code===(kind==='receipt'?'4100':'5140')?'selected':''}>${a.code} · ${esc12(a.name)}</option>`).join('')}</select></td><td><input value="${kind==='receipt'?'RCPT':'PAY'}-${String(i).padStart(3,'0')}"></td><td><input placeholder="Business narration"></td><td><input type="number" step="0.01" value="${kind==='receipt'&&i===1?'1000':'0'}"></td><td><input type="number" step="0.01" value="${kind==='payment'&&i===1?'1000':'0'}"></td><td><select><option value="0">No VAT</option><option value="0.15">VAT 15%</option><option value="0">Zero rated</option></select></td><td><select><option>Corporate</option><option>Growth Fund I</option><option>MFI Portfolio</option><option>Pension Liquidity</option></select></td><td><button class="v12-btn small danger" data-v12="cash-line-remove">×</button></td>`;tbody.appendChild(tr);tr.querySelectorAll('input,select').forEach(x=>x.addEventListener('input',updateCashTotals12));updateCashTotals12()}
function readCashRows12(){return $$('#v12CashRows tr').map(tr=>{const c=tr.querySelectorAll('input,select');return {date:c[0].value,source:c[1].value,counterparty:c[2].value,account:c[3].value,reference:c[4].value,description:c[5].value,receipt:num12(c[6].value),payment:num12(c[7].value),tax:num12(c[8].value),project:c[9].value}}).filter(x=>x.receipt||x.payment)}
function updateCashTotals12(){const rows=readCashRows12(),r=rows.reduce((s,x)=>s+x.receipt,0),p=rows.reduce((s,x)=>s+x.payment,0);if($('#v12BatchEntries'))$('#v12BatchEntries').textContent=rows.length;if($('#v12BatchReceipts'))$('#v12BatchReceipts').textContent=money12(r,$('#v12BatchCurrency')?.value||'USD');if($('#v12BatchPayments'))$('#v12BatchPayments').textContent=money12(p,$('#v12BatchCurrency')?.value||'USD');if($('#v12BatchValidation'))$('#v12BatchValidation').textContent=rows.length&&rows.every(x=>x.account&&x.reference&&(x.receipt>0)!==(x.payment>0))?'Ready':'Review';if($('#v12BatchResult'))$('#v12BatchResult').className=`v12-callout ${rows.length&&rows.every(x=>x.account&&x.reference&&(x.receipt>0)!==(x.payment>0))?'':'warn'}`}
function postCashBatch12(kind){const s=core12(),rows=readCashRows12(),bank=s.banks?.find(x=>x.id===$('#v12BatchBank')?.value);if(!bank||!rows.length)return toast('Batch incomplete','Select a cashbook and enter at least one valid line.','bad');const currency=$('#v12BatchCurrency')?.value||'USD',rate=currency==='USD'?1:currency==='ZWG'?1/(s.fxRates?.find(x=>x.pair==='USD/ZWG')?.rate||26.8776):s.fxRates?.find(x=>x.pair==='ZAR/USD')?.rate||.0552,created=[];for(const row of rows){if((row.receipt>0)===(row.payment>0))throw new Error(`Row ${row.reference}: enter either a receipt or a payment.`);const gross=row.receipt||row.payment,net=row.tax?gross/(1+row.tax):gross,tax=gross-net,lines=row.receipt?[{account:bank.gl,debit:gross,credit:0,description:row.description,project:row.project,currency,rate},{account:row.account,debit:0,credit:net,description:row.description,project:row.project,currency,rate},...(tax?[{account:'2100',debit:0,credit:tax,description:'Output VAT',project:row.project,currency,rate}]:[])]:[{account:row.account,debit:net,credit:0,description:row.description,project:row.project,currency,rate},...(tax?[{account:'1350',debit:tax,credit:0,description:'Recoverable VAT',project:row.project,currency,rate}]:[]),{account:bank.gl,debit:0,credit:gross,description:row.description,project:row.project,currency,rate}];created.push(window.MatanhoAccountingV8.postJournal({date:row.date,reference:row.reference,description:row.description||`${kind} · ${row.counterparty}`,source:'Cashbook',sourceId:$('#v12BatchNumber').value,currency,rate,lines,status:'Posted',maker:$('#v12BatchOwner').value,evidence:['Cashbook batch']}))}V12.cashBatches.unshift({id:$('#v12BatchNumber').value,kind,date:$('#v12BatchDate').value,bank:bank.name,currency,rows:rows.map((x,i)=>({...x,journal:created[i].id,status:'Posted'}))});save12();closeModal();window.MatanhoAccountingV8.navigate('cash');toast('Cashbook batch posted',`${created.length} balanced journal(s) were posted and linked to the batch.`)}
function invoiceIntake12(){const s=core12();openModal('AI supplier invoice intake','Capture a picture, upload a PDF or import an email attachment. Extracted fields remain editable before posting.',`<div class="v12-grid v12-two"><div>${panel12('Source image or document','The original file is retained with checksum, uploader and timestamp.',`<input class="v12-input" id="v12InvoiceFile" type="file" accept="image/*,.pdf" capture="environment"><div class="v12-callout" style="margin-top:9px"><strong>AI extraction preview</strong><br>Supplier: Cloud Africa · Invoice CA-4410 · Date 27 Jul 2026 · Net USD 5,930.43 · VAT USD 889.57 · Gross USD 6,820.00.</div>`)}</div><aside>${panel12('Extracted accounting fields','Review every field before a bill and GL journal are created.',`${field12('Vendor',select12('v12AiVendor',(s.vendors||[]).map(x=>[x.id,x.name]),'VND-0026'))}${field12('Supplier invoice',input12('v12AiInvoice','CA-4410'))}${field12('Invoice date',input12('v12AiDate','2026-08-01','date'))}${field12('Expense account',select12('v12AiAccount',(s.accounts||[]).filter(x=>x.posting&&x.type==='Expense').map(x=>[x.code,`${x.code} · ${x.name}`]),'5140'))}${field12('Net amount',input12('v12AiNet','5930.43','number'))}${field12('VAT amount',input12('v12AiVat','889.57','number'))}${field12('Project / fund',select12('v12AiProject',['Corporate','Technology','Growth Fund I','MFI Portfolio'],'Technology'))}`)}</aside></div>`,btn12('Cancel','modal-close')+btn12('Validate extraction','ai-validate','soft')+btn12('Create bill and GL journal','ai-post','primary'),true)}
function reportPreview12(type){openModal(`${reportCatalog12.find(x=>x[0]===type)?.[1]||'Financial Report'} · Preview`,'Controlled document preview · zoom, maximise, sign and email',`<div class="v12-preview-toolbar">${btn12('− Zoom','doc-zoom-out','small')}${btn12('+ Zoom','doc-zoom-in','small')}${btn12('Maximise','doc-max','small soft')}${btn12('Minimise','doc-min','small')}</div><div style="overflow:auto;background:#eaf0f7;padding:13px;border-radius:12px"><div class="v12-preview-stage" id="v12PreviewStage">${reportSheet12(type)}</div></div>`,btn12('Edit letterhead','letterhead-edit')+btn12('Email secure link','doc-email','soft',`REPORT-${type}`)+(['CEO','Finance Director','Financial Controller','Group Administrator'].includes(state.role)&&!V12.signed[`REPORT-${type}`]?btn12('Sign document','doc-sign','primary',`REPORT-${type}`):btn12('Close','modal-close','primary')));setTimeout(()=>$('#modal')?.classList.add('v12-preview-modal'),0)}
function financeDocPreview12(token){const [kind,id]=String(token).split('|'),signed=V12.signed[`DOC-${id}`];openModal(`${kind} · ${id}`,'Premium controlled business document preview',`<div class="v12-preview-toolbar">${btn12('− Zoom','doc-zoom-out','small')}${btn12('+ Zoom','doc-zoom-in','small')}${btn12('Maximise','doc-max','small soft')}${btn12('Minimise','doc-min','small')}</div><div style="overflow:auto;background:#eaf0f7;padding:13px;border-radius:12px"><div class="v12-preview-stage" id="v12PreviewStage"><article class="v12-sheet">${lh12()}<div class="v12-report-mast"><div><div class="v12-eye">${esc12(kind)}</div><h2>${esc12(id)}</h2><p>Matanho Capital Partners · 01 Aug 2026 · USD</p></div><div class="v12-version">${signed?'Signed controlled copy':'Draft controlled copy'}<br>Version 3</div></div><div style="padding:0 34px 16px"><div class="v12-facts"><div class="v12-fact"><span>Counterparty</span><strong>${kind==='Purchase order'?'Dube & Partners':'Mukuru Microfinance'}</strong></div><div class="v12-fact"><span>Document total</span><strong>${money12(28476)}</strong></div><div class="v12-fact"><span>Terms</span><strong>30 days</strong></div><div class="v12-fact"><span>Status</span><strong>${signed?'Signed':'Ready'}</strong></div></div></div><table class="v12-statement"><thead><tr><th>Description</th><th>Quantity</th><th>Rate</th><th>Tax</th><th>Total</th></tr></thead><tbody><tr><td>Professional services and implementation support</td><td>1</td><td>${money12(24761.74)}</td><td>${money12(3714.26)}</td><td>${money12(28476)}</td></tr><tr class="grand"><td colspan="4">Document total</td><td>${money12(28476)}</td></tr></tbody></table><div class="v12-signatures"><div class="v12-signature"><strong>Chipo Ndlovu</strong><span>Prepared by</span></div><div class="v12-signature"><strong>Farai Mapfumo</strong><span>Reviewed by</span></div><div class="v12-signature"><strong>${signed?esc12(signed.user):'Signature pending'}</strong><span>${signed?esc12(signed.time):'Authorised signatory'}</span></div></div></article></div></div>`,btn12('Edit document','doc-edit','',id)+btn12('Email document','doc-email','soft',`DOC-${id}`)+(['CEO','Finance Director','Financial Controller','Group Administrator'].includes(state.role)&&!signed?btn12('Sign document','doc-sign','primary',`DOC-${id}`):btn12('Close','modal-close','primary')))}
function letterheadEditor12(){const l=V12.letterhead;openModal('Edit premium letterhead','Customise controlled reports, invoices, quotations, purchase orders and compliance packs.',`<div class="v12-grid v12-two"><div>${panel12('Letterhead settings','Minimal institutional identity with controlled metadata.',`${field12('Legal name',input12('v12LhLegal',l.legalName))}${field12('Descriptor / tagline',input12('v12LhTag',l.tagline))}${field12('Address',input12('v12LhAddress',l.address))}${field12('Finance email',input12('v12LhEmail',l.email,'email'))}${field12('Registration',input12('v12LhReg',l.registration))}${field12('Tax identity',input12('v12LhTax',l.tax))}${field12('Accent colour',input12('v12LhAccent',l.accent,'color'))}`)}</div><aside>${panel12('Live preview','The same letterhead is applied to all governed output.',`<article class="v12-sheet" style="min-width:0">${lh12()}<div class="v12-report-mast"><div><div class="v12-eye">Controlled document</div><h2>Management Accounts</h2><p>July 2026 · USD · Accrual basis</p></div></div></article>`)}</aside></div>`,btn12('Cancel','modal-close')+btn12('Save letterhead version','letterhead-save','primary'),true)}
function notifications12(){openDrawer('Finance notifications','Signatures, approvals, access requests and accounting control events',V12.notifications.length?V12.notifications.map(n=>`<div class="v12-callout ${n.type==='Signature'?'warn':''}" style="margin-bottom:8px"><strong>${esc12(n.title)}</strong><br>${esc12(n.detail)}<span class="v12-sub">${esc12(n.time)} · ${esc12(n.type)}</span></div>`).join(''):'<div class="v12-callout">No unread finance notifications.</div>',btn12('Mark all read','notifications-clear','primary'))}
function openJournal12(id){const s=core12(),j=(s.journals||[]).find(x=>x.id===id);if(!j)return;openDrawer(j.id,`${j.source} · ${j.reference} · ${j.status}`,`<div class="v12-facts"><div class="v12-fact"><span>Date</span><strong>${d12(j.date)}</strong></div><div class="v12-fact"><span>Maker</span><strong>${esc12(j.maker)}</strong></div><div class="v12-fact"><span>Checker</span><strong>${esc12(j.checker||'Pending')}</strong></div><div class="v12-fact"><span>Total</span><strong>${money12(j.total)}</strong></div></div><div style="margin-top:10px">${table12(['Account','Description','Project / fund','Debit','Credit','Currency / rate'],(j.lines||[]).map(l=>`<tr data-action="noop"><td><strong>${l.account}</strong><span class="v12-sub">${esc12(accountMap12()[l.account]?.name)}</span></td><td>${esc12(l.description)}</td><td>${esc12(l.project)}</td><td class="v12-num">${l.baseDebit?money12(l.baseDebit):'—'}</td><td class="v12-num">${l.baseCredit?money12(l.baseCredit):'—'}</td><td>${esc12(l.currency)} · ${num12(l.rate).toFixed(4)}</td></tr>`).join(''),'780px','360px')}</div><div class="v12-callout" style="margin-top:10px"><strong>Audit relationship</strong><br>${esc12(j.description)} · source ${esc12(j.sourceId||j.reference)} · immutable ${j.immutable?'yes':'no'}.</div>`,btn12('Open source module','go','soft',({Cashbook:'cash',Receivables:'receivables',Payables:'payables',Investments:'investments',Inventory:'inventory'}[j.source]||'ledger')))}
function genericRecord12(kind,id){toast(`${kind} opened`,`${id} is linked to its detailed operational workspace.`)}
function addNotification12(title,detail,type='Workflow'){V12.notifications.unshift({id:`N-${Date.now()}`,title,detail,time:'Just now',type,status:'Unread'});save12();enhance12()}
function docSign12(id){const user=state.role==='CEO'?'Tinashe Matanho':'Tariro Moyo';V12.signed[id]={user,role:state.role,time:new Date().toLocaleString('en-ZW')};V12.notifications=V12.notifications.filter(x=>!x.detail.includes(id.replace('COMP-','').replace('REPORT-','')));addNotification12('Document signed',`${id} was digitally signed by ${user} as ${state.role}.`,'Signature');closeModal();toast('Digital signature applied',`${id} now contains the signer identity, role, time and controlled document hash.`);render()}
function sortTable12(th){const table=th.closest('table'),tbody=table?.tBodies?.[0];if(!tbody)return;const index=[...th.parentElement.children].indexOf(th),asc=th.dataset.dir!=='asc';$$('th',th.parentElement).forEach(x=>delete x.dataset.dir);th.dataset.dir=asc?'asc':'desc';const rows=$$('tr',tbody).filter(r=>!r.classList.contains('v12-row-expand')&&!r.classList.contains('v12-tb-group'));rows.sort((a,b)=>{const A=a.children[index]?.innerText.trim()||'',B=b.children[index]?.innerText.trim()||'',na=parseFloat(A.replace(/[^0-9.-]/g,'')),nb=parseFloat(B.replace(/[^0-9.-]/g,'')),cmp=Number.isFinite(na)&&Number.isFinite(nb)?na-nb:A.localeCompare(B);return asc?cmp:-cmp});rows.forEach(r=>tbody.appendChild(r))}
function enhanceClose12(){const root=$('.v11');if(!root)return;$$('[data-v10-ready="row"]',root).forEach(r=>r.removeAttribute('data-v10-ready'));$$('tbody tr',root).forEach(r=>{if(!r.dataset.action)r.dataset.action='noop'});const panel=$$('.v11-panel',root).find(p=>p.querySelector('.v11-panel-head h2')?.textContent.trim()==='Close task register');if(panel){const wrap=panel.querySelector('.v11-table-wrap'),table=panel.querySelector('.v11-table');if(wrap)wrap.classList.add('v12-clamped');if(table){table.dataset.v12Close='1';$$('thead th',table).forEach((th,i)=>{th.dataset.v12CloseSort=i;th.style.cursor='pointer'});if(!panel.querySelector('.v12-table-slice')){const c=document.createElement('div');c.className='v12-table-slice';c.innerHTML=`<button data-v12="close-slice" data-id="top">Top 10</button><button data-v12="close-slice" data-id="bottom">Bottom 10</button><button data-v12="close-slice" data-id="all">All</button>`;wrap?.parentNode?.insertBefore(c,wrap)}applyCloseSlice12()}}}
function applyCloseSlice12(){const table=$('[data-v12-close="1"]');if(!table)return;const rows=$$('tbody tr',table),mode=V12.closeSlice;rows.forEach((r,i)=>r.hidden=mode==='top'?i>=10:mode==='bottom'?i<Math.max(0,rows.length-10):false);$$('[data-v12="close-slice"]').forEach(b=>b.classList.toggle('active',b.dataset.id===mode))}
function enhanceProfile12(){const profile=$('.profile'),av=profile?.querySelector('.avatar'),name=state.role==='CEO'?'Tinashe Matanho':'Tariro Moyo';if(av){let img=av.querySelector('img');if(!img){img=document.createElement('img');av.replaceChildren(img)}img.src=photo12(name);img.alt=`${name} profile`;img.width=36;img.height=36}const strong=profile?.querySelector('strong');if(strong)strong.textContent=name;const menuImg=$('#v5ProfileMenu .profile-menu-head img');if(menuImg){menuImg.src=photo12(name);menuImg.alt=`${name} profile`}const bell=$('#bellBtn');if(bell){bell.dataset.action='noop';bell.dataset.v12='notifications';let n=bell.querySelector('.v12-bell-count');const count=V12.notifications.filter(x=>x.status!=='Read').length;if(count){if(!n){n=document.createElement('span');n.className='v12-bell-count';bell.appendChild(n)}n.textContent=count}else n?.remove()}}
