function reconciliation17(){const bank=V17.reconMode==='bank';const stmt=[['31 Jul','BANK-CHG-07','Bank charges',-148,'Exception'],['31 Jul','MAMBO-RTGS','Mambo Foods receipt',42600,'Suggested'],['30 Jul','PR-034','Supplier payment batch',-63000,'Matched'],['29 Jul','UNKNOWN-088','Unidentified deposit',2410,'Exception'],['28 Jul','RENT-JUL','Office rent',-7600,'Matched']];const ledger=[['31 Jul','GL-78412','Mambo Foods receipt',42600,'Suggested'],['31 Jul','GL-78389','Monthly bank charges',-148,'Suggested'],['30 Jul','GL-78409','Supplier payment batch',-63000,'Matched'],['29 Jul','GL-78355','Mobile money sweep',8700,'Review'],['28 Jul','GL-78320','Office rent',-7600,'Matched']];const modules=[['Portfolio Management','Matanho Growth Fund I','$12,440','Exception'],['Payroll','July payroll control','$0','Matched'],['Procurement','Approved supplier commitments','$4,920','Review'],['Loan Management','Borrower collections','$0','Matched']];return `<div class="v17-page ${V17.reconMax?'v17-recon-max':''}" id="v17ReconPage">${head17('Reconciliation control','Bank & Internal Module Reconciliation','Compare external bank evidence or internal ERP sub-ledgers to accounting, investigate differences and retain governed sign-off.',`${b17(V17.reconMax?'Minimise comparison':'Maximise comparison','recon-max','soft')}${b17('Import evidence','recon-import','')}${b17('Run auto-match','recon-auto','primary')}`)}<div class="v17-kpis">${kpi17('Statement balance','$2.037m','Selected source balance','#006cff')}${kpi17('Ledger balance','$2.025m','Accounting book balance','#6a45ff')}${kpi17('Difference','$11.84k','Requires investigation','#d92d4b')}${kpi17('Matched','184 / 195','94.4% of lines','#008c66')}${kpi17('Suggested matches','6','Confidence above 85%','#db7b00')}${kpi17('Open exceptions','5','Owner and due date required','#d92d4b')}</div>${filterButton17('reconciliation',4)}<div class="v17-filters ${V17.filters.reconciliation?'open':''}" data-filter="reconciliation">${field17('Reconciliation type',select17('v17ReconMode',[['bank','Bank to accounting'],['module','Internal ERP module to accounting']],V17.reconMode))}${field17(bank?'Bank account':'Internal module',select17('v17ReconSource',bank?['CBZ USD Operating','Stanbic USD Reserve','ZiG Operating','NMB USD Collections']:['Portfolio Management','Payroll','Procurement','Loan Management'],bank?V17.reconBank:'Portfolio Management'))}${field17('Period',select17('v17ReconPeriod',['Jul 2026','Jun 2026','Custom'],'Jul 2026'))}${field17('Matching window',select17('v17ReconWindow',['Same day','± 2 days','± 5 days'],'± 2 days'))}${field17('Amount tolerance',input17('v17ReconTolerance','1.00','number'))}${field17('Status',select17('v17ReconStatus',['All lines','Exceptions','Suggested','Matched'],'All lines'))}</div>${bank?`<div class="v17-recon-grid"><section class="v17-recon-pane"><header><div><strong>External bank statement</strong><span>${esc17(V17.reconBank)} · imported evidence</span></div>${status17('Source evidence')}</header>${table17(['Date','Reference','Description','Amount','Status'],stmt.map((x,i)=>`<tr data-v17="recon-line" data-id="S${i}"><td>${x[0]}</td><td class="v17-link">${x[1]}</td><td>${x[2]}</td><td class="num">${money17(x[3])}</td><td>${status17(x[4])}</td></tr>`).join(''),'620px',true)}</section><section class="v17-recon-pane"><header><div><strong>Cashbook and General Ledger</strong><span>Posted accounting population</span></div>${status17('Book evidence')}</header>${table17(['Date','Journal','Narrative','Amount','Status'],ledger.map((x,i)=>`<tr data-v17="recon-line" data-id="L${i}"><td>${x[0]}</td><td class="v17-link">${x[1]}</td><td>${x[2]}</td><td class="num">${money17(x[3])}</td><td>${status17(x[4])}</td></tr>`).join(''),'620px',true)}</section></div>`:`<div class="v17-grid two">${panel17('Internal module ledgers','Reconcile operational sub-ledgers to the accounting control accounts.',table17(['Module','Scope','Difference','Status'],modules.map((x,i)=>`<tr data-v17="module-recon" data-id="${i}"><td class="v17-link">${x[0]}</td><td>${x[1]}</td><td class="num">${x[2]}</td><td>${status17(x[3])}</td></tr>`).join(''),'620px',false))}${panel17('Accounting control accounts','Period balances and interface controls.',`<div class="v17-file-list">${[['Portfolio investments control','1510 · $4.02m','Review'],['Payroll clearing','2180 · $0','Matched'],['Purchase commitments','2090 · $184.6k','Review'],['Loan receivables control','1320 · $2.81m','Matched']].map(x=>`<div class="v17-file" data-v17="module-detail"><i>↔</i><div><strong>${x[0]}</strong><span>${x[1]}</span></div>${status17(x[2])}</div>`).join('')}</div>`)}</div>`}<div class="v17-toolbar"><div class="v17-actions">${b17('Create adjustment','recon-adjust','soft')}${b17('Match selected','recon-match','primary')}${b17('Submit reconciliation','recon-submit','')}</div><span class="v17-small">Every manual match, adjustment and sign-off records the user, timestamp, reason and evidence.</span></div></div>`}
