function payables17(){const tab=V17.payTab;let body='';if(tab==='overview')body=`<div class="v17-grid two"><div class="v17-stack">${panel17('Payables work queue','Bills, exceptions and payment readiness.',table17(['Bill','Vendor','Due date','Amount','Variance','Status'],supplierInvoices.map(x=>`<tr data-v17="bill" data-id="${x.id}"><td class="v17-link">${x.id}<span class="v17-sub">${x.invoice}</span></td><td>${x.supplier}</td><td>${x.due}</td><td class="num">${money17(x.amount,x.currency)}</td><td class="num">${x.variance?money17(x.variance,x.currency):'—'}</td><td>${status17(x.status)}</td></tr>`).join(''),'800px',true))}</div><aside class="v17-stack">${panel17('Payment readiness','Control checks before bank release.',`<div class="v17-file-list">${[['Beneficiary validation','2 vendors require independent verification','Exception'],['Duplicate-payment scan','No duplicates in current run','Complete'],['Tax deductions','$15.6k configured','Review'],['Liquidity coverage','1.8× scheduled payments','Complete']].map(x=>`<div class="v17-file" data-v17="go" data-id="payables"><i>✓</i><div><strong>${x[0]}</strong><span>${x[1]}</span></div>${status17(x[2])}</div>`).join('')}</div>`)}${panel17('Upcoming cash requirements','Approved obligations by horizon.',`<div class="v17-facts"><div class="v17-fact"><span>Today</span><strong>$63.0k</strong></div><div class="v17-fact"><span>7 days</span><strong>$176.4k</strong></div><div class="v17-fact"><span>30 days</span><strong>$401.8k</strong></div><div class="v17-fact"><span>Overdue</span><strong>$24.9k</strong></div></div>`)}</aside></div>`;if(tab==='bills')body=panel17('Supplier bills','Three-way matching, tax, evidence and approvals.',table17(['Bill','Vendor','Invoice date','Due','PO / receipt','Amount','Variance','Status'],supplierInvoices.map(x=>`<tr data-v17="bill" data-id="${x.id}"><td class="v17-link">${x.id}</td><td>${x.supplier}</td><td>${x.date}</td><td>${x.due}</td><td>${x.po}<span class="v17-sub">${x.grn}</span></td><td class="num">${money17(x.amount,x.currency)}</td><td class="num">${x.variance?money17(x.variance):'—'}</td><td>${status17(x.status)}</td></tr>`).join(''),'960px',true));if(tab==='vendors')body=panel17('Vendor registry and digital KYC','Open any vendor for commercial history, editable profile fields, KYC, tax, banking, risk and audit evidence.',table17(['Vendor','Category','Currency','YTD spend','KYC','Tax status','Owner','Status'],vendors17.map(v=>`<tr data-v17="vendor-profile" data-id="${v.name}"><td class="v17-link">${v.name}<span class="v17-sub">${v.id}</span></td><td>${v.category}</td><td>${v.currency}</td><td class="num">${money17(v.spend,v.currency)}</td><td>${v.kyc}%</td><td>${v.tax}</td><td>${v.owner}</td><td>${status17(v.status)}</td></tr>`).join(''),'950px',true));if(tab==='ageing')body=panel17('Creditors ageing','Outstanding supplier obligations by ageing bucket.',table17(['Vendor','Total','Current','31–60 days','61–90 days','Status'],ageingRows17('ap'),'820px',false));if(tab==='recurring')body=recurringPanel17('Supplier bill');if(tab==='payments')body=panel17('Supplier payment runs','Select approved bills, validate beneficiaries, approve and generate the bank instruction.',`<div class="v17-callout"><strong>Current run PAYRUN-2026-08-05-01.</strong><br>34 invoices · gross $418,760.40 · deductions $15,602.85 · net bank file $403,157.55.</div><div class="v17-toolbar"><div class="v17-actions">${b17('Open payment selection','payment-run','primary')}${b17('Preview bank file','document-preview','soft','PAYRUN-2026-08-05-01')}</div></div>${table17(['Bill','Vendor','Due date','Gross','Deductions','Net','Validation'],supplierInvoices.map(x=>`<tr><td>${x.id}</td><td>${x.supplier}</td><td>${x.due}</td><td class="num">${money17(x.amount)}</td><td class="num">${money17(x.amount*.05)}</td><td class="num">${money17(x.amount*.95)}</td><td>${status17(x.status==='Match exception'?'Blocked':'Ready')}</td></tr>`).join(''),'900px',true)}`);return `<div class="v17-page">${head17('Accounts payable','Payables & Payments','Manage supplier bills, three-way matching, vendor KYC, payment selection, ageing and recurring obligations.',`${b17('New supplier bill','new-document','primary','bill')}${b17('Create payment run','payment-run','')}`)}<div class="v17-kpis">${kpi17('Outstanding payables','$401.8k','34 open bills','#006cff')}${kpi17('Due within 7 days','$176.4k','13 suppliers','#db7b00')}${kpi17('Overdue','$24.9k','4 bills','#d92d4b')}${kpi17('Match exceptions','3','$29.1k blocked','#d92d4b')}${kpi17('Payment run','$403.2k','Net bank instruction','#6a45ff')}${kpi17('Vendor KYC','94.6%','7 profiles require review','#008c66')}</div>${filterButton17('payables',3)}<div class="v17-filters ${V17.filters.payables?'open':''}" data-filter="payables">${field17('Vendor',select17('v17PayVendor',['All vendors',...vendors17.map(x=>x.name)],'All vendors'))}${field17('Due date',select17('v17PayDue',['All due dates','Overdue','Next 7 days','Next 30 days'],'All due dates'))}${field17('Currency',select17('v17PayCurrency',['All currencies','USD','ZWG','ZAR'],'All currencies'))}${field17('Status',select17('v17PayStatus',['All statuses','Ready','Review','Blocked'],'All statuses'))}${field17('Project / mandate',select17('v17PayProject',['All projects','None','Growth Fund I','MFI Portfolio','Pension Liquidity'],'All projects'))}</div>${tabs17([['overview','Overview'],['bills','Bills'],['payments','Payments'],['vendors','Vendors & KYC'],['ageing','Creditors ageing'],['recurring','Recurring']],tab,'pay-tab')}${body}</div>`}
function receivables17(){const tab=V17.arTab;let body='';if(tab==='overview')body=`<div class="v17-grid two">${panel17('Collection work queue','Invoices, promises, disputes and receipt allocation.',table17(['Customer','Invoice','Due date','Outstanding','Age','Status'],receivables.map(x=>`<tr data-v17="client-profile" data-id="${x.customer}"><td class="v17-link">${x.customer}</td><td>${x.invoice}</td><td>${x.due}</td><td class="num">${money17(x.outstanding,x.currency)}</td><td>${x.age} days</td><td>${status17(x.status)}</td></tr>`).join(''),'780px',true))}${panel17('Collection performance','Cash conversion and promised receipts.',`${growthChart17('collections')}<div class="v17-facts" style="margin-top:10px"><div class="v17-fact"><span>DSO</span><strong>38 days</strong></div><div class="v17-fact"><span>Promise coverage</span><strong>74%</strong></div><div class="v17-fact"><span>Disputes</span><strong>$28.4k</strong></div><div class="v17-fact"><span>Receipts MTD</span><strong>$426.8k</strong></div></div>`)}</div>`;if(tab==='invoices')body=panel17('Customer invoices','Open, partially paid and disputed invoices.',table17(['Invoice','Customer','Invoice date','Due','Original','Outstanding','Status'],receivables.map(x=>`<tr data-v17="document-preview" data-id="${x.invoice}"><td class="v17-link">${x.invoice}</td><td>${x.customer}</td><td>${x.date}</td><td>${x.due}</td><td class="num">${money17(x.original,x.currency)}</td><td class="num">${money17(x.outstanding,x.currency)}</td><td>${status17(x.status)}</td></tr>`).join(''),'900px',true));if(tab==='clients')body=panel17('Client registry','Responsive client profiles, transactions, contacts, statements, documents and audit history.',table17(['Client','Sector','Currency','Outstanding','KYC','Manager','Status'],clients17.map(c=>`<tr data-v17="client-profile" data-id="${c.name}"><td class="v17-link">${c.name}<span class="v17-sub">${c.id}</span></td><td>${c.sector}</td><td>${c.currency}</td><td class="num">${money17(c.balance,c.currency)}</td><td>${c.kyc}%</td><td>${c.manager}</td><td>${status17(c.status)}</td></tr>`).join(''),'860px',true));if(tab==='ageing')body=panel17('Debtors ageing','Customer balances by ageing bucket with statement and collection actions.',table17(['Customer','Total','Current','31–60 days','61–90 days','Status'],ageingRows17('ar'),'820px',false));if(tab==='statements')body=panel17('Client statements','Preview and securely email account statements.',table17(['Client','Period','Opening','Invoices','Receipts','Closing','Action'],clients17.map(c=>`<tr data-v17="client-profile" data-id="${c.name}"><td class="v17-link">${c.name}</td><td>Jul 2026</td><td class="num">${money17(c.balance*.72,c.currency)}</td><td class="num">${money17(c.balance*.55,c.currency)}</td><td class="num">${money17(c.balance*.27,c.currency)}</td><td class="num">${money17(c.balance,c.currency)}</td><td>${b17('Send statement','send-statement','small',c.name)}</td></tr>`).join(''),'920px',true));if(tab==='recurring')body=recurringPanel17('Customer invoice');if(tab==='receipts')body=panel17('Receipt allocation','Allocate receipts to invoices and retain remittance evidence.',table17(['Receipt','Customer','Date','Amount','Unallocated','Status'],[['RCPT-2190','Mambo Foods','31 Jul',42600,0,'Allocated'],['RCPT-2188','Horizon Mining','30 Jul',98600,0,'Allocated'],['RCPT-2182','B Financial Services','28 Jul',32000,21600,'Part allocated']].map(x=>`<tr><td class="v17-link">${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td class="num">${money17(x[3])}</td><td class="num">${money17(x[4])}</td><td>${status17(x[5])}</td></tr>`).join(''),'760px',false));return `<div class="v17-page">${head17('Accounts receivable','Receivables & Collections','Manage customer invoices, receipts, ageing, disputes, recurring billing and secure statement delivery.',`${b17('New customer invoice','new-document','primary','invoice')}${b17('Allocate receipt','allocate-receipt','')}`)}<div class="v17-kpis">${kpi17('Outstanding','$618.4k','All open invoices','#006cff')}${kpi17('Current','$402.6k','65.1% of total','#008c66')}${kpi17('31–60 days','$126.8k','20.5% of total','#db7b00')}${kpi17('61+ days','$89.0k','14.4% of total','#d92d4b')}${kpi17('DSO','38 days','Target 32 days','#6a45ff')}${kpi17('Promises to pay','$74.6k','Due this week','#00a9e8')}</div>${filterButton17('receivables',3)}<div class="v17-filters ${V17.filters.receivables?'open':''}" data-filter="receivables">${field17('Client',select17('v17ArClient',['All clients',...clients17.map(x=>x.name)],'All clients'))}${field17('Ageing',select17('v17ArAge',['All ages','Current','31–60 days','61–90 days','90+ days'],'All ages'))}${field17('Currency',select17('v17ArCurrency',['All currencies','USD','ZWG'],'All currencies'))}${field17('Status',select17('v17ArStatus',['All statuses','Current','Promise to pay','Disputed','Escalated'],'All statuses'))}</div>${tabs17([['overview','Overview'],['invoices','Invoices'],['receipts','Receipts'],['clients','Clients'],['ageing','Debtors ageing'],['statements','Statements'],['recurring','Recurring']],tab,'ar-tab')}${body}</div>`}
function recurringPanel17(type='All'){const rows=recurring17.filter(x=>type==='All'||x.type===type);return panel17('Recurring schedules','Reusable billing, invoice, expense, bill and accrual automation.',`${table17(['Schedule','Type','Counterparty','Description','Frequency','Next run','Amount','Status'],rows.map(x=>`<tr data-v17="recurring-detail" data-id="${x.id}"><td class="v17-link">${x.id}</td><td>${x.type}</td><td>${x.counterparty}</td><td>${x.description}</td><td>${x.frequency}</td><td>${x.next}</td><td class="num">${money17(x.amount)}</td><td>${status17(x.status)}</td></tr>`).join(''),'940px',false)}<div class="v17-toolbar"><span></span>${b17('New recurring schedule','new-recurring','primary',type)}</div>`)}
function expenses17(){const tab=V17.expenseTab;let body='';if(tab==='claims')body=panel17('Submitted expense claims','Open a claim to inspect itemised expenses, images, receipts, policy and approval evidence.',table17(['Claim','Employee','Purpose','Submitted','Amount','Evidence','Policy','Status'],claims.map((x,i)=>`<tr data-v17="claim" data-id="${x.id}"><td class="v17-link">${x.id}</td><td>${x.employee}</td><td>${x.purpose}</td><td>${x.submitted}</td><td class="num">${money17(x.amount,x.currency)}</td><td>${x.receipts} · ${i%2?'2 images':'PDF + image'}</td><td>${x.policy}</td><td>${status17(x.status)}</td></tr>`).join(''),'940px',true));if(tab==='corporate')body=panel17('Corporate card feed','Import, code, match evidence and approve card transactions.',table17(['Date','Cardholder','Merchant','Amount','GL account','Project','Evidence','Status'],[['31 Jul','Kundai Moyo','Rainbow Towers',420,'Travel','Growth Fund I','Receipt image','Matched'],['30 Jul','Tendai Ncube','Microsoft',1840,'Software','Corporate','Invoice PDF','Review'],['29 Jul','Rudo Kaseke','Zuva Petroleum',286,'Travel','MFI Portfolio','Receipt image','Matched']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td class="num">${money17(x[3])}</td><td>${x[4]}</td><td>${x[5]}</td><td class="v17-link" data-v17="document-preview" data-id="${x[6]}">${x[6]}</td><td>${status17(x[7])}</td></tr>`).join(''),'880px',false));if(tab==='recurring')body=recurringPanel17('Expense accrual');return `<div class="v17-page">${head17('Expense control','Expenses & Employee Claims','Review employee claims, corporate card activity, receipt images, policy exceptions and recurring expenses.',`${b17('New expense claim','new-claim','primary')}${b17('Import corporate card','expense-import','')}`)}<div class="v17-kpis">${kpi17('Submitted claims','$36.5k','42 open records','#006cff')}${kpi17('Ready to approve','$18.7k','All controls passed','#008c66')}${kpi17('Policy exceptions','4','2 require manager rationale','#d92d4b')}${kpi17('Evidence coverage','96%','3 receipts missing','#db7b00')}${kpi17('Corporate card','$12.4k','Unposted current feed','#6a45ff')}${kpi17('Reimbursements','$18.3k','Next payment run','#00a9e8')}</div>${filterButton17('expenses',3)}<div class="v17-filters ${V17.filters.expenses?'open':''}" data-filter="expenses">${field17('Employee',select17('v17ExpEmployee',['All employees',...new Set(claims.map(x=>x.employee))],'All employees'))}${field17('Project / mandate',select17('v17ExpProject',['All projects','None','Growth Fund I','MFI Portfolio','Pension Liquidity'],'All projects'))}${field17('Policy status',select17('v17ExpPolicy',['All statuses','Clear','Exception','Missing receipt'],'All statuses'))}${field17('Period',select17('v17ExpPeriod',['Jul 2026','Jun 2026','Custom'],'Jul 2026'))}</div>${tabs17([['claims','Claims'],['corporate','Corporate card'],['recurring','Recurring expenses']],tab,'expense-tab')}${body}</div>`}
function billing17(){const tab=V17.billingTab;let body='';const docs={invoices:[['INV-2026-00492','Horizon Mining','15 Jul 2026','14 Aug 2026',98600,'Open'],['INV-2026-00481','Mambo Foods','30 Jun 2026','31 Jul 2026',42600,'Promise to pay']],quotes:[['QT-2026-0091','Mukuru Microfinance','Loan system expansion',184000,'Submitted'],['QT-2026-0088','Pension Mandate','Treasury analytics',126000,'Draft']],pos:[['PO-2026-1108','ZimTech Solutions','Technology equipment',27836,'Received'],['PO-2026-1096','Dube & Partners','Legal services',18750,'Open']]};if(tab==='invoices')body=panel17('Billing and invoices','Create, approve, email and schedule recurring customer invoices.',table17(['Document','Customer','Issue date','Due date','Amount','Status'],docs.invoices.map(x=>`<tr class="v17-document" data-v17="document-preview" data-id="${x[0]}"><td class="v17-link">${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td class="num">${money17(x[4])}</td><td>${status17(x[5])}</td></tr>`).join(''),'720px',false));if(tab==='quotes')body=panel17('Quotations','Human-controlled quotations with AI-assisted comparison and ranking.',`${table17(['Quotation','Client','Scope','Amount','Status'],docs.quotes.map(x=>`<tr class="v17-document" data-v17="document-preview" data-id="${x[0]}"><td class="v17-link">${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td class="num">${money17(x[3])}</td><td>${status17(x[4])}</td></tr>`).join(''),'720px',false)}<div class="v17-toolbar"><span class="v17-small">AI ranks responsive bids using weighted commercial, technical, delivery and risk criteria. Humans retain final authority.</span>${b17('Open AI comparison','ai-quotation','primary')}</div>`);if(tab==='pos')body=panel17('Purchase orders','Approved commitments linked to supplier bills and receipts.',table17(['Purchase order','Vendor','Description','Amount','Status'],docs.pos.map(x=>`<tr class="v17-document" data-v17="document-preview" data-id="${x[0]}"><td class="v17-link">${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td class="num">${money17(x[3])}</td><td>${status17(x[4])}</td></tr>`).join(''),'720px',false));if(tab==='intake')body=panel17('AI invoice intake','Upload or photograph a supplier invoice. The system extracts fields for review before creating the bill and balanced journal.',`<div class="v17-grid two"><div class="v17-callout"><strong>Capture a source document.</strong><br>Supported inputs: camera image, PNG, JPG and PDF. AI extraction never posts directly; the AP officer validates every field.</div><div class="v17-actions">${b17('Take picture','invoice-capture','primary')}${b17('Upload invoice','invoice-upload','soft')}</div></div><div class="v17-facts" style="margin-top:12px"><div class="v17-fact"><span>Vendor</span><strong>ZimTech Solutions</strong></div><div class="v17-fact"><span>Invoice number</span><strong>ZTS-8842</strong></div><div class="v17-fact"><span>Gross amount</span><strong>$28,476.00</strong></div><div class="v17-fact"><span>Extraction confidence</span><strong>97.4%</strong></div></div><div class="v17-toolbar"><span></span>${b17('Review extracted bill','new-document','primary','bill')}</div>`);return `<div class="v17-page">${head17('Commercial documents','Billing, Invoices & Quotations','Create customer invoices, quotations and purchase orders, intake supplier invoices with AI and schedule recurring documents.',`${b17('Create document','new-document','primary',tab==='pos'?'po':tab==='quotes'?'quotation':'invoice')}${b17('Recurring schedules','new-recurring','')}`)}<div class="v17-kpis">${kpi17('Invoices issued','$682.4k','46 this period','#006cff')}${kpi17('Outstanding','$618.4k','38 days DSO','#00a9e8')}${kpi17('Quotations','$1.28m','6 awaiting decision','#6a45ff')}${kpi17('Purchase orders','$184.6k','12 open commitments','#db7b00')}${kpi17('AI intake','97.4%','Average extraction confidence','#008c66')}${kpi17('Recurring documents','14','Next run within 7 days','#d92d4b')}</div>${filterButton17('billing',2)}<div class="v17-filters ${V17.filters.billing?'open':''}" data-filter="billing">${field17('Customer / vendor',select17('v17BillParty',['All counterparties',...clients17.map(x=>x.name),...vendors17.map(x=>x.name)],'All counterparties'))}${field17('Project / mandate',select17('v17BillProject',['All projects','None','Growth Fund I','MFI Portfolio','Pension Liquidity'],'All projects'))}${field17('Status',select17('v17BillStatus',['All statuses','Draft','Submitted','Approved','Open'],'All statuses'))}${field17('Period',select17('v17BillPeriod',['Jul 2026','Jun 2026','Custom'],'Jul 2026'))}</div>${tabs17([['invoices','Invoices'],['quotes','Quotations'],['pos','Purchase orders'],['intake','AI invoice intake']],tab,'billing-tab')}${body}</div>`}
function timesheetsPage17(){return `<div class="v17-page">${head17('Project accounting','Timesheets & Cost Allocation','Review submitted time, project dimensions, billability, labour cost and customer billing eligibility.',`${b17('Import timesheets','timesheet-import','')}${b17('Approve selected','timesheet-approve','primary')}`)}<div class="v17-kpis">${kpi17('Submitted hours','406.5','12 timesheets','#006cff')}${kpi17('Billable hours','334.0','82.2% utilisation','#008c66')}${kpi17('Labour cost','$13.7k','Pending allocation','#6a45ff')}${kpi17('Billing value','$28.6k','Eligible after approval','#00a9e8')}${kpi17('Exceptions','2','Missing narration or task code','#d92d4b')}${kpi17('Approval SLA','91%','Within 24 hours','#db7b00')}</div>${filterButton17('timesheets',4)}<div class="v17-filters ${V17.filters.timesheets?'open':''}" data-filter="timesheets">${field17('Employee',select17('v17TsEmployee',['All employees',...new Set(timesheets17.map(x=>x.employee))],'All employees'))}${field17('Project / mandate',select17('v17TsProject',['All projects',...new Set(timesheets17.map(x=>x.project))],'All projects'))}${field17('Client',select17('v17TsClient',['All clients',...new Set(timesheets17.map(x=>x.client))],'All clients'))}${field17('Status',select17('v17TsStatus',['All statuses','Submitted','Approved','Review','Returned'],'All statuses'))}${field17('Week',select17('v17TsWeek',['27 Jul – 02 Aug','20–26 Jul','Custom'],'27 Jul – 02 Aug'))}</div>${panel17('Submitted timesheets','Click column headers to sort. Open any row for daily time, narration, cost and billing allocation.',table17(['Timesheet','Employee','Project / mandate','Client','Hours','Billable','Cost','Approver','Status'],timesheets17.map(x=>`<tr data-v17="timesheet" data-id="${x.id}"><td class="v17-link">${x.id}</td><td>${x.employee}</td><td>${x.project}</td><td>${x.client}</td><td class="num">${x.hours}</td><td class="num">${x.billable}</td><td class="num">${money17(x.cost)}</td><td>${x.owner}</td><td>${status17(x.status)}</td></tr>`).join(''),'1050px',true))}</div>`}
function investments17(){const total=investments.reduce((a,b)=>a+b.carrying,0);const spans=[['1 / span 7','1 / span 4'],['8 / span 5','1 / span 2'],['8 / span 5','3 / span 2'],['1 / span 5','5 / span 2'],['6 / span 7','5 / span 2']];return `<div class="v17-page">${head17('Treasury and liquidity','Short-Term Investments','CFO-grade portfolio valuation, yield, concentration, daily accruals, maturities and multi-currency liquidity management.',`${b17('New investment instrument','investment-new','primary')}${b17('Run daily accrual','investment-accrue','')}`)}<div class="v17-kpis">${kpi17('Portfolio value',money17(total),'Principal plus accrued interest','#006cff')}${kpi17('Weighted yield','9.84%','Annualised portfolio yield','#008c66')}${kpi17('Accrued income','$46.3k','Current month','#6a45ff')}${kpi17('30-day maturities','$827.6k','Available liquidity','#00a9e8')}${kpi17('Issuer concentration','31.4%','Largest issuer exposure','#db7b00')}${kpi17('FX exposure','$1.74m','Foreign currency carrying value','#d92d4b')}</div>${filterButton17('investments',4)}<div class="v17-filters ${V17.filters.investments?'open':''}" data-filter="investments">${field17('Portfolio growth',select17('v17InvestmentGrowth',[['1m','1 month'],['3m','3 months'],['6m','6 months'],['12m','12 months'],['ytd','Year to date']],V17.investmentGrowth))}${field17('Entity',select17('v17InvEntity',['Group consolidated','Matanho Capital Partners','Growth Fund I','Pension Liquidity'],'Group consolidated'))}${field17('Instrument type',select17('v17InvType',['All instruments','Money Market','Treasury Bill','Fixed Deposit','Commercial Paper'],'All instruments'))}${field17('Currency',select17('v17InvCurrency',['All currencies','USD','ZWG','ZAR'],'All currencies'))}${field17('Broker / institution',select17('v17InvBroker',['All institutions',...new Set(investments.map(x=>x.issuer))],'All institutions'))}</div><div class="v17-grid two"><div>${panel17('Portfolio value and accrued income','Time-series growth for the selected period. Select the chart to enlarge it.',growthChart17('investment-growth'))}</div><div>${panel17('Liquidity forecast','Upcoming principal and interest inflows.',table17(['Horizon','Principal','Interest','Expected cash','Instruments'],[['0–30 days',820000,7600,827600,1],['31–60 days',1250000,19800,1269800,1],['61–90 days',640000,11300,651300,1],['91+ days',9380000,134400,9514400,2]].map(x=>`<tr><td>${x[0]}</td><td class="num">${money17(x[1])}</td><td class="num">${money17(x[2])}</td><td class="num">${money17(x[3])}</td><td>${x[4]}</td></tr>`).join(''),'620px',false))}</div></div><div class="v17-grid two" style="margin-top:12px"><div>${panel17('Portfolio yield heat map','Treemap size is proportional to investment value. Colour shows yield quality and concentration risk.',`<div class="v17-treemap">${investments.map((x,i)=>`<article class="v17-tile ${i===3?'r1':i===1?'a1':i===4?'g2':'g1'}" style="grid-column:${spans[i][0]};grid-row:${spans[i][1]}" data-v17="investment" data-id="${x.id}"><div><strong>${x.issuer}</strong><span>${x.type} · ${x.currency}</span></div><div><b>${(x.carrying/total*100).toFixed(1)}%</b><span>${x.rate.toFixed(1)}% yield · ${money17(x.carrying,x.currency)}</span></div></article>`).join('')}</div>`)}</div><div>${panel17('Yield and risk watch','Expected yield, realised yield and policy observations.',`<div class="v17-file-list">${investments.map(x=>`<div class="v17-file" data-v17="investment" data-id="${x.id}"><i>${x.rate.toFixed(1)}</i><div><strong>${x.id} · ${x.issuer}</strong><span>${x.type} · matures ${x.maturity}</span></div>${status17(x.limit==='Within limit'?'Within limit':'Review')}</div>`).join('')}</div>`)}</div></div><div style="margin-top:12px">${panel17('Investment register','Full-width instrument register with dimensional, yield, valuation and settlement information.',table17(['Instrument','Issuer','Type','Currency','Principal','APY','Carrying value','Maturity','Days','Limit','Status'],investments.map(x=>`<tr data-v17="investment" data-id="${x.id}"><td class="v17-link">${x.id}</td><td>${x.issuer}</td><td>${x.type}</td><td>${x.currency}</td><td class="num">${money17(x.principal,x.currency)}</td><td class="num">${x.rate.toFixed(2)}%</td><td class="num">${money17(x.carrying,x.currency)}</td><td>${x.maturity}</td><td>${x.days}</td><td>${x.limit}</td><td>${status17(x.status)}</td></tr>`).join(''),'1150px',true))}</div><div style="margin-top:12px">${panel17('Daily accrual register','Latest 12 accrual records. The register covers the full width and scrolls inside its own surface.',table17(['Date','Instrument','Issuer','Currency','Opening','APY','Daily accrual','Closing','Journal status'],accrual17.map(x=>`<tr data-v17="investment" data-id="${x.instrument}"><td>${x.date}</td><td class="v17-link">${x.instrument}</td><td>${x.issuer}</td><td>${x.currency}</td><td class="num">${money17(x.opening,x.currency)}</td><td class="num">${x.rate.toFixed(2)}%</td><td class="num">${money17(x.daily,x.currency)}</td><td class="num">${money17(x.closing,x.currency)}</td><td>${status17(x.status)}</td></tr>`).join(''),'1080px',true))}</div></div>`}
function compliance17(){return `<div class="v17-page">${head17('Compliance and assurance','Compliance Reporting Centre','A practical workspace for accounting, tax and audit teams to prepare, evidence, review, sign and archive controlled compliance packs.',`${b17('New compliance pack','compliance-new','')}${b17('Run readiness scan','compliance-scan','primary')}`)}<div class="v17-kpis">${kpi17('Packs in progress','5','Tax, IFRS and audit outputs','#006cff')}${kpi17('Overall readiness','87%','Evidence-weighted completion','#008c66')}${kpi17('Open exceptions','13','5 material issues','#d92d4b')}${kpi17('Due within 7 days','2','VAT and WHT packs','#db7b00')}${kpi17('Awaiting signature','3','Authorised users notified','#6a45ff')}${kpi17('Evidence coverage','96%','One missing tax document','#00a9e8')}</div>${filterButton17('compliance',4)}<div class="v17-filters ${V17.filters.compliance?'open':''}" data-filter="compliance">${field17('Pack type',select17('v17CompType',['All pack types','VAT','WHT','Income tax','IFRS','Audit file'],'All pack types'))}${field17('Period',select17('v17CompPeriod',['Jul 2026','Q3 2026','FY 2026'],'Jul 2026'))}${field17('Owner',select17('v17CompOwner',['All owners','Rudo Chivero','Tax Team','Farai Mapfumo'],'All owners'))}${field17('Status',select17('v17CompStatus',['All statuses','Draft','In review','Ready for approval','Approved'],'All statuses'))}${field17('Exception',select17('v17CompException',['All packs','With exceptions','Clean packs'],'All packs'))}</div><div class="v17-grid two"><div class="v17-stack">${panel17('Compliance pack register','Select any row to open its full preview, working papers, evidence and sign-off. No separate preview icon is required.',table17(['Pack','Type','Period','Owner','Due date','Readiness','Exceptions','Status'],compliancePacks.map(x=>`<tr class="v17-document" data-v17="compliance-preview" data-id="${x.id}"><td class="v17-link">${x.name}</td><td>${x.type}</td><td>${x.period}</td><td>${x.owner}</td><td>${x.due}</td><td>${x.readiness}%</td><td>${x.exceptions}</td><td>${status17(x.status)}</td></tr>`).join(''),'970px',true))}${panel17('Audit request and evidence tracker','PBC requests, owners, due dates and evidence sufficiency.',table17(['Request','Area','Owner','Due','Evidence','Reviewer','Status'],[['PBC-024','Bank confirmations','Rudo Kaseke','04 Aug','4 / 4','External audit','Ready'],['PBC-031','Revenue samples','Nyasha Dube','05 Aug','16 / 20','External audit','In progress'],['PBC-044','Tax returns','Rudo Chivero','05 Aug','5 / 5','Tax manager','Review'],['PBC-052','Investment valuations','Farai Mapfumo','06 Aug','7 / 8','CFO','In progress']].map(x=>`<tr><td class="v17-link">${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${x[4]}</td><td>${x[5]}</td><td>${status17(x[6])}</td></tr>`).join(''),'800px',false))}</div><aside class="v17-stack">${panel17('Immediate compliance attention','Risk-ranked issues preventing clean filing.',`<div class="v17-file-list">${compliancePacks.filter(x=>x.exceptions).map(x=>`<div class="v17-file" data-v17="compliance-preview" data-id="${x.id}"><i>!</i><div><strong>${x.name}</strong><span>${x.exceptions} exception(s) · ${x.owner}</span></div>${status17(x.status)}</div>`).join('')}</div>`)}${panel17('Signature queue','Authorised reviewers receive task-linked notifications.',V17.notifications.filter(x=>/signature|VAT/i.test(x.title)).map(x=>`<div class="v17-notification ${x.kind}" data-v17="notification" data-id="${x.id}"><i></i><div><strong>${x.title}</strong><span>${x.detail}</span></div><time>${x.time}</time></div>`).join(''))}${panel17('Compliance workflow','Source data, reconciliation, exceptions, review, signature and archive.',`<div class="v17-kyc-steps">${[['1','Compile','Ledgers locked'],['2','Reconcile','Differences explained'],['3','Evidence','Documents linked'],['4','Review','Independent checker'],['5','File','Receipt archived']].map(x=>`<div class="v17-kyc-step"><i>${x[0]}</i><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join('')}</div>`)}</aside></div></div>`}
function settings17(){const tab=V17.settingsTab;let body='';if(tab==='general')body=`<div class="v17-grid two">${panel17('Finance configuration','Entity, fiscal calendar, base currency and posting policy.',`<div class="v17-filters open" style="margin:0">${field17('Tenant name',input17('v17Tenant','Matanho Capital Partners'))}${field17('Base currency',select17('v17BaseCurrency',['USD','ZWG'],'USD'))}${field17('Fiscal year end',select17('v17FiscalYear',['31 December','30 June'],'31 December'))}${field17('Default journal policy',select17('v17JournalPolicy',['Draft then approve','Auto-post approved sources'],'Draft then approve'))}</div>`)}${panel17('Configured banks','Add banks and map each cashbook to its control account.',table17(['Bank / cashbook','Currency','GL account','Feed','Status'],[['CBZ USD Operating','USD','1100','API','Active'],['Stanbic USD Reserve','USD','1102','SFTP','Active'],['ZiG Operating','ZWG','1105','Upload','Active']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${status17(x[4])}</td></tr>`).join(''),'620px',false),b17('Add bank','settings-add-bank','small primary'))}</div>`;if(tab==='periods')body=`<div class="v17-period-grid">${[['Jul 2026','Open','Close in progress','82%'],['Jun 2026','Closed','Locked 03 Jul','100%'],['May 2026','Closed','Locked 04 Jun','100%'],['Apr 2026','Closed','Locked 05 May','100%']].map(x=>`<article class="v17-period"><strong>${x[0]}</strong><span>${x[2]}</span><footer>${status17(x[1])}<b>${x[3]}</b></footer></article>`).join('')}</div><div class="v17-grid two" style="margin-top:12px">${panel17('Close current period','Complete mandatory controls before locking July 2026.',`<div class="v17-callout warn"><strong>3 gates remain.</strong><br>VAT review, fixed-asset exception and financial statement approval must be complete.</div><div class="v17-toolbar"><span></span>${b17('Open Close Control Centre','go','primary','close')}</div>`)}${panel17('Period lock policy','Locking prevents new postings. Corrections require controlled reopening or next-period adjustment.',`<div class="v17-file-list">${[['General ledger balanced','Complete'],['All bank reconciliations','Review'],['Compliance review','Review'],['Finance Director approval','Pending']].map(x=>`<div class="v17-file"><i>✓</i><div><strong>${x[0]}</strong><span>Mandatory lock gate</span></div>${status17(x[1])}</div>`).join('')}</div><div class="v17-toolbar"><span></span>${b17('Lock July 2026','period-lock','danger')}</div>`)}</div>`;if(tab==='letterhead')body=`<div class="v17-letterhead-config"><div class="v17-stack">${panel17('Letterhead identity','Edit legal name, tagline and colours used on controlled documents.',`<div class="v17-stack">${field17('Legal entity name',input17('v17LhLegal',V17.letterhead.legal))}${field17('Tagline',input17('v17LhTagline',V17.letterhead.tagline))}<div class="v17-color-row">${field17('Primary colour',input17('v17LhPrimary',V17.letterhead.primary,'text'))}<input id="v17LhPrimaryColor" type="color" value="${V17.letterhead.primary}"></div><div class="v17-color-row">${field17('Accent colour',input17('v17LhAccent',V17.letterhead.accent,'text'))}<input id="v17LhAccentColor" type="color" value="${V17.letterhead.accent}"></div><div class="v17-toolbar"><span></span>${b17('Save letterhead','letterhead-save','primary')}</div></div>`)}</div><div class="v17-report-preview">${reportSheet17('pnl')}</div></div>`;if(tab==='access')body=`<div class="v17-grid two">${panel17('Users and effective access','Group administrators and the CEO may assign roles, scope and limits per named user.',table17(['User','Role','Entity scope','Approval limit','MFA','Status'],[['Tariro Moyo','Finance Director','Group','$2.0m','Enforced','Active'],['Farai Mapfumo','Financial Controller','Group','$500k','Enforced','Active'],['Rudo Kaseke','Treasury Officer','MCP + banks','$250k','Enforced','Active'],['Nyasha Dube','AR Officer','MCP','$50k','Enforced','Active'],['External Audit','External Auditor','FY2026 vault','Read only','Enforced','Time limited']].map(x=>`<tr data-v17="user-access" data-id="${x[0]}"><td class="v17-link">${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${x[4]}</td><td>${status17(x[5])}</td></tr>`).join(''),'780px',false),b17('Invite user','user-invite','small primary'))}${panel17('Access requests awaiting approval','Review requested permission, business reason, duration and segregation-of-duties impact.',`<div class="v17-file-list">${[['AR-1042','Chipo Ndlovu','Approve supplier bills up to $25k','7 days'],['AR-1041','External Audit','Read investment valuation evidence','30 days'],['AR-1038','Rudo Chivero','Post tax correction journals','$50k limit']].map(x=>`<div class="v17-file" data-v17="access-request" data-id="${x[0]}"><i>+</i><div><strong>${x[1]}</strong><span>${x[2]} · ${x[3]}</span></div>${status17('Pending')}</div>`).join('')}</div>`)}${panel17('Permission policy','Dynamic role, user, entity, field, amount and time controls.',`<div class="v17-kyc-steps">${[['1','Role','Base permissions'],['2','User','Named overrides'],['3','Scope','Entity and account'],['4','Limit','Amount and risk'],['5','Approval','Maker-checker']].map(x=>`<div class="v17-kyc-step"><i>${x[0]}</i><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join('')}</div>`)}</div>`;if(tab==='audit')body=panel17('Immutable audit trail','Material user, system, integration and control events.',table17(['Timestamp','Event','Record','User','Role','Detail','Classification'],auditLog.slice(0,20).map(x=>`<tr><td>${x.time}</td><td>${x.event}</td><td>${x.record}</td><td>${x.user}</td><td>${x.role}</td><td>${x.detail}</td><td>${status17(x.class)}</td></tr>`).join(''),'1080px',true));if(tab==='integrations')body=`<div class="v17-grid three">${[['Portfolio Management','Investment positions, valuations and period reconciliation','Connected'],['Procurement','PO, receipt, vendor and commitment interfaces','Connected'],['Payroll & HR','Payroll journals, employees and cost centres','Connected'],['Loan Management','Borrower receipts, interest and control-account reconciliation','Review'],['Banking Hub','Statements, balances and payment files','Connected'],['Tax & Filing','Configured return outputs and submission receipts','Sandbox']].map(x=>panel17(x[0],x[1],`${status17(x[2])}<div class="v17-toolbar"><span></span>${b17('Configure','integration-config','small',x[0])}</div>`)).join('')}</div>`;return `<div class="v17-page">${head17('Platform configuration','Accounting Settings','Banks, periods, letterheads, RBAC, audit and integrations are managed in one governed settings workspace.',b17('Save configuration','settings-save','primary'))}<div class="v17-subnav">${[['general','General & banks'],['periods','Periods & lock'],['letterhead','Letterheads'],['access','Security & RBAC'],['audit','Audit trail'],['integrations','Integrations']].map(x=>`<button class="${tab===x[0]?'active':''}" data-v17="settings-tab" data-id="${x[0]}">${x[1]}</button>`).join('')}</div>${body}</div>`}
function profileWorkspace17(type,name){const isVendor=type==='vendor',item=isVendor?vendors17.find(x=>x.name===name):clients17.find(x=>x.name===name);if(!item)return;const initials=item.name.split(/\s+/).map(x=>x[0]).slice(0,2).join('');openModal(`${isVendor?'Vendor':'Client'} profile · ${item.name}`,`${isVendor?'Digital KYC, commercial, banking and payment controls':'Commercial relationship, transactions, statements and collections'}`,`<div class="v17-profile-hero"><div class="v17-org-avatar">${initials}</div><div><h2>${item.name}</h2><p>${isVendor?item.category:item.sector} · ${item.currency} · ${item.email}</p></div>${status17(item.status)}</div><div class="v17-tabs" style="margin-top:12px">${[['overview','Overview'],['transactions','Transactions'],['documents','Documents'],['communications','Communications'],['audit','Audit trail'],...(isVendor?[['kyc','Digital KYC']]:[['statement','Statement']])].map((x,i)=>`<button class="v17-tab ${i===0?'active':''}" data-v17="profile-tab" data-id="${type}|${item.name}|${x[0]}">${x[1]}</button>`).join('')}</div><div id="v17ProfileBody">${profileTabBody17(type,item,'overview')}</div>`,`${b17('Close','modal-close','')}${isVendor?b17('Edit permitted fields','profile-edit','soft',item.name):b17('Send statement','send-statement','soft',item.name)}${b17('Open full history','profile-history','primary',type+'|'+item.name)}`,true);q('#modal')?.classList.add('v17-preview')}
function profileTabBody17(type,item,tab){const isVendor=type==='vendor';if(tab==='overview')return `<div class="v17-facts"><div class="v17-fact"><span>Reference</span><strong>${item.id}</strong></div><div class="v17-fact"><span>${isVendor?'YTD spend':'Outstanding'}</span><strong>${money17(isVendor?item.spend:item.balance,item.currency)}</strong></div><div class="v17-fact"><span>KYC completeness</span><strong>${item.kyc}%</strong></div><div class="v17-fact"><span>Relationship owner</span><strong>${isVendor?item.owner:item.manager}</strong></div></div><div class="v17-grid two" style="margin-top:12px">${panel17('Contact and commercial data','Editable according to role and field policy.',`<div class="v17-facts"><div class="v17-fact"><span>Email</span><strong>${item.email}</strong></div><div class="v17-fact"><span>Phone</span><strong>${item.phone}</strong></div><div class="v17-fact"><span>Currency</span><strong>${item.currency}</strong></div><div class="v17-fact"><span>Status</span><strong>${item.status}</strong></div></div>`)}${panel17('Accounting relationship','Control accounts, terms and current exposure.',`<div class="v17-file-list">${[['Control account',isVendor?'2100 · Trade Payables':'1200 · Trade Receivables'],['Payment terms','30 days'],['Open transactions',isVendor?'6 supplier bills':'4 customer invoices'],['Credit / exposure limit',isVendor?'Payment policy based':'$250,000']].map(x=>`<div class="v17-file"><i>•</i><div><strong>${x[0]}</strong><span>${x[1]}</span></div></div>`).join('')}</div>`)}</div>`;if(tab==='transactions')return table17(['Date','Document','Description','Debit','Credit','Balance','Status'],ledgerTxns.slice(0,6).map((x,i)=>`<tr data-v17="journal" data-id="${x.id}"><td>${x.date}</td><td class="v17-link">${x.id}</td><td>${x.desc}</td><td class="num">${x.debit?money17(x.debit):'—'}</td><td class="num">${x.credit?money17(x.credit):'—'}</td><td class="num">${money17((i+1)*18400)}</td><td>${status17(x.status)}</td></tr>`).join(''),'900px',true);if(tab==='documents')return `<div class="v17-file-list">${[['Tax certificate','PDF · verified'],['Bank confirmation','PDF · independently validated'],['Signed contract','PDF · version 4'],['Beneficial ownership declaration','PDF · current']].map((x,i)=>`<div class="v17-file v17-document" data-v17="document-preview" data-id="${item.id}-DOC-${i+1}"><i>PDF</i><div><strong>${x[0]}</strong><span>${x[1]}</span></div>${status17('Ready')}</div>`).join('')}</div>`;if(tab==='communications')return `<div class="v17-file-list">${[['02 Aug 2026','Statement / remittance email sent'],['31 Jul 2026','Payment or collection reminder'],['28 Jul 2026','Supporting document requested']].map(x=>`<div class="v17-file"><i>@</i><div><strong>${x[1]}</strong><span>${x[0]} · Finance Operations</span></div>${status17('Delivered')}</div>`).join('')}</div>`;if(tab==='audit')return table17(['Timestamp','Event','User','Before','After'],[['01 Aug 14:22','Profile reviewed','Chipo Ndlovu','Review due','Complete'],['30 Jul 11:48','Contact updated','Vendor Master Team','Old email','Current email'],['28 Jul 09:05','KYC document uploaded',item.name,'Missing','Received']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${x[4]}</td></tr>`).join(''),'680px',false);if(tab==='kyc')return `<div class="v17-kyc-steps">${[['1','Identity','Legal and tax registration'],['2','Ownership','Beneficial owners screened'],['3','Banking','Independent verification'],['4','Risk','Sanctions and adverse media'],['5','Approval','Periodic certification']].map((x,i)=>`<div class="v17-kyc-step"><i>${i<4?'✓':5}</i><strong>${x[1]}</strong><span>${x[2]}</span>${status17(i<4?'Complete':'Review')}</div>`).join('')}</div><div style="margin-top:12px">${table17(['Requirement','Document / evidence','Expiry','Reviewer','Status'],[['Company registration','Certificate of incorporation','Permanent','Vendor Master Team','Complete'],['Tax registration',item.tax,'—','Tax Team',/expired|review/i.test(item.tax)?'Review':'Complete'],['Bank confirmation',item.bank,'31 Dec 2026','Treasury','Complete'],['Beneficial ownership','Declaration and screening','31 Jul 2027','Compliance','Complete']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${status17(x[4])}</td></tr>`).join(''),'760px',false)}</div>`;if(tab==='statement')return `<div class="v17-report-preview">${statementSheet17(item)}</div>`;return ''}
function statementSheet17(item){return `<article class="v17-sheet" style="--lh-primary:${V17.letterhead.primary};--lh-accent:${V17.letterhead.accent}"><header class="v17-letterhead"><div><div class="brandline">matanho<span>.</span></div><p>${V17.letterhead.tagline}</p></div><aside>${V17.letterhead.legal}<br>Client statement<br>Jul 2026</aside></header><div class="v17-report-title"><div><h2>Statement of Account</h2><p>${item.name} · ${item.currency} · 01–31 July 2026</p></div><div class="control">STAT-${item.id}-202607<br>Controlled copy</div></div><table class="v17-statement"><thead><tr><th>Date / description</th><th>Debit</th><th>Credit</th><th>Balance</th></tr></thead><tbody><tr><td>Opening balance</td><td>—</td><td>—</td><td>${money17(item.balance*.72,item.currency)}</td></tr><tr><td>Invoice INV-2026-00492</td><td>${money17(item.balance*.55,item.currency)}</td><td>—</td><td>${money17(item.balance*1.27,item.currency)}</td></tr><tr><td>Receipt allocation</td><td>—</td><td>${money17(item.balance*.27,item.currency)}</td><td>${money17(item.balance,item.currency)}</td></tr><tr class="grand"><td>Closing balance</td><td></td><td></td><td>${money17(item.balance,item.currency)}</td></tr></tbody></table></article>`}
function billWorkspace17(id){const bill=supplierInvoices.find(x=>x.id===id)||supplierInvoices[0];openModal(`Supplier bill workspace · ${bill.id}`,`${bill.supplier} · ${bill.invoice} · source, match, tax, evidence, approval and ledger`,`${tabs17([['overview','Overview'],['match','Three-way match'],['documents','Documents'],['approval','Approval'],['ledger','Ledger lineage']], 'overview','bill-tab')}<div id="v17BillBody">${billTabBody17(bill,'overview')}</div>`,`${b17('Close','modal-close','')}${b17('Return to vendor','vendor-profile','soft',bill.supplier)}${b17('Approve bill','bill-approve','primary',bill.id)}`,true);q('#modal')?.classList.add('v17-preview')}
function billTabBody17(b,tab){if(tab==='overview')return `<div class="v17-facts"><div class="v17-fact"><span>Invoice total</span><strong>${money17(b.amount,b.currency)}</strong></div><div class="v17-fact"><span>Due date</span><strong>${b.due}</strong></div><div class="v17-fact"><span>PO / GRN variance</span><strong>${money17(b.variance,b.currency)}</strong></div><div class="v17-fact"><span>Status</span><strong>${b.status}</strong></div></div><div class="v17-grid two" style="margin-top:12px">${panel17('Bill information','Supplier, invoice, tax and project dimensions.',`<div class="v17-facts"><div class="v17-fact"><span>Supplier</span><strong>${b.supplier}</strong></div><div class="v17-fact"><span>Invoice</span><strong>${b.invoice}</strong></div><div class="v17-fact"><span>Project / mandate</span><strong>Corporate</strong></div><div class="v17-fact"><span>Tax</span><strong>VAT 15%</strong></div></div>`)}${panel17('Control conclusion','What prevents or permits approval.',`<div class="v17-file-list">${[['Supplier KYC','Complete'],['Duplicate invoice','Complete'],['Quantity match','Complete'],['Rate variance',b.variance?'Exception':'Complete'],['Tax invoice','Review']].map(x=>`<div class="v17-file"><i>✓</i><div><strong>${x[0]}</strong><span>Evidence retained</span></div>${status17(x[1])}</div>`).join('')}</div>`)}</div>`;if(tab==='match')return table17(['Source','Description','Quantity','Rate','Amount','Difference','Status'],[['Purchase order',b.po,20,1391.80,27836,0,'Matched'],['Goods receipt',b.grn,20,0,27836,0,'Matched'],['Supplier invoice',b.invoice,20,1423.80,b.amount,b.variance,b.variance?'Exception':'Matched']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td class="num">${money17(x[3])}</td><td class="num">${money17(x[4])}</td><td class="num">${x[5]?money17(x[5]):'—'}</td><td>${status17(x[6])}</td></tr>`).join(''),'760px',false);if(tab==='documents')return `<div class="v17-file-list">${[['Supplier invoice.pdf','Vendor source document'],[b.po+'.pdf','Approved purchase order'],[b.grn+'.pdf','Goods / service receipt'],['Vendor KYC pack','Tax, ownership and bank evidence']].map((x,i)=>`<div class="v17-file v17-document" data-v17="document-preview" data-id="${b.id}-DOC-${i+1}"><i>PDF</i><div><strong>${x[0]}</strong><span>${x[1]}</span></div>${status17('Ready')}</div>`).join('')}</div>`;if(tab==='approval')return `<div class="v17-kyc-steps">${[['1','AP maker','Match and code'],['2','Tax review','VAT validation'],['3','Controller','Bill approval'],['4','Treasury','Payment selection'],['5','Director','Bank release']].map((x,i)=>`<div class="v17-kyc-step"><i>${i<2?'✓':i+1}</i><strong>${x[1]}</strong><span>${x[2]}</span>${status17(i<2?'Complete':'Pending')}</div>`).join('')}</div>`;if(tab==='ledger')return table17(['Journal','Date','Account','Description','Debit','Credit','Status'],[['JE-2026-0106','17 Jul','5104','Professional and custody services',b.amount,0,'Posted'],['JE-2026-0106','17 Jul','2100','Trade payables',0,b.amount,'Posted']].map(x=>`<tr data-v17="journal" data-id="${x[0]}"><td class="v17-link">${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td class="num">${x[4]?money17(x[4]):'—'}</td><td class="num">${x[5]?money17(x[5]):'—'}</td><td>${status17(x[6])}</td></tr>`).join(''),'760px',false);return ''}
function newDocument17(kind){const isBill=kind==='bill'||kind==='po',title={bill:'New supplier bill',invoice:'New customer invoice',quotation:'New quotation',po:'New purchase order'}[kind]||'New finance document',parties=isBill?vendors17:clients17;openModal(title,'Business-friendly entry with controlled accounting, dimensions, evidence and recurring scheduling.',`<div class="v17-grid two"><div class="v17-stack">${panel17('Document header','Counterparty, dates, currency and project context.',`<div class="v17-filters open" style="margin:0">${field17(isBill?'Vendor':'Customer',`<div class="inline">${select17('v17DocParty',[...parties.map(x=>[x.id,x.name]),['create','＋ Create new counterpart']],parties[0].id)}</div>`)}${field17('Document date',input17('v17DocDate','2026-08-02','date'))}${field17('Due / expiry date',input17('v17DocDue','2026-09-01','date'))}${field17('Currency',select17('v17DocCurrency',['USD','ZWG','ZAR'],'USD'))}${field17('Project / mandate',select17('v17DocProject',['None','Corporate','Growth Fund I','MFI Portfolio','Pension Liquidity'],'None'))}${field17('Recurring',select17('v17DocRecurring',['One time','Monthly','Quarterly','Annually'],'One time'))}</div>`)}${panel17('Line items','Add products or services with unit of measurement, tax and GL mapping.',table17(['Description','Quantity','Unit of measurement','Rate','Tax','GL account','Amount'],`<tr><td><input value="Professional services"></td><td><input type="number" value="1"></td><td>${select17('v17DocUom',['Each','Hour','Day','Month','Project','Kilometre','Litre'],'Each')}</td><td><input type="number" value="1000"></td><td>${select17('v17DocTax',['No VAT','VAT 15%','Zero rated'],'VAT 15%')}</td><td>${select17('v17DocGl',isBill?['5104 · Professional fees','5302 · Travel','5200 · Technology']:['4100 · Service revenue','4200 · Management fees'],'4100 · Service revenue')}</td><td class="num">$1,150.00</td></tr>`,'900px',false),b17('Add line','document-add-line','small'))}</div><aside class="v17-stack">${panel17('Evidence and delivery','Attach source documents and configure email delivery.',`<div class="v17-file-list"><div class="v17-file"><i>+</i><div><strong>Attach documents or images</strong><span>PDF, PNG, JPG or office document</span></div><input type="file" multiple style="max-width:150px"></div></div>${field17('Recipient email',input17('v17DocEmail',parties[0].email,'email'))}`)}${panel17('Expected accounting','Preview the balanced journal created after approval.',`<div class="v17-callout"><strong>${isBill?'Debit expense / asset and tax; credit trade payables.':'Debit trade receivables; credit revenue and output tax.'}</strong><br>No journal is posted until required approval and document controls pass.</div>`)}</aside></div>`,`${b17('Cancel','modal-close','')}${b17('Save draft','document-save','soft',kind)}${b17('Review & submit','document-submit','primary',kind)}`,true);q('#modal')?.classList.add('v17-preview')}
function claim17(id){const x=claims.find(c=>c.id===id)||claims[0];openModal(`Expense claim · ${x.id}`,`${x.employee} · ${x.purpose} · ${x.status}`,`<div class="v17-facts"><div class="v17-fact"><span>Claim amount</span><strong>${money17(x.amount,x.currency)}</strong></div><div class="v17-fact"><span>Submitted</span><strong>${x.submitted}</strong></div><div class="v17-fact"><span>Evidence</span><strong>${x.receipts}</strong></div><div class="v17-fact"><span>Policy</span><strong>${x.policy}</strong></div></div><div class="v17-grid two" style="margin-top:12px">${panel17('Itemised expenses','Expense lines, project, tax and policy.',table17(['Date','Merchant','Category','Project','Amount','Policy'],[['27 Jul','Rainbow Towers','Accommodation','Growth Fund I',840,'Within'],['28 Jul','Zuva Petroleum','Travel','Growth Fund I',286,'Within'],['29 Jul','Air Zimbabwe','Travel','Growth Fund I',694,'Review']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td class="num">${money17(r[4])}</td><td>${status17(r[5])}</td></tr>`).join(''),'700px',false))}${panel17('Receipts and evidence','Images and documents attached to the claim.',`<div class="v17-file-list">${[['Hotel receipt.jpg','Image · 1.8 MB'],['Fuel receipt.png','Image · 840 KB'],['Flight invoice.pdf','PDF · 224 KB']].map((r,i)=>`<div class="v17-file v17-document" data-v17="document-preview" data-id="${x.id}-EVID-${i+1}"><i>${i<2?'IMG':'PDF'}</i><div><strong>${r[0]}</strong><span>${r[1]}</span></div>${status17('Verified')}</div>`).join('')}</div>`)}</div>`,`${b17('Return for correction','claim-return','danger',x.id)}${b17('Approve claim','claim-approve','primary',x.id)}`,true);q('#modal')?.classList.add('v17-preview')}
function timesheet17(id){const t=timesheets17.find(x=>x.id===id)||timesheets17[0];openModal(`Timesheet · ${t.id}`,`${t.employee} · ${t.project} · ${t.week}`,`<div class="v17-facts"><div class="v17-fact"><span>Total hours</span><strong>${t.hours}</strong></div><div class="v17-fact"><span>Billable</span><strong>${t.billable}</strong></div><div class="v17-fact"><span>Cost</span><strong>${money17(t.cost)}</strong></div><div class="v17-fact"><span>Status</span><strong>${t.status}</strong></div></div><div style="margin-top:12px">${table17(['Day','Project / mandate','Task code','Hours','Billable','Narration'],[['Mon',t.project,'FIN-101',8,7,'Analysis and control review'],['Tue',t.project,'FIN-102',8,7,'Client workshop and documentation'],['Wed',t.project,'FIN-103',9,8,'Financial modelling and review'],['Thu',t.project,'FIN-104',8,7,'Data validation and delivery'],['Fri',t.project,'FIN-105',7,5,'Reporting and sign-off']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td class="num">${x[3]}</td><td class="num">${x[4]}</td><td>${x[5]}</td></tr>`).join(''),'760px',false)}</div>`,`${b17('Return','timesheet-return','danger',id)}${b17('Approve timesheet','timesheet-approve-one','primary',id)}`,true);q('#modal')?.classList.add('v17-preview')}
function instrument17(id){const x=investments.find(i=>i.id===id)||investments[0];openDrawer(`${x.id} · ${x.issuer}`,`${x.type} · ${x.currency} · daily accrual, rates, journals and settlement`,`${growthChart17('instrument-'+x.id)}<div class="v17-facts" style="margin-top:12px"><div class="v17-fact"><span>Principal</span><strong>${money17(x.principal,x.currency)}</strong></div><div class="v17-fact"><span>Carrying value</span><strong>${money17(x.carrying,x.currency)}</strong></div><div class="v17-fact"><span>APY</span><strong>${x.rate.toFixed(2)}%</strong></div><div class="v17-fact"><span>Maturity</span><strong>${x.maturity}</strong></div></div><div style="margin-top:12px">${tabs17([['overview','Overview'],['accruals','Daily accruals'],['rates','Rate history'],['journals','Journals'],['settlement','Settlement']], 'overview','instrument-tab')}</div><div id="v17InstrumentBody">${instrumentTab17(x,'overview')}</div>`,`${b17('Liquidate / mature','investment-settle','')}${b17('Edit effective-dated rate','investment-rate','primary',x.id)}`);q('#drawer')?.classList.add('v17-drawer-wide')}
function instrumentTab17(x,tab){if(tab==='overview')return `<div class="v17-file-list">${[['Settlement account','CBZ USD Operating'],['Principal asset account','1510 · Short-term investments'],['Accrued interest account','1350 · Accrued interest receivable'],['Interest income account','4205 · Investment income'],['Day-count convention','Actual / 365'],['Posting policy','Draft · weekly CFO approval']].map(r=>`<div class="v17-file"><i>•</i><div><strong>${r[0]}</strong><span>${r[1]}</span></div></div>`).join('')}</div>`;if(tab==='accruals')return table17(['Date','Opening','Rate','Daily accrual','Closing','Journal'],accrual17.filter(a=>a.instrument===x.id).concat(accrual17.slice(0,5)).slice(0,8).map(a=>`<tr><td>${a.date}</td><td class="num">${money17(a.opening,a.currency)}</td><td class="num">${a.rate.toFixed(2)}%</td><td class="num">${money17(a.daily,a.currency)}</td><td class="num">${money17(a.closing,a.currency)}</td><td>${status17(a.status)}</td></tr>`).join(''),'680px',true);if(tab==='rates')return table17(['Effective date','APY','Entered by','Reason','Status'],[['01 Jul 2026',x.rate+'%','Farai Mapfumo','Monthly rate confirmation','Active'],['01 Jun 2026',(x.rate-.3)+'%','Farai Mapfumo','Broker rate notice','Superseded'],['01 May 2026',(x.rate-.45)+'%','Tariro Moyo','Placement setup','Superseded']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td>${status17(r[4])}</td></tr>`).join(''),'620px',false);if(tab==='journals')return table17(['Journal','Date','Description','Debit','Credit','Status'],[['JE-INV-0731','31 Jul','Daily investment income accrual',142.47,142.47,'Posted'],['JE-INV-0730','30 Jul','Daily investment income accrual',142.47,142.47,'Posted']].map(r=>`<tr data-v17="journal" data-id="${r[0]}"><td class="v17-link">${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td class="num">${money17(r[3])}</td><td class="num">${money17(r[4])}</td><td>${status17(r[5])}</td></tr>`).join(''),'640px',false);if(tab==='settlement')return `<div class="v17-callout"><strong>Expected maturity settlement.</strong><br>Debit operating cash for principal plus accrued interest; credit investment principal and accrued-interest receivable. Realised FX differences post separately.</div><div class="v17-facts" style="margin-top:10px"><div class="v17-fact"><span>Expected cash</span><strong>${money17(x.carrying,x.currency)}</strong></div><div class="v17-fact"><span>Settlement account</span><strong>CBZ USD Operating</strong></div><div class="v17-fact"><span>Final partial-day interest</span><strong>${money17(x.principal*x.rate/100/365,x.currency)}</strong></div><div class="v17-fact"><span>Approval</span><strong>CFO required</strong></div></div>`;return ''}
function compliancePreview17(id){const p=compliancePacks.find(x=>x.id===id)||compliancePacks[0];openModal(`${p.name} · Controlled Preview`,`${p.type} · ${p.period} · readiness ${p.readiness}%`,`${previewToolbar17()}<div class="v17-report-preview"><article class="v17-sheet" style="--lh-primary:${V17.letterhead.primary};--lh-accent:${V17.letterhead.accent}"><header class="v17-letterhead"><div><div class="brandline">matanho<span>.</span></div><p>${V17.letterhead.tagline}</p></div><aside>${V17.letterhead.legal}<br>Compliance working paper<br>${p.id}</aside></header><div class="v17-report-title"><div><h2>${p.name}</h2><p>${p.period} · USD · controlled working paper</p></div><div class="control">Readiness ${p.readiness}%<br>${V17.signed['COMP-'+id]?'Digitally signed':p.status}</div></div><div style="padding:0 30px 14px"><div class="v17-facts"><div class="v17-fact"><span>Owner</span><strong>${p.owner}</strong></div><div class="v17-fact"><span>Exceptions</span><strong>${p.exceptions}</strong></div><div class="v17-fact"><span>Due date</span><strong>${p.due}</strong></div><div class="v17-fact"><span>Status</span><strong>${p.status}</strong></div></div></div><table class="v17-statement"><thead><tr><th>Section / source</th><th>Ledger value</th><th>Return value</th><th>Difference</th></tr></thead><tbody><tr><td>Standard-rated sales · Sales ledger</td><td>${money17(477625)}</td><td>${money17(477625)}</td><td>—</td></tr><tr><td>Input tax · Purchase ledger</td><td>${money17(237500)}</td><td>${money17(233500)}</td><td>${money17(4000)}</td></tr><tr><td>Adjustments · General ledger</td><td>${money17(9500)}</td><td>${money17(9500)}</td><td>—</td></tr></tbody></table><footer class="v17-report-foot"><div class="v17-sign"><strong>${p.owner}</strong><span>Prepared by</span></div><div class="v17-sign"><strong>Farai Mapfumo</strong><span>Reviewed by</span></div><div class="v17-sign"><strong>${V17.signed['COMP-'+id]?'Tariro Moyo':'Signature pending'}</strong><span>Authorised signatory</span></div></footer></article></div>`,`${b17('Close','modal-close','')}${b17('Edit working paper','compliance-edit','soft',id)}${b17('Email secure link','document-email','')}${!V17.signed['COMP-'+id]?b17('Sign document','document-sign','primary','COMP-'+id):''}`,true);q('#modal')?.classList.add('v17-preview')}
function previewToolbar17(){return `<div class="v17-preview-toolbar">${b17('− Zoom','preview-zoom-out','small')}${b17('+ Zoom','preview-zoom-in','small')}${b17('Maximise','preview-max','small soft')}${b17('Minimise','preview-min','small soft')}</div>`}
function reportPreview17(id){openModal(`${reportMap17[id]||'Financial Report'} · Preview`,'Large-format controlled preview with visible totals, calendar years and individual management signatures.',`${previewToolbar17()}<div class="v17-report-preview v19-preview" id="v17PreviewStage">${reportSheet17(id,true)}</div>`,`${b17('Close','modal-close','')}${b17('Edit letterhead','go-settings-letterhead','soft')}${b17('Email secure link','document-email','')}`,true);q('#modal')?.classList.add('v17-preview','v19-report-modal')}
function documentPreview17(id){openModal(`Document preview · ${id}`,'Click, review, sign and distribute the controlled source document.',`${previewToolbar17()}<div class="v17-report-preview" id="v17PreviewStage"><article class="v17-sheet" style="--lh-primary:${V17.letterhead.primary};--lh-accent:${V17.letterhead.accent}"><header class="v17-letterhead"><div><div class="brandline">matanho<span>.</span></div><p>${V17.letterhead.tagline}</p></div><aside>${V17.letterhead.legal}<br>Controlled business document<br>Version 3</aside></header><div class="v17-report-title"><div><h2>${esc17(id)}</h2><p>02 Aug 2026 · USD · Matanho Capital Partners</p></div><div class="control">${V17.signed['DOC-'+id]?'Digitally signed':'Ready for review'}<br>DOC-${esc17(id)}</div></div><table class="v17-statement"><thead><tr><th>Description</th><th>Quantity</th><th>UOM</th><th>Rate</th><th>Tax</th><th>Total</th></tr></thead><tbody><tr><td>Professional services and implementation support</td><td>1</td><td>Project</td><td>${money17(24761.74)}</td><td>${money17(3714.26)}</td><td>${money17(28476)}</td></tr><tr class="grand"><td colspan="5">Document total</td><td>${money17(28476)}</td></tr></tbody></table><footer class="v17-report-foot"><div class="v17-sign"><strong>Chipo Ndlovu</strong><span>Prepared by</span></div><div class="v17-sign"><strong>Farai Mapfumo</strong><span>Reviewed by</span></div><div class="v17-sign"><strong>${V17.signed['DOC-'+id]?'Tariro Moyo':'Signature pending'}</strong><span>Authorised signatory</span></div></footer></article></div>`,`${b17('Close','modal-close','')}${b17('Edit document','document-edit','soft',id)}${b17('Email document','document-email','')}${!V17.signed['DOC-'+id]?b17('Sign document','document-sign','primary','DOC-'+id):''}`,true);q('#modal')?.classList.add('v17-preview')}
function newRecurring17(type='All'){openModal('New recurring schedule','Create reusable billing, invoice, expense, supplier bill or accrual automation.',`<div class="v17-grid two"><div class="v17-stack">${panel17('Schedule definition','What should be generated and when.',`<div class="v17-filters open" style="margin:0">${field17('Schedule type',select17('v17RecType',['Supplier bill','Customer invoice','Expense accrual','Revenue accrual','Cash transfer'],type==='All'?'Supplier bill':type))}${field17('Counterparty',`<div class="inline">${select17('v17RecParty',[...clients17.map(x=>x.name),...vendors17.map(x=>x.name),'＋ Create new counterpart'],clients17[0].name)}${b17('Create','counterpart-create','small')}</div>`)}${field17('Frequency',select17('v17RecFrequency',['Weekly','Monthly','Quarterly','Annually'],'Monthly'))}${field17('Next run',input17('v17RecNext','2026-08-31','date'))}${field17('End rule',select17('v17RecEnd',['No end date','After 12 occurrences','Specific end date'],'No end date'))}${field17('Approval policy',select17('v17RecApproval',['Create draft','Submit for approval','Post if under threshold'],'Create draft'))}</div>`)}${panel17('Accounting and dimensions','Mapping inherited by each occurrence.',`<div class="v17-filters open" style="margin:0">${field17('GL account',select17('v17RecGl',['5104 · Professional fees','4100 · Service revenue','2205 · Accrued expenses'],'5104 · Professional fees'))}${field17('Project / mandate',select17('v17RecProject',['None','Corporate','Growth Fund I','MFI Portfolio','Pension Liquidity'],'None'))}${field17('Currency',select17('v17RecCurrency',['USD','ZWG','ZAR'],'USD'))}${field17('Amount',input17('v17RecAmount','1000','number'))}${field17('Tax',select17('v17RecTax',['No VAT','VAT 15%','Zero rated'],'VAT 15%'))}${field17('Unit of measurement',select17('v17RecUom',['Each','Hour','Day','Month','Project'],'Month'))}</div>`)}</div><aside class="v17-stack">${panel17('Occurrence preview','Projected schedules and accounting effect.',table17(['Occurrence','Date','Amount','Status'],[['1','31 Aug 2026',1000,'Planned'],['2','30 Sep 2026',1000,'Planned'],['3','31 Oct 2026',1000,'Planned'],['4','30 Nov 2026',1000,'Planned']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td class="num">${money17(x[2])}</td><td>${status17(x[3])}</td></tr>`).join(''),'520px',false))}${panel17('Expected result','Each occurrence creates a new governed source document and balanced journal.',`<div class="v17-callout"><strong>No silent posting.</strong><br>The configured approval policy determines whether each occurrence remains draft, enters approval or posts below an authorised threshold.</div>`)}</aside></div>`,`${b17('Cancel','modal-close','')}${b17('Save schedule','recurring-save','primary',type)}`,true);q('#modal')?.classList.add('v17-preview')}
