function initSignatureCanvas20(existing){
 const canvas=q('#v20SignatureCanvas');if(!canvas)return;const pad=canvas.closest('.v20-signature-pad'),rect=canvas.getBoundingClientRect(),cssW=Math.max(320,Math.round(rect.width||620)),cssH=innerWidth<=620?180:210,dpr=Math.max(1,Math.min(2,devicePixelRatio||1));canvas.width=Math.round(cssW*dpr);canvas.height=Math.round(cssH*dpr);canvas.style.height=cssH+'px';const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.lineWidth=2.35;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#0b3f87';canvas.__hasInk=false;canvas.__clear=()=>{ctx.clearRect(0,0,cssW,cssH);canvas.__hasInk=false;pad?.classList.remove('has-ink')};const point=e=>{const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}};let drawing=false,last=null;canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture?.(e.pointerId);drawing=true;last=point(e);ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(last.x+.01,last.y+.01);ctx.stroke();canvas.__hasInk=true;pad?.classList.add('has-ink')});canvas.addEventListener('pointermove',e=>{if(!drawing)return;e.preventDefault();const p=point(e);ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x,p.y);ctx.stroke();last=p;canvas.__hasInk=true;pad?.classList.add('has-ink')});const stop=e=>{if(!drawing)return;drawing=false;try{canvas.releasePointerCapture?.(e.pointerId)}catch(_){}};canvas.addEventListener('pointerup',stop);canvas.addEventListener('pointercancel',stop);canvas.addEventListener('pointerleave',e=>{if(e.buttons===0)stop(e)});if(existing?.dataUrl){const img=new Image();img.onload=()=>{const margin=24,maxW=cssW-margin*2,maxH=cssH-44,scale=Math.min(maxW/img.width,maxH/img.height,1),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,margin,(cssH-h)/2,w,h);canvas.__hasInk=true;pad?.classList.add('has-ink')};img.src=existing.dataUrl}
}
