(()=>{
 'use strict';
 const dateLabels=/\b(date|period|horizon|window|maturity)\b/i;
 const pageRoot=()=>document.querySelector('#main');
 function upgrade(){
  const root=pageRoot();if(!root)return;
  root.querySelectorAll('.v17-filters,.v18-filter-panel').forEach(panel=>{
   panel.querySelectorAll('.v17-field,.v18-filter-field,.v12-field,.v15-field,.field').forEach(field=>{
    if(field.dataset.v19Date==='1')return;
    const label=field.querySelector('label')?.textContent?.trim()||'';
    if(!dateLabels.test(label)||/\b(from|to)\b|up to/i.test(label))return;
    field.dataset.v19Date='1';field.classList.add('v19-date-range');
    const base=(state?.period||'Jul 2026').includes('Jun')?['2026-06-01','2026-06-30']:['2026-07-01','2026-07-31'];
    field.innerHTML=`<div class="v19-date-field"><label>From date</label><input type="date" value="${base[0]}" data-v19-date="from"></div><div class="v19-date-field"><label>Up to date</label><input type="date" value="${base[1]}" data-v19-date="to"></div>`;
   });
  });
 }
 setTimeout(()=>{document.title='Matanho Accounting Operating System · Enterprise Finance v22';upgrade()},1000);
 window.MatanhoAccountingV19=Object.freeze({version:'19.0.0',refreshDateFilters:upgrade});
})();


