document.addEventListener('click',e=>{const a=e.target.closest('[data-v21]');if(!a)return;const act=a.dataset.v21;if(act==='kpi'){e.preventDefault();e.stopPropagation();openKpi(a);return}if(act==='panel'){e.preventDefault();e.stopPropagation();openPanel(a.closest('.v17-panel,.v8-panel,.v15-panel,.v12-panel,.panel,.card'));return}if(act==='record'){e.preventDefault();openRecord(a);return}if(act==='back'){e.preventDefault();const prev=state21.stack.pop();if(prev)mount(prev,false);else $('.v21-layer')?.remove();return}},true);
