function consolidationPage23(){const entities=[['Matanho Capital Partners',6189000,'USD','Imported'],['Growth Fund I',2840000,'USD','Imported'],['Operations Ltd',1760000,'USD','Imported'],['Property SPV',1350000,'USD','Imported']],inter=[['MCP','Growth Fund I',68420,67000,1420,'Review'],['MCP','Operations Ltd',128600,128600,0,'Matched'],['Growth Fund I','Operations Ltd',46600,45200,1400,'Review'],['MCP','Property SPV',214000,214000,0,'Matched'],['Operations Ltd','Property SPV',38200,38200,0,'Matched']];return `<div class="v23-page">${head23('Group reporting','Group Consolidation & Eliminations','Import entity trial balances, translate currencies, reconcile intercompany positions, post eliminations and produce a controlled consolidated reporting view.',`${btn23('Import trial balances','cons-import')}${btn23('Run matching','cons-match')}${btn23('Generate consolidation','cons-generate','primary')}`)}<div class="v23-kpis">${kpi23('Entities loaded','4 / 4','All expected entities','#0a6cff')}${kpi23('Combined assets','$12.14m','Before eliminations','#00a9e8')}${kpi23('Intercompany',money(496620),'Reciprocal balances','#6f4cff')}${kpi23('Unmatched differences','$2.82k','Two relationships','#df3654')}${kpi23('Eliminations','$493.8k','Draft journal set','#ef9700')}${kpi23('Consolidation status','Review','2 controls remaining','#00a878')}</div><div class="v23-filter-row"><button class="v23-filter-toggle" data-v23="cons-filter"><i></i><span>Filters</span><b>Show</b></button><span style="font-size:10px;color:#71839a">Filter the consolidation scope and reporting window.</span></div><div class="v23-filter-panel" id="v23ConsFilters">${field23('From',input23('v23ConsFrom','2026-07-01','date'))}${field23('To',input23('v23ConsTo','2026-07-31','date'))}${field23('Reporting currency',select23('v23ConsCurrency',['USD','ZWG','ZAR'],'USD'))}${field23('Scope',select23('v23ConsScope',['Full group','Investment entities','Operating entities'],'Full group'))}${field23('Scenario',select23('v23ConsScenario',['Actual','Budget','Forecast'],'Actual'))}</div>${panel23('Consolidation workflow','Progressive controls from source trial balance to governed group output.',`<div class="v23-stepper"><div class="v23-step"><i>01</i><strong>Load entities</strong><span>4/4 trial balances imported</span></div><div class="v23-step"><i>02</i><strong>Translate</strong><span>Functional currencies normalised</span></div><div class="v23-step"><i>03</i><strong>Match</strong><span>2 reciprocal differences remain</span></div><div class="v23-step"><i>04</i><strong>Eliminate</strong><span>Draft elimination journals prepared</span></div><div class="v23-step"><i>05</i><strong>Publish</strong><span>Awaiting controller approval</span></div></div>`) }<div class="v23-grid two" style="margin-top:12px"><div>${panel23('Entity trial balances','Loaded source balances and translation status.',`<div class="v23-scroll"><table class="v23-table" style="min-width:760px"><thead><tr><th>Entity</th><th>Functional currency</th><th class="num">Assets</th><th class="num">Liabilities</th><th class="num">Equity</th><th>Import status</th><th>Translation</th></tr></thead><tbody>${entities.map((x,i)=>`<tr data-v23="cons-entity" data-id="${x[0]}"><td class="link">${x[0]}</td><td>${x[2]}</td><td class="num">${money(x[1])}</td><td class="num">${money(x[1]*.34)}</td><td class="num">${money(x[1]*.66)}</td><td>${status(x[3])}</td><td>${status(i===2?'Review':'Ready')}</td></tr>`).join('')}</tbody></table></div>`)}</div><aside>${panel23('Group contribution','Pre-elimination contribution to consolidated assets.',`<div class="v23-bars">${entities.map((x,i)=>`<div class="v23-bar ${i%2?'alt':''}" style="height:${Math.max(22,Math.round(x[1]/entities[0][1]*82))}%"><b>${money(x[1]/1000000).replace('$','$')}m</b><span>${['MCP','Fund','Ops','SPV'][i]}</span></div>`).join('')}</div>`)}</aside></div><div style="margin-top:12px">${panel23('Intercompany matching & elimination queue','Select a relationship to investigate reciprocal records and prepare elimination journals.',`<div class="v23-scroll tall"><table class="v23-table" style="min-width:900px"><thead><tr><th>Entity A</th><th>Entity B</th><th class="num">A balance</th><th class="num">B reciprocal</th><th class="num">Difference</th><th>Root cause</th><th>Status</th></tr></thead><tbody>${inter.map(x=>`<tr data-v23="cons-match" data-id="${x[0]}|${x[1]}"><td class="link">${x[0]}</td><td>${x[1]}</td><td class="num">${money(x[2])}</td><td class="num">${money(x[3])}</td><td class="num">${money(x[4])}</td><td>${x[4]?'Cut-off / FX timing':'Matched source references'}</td><td>${status(x[5])}</td></tr>`).join('')}</tbody></table></div>`)}</div></div>`}

