/* ---------- Control layer uniqueness ---------- */
function controlContext(layer){const s=(layer.querySelector('.v21-layer-head')?.textContent+' '+layer.querySelector('.v21-layer-path')?.textContent).toLowerCase();if(/close|month-end/.test(s))return 'close';if(/compliance|tax|audit/.test(s))return 'compliance';if(/inventory|stock/.test(s))return 'inventory';if(/vendor|supplier/.test(s))return 'vendor';if(/access|rbac|permission/.test(s))return 'access';if(/recon|bank/.test(s))return 'recon';return 'control'}
function uniqueControlHTML(kind){const defs={close:{title:'Close readiness cockpit',sub:'Dependencies, evidence and blockers by workstream.',cells:[['Close completion','82%'],['Evidence coverage','96%'],['Blocking controls','3'],['Expected lock','02 Aug 18:00'],['Late tasks','4'],['Manual journals','8%']],events:[['09:40','Bank review','11 unmatched lines routed to treasury'],['10:05','Tax evidence','One VAT invoice requested'],['10:22','Fixed assets','Transfer exception assigned']]},compliance:{title:'Filing & assurance intelligence',sub:'Return readiness, evidence sufficiency and reviewer exceptions.',cells:[['Pack readiness','87%'],['Evidence','96%'],['Open findings','13'],['Material findings','5'],['Awaiting signature','3'],['Due in 7 days','2']],events:[['08:30','VAT pack','Input tax difference detected'],['09:18','PBC request','Bank confirmation evidence completed'],['10:12','Signature','CFO notified for tax pack']]},inventory:{title:'Inventory control intelligence',sub:'Counts, valuation, usage and GL reconciliation.',cells:[['Count completion','94%'],['Valuation variance','$1.24k'],['Slow moving','$1.43k'],['Negative stock','0'],['Missing costs','2'],['GL reconcile','Review']],events:[['07:45','Cycle count','Workshop variance captured'],['08:12','Cost layer','Two receipt costs need review'],['09:34','Adjustment','Draft journal created']]},vendor:{title:'Supplier master risk',sub:'KYC, bank changes and payment eligibility.',cells:[['Active vendors','356'],['KYC complete','96%'],['Bank verified','98%'],['Tax renewals','31'],['High-risk changes','3'],['Payment holds','7']],events:[['08:51','Bank change','ZimTech beneficiary update received'],['09:26','KYC','Cloud Africa certificate due'],['10:06','Duplicate signal','PrintWorks phone match reviewed']]},access:{title:'Access & segregation intelligence',sub:'Effective permissions, overrides and policy exceptions.',cells:[['Finance users','42'],['MFA coverage','100%'],['Access requests','3'],['SoD conflicts','0'],['Elevated users','6'],['Reviews due','5']],events:[['08:00','Access review','Quarterly review opened'],['09:14','Request','External Audit requested vault scope'],['10:31','Override','Treasury limit change awaits CEO']]},recon:{title:'Reconciliation control intelligence',sub:'Unmatched cash, stale items and reviewer capacity.',cells:[['Matched','98.7%'],['Unmatched','$18.4k'],['Stale >7d','4'],['Banks complete','2 / 3'],['Internal ledgers','3 / 4'],['Reviewer queue','11']],events:[['07:33','CBZ feed','Statement imported successfully'],['08:45','Auto-match','94 lines matched'],['09:58','Exception','Portfolio ledger difference assigned']]},control:{title:'Finance control cockpit',sub:'Control health, exceptions and evidence across accounting.',cells:[['Controls passed','91%'],['Evidence','95%'],['Open exceptions','18'],['Critical','1'],['Owners overdue','3'],['Review SLA','88%']],events:[['08:10','Control scan','Ledger integrity passed'],['09:05','Evidence','New exception document attached'],['10:20','Escalation','Material item escalated to controller']]}}[kind];return `<div class="v23-control-layout"><section class="v23-control-hero"><header><strong>${defs.title}</strong><span>${defs.sub}</span></header><div class="v23-control-matrix">${defs.cells.map(x=>`<div class="v23-control-cell"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div></section><section class="v23-control-hero"><header><strong>Live control chronology</strong><span>Events are specific to this workflow, not a generic template.</span></header><div class="v23-control-timeline">${defs.events.map(x=>`<div class="v23-control-event"><time>${x[0]}</time><i></i><div><strong>${x[1]}</strong><span>${x[2]}</span></div></div>`).join('')}</div></section></div>`}
function upgradeControlLayer(){const layer=q('.v21-layer[data-level="2"]');if(!layer||layer.dataset.v23Control)return;const txt=(layer.textContent||'');if(!/Control intelligence|control|compliance|close|risk/i.test(txt))return;layer.dataset.v23Control='1';const kind=controlContext(layer);const old=q('.v22-subview-grid,.v22-subview',layer);if(old)old.outerHTML=uniqueControlHTML(kind);else q('.v21-layer-body',layer)?.insertAdjacentHTML('afterbegin',uniqueControlHTML(kind));if(!q('[data-v23="back"]',layer)){const h=q('.v21-layer-head',layer);h?.insertAdjacentHTML('afterbegin','<button class="v23-btn" data-v23="back">← Back</button>')}}

