function timesheetEvidence23(id){openModal(`Timesheet evidence · ${id}`,'Review evidence before approving project time, labour cost and downstream customer billing.',`<div class="v23-grid equal">${panel23('Submitted evidence','Files uploaded by the employee and project manager.',`<div class="v23-list"><div class="v23-list-item" data-v23="doc-preview" data-id="${id}-WORKLOG"><div><strong>Weekly work log.pdf</strong><span>8 pages · uploaded 02 Aug 08:15</span></div>${status('Verified')}</div><div class="v23-list-item" data-v23="doc-preview" data-id="${id}-CLIENT"><div><strong>Client meeting notes.docx</strong><span>Signed engagement evidence</span></div>${status('Ready')}</div><div class="v23-list-item" data-v23="doc-preview" data-id="${id}-TASK"><div><strong>Task tracker export.csv</strong><span>38 linked work items</span></div>${status('Ready')}</div></div>`)}${panel23('Evidence checks','Finance review against time and billing policy.',`<div class="v23-list"><div class="v23-list-item"><div><strong>Hours supported</strong><span>40.0 submitted / 40.0 evidenced</span></div>${status('Complete')}</div><div class="v23-list-item"><div><strong>Mandate active</strong><span>Project code valid for the week</span></div>${status('Complete')}</div><div class="v23-list-item"><div><strong>Client-billable support</strong><span>35.0 hours supported by deliverables</span></div>${status('Complete')}</div></div>`)}</div><div style="margin-top:12px">${panel23('Daily evidence map','Each day links to its specific deliverable or source record.',`<div class="v23-scroll"><table class="v23-table" style="min-width:720px"><thead><tr><th>Day</th><th>Hours</th><th>Project task</th><th>Evidence</th><th>Review</th></tr></thead><tbody>${[['Mon',8,'Financial model review','Model v12 + comments'],['Tue',8,'Client workshop','Meeting notes + attendance'],['Wed',9,'Data validation','QA register export'],['Thu',8,'Investment memo','Draft memo + mark-up'],['Fri',7,'Reporting & sign-off','Report pack v4']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td class="link" data-v23="doc-preview" data-id="${id}-${x[0]}">${x[3]}</td><td>${status('Verified')}</td></tr>`).join('')}</tbody></table></div>`)}</div>`,`${btn('Close','close-modal')}${btn('Approve evidence & timesheet','v23-timesheet-approve','primary',id)}`,true)}
