function pageHeadAndFilters(eye,title,desc,actions,key,extraFields=[]){return `${head(eye,title,desc,actions)}${filter(key,[field('From','<input type="date" value="2026-07-01">'),field('To','<input type="date" value="2026-08-31">'),...extraFields])}`}
function apPage34(){const t=V34.ap;const vs=vendors();const inv=supplierInvoices||[];const total=inv.reduce((s,x)=>s+Number(x.amount||0),0);let body='';
 if(t==='command')body=`<div class="v34-hero-band"><div class="v34-hero-main"><h2>Procure-to-pay pulse</h2><p>One place to understand obligations, vendor risk, payment readiness and exceptions before cash leaves the organisation.</p></div><div class="v34-hero-metric"><span>Next 7 days</span><strong>$126.5k</strong></div><div class="v34-hero-metric"><span>Payment-ready</span><strong>$270.8k</strong></div><div class="v34-hero-metric"><span>Control blocks</span><strong>3</strong></div></div><div class="v34-grid two"><div>${panel('Cash requirement curve','Approved and forecast supplier cash requirements by month.',chart([128,164,152,188,214,198,241,269,288,314,297,341],'Supplier cash requirements','#6b4cff'))}</div><div class="v34-stack">${panel('Immediate AP attention','Highest-value issues requiring finance action.',`<div class="v34-list">${row('Three-way match variance','2 bills · $71.6k exposure',st('Exception'),'ap-tab','bills')}${row('Beneficiary re-verification','2 bank accounts changed this month',st('Review'),'ap-tab','vendors')}${row('Payment run approval','3 bills · $270.8k net cash',st('Pending'),'ap-tab','payments')}${row('Supplier KYC expiry','1 vendor blocked from payment',st('Hold'),'ap-tab','vendors')}</div>`)}${panel('AP service levels','Control and processing performance.',`<div class="v34-bar"><b>Invoice capture</b><div class="v34-meter"><i style="width:93%;--bar:#0b74ff"></i></div><strong>93%</strong></div><div class="v34-bar"><b>3-way match</b><div class="v34-meter"><i style="width:86%;--bar:#6b4cff"></i></div><strong>86%</strong></div><div class="v34-bar"><b>On-time payment</b><div class="v34-meter"><i style="width:96%;--bar:#009b68"></i></div><strong>96%</strong></div>`)} </div></div>`;
 else if(t==='bills')body=panel('Supplier bill workbench','Capture, code, match, approve and schedule payment without leaving the AP register.',table(['Bill','Supplier','Supplier ref','Date','Due','PO / GRN','Gross','Variance','Payment','Status',''],inv.map((x,i)=>`<tr data-v34="ap-record" data-id="${e(x.id)}"><td class="v34-link">${e(x.id)}</td><td>${e(x.supplier)}</td><td>${e(x.invoice)}</td><td>${e(x.date)}</td><td>${e(x.due)}</td><td>${e(x.po)}<span class="v34-sub">${e(x.grn)}</span></td><td class="num">${money(x.amount)}</td><td class="num">${x.variance?money(x.variance):'—'}</td><td>${i%3===0?'Hold':'Ready'}</td><td>${st(x.status)}</td><td onclick="event.stopPropagation()">${more(`v34ap-${i}`,[{label:'Open bill workspace',action:'ap-record',id:x.id},{label:'Preview source documents',action:'document',id:x.id},{label:'Schedule payment',action:'action-modal',id:x.id}])}</td></tr>`).join(''),'1280px'));
 else if(t==='payments')body=`<div class="v34-grid two"><div>${panel('Payment release queue','Selected obligations, deductions, beneficiary checks and release status.',table(['Bill','Vendor','Due','Gross','WHT','Net','Bank check','Release'],inv.slice(0,8).map((x,i)=>`<tr><td class="v34-link">${e(x.id)}</td><td>${e(x.supplier)}</td><td>${e(x.due)}</td><td class="num">${money(x.amount)}</td><td class="num">${money((x.amount||0)*.025)}</td><td class="num">${money((x.amount||0)*.975)}</td><td>${st(i===0?'Review':'Ready')}</td><td>${st(i<2?'Pending':'Approved')}</td></tr>`).join(''),'920px'))}</div><div class="v34-stack">${panel('Funding position','Projected post-run liquidity by settlement bank.',`${kpi('Selected obligations','$270.8k','3 bills','#6b4cff')}${kpi('Available cash','$2.04m','CBZ USD Operating','#0b74ff')}${kpi('Post-run cash','$1.77m','87% liquidity buffer','#009b68')}`)}${panel('Release gates','Every payment must clear these controls.',`<div class="v34-list">${row('Beneficiary validation','Independent bank ownership check',st('Ready'))}${row('Duplicate payment scan','No duplicate reference detected',st('Ready'))}${row('Tax deductions','Withholding and VAT verified',st('Ready'))}${row('Signatory authority','Finance Director + bank signatory',st('Pending'))}</div>`)}</div></div>`;
 else if(t==='vendors')body=`<div class="v34-grid two"><div>${panel('Vendor master register','Vendor Registry now sits inside Payables. Select any vendor for KYC, transactions, statements and payment eligibility.',table(['Vendor','Category','Country','Currency','Compliance','12m spend','Tax / KYC','Status',''],(vs.length?vs:[{id:'VEN-001',name:'Dube & Partners',category:'Professional services',country:'Zimbabwe',currency:'USD',compliance:96,spend:468000,taxExpiry:'31 Jan 2027',status:'Active'}]).map((v,i)=>`<tr data-v34="vendor" data-id="${e(v.id)}"><td class="v34-link">${e(v.name)}<span class="v34-sub">${e(v.id)}</span></td><td>${e(v.category||'General')}</td><td>${e(v.country||'Zimbabwe')}</td><td>${e(v.currency||'USD')}</td><td>${v.compliance||v.kyc||90}%</td><td class="num">${money(v.spend||0)}</td><td>${e(v.taxExpiry||v.tax||'Verified')}</td><td>${st(v.status||'Active')}</td><td onclick="event.stopPropagation()">${more(`v34ven-${i}`,[{label:'Open vendor 360°',action:'vendor',id:v.id},{label:'Digital KYC',action:'vendor-kyc',id:v.id},{label:'Send vendor statement',action:'action-modal',id:v.id},{label:'Edit permitted fields',action:'vendor-edit',id:v.id}])}</td></tr>`).join(''),'1120px'))}</div><div class="v34-stack">${panel('Vendor risk distribution','Payment eligibility and compliance concentration.',chart([96,92,89,82,77,88,91,94,90,93,95,97],'Vendor compliance score','#00a8dc','%'))}${panel('Master-data controls','Sensitive changes require independent approval.',`<div class="v34-list">${row('Bank account changes','1 pending checker review',st('Review'))}${row('Tax renewals','2 due within 60 days',st('Pending'))}${row('Beneficial ownership','100% of active vendors evidenced',st('Ready'))}${row('Payment holds','1 active vendor hold',st('Hold'))}</div>`)}</div></div>`;
 else if(t==='aging')body=`<div class="v34-grid equal">${panel('Creditors ageing','Open liabilities by ageing bucket.',`<div class="v34-age"><div><strong>$213k</strong><span>Current</span></div><div><strong>$68k</strong><span>1–30</span></div><div><strong>$43k</strong><span>31–60</span></div><div><strong>$18k</strong><span>61–90</span></div><div><strong>$0</strong><span>90+</span></div></div>`)}${panel('Ageing trend','How unpaid supplier balances are changing.',chart([221,218,238,252,244,268,277,293,286,302,324,342],'Payables balance','#6b4cff'))}</div>`;
 else body=`<div class="v34-grid equal">${panel('Purchase commitments','Open POs and uninvoiced receipts by owner.',table(['PO','Supplier','Commitment','Received','Invoiced','Open','Owner','Status'],[['PO-2026-1171','TechNova Solutions',96192,48096,0,96192,'Chipo Ndlovu','Open'],['PO-2026-1162','Cloud Africa',28400,28400,18600,9800,'Rudo Kaseke','Partial'],['PO-2026-1158','Westend Properties',12600,12600,12600,0,'Tariro Moyo','Closed']].map(r=>`<tr>${r.map((c,i)=>`<td class="${i>=2&&i<=5?'num':''}">${typeof c==='number'?money(c):i===7?st(c):e(c)}</td>`).join('')}</tr>`).join(''),'860px'))}${panel('Commitment analytics','Budget consumption and goods-receipt completeness.',`<div class="v34-bar"><b>Technology</b><div class="v34-meter"><i style="width:78%;--bar:#6b4cff"></i></div><strong>$96k</strong></div><div class="v34-bar"><b>Professional</b><div class="v34-meter"><i style="width:64%;--bar:#0b74ff"></i></div><strong>$74k</strong></div><div class="v34-bar"><b>Facilities</b><div class="v34-meter"><i style="width:42%;--bar:#00a8dc"></i></div><strong>$51k</strong></div>`)}</div>`;
 return `<div class="v34-page">${pageHeadAndFilters('Accounts payable','Payables & Payments','Procure-to-pay control for supplier bills, vendor governance, ageing, commitments, treasury funding and payment release.',`${btn('New supplier bill','action-modal','primary','New supplier bill')}${btn('Create payment run','action-modal','','Payment run')}`,'ap',[field('Vendor',select(['All vendors',...vs.map(v=>v.name)])),field('Status',select(['All statuses','Approved','Review','Hold','Paid'])),field('Currency',select(['All currencies','USD','ZWG','ZAR']))])}<div class="v34-kpis">${kpi('Outstanding',money(total),'Supplier liabilities','#6b4cff')}${kpi('Due in 7 days','$126.5k','Treasury funding','#e99000')}${kpi('Approved to pay','$270.8k','Validated population','#009b68')}${kpi('Match exceptions','2','$71.6k exposure','#db3450')}${kpi('Open commitments','$118.6k','PO not invoiced','#00a8dc')}${kpi('Vendor holds','1','Payment ineligible','#db3450')}</div>${tabs('ap',[['command','Command'],['bills','Supplier bills'],['payments','Payments'],['vendors','Vendor Registry'],['aging','Creditors ageing'],['commitments','Commitments']],t)}${body}</div>`}
