  function riskIntel25(){return `<div class="v25-grid-2"><section class="v25-intel-card"><h3>Finance risk map</h3><p>Material finance risks positioned by financial exposure and urgency.</p><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:7px">${[['MFI PAR30','$214k','High'],['Unhedged USD/ZWG','$188k','High'],['Issuer concentration','$146k','Medium'],['Close evidence','$48k','Medium'],['Vendor bank change','$122k','High'],['Covenant headroom','$91k','Medium'],['Tax filing','$38k','Low'],['Customer dispute','$123k','Medium']].map(x=>`<div data-v25="intel-record" data-id="${x[0]}" style="cursor:pointer;border:1px solid ${x[2]==='High'?'#e9a7ad':x[2]==='Medium'?'#ebd39c':'#b9d7fb'};border-radius:12px;padding:11px;background:#fff"><b style="font-size:10px">${x[0]}</b><strong style="display:block;margin-top:6px;font-size:15px">${x[1]}</strong><span style="font-size:10px;color:#718198">${x[2]} priority</span></div>`).join('')}</div></section><section class="v25-intel-card"><h3>Risk movement</h3><p>Total quantified exposure and overdue actions across recent review points.</p><div class="v25-chart" data-v25="chart-focus">${miniLineSvg25([812,774,846,791,752,718,744,690,662,638,612,584],'Finance risk exposure')}<div class="v25-chart-label">Quantified finance risk exposure (USD'000)</div></div></section></div>`}
  function closeIntel25(){return `<div class="v25-grid-equal"><section class="v25-intel-card"><h3>Close critical path</h3><p>Dependencies that determine whether the period can close on schedule.</p>${[['Cash & bank reconciliation','94%','1 exception'],['Receivables cut-off','88%','2 tasks'],['Payables cut-off','91%','1 task'],['Tax readiness','89%','1 return'],['Reporting & consolidation','78%','3 tasks'],['Executive sign-off','0%','Not started']].map((x,i)=>`<div data-v25="intel-record" data-id="${x[0]}" style="cursor:pointer;display:grid;grid-template-columns:26px 1fr 52px 78px;gap:8px;align-items:center;padding:9px 0;border-bottom:1px solid #e7eef7"><span style="width:22px;height:22px;border-radius:7px;background:#eef5ff;color:#0878f6;display:grid;place-items:center;font-weight:850">${i+1}</span><b style="font-size:10px">${x[0]}</b><strong>${x[1]}</strong><span style="font-size:10px;color:#718198">${x[2]}</span></div>`).join('')}</section><section class="v25-intel-card"><h3>Close duration and owner load</h3><p>Trend in close performance and current concentration of unresolved work.</p><div class="v25-chart" data-v25="chart-focus">${miniLineSvg25([8.2,7.8,7.4,7.6,7.1,6.8,6.5,6.2,6.0,5.7,5.4,5.1],'Close duration')}<div class="v25-chart-label">Close duration (business days)</div></div>${[['Tariro Moyo','7 tasks'],['Rudo Chivero','5 tasks'],['Farai Mapfumo','4 tasks']].map(x=>`<div style="display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #e7eef7"><b style="font-size:10px">${x[0]}</b><span style="font-size:10px;color:#718198">${x[1]}</span></div>`).join('')}</section></div>`}
  function complianceIntel25(){return `<div class="v25-grid-2"><section class="v25-intel-card"><h3>Filing calendar</h3><p>Returns, evidence and reviewer readiness across the compliance cycle.</p><div class="v25-table-wrap"><table class="v25-table" style="min-width:620px"><thead><tr><th>Return</th><th>Due</th><th>Evidence</th><th>Reviewer</th><th>Status</th></tr></thead><tbody>${[['VAT Jul 2026','25 Aug','96%','Rudo Chivero','Review'],['PAYE Jul 2026','10 Aug','100%','Farai Mapfumo','Ready'],['QPD 3','25 Sep','84%','Finance Director','In progress'],['Withholding tax','10 Aug','100%','Tariro Moyo','Ready']].map(x=>`<tr data-clickable="1" data-v25="intel-record" data-id="${x[0]}"><td><b>${x[0]}</b></td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${status25(x[4])}</td></tr>`).join('')}</tbody></table></div></section><section class="v25-intel-card"><h3>Compliance exceptions</h3><p>Reconciling items and missing evidence by monetary exposure.</p><div class="v25-chart" data-v25="chart-focus">${miniLineSvg25([82,74,69,61,58,54,47,43,39,36,31,28],'Compliance exceptions')}<div class="v25-chart-label">Open compliance exception value (USD'000)</div></div></section></div>`}
