  function inventoryIntel25(){return `<div class="v25-grid-2"><section class="v25-intel-card"><h3>Usage and replenishment</h3><p>Inventory consumption versus receipts and projected reorder pressure.</p><div class="v25-chart" data-v25="chart-focus">${miniLineSvg25([118,132,127,146,154,149,172,188,181,204,196,218],'Inventory usage')}<div class="v25-chart-label">Monthly issued inventory value (USD'000)</div></div></section><section class="v25-intel-card"><h3>Items requiring action</h3><p>Low cover, count variance and slow-moving exposure.</p>${[['Laptop accessories','8 days cover','$18.2k'],['Fuel cards','Count variance','$6.4k'],['Printer consumables','12 days cover','$9.8k'],['Legacy network stock','Slow moving','$22.1k']].map(x=>`<div data-v25="intel-record" data-id="${x[0]}" style="cursor:pointer;padding:10px 0;border-bottom:1px solid #e8eef6"><b style="font-size:10px">${x[0]}</b><div style="display:flex;justify-content:space-between;font-size:10px;color:#718198;margin-top:3px"><span>${x[1]}</span><strong style="color:#14243a">${x[2]}</strong></div></div>`).join('')}</section></div>`}
  function investIntel25(){return `<div class="v25-intel-invest"><div class="v25-intel-card"><h3>Yield and carrying value</h3><p>Portfolio appreciation and weighted yield across the active investment book.</p><div class="v25-chart" data-v25="chart-focus">${miniLineSvg25([9.8,10.1,10.7,11.2,11.6,12.1,12.5,12.9,13.2,13.8,14.1,14.6],'Portfolio carrying value')}<div class="v25-chart-label">Carrying value trend (USDm equivalent)</div></div><h3 style="margin-top:14px">Maturity ladder</h3><div class="v25-maturity-ladder">${[['0-30d','42%'],['31-60d','29%'],['61-90d','18%'],['90d+','11%']].map(x=>`<div class="v25-maturity-row"><span style="font-size:10px">${x[0]}</span><div class="v25-maturity-bar"><i style="width:${x[1]}"></i></div><b style="font-size:10px;text-align:right">${x[1]}</b></div>`).join('')}</div></div><div class="v25-intel-card"><h3>Issuer concentration</h3><p>Principal plus accrued interest by financial institution.</p>${[['Old Mutual','$4.12m','28.2%'],['CBZ Treasury','$3.44m','23.6%'],['NMB Bank','$2.88m','19.7%'],['Stanbic','$2.06m','14.1%'],['Other','$2.10m','14.4%']].map(x=>`<div data-v25="intel-record" data-id="${x[0]} investments" style="cursor:pointer;padding:9px 0;border-bottom:1px solid #e8eef6;display:grid;grid-template-columns:1fr auto;gap:8px"><div><b style="font-size:10px">${x[0]}</b><div style="font-size:10px;color:#718198">${x[2]} of portfolio</div></div><strong style="font-size:10px">${x[1]}</strong></div>`).join('')}</div></div>`}
