  function ledgerIntel25(){return `<div class="v25-intel-ledger"><div class="v25-intel-card"><h3>Posting integrity</h3><p>Automation, reversals and manual-entry concentration.</p><div class="v25-integrity-ring"><div class="ring"></div></div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:6px;text-align:center"><div><b>2.1%</b><small style="display:block;color:#718198">manual</small></div><div><b>1.4%</b><small style="display:block;color:#718198">reversals</small></div><div><b>0</b><small style="display:block;color:#718198">imbalanced</small></div></div></div><div class="v25-intel-card"><h3>Journal volume and source mix</h3><p>Daily posting activity with the highest-volume source systems.</p><div class="v25-chart" data-v25="chart-focus">${miniLineSvg25([112,146,138,182,169,204,197,231,219,258,246,278],'Journal volume')}<div class="v25-chart-label">Journal lines posted per business day</div></div>${[['Cashbook','29%'],['Payables','24%'],['Receivables','18%'],['Investments','13%'],['Payroll','9%'],['Manual journals','7%']].map(x=>`<div style="display:grid;grid-template-columns:110px 1fr 42px;gap:8px;align-items:center;margin-top:7px"><span style="font-size:10px">${x[0]}</span><div class="v25-maturity-bar"><i style="width:${x[1]}"></i></div><b style="font-size:10px">${x[1]}</b></div>`).join('')}</div></div>`}
  function enhanceIntel25(root=document){
    qa25('.v21-layer[data-level="2"]',root).forEach(layer=>{
      qa25('.v23-control-layout',layer).forEach(x=>x.remove());
      qa25('.v21-layer-head button',layer).forEach(x=>{if(/^\s*(?:←\s*)?Back\s*$/i.test((x.textContent||'').trim()))x.remove()});
      if(layer.dataset.v25Unique==='1')return;const kind=inferIntelKind25(layer);layer.dataset.v25Unique='1';layer.dataset.v25Kind=kind;
      qa25('.v21-hero,.v21-layer-grid,.v22-journey,.v22-insight-nav,.v22-subview,.v22-subview-grid',layer).forEach(x=>x.remove());
      qa25('.v21-layer-head button',layer).forEach(x=>{if(/^\s*(?:←\s*)?Back\s*$/i.test((x.textContent||'').trim()))x.remove()});
      removeGenericActions25(layer);
      const host=document.createElement('div');host.className='v25-intel';host.innerHTML=`<h2 class="v25-intel-title">${({cash:'Liquidity intelligence',ar:'Receivables intelligence',ap:'Payables intelligence',risk:'Finance risk intelligence',close:'Close performance intelligence',compliance:'Compliance intelligence',vendor:'Vendor control intelligence',inventory:'Inventory intelligence',invest:'Treasury portfolio intelligence',report:'Performance intelligence',ledger:'Ledger integrity intelligence',control:'Control intelligence'})[kind]||'Finance intelligence'}</h2>${({cash:cashIntel25,ar:arIntel25,ap:apIntel25,risk:riskIntel25,close:closeIntel25,compliance:complianceIntel25,vendor:vendorIntel25,inventory:inventoryIntel25,invest:investIntel25,report:reportIntel25,ledger:ledgerIntel25,control:controlIntel25})[kind]?.()||controlIntel25()}`;
      const head=q25('.v21-layer-head',layer);if(head)head.after(host);else layer.prepend(host);
    });
  }

