  function reconCompare25(){return `<div class="v25-recon-account-strip"><div><div class="k">Bank account</div><div class="v">${RE25.bank}</div></div><div><div class="k">Statement period</div><div class="v">${RE25.from} → ${RE25.to}</div></div><div><div class="k">Statement source</div><div class="v">Direct feed + signed file</div></div><div><div class="k">Import checksum</div><div class="v">5D39-A8C4-11F2</div></div><div><div class="k">Prepared by</div><div class="v">Tariro Moyo · 08:12</div></div></div><div class="v25-recon-grid"><section class="v25-recon-pane"><div class="v25-recon-pane-head"><div><strong>Bank statement</strong><br><span>External evidence · ${stmt25.length} displayed lines</span></div>${status25('2 unmatched')}</div>${reconTable25(stmt25,'stmt')}</section><div class="v25-recon-rail"><button class="v25-btn primary" title="Match selected" data-v25="recon-match">⇄</button>${more25([{label:'Split match',action:'recon-split'},{label:'Create bank adjustment',action:'recon-adjust'},{label:'Raise exception',action:'recon-exception'}])}</div><section class="v25-recon-pane"><div class="v25-recon-pane-head"><div><strong>Cashbook & General Ledger</strong><br><span>Posted accounting records · ${gl25.length} candidates</span></div>${status25('GL balanced')}</div>${reconTable25(gl25,'gl')}</section></div><div class="v25-recon-summary"><div><div class="k">Statement closing</div><div class="v">$2.32m</div></div><div><div class="k">Ledger closing</div><div class="v">$2.31m</div></div><div><div class="k">Matched</div><div class="v">98.7%</div></div><div><div class="k">Unexplained difference</div><div class="v">$475.00</div></div><div><div class="k">Control status</div><div class="v">Review required</div></div></div>`}
  function reconInternal25(){const mods=[['Portfolio Management','$14.64m','$14.64m','$0.00','Ready'],['Procurement / AP','$421.8k','$421.8k','$0.00','Ready'],['Payroll','$188.4k','$188.4k','$0.00','Ready'],['Investment Management','$14.60m','$14.64m','$42.7k','Review'],['Fund Administration','$6.82m','$6.80m','$18.2k','Review']];return `<div class="v25-panel"><div class="v25-panel-head"><div><h3>Internal-module ledger reconciliation</h3><p>Reconcile operational sub-ledgers to Accounting by entity and period before close.</p></div></div><div class="v25-table-wrap"><table class="v25-table"><thead><tr><th>Source module</th><th>Sub-ledger balance</th><th>Accounting GL</th><th>Difference</th><th>Status</th><th></th></tr></thead><tbody>${mods.map((x,i)=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${status25(x[4])}</td><td>${more25([{label:'Open difference analysis',action:'recon-module',id:x[0]},{label:'View source ledger',action:'recon-source',id:x[0]},{label:'Create reconciliation note',action:'recon-note',id:x[0]}])}</td></tr>`).join('')}</tbody></table></div></div>`}
  function reconExceptions25(){const rows=[['Bank service charge','$475','Tariro Moyo','4h','Awaiting adjustment'],['Investment maturity timing','$2,180','Rudo Chivero','8h','Source date mismatch'],['Interest credit','$2,840','Tariro Moyo','1d','Missing cashbook receipt']];return `<div class="v25-grid-2"><section class="v25-panel"><div class="v25-panel-head"><div><h3>Exception queue</h3><p>Unmatched items requiring evidence, accounting treatment or owner action.</p></div></div><div class="v25-table-wrap"><table class="v25-table" style="min-width:680px"><thead><tr><th>Exception</th><th>Amount</th><th>Owner</th><th>Age</th><th>Reason</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${x[4]}</td><td>${more25([{label:'Investigate',action:'recon-exception-open',id:x[0]},{label:'Attach evidence',action:'recon-evidence',id:x[0]},{label:'Escalate',action:'recon-escalate',id:x[0]}])}</td></tr>`).join('')}</tbody></table></div></section><section class="v25-panel"><div class="v25-panel-head"><div><h3>Exception ageing</h3><p>Resolution SLA and materiality posture.</p></div></div><div class="v25-panel-body"><div class="v25-chart" data-v25="chart-focus">${miniLineSvg25([11,9,8,7,6,5,5,4,4,3,3,3],'Unmatched exceptions')}<div class="v25-chart-label">Open exceptions over the last 12 reconciliation runs</div></div></div></section></div>`}
  function reconSignoff25(){return `<div class="v25-grid-equal"><section class="v25-panel"><div class="v25-panel-head"><div><h3>Control completion</h3><p>The reconciliation cannot be signed off until the unexplained difference reaches zero or an approved adjustment exists.</p></div></div><div class="v25-panel-body">${[['Statement completeness','Complete'],['GL population locked','Complete'],['Auto-match reviewed','Complete'],['Manual matches evidenced','Complete'],['Exceptions resolved','Review'],['Adjusted balance equals GL','Review']].map(x=>`<div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #e7eef7"><b style="font-size:10px">${x[0]}</b>${status25(x[1])}</div>`).join('')}</div></section><section class="v25-panel"><div class="v25-panel-head"><div><h3>Maker-checker sign-off</h3><p>Independent accounting review with retained source evidence.</p></div></div><div class="v25-panel-body"><div style="padding:12px;border:1px solid #dce6f2;border-radius:12px"><b>Tariro Moyo</b><div style="font-size:10px;color:#718198;margin-top:3px">Prepared · 31 Jul 2026 17:42</div></div><div style="padding:12px;border:1px solid #dce6f2;border-radius:12px;margin-top:8px"><b>Rudo Chivero</b><div style="font-size:10px;color:#718198;margin-top:3px">Checker · pending</div></div><button class="v25-btn primary" data-v25="recon-signoff" style="margin-top:12px">Review and sign off</button></div></section></div>`}
