function extract47(html,cfg){const root=parse47(html);if(!root)return null;const head=root.querySelector(cfg.head);let actions='';if(head){const a=head.querySelector(cfg.actions);if(a){actions=a.innerHTML;a.remove()}}const tabs=root.querySelector(cfg.tabs);const active=tabs?.querySelector('.active')?.dataset?.id||tabs?.querySelector('.active')?.dataset?.tab||tabs?.querySelector('.active')?.dataset?.v27||'';const filter=root.querySelector(cfg.filter);[head,tabs,filter].forEach(x=>x?.remove());root.querySelectorAll(cfg.remove).forEach(x=>x.remove());const rest=Array.from(root.children).map(n=>n.outerHTML).join('');return {head:head?.outerHTML||'',tabs:tabs?.outerHTML||'',filter:filter?.outerHTML||'',actions,active,rest}}
function common47(b,cls,kpis,main,lower,appendRest=true){return `<div class="v47-page ${cls}">${b.head}${b.tabs}<div class="v47-kpis">${kpis}</div><div class="v47-actionbar">${b.actions}</div>${b.filter}${main}${lower}${appendRest?`<div class="v47-rest">${b.rest}</div>`:''}</div>`}
