(()=>{
 const q=(s,r=document)=>r.querySelector(s),qa=(s,r=document)=>[...r.querySelectorAll(s)];
 const sel={
  head:'.page-head,.v8-page-head,.v11-head,.v12-head,.v15-head,.v17-head,.v23-head,.v25-head,.v27-page-head,.v28-hero,.v34-head',
  tabs:'.v34-tabs,.v27-tabs-row,.v28-toolbar,.v17-tabs,.v25-tabs,.v8-tabs,.v11-tabs,.v15-tabs,.v23-tabs,.v6-tabs,.v7-recurring-tabs,.tabs',
  kpis:'.v48-stats,.v34-kpis,.v28-kpis,.v27-kpis,.v17-kpis,.v25-kpis,.v8-kpis,.v11-kpis,.v15-kpis,.v23-kpis,.grid.kpis,.kpis',
  actions:'.v34-actions,.v28-hero-actions,.v27-head-actions,.v17-actions,.v25-actions,.v8-actions,.v11-actions,.v15-actions,.v23-actions,.v36-action-row,.page-actions',
  filters:'.v34-filter-panel,.v28-filter-panel,.v27-filter-panel,.v17-filters,.v25-filter-panel,.v8-filterbar,.v12-filterbar,.v15-filterbar,.v23-filter-panel,.v36-filter-panel',
  panels:'.panel,.v8-panel,.v11-panel,.v12-panel,.v15-panel,.v17-panel,.v23-panel,.v25-panel,.v27-panel,.v28-panel,.v34-panel,.v47-panel,.v48-surface'
 };
 function visible(el){if(!el)return false;const s=getComputedStyle(el);return s.display!=='none'&&s.visibility!=='hidden'}
 function refine(){
   const root=q('#main');if(!root)return;
   root.classList.add('v50-refined');
   const head=qa(sel.head,root).find(visible);if(head)head.classList.add('v50-head');
   const tabs=qa(sel.tabs,root).find(visible);if(tabs)tabs.classList.add('v50-subnav');
   const kpis=qa(sel.kpis,root).find(visible);if(kpis)kpis.classList.add('v50-kpis');
   qa(sel.actions,root).filter(visible).forEach(x=>x.classList.add('v50-actions'));
   qa(sel.filters,root).filter(visible).forEach(x=>x.classList.add('v50-filters'));
   qa(sel.panels,root).filter(visible).forEach(x=>x.classList.add('v50-panel'));
   qa('table',root).forEach(x=>x.classList.add('v50-table'));
   qa('button,a',root).filter(x=>/^\s*(back|return)(\s|$)/i.test((x.textContent||'').trim())).forEach(x=>x.classList.add('v50-back'));
   // Standardise document hierarchy without duplicating page furniture.
   qa('h1,h2,h3,h4',root).forEach(h=>h.style.textAlign='left');
 }
 const prior=typeof render==='function'?render:null;
 if(prior){render=function(){const out=prior.apply(this,arguments);requestAnimationFrame(refine);return out}}
 requestAnimationFrame(refine);
 document.title='Matanho Accounting Operating System · Enterprise Finance v50';
 window.MatanhoAccountingV50={version:'50.0.0',refine};
})();



(()=>{'use strict';
const q=(s,r=document)=>r.querySelector(s),qa=(s,r=document)=>[...r.querySelectorAll(s)];
const STORE='matanho-accounting-v51';
const load=()=>{try{return JSON.parse(localStorage.getItem(STORE)||'{}')}catch{return {}}};
const V=Object.assign({invTab:'overview',assetTab:'overview',invSearch:'',invWarehouse:'All warehouses',invCategory:'All categories',assetSearch:'',assetClass:'All classes',movements:[],fxMethod:'IAS 21 policy'},load());
const save=()=>{try{localStorage.setItem(STORE,JSON.stringify(V))}catch(_){}};
const e=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const money=n=>`$${Number(n||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const pill=(s,c='info')=>`<span class="v51-pill ${c}">${e(s)}</span>`;
const btn=(l,a,cls='',id='')=>`<button class="v51-btn ${cls}" data-v51="${a}" ${id?`data-id="${e(id)}"`:''}>${l}</button>`;
const field=(l,html,wide='')=>`<div class="v51-field ${wide}"><label>${e(l)}</label>${html}</div>`;
const select=(id,opts,val)=>`<select id="${id}">${opts.map(x=>`<option ${x===val?'selected':''}>${e(x)}</option>`).join('')}</select>`;
const input=(id,val='',type='text',ph='')=>`<input id="${id}" type="${type}" value="${e(val)}" placeholder="${e(ph)}">`;
const head=(eye,title,desc,actions='')=>`<div class="v51-head"><div><div class="eye">${e(eye)}</div><h1>${e(title)}</h1><p>${e(desc)}</p></div><div class="v51-actions">${actions}</div></div>`;
const tabs=(key,active,items)=>`<nav class="v51-tabs">${items.map(x=>`<button class="${active===x[0]?'active':''}" data-v51="${key}" data-id="${x[0]}">${e(x[1])}</button>`).join('')}</nav>`;
const kpi=(l,v,m,c)=>`<article class="v51-kpi" style="--c:${c}"><span>${e(l)}</span><strong>${e(v)}</strong><small>${e(m)}</small></article>`;
const panel=(t,s,b,f='')=>`<section class="v51-panel"><header><div><h3>${e(t)}</h3><p>${e(s)}</p></div></header><div class="v51-panel-body">${b}</div>${f?`<footer class="v51-panel-foot">${f}</footer>`:''}</section>`;
function seed(){if(V.movements.length)return;V.movements=[
 {id:'MOV-260814-019',date:'2026-08-14',sku:'SP-044-120',type:'Issue',qty:-12,project:'Workshop Service Mandate',counterparty:'Internal workshop',ref:'ISS-4118',owner:'T. Moyo'},
 {id:'MOV-260814-018',date:'2026-08-14',sku:'IT-006-087',type:'Reserve',qty:-2,project:'Technology Refresh',counterparty:'IT',ref:'RSV-0871',owner:'F. Mapfumo'},
 {id:'MOV-260813-044',date:'2026-08-13',sku:'PPE-021-014',type:'Receipt',qty:24,project:'None',counterparty:'Safety First Supplies',ref:'GRN-2391',owner:'R. Chikomba'},
 {id:'MOV-260812-031',date:'2026-08-12',sku:'OFF-014-022',type:'Count adjustment',qty:-1,project:'Corporate',counterparty:'Physical count',ref:'CNT-2026-088',owner:'N. Moyo'}
 ];save()}
seed();
function invRows(){const term=V.invSearch.toLowerCase();return inventory.filter(x=>(V.invWarehouse==='All warehouses'||x.warehouse===V.invWarehouse)&&(V.invCategory==='All categories'||x.category===V.invCategory)&&(!term||`${x.sku} ${x.item} ${x.category} ${x.warehouse}`.toLowerCase().includes(term)))}
function invFilter(){return `<div class="v51-filter">${field('Search',input('v51InvSearch',V.invSearch,'search','SKU, item, warehouse...'))}${field('Warehouse',select('v51InvWarehouse',['All warehouses',...new Set(inventory.map(x=>x.warehouse))],V.invWarehouse))}${field('Category',select('v51InvCategory',['All categories',...new Set(inventory.map(x=>x.category))],V.invCategory))}${field('From',input('v51InvFrom','2026-08-01','date'))}${field('To',input('v51InvTo','2026-08-14','date'))}</div>`}
function movementTable(rows=V.movements){return `<div class="v51-tablewrap"><table class="v51-table"><thead><tr><th>Date</th><th>Movement</th><th>SKU</th><th>Reference</th><th>Project / mandate</th><th>Counterparty</th><th class="num">Qty</th><th>Owner</th></tr></thead><tbody>${rows.map(m=>`<tr data-v51="inv-item" data-id="${e(m.sku)}"><td>${e(m.date)}</td><td>${pill(m.type,/adjust/i.test(m.type)?'warn':/receipt/i.test(m.type)?'good':'info')}</td><td class="v51-link">${e(m.sku)}</td><td>${e(m.ref)}</td><td>${e(m.project)}</td><td>${e(m.counterparty)}</td><td class="num">${m.qty>0?'+':''}${m.qty}</td><td>${e(m.owner)}</td></tr>`).join('')}</tbody></table></div>`}
function invOverview(){const rows=invRows(),total=rows.reduce((s,x)=>s+x.qty*x.unitCost,0),exceptions=rows.filter(x=>x.status!=='Controlled').length,units=rows.reduce((s,x)=>s+x.qty,0);const stock=`<div class="v51-tablewrap"><table class="v51-table"><thead><tr><th>SKU / item</th><th>Warehouse</th><th>Category</th><th class="num">On hand</th><th class="num">Unit cost</th><th class="num">Carrying value</th><th class="num">Count variance</th><th>Status</th></tr></thead><tbody>${rows.map(x=>`<tr data-v51="inv-item" data-id="${e(x.sku)}"><td><strong class="v51-link">${e(x.sku)}</strong><div class="v51-muted">${e(x.item)}</div></td><td>${e(x.warehouse)}</td><td>${e(x.category)}</td><td class="num">${x.qty}</td><td class="num">${money(x.unitCost)}</td><td class="num">${money(x.qty*x.unitCost)}</td><td class="num">${x.countVar}</td><td>${pill(x.status,x.status==='Controlled'?'good':x.status==='Exception'?'bad':'warn')}</td></tr>`).join('')}</tbody></table></div>`;const alerts=`<div class="v51-attention"><div><strong>Brake pad count variance</strong><span>SP-044-120 is 4 units short against system quantity.</span><footer>${btn('Investigate','inv-item','','SP-044-120')}</footer></div><div><strong>Legacy toner obsolescence</strong><span>Potential obsolete stock; finance provision review required.</span><footer>${btn('Open item','inv-item','','ST-103-016')}</footer></div><div><strong>Office chair recount</strong><span>One-unit count variance remains unresolved.</span><footer>${btn('Start count','inv-action','','count')}</footer></div></div>`;return `<div class="v51-kpis">${kpi('Carrying value',money(total),'Weighted average cost','#0a66ff')}${kpi('Units on hand',String(units),'Filtered stock population','#06a7e8')}${kpi('30-day movements',String(V.movements.length),'Receipts, issues and adjustments','#6d35f2')}${kpi('Control attention',String(exceptions),'Review and exception items','#e59100')}${kpi('Count difference',money(rows.reduce((s,x)=>s+x.countVar*x.unitCost,0)),'Unposted physical variance','#d92d4c')}</div>${invFilter()}${panel('Physical stock flow','Operational movement from receipt through use and financial control.',`<div class="v51-flow"><div><span>Received</span><strong>1,842</strong><small>30-day units</small></div><div><span>Available</span><strong>1,476</strong><small>After reservations</small></div><div><span>Reserved</span><strong>266</strong><small>Project commitments</small></div><div><span>Issued</span><strong>624</strong><small>30-day consumption</small></div><div><span>Count variance</span><strong>$1.24k</strong><small>Awaiting review</small></div></div>`,`${btn('Receive stock','inv-action','green','receipt')}${btn('Issue stock','inv-action','blue','issue')}${btn('Transfer','inv-action','','transfer')}${btn('Cycle count','inv-action','','count')}`)}<div class="v51-grid two" style="margin-top:10px">${panel('Inventory control register','Full carrying value, quantity and count-control view. Select an item for movement history and accounting context.',stock)}${panel('Attention queue','Only exceptions that require an accountant, warehouse custodian or controller action.',alerts)}</div><div style="margin-top:10px">${panel('Recent stock movements','Every receipt, issue and adjustment retains project, counterparty and source reference.',movementTable(V.movements.slice(0,8)))}</div>`}
function invPage(){let body='';if(V.invTab==='overview')body=invOverview();else if(V.invTab==='movements')body=`${invFilter()}${panel('Movement ledger','Chronological stock receipts, issues, transfers, reservations and count adjustments.',movementTable())}`;else if(V.invTab==='usage'){const usage=V.movements.filter(x=>x.qty<0);body=`${invFilter()}<div class="v51-grid equal">${panel('Project & mandate usage','Track the destination of stock consumption rather than only its accounting value.',`<div class="v51-tablewrap"><table class="v51-table" style="min-width:700px"><thead><tr><th>Project / mandate</th><th>Movement</th><th>SKU</th><th class="num">Units</th><th>Reference</th></tr></thead><tbody>${usage.map(x=>`<tr><td>${e(x.project)}</td><td>${e(x.type)}</td><td class="v51-link">${e(x.sku)}</td><td class="num">${Math.abs(x.qty)}</td><td>${e(x.ref)}</td></tr>`).join('')}</tbody></table></div>`)}${panel('Consumption controls','Operational controls applied before stock usage posts to the inventory sub-ledger.',`<div class="v51-attention"><div><strong>Project coding</strong><span>Required for all project or mandate stock issues.</span></div><div><strong>Custodian approval</strong><span>Issues above policy quantity require independent approval.</span></div><div><strong>Inventory to GL</strong><span>Cost movements reconcile to account 1400 at period end.</span></div></div>`)}</div>`}else if(V.invTab==='replenishment'){body=`${invFilter()}${panel('Replenishment planner','Demand, days cover and reorder points by SKU.',`<div class="v51-tablewrap"><table class="v51-table"><thead><tr><th>SKU / item</th><th>Warehouse</th><th class="num">On hand</th><th class="num">Reorder point</th><th class="num">Suggested order</th><th>Lead time</th><th>Decision</th></tr></thead><tbody>${invRows().map((x,i)=>`<tr data-v51="inv-item" data-id="${e(x.sku)}"><td><strong>${e(x.sku)}</strong><div class="v51-muted">${e(x.item)}</div></td><td>${e(x.warehouse)}</td><td class="num">${x.qty}</td><td class="num">${[18,8,35,92,7,12][i]||10}</td><td class="num">${Math.max(0,([18,8,35,92,7,12][i]||10)*2-x.qty)}</td><td>${[21,10,14,7,18,30][i]||14} days</td><td>${x.qty<([18,8,35,92,7,12][i]||10)?pill('Reorder','warn'):pill('Covered','good')}</td></tr>`).join('')}</tbody></table></div>`,'')}` }else if(V.invTab==='counts'){body=`${invFilter()}${panel('Physical count control','Plan cycle counts, capture variances and post approved adjustments.',`<div class="v51-attention"><div><strong>Harare Main cycle count</strong><span>126 SKUs · due 14 Aug · 3 variances captured</span><footer>${btn('Capture count','inv-action','primary','count')}</footer></div><div><strong>Workshop Central recount</strong><span>SP-044-120 · 4-unit shortage requires recount evidence</span><footer>${btn('Open item','inv-item','','SP-044-120')}</footer></div></div>`)}` }else body=`${invFilter()}<div class="v51-grid equal">${panel('Valuation & GL tie-out','Weighted-average carrying value reconciled to the inventory control account.',`<div class="v51-facts"><div class="v51-fact"><span>Sub-ledger value</span><strong>${money(inventory.reduce((s,x)=>s+x.qty*x.unitCost,0))}</strong></div><div class="v51-fact"><span>GL control account 1400</span><strong>$49,342.00</strong></div><div class="v51-fact"><span>Difference</span><strong>$1,240.00</strong></div><div class="v51-fact"><span>Valuation method</span><strong>Weighted average</strong></div></div>`)}${panel('Period-end valuation controls','Exception-first review before the valuation journal is signed off.',`<div class="v51-attention"><div><strong>Count variance journal</strong><span>$1.24k requires maker-checker approval.</span></div><div><strong>Obsolescence review</strong><span>ST-103-016 requires provision assessment.</span></div><div><strong>Negative inventory</strong><span>No negative quantities detected.</span></div></div>`)}</div>`;return `<div class="v51-page">${head('Inventory sub-ledger','Inventory & Usage','Track quantities, physical use, project consumption, replenishment, counts and valuation without losing the link to the General Ledger.',`${btn('Receive stock','inv-action','green','receipt')}${btn('Issue stock','inv-action','blue','issue')}${btn('Adjust','inv-action','','adjust')}`)}${tabs('inv-tab',V.invTab,[['overview','Overview'],['movements','Movement ledger'],['usage','Usage & projects'],['replenishment','Replenishment'],['counts','Physical counts'],['valuation','Valuation & GL']])}${body}</div>`}

function assetFilter(){return `<div class="v51-filter">${field('Search',input('v51AssetSearch',V.assetSearch,'search','Asset, custodian, location...'))}${field('Class',select('v51AssetClass',['All classes',...new Set(assets.map(x=>x.category))],V.assetClass))}${field('From',input('v51AssetFrom','2026-01-01','date'))}${field('To',input('v51AssetTo','2026-08-14','date'))}${field('Status',select('v51AssetStatus',['All statuses','Active','Transfer pending','Disposed'],'All statuses'))}</div>`}
function assetRows(){const t=V.assetSearch.toLowerCase();return assets.filter(x=>(V.assetClass==='All classes'||x.category===V.assetClass)&&(!t||`${x.id} ${x.desc} ${x.category} ${x.location} ${x.custodian}`.toLowerCase().includes(t)))}
function assetRegister(){return `<div class="v51-tablewrap"><table class="v51-table"><thead><tr><th>Asset</th><th>Class</th><th>Location</th><th>Custodian</th><th class="num">Cost</th><th class="num">Accum. dep.</th><th class="num">NBV</th><th>Useful life</th><th>Status</th></tr></thead><tbody>${assetRows().map(x=>`<tr data-v51="asset-item" data-id="${e(x.id)}"><td><strong class="v51-link">${e(x.id)}</strong><div class="v51-muted">${e(x.desc)}</div></td><td>${e(x.category)}</td><td>${e(x.location)}</td><td>${e(x.custodian)}</td><td class="num">${money(x.cost)}</td><td class="num">${money(x.accum)}</td><td class="num">${money(x.nbv)}</td><td>${e(x.life)}</td><td>${pill(x.status,x.status==='Active'?'good':'warn')}</td></tr>`).join('')}</tbody></table></div>`}
function assetOverview(){const cost=assetRows().reduce((s,x)=>s+x.cost,0),nbv=assetRows().reduce((s,x)=>s+x.nbv,0),acc=assetRows().reduce((s,x)=>s+x.accum,0);return `<div class="v51-kpis">${kpi('Gross carrying cost',money(cost),'Asset register','#0a66ff')}${kpi('Net book value',money(nbv),'After accumulated depreciation','#6d35f2')}${kpi('Accumulated depreciation',money(acc),'Current register','#06a7e8')}${kpi('CIP','$274.4k','3 projects not yet in service','#e59100')}${kpi('Control attention','4','Verification, transfer and valuation','#d92d4c')}</div>${assetFilter()}${panel('Asset lifecycle','A controlled path from acquisition evidence to depreciation, physical verification and eventual disposal.',`<div class="v51-lifecycle"><div class="v51-life"><i>1</i><strong>Acquire</strong><span>PO, invoice, funding</span></div><div class="v51-life"><i>2</i><strong>Capitalise</strong><span>Tag, class, GL mapping</span></div><div class="v51-life"><i>3</i><strong>Custody</strong><span>Location and owner</span></div><div class="v51-life"><i>4</i><strong>Depreciate</strong><span>Scheduled journal</span></div><div class="v51-life"><i>5</i><strong>Verify</strong><span>Physical evidence</span></div><div class="v51-life"><i>6</i><strong>Dispose</strong><span>Approval and gain/loss</span></div></div>`)}<div class="v51-grid two" style="margin-top:10px">${panel('Fixed asset register','Select an asset for depreciation schedule, custody, evidence, maintenance and lifecycle actions.',assetRegister())}${panel('Finance control queue','Only actions that affect stewardship, valuation or the accounting record.',`<div class="v51-attention"><div><strong>Depreciation run</strong><span>$31.9k July run ready for review and posting.</span><footer>${btn('Preview','asset-action','','depreciation')}</footer></div><div><strong>Physical verification</strong><span>2 assets need current evidence before close.</span><footer>${btn('Open custody','asset-tab','','custody')}</footer></div><div><strong>CIP commissioning</strong><span>$34.8k awaits in-service certificate.</span><footer>${btn('Open additions','asset-tab','','additions')}</footer></div><div><strong>Valuation review</strong><span>2 impairment indicators need assessment.</span><footer>${btn('Review','asset-tab','','valuation')}</footer></div></div>`)}</div>`}
function assetPage(){let body='';if(V.assetTab==='overview')body=assetOverview();else if(V.assetTab==='register')body=`${assetFilter()}${panel('Fixed asset register','Complete sub-ledger population with carrying value, useful life, location and custodian.',assetRegister())}`;else if(V.assetTab==='depreciation')body=`${assetFilter()}<div class="v51-grid equal">${panel('Depreciation run','Preview the proposed non-cash posting before maker-checker approval.',`<div class="v51-facts"><div class="v51-fact"><span>Period</span><strong>July 2026</strong></div><div class="v51-fact"><span>Assets included</span><strong>${assets.length}</strong></div><div class="v51-fact"><span>Expense</span><strong>$31,860.00</strong></div><div class="v51-fact"><span>Method exceptions</span><strong>0</strong></div></div><div style="margin-top:10px">${assetRegister()}</div>`,`${btn('Post run','asset-action','primary','post-depreciation')}`)}${panel('Accounting treatment','Balanced journal generated from the sub-ledger, not manually keyed.',`<div class="v51-tablewrap"><table class="v51-table" style="min-width:560px"><thead><tr><th>Account</th><th class="num">Debit</th><th class="num">Credit</th></tr></thead><tbody><tr><td>5130 · Depreciation Expense</td><td class="num">$31,860.00</td><td class="num">-</td></tr><tr><td>1550 · Accumulated Depreciation</td><td class="num">-</td><td class="num">$31,860.00</td></tr></tbody></table></div>`)}</div>`;else if(V.assetTab==='additions')body=`${assetFilter()}${panel('Additions & capital work in progress','Assets are only capitalised when evidence, in-service date and GL mapping are complete.',`<div class="v51-attention"><div><strong>Data centre resilience upgrade</strong><span>$34.8k · commissioning certificate outstanding</span><footer>${btn('Capitalise','asset-action','primary','capitalise')}</footer></div><div><strong>Fleet replacement programme</strong><span>$119.2k · supplier invoice and registration evidence complete</span><footer>${btn('Review','asset-action','','capitalise')}</footer></div></div>`,`${btn('Add fixed asset','asset-action','primary','add')}`)}`;else if(V.assetTab==='custody')body=`${assetFilter()}${panel('Custody & physical verification','Current custodian, location, evidence date and transfer status.',assetRegister(),`${btn('Record transfer','asset-action','','transfer')}${btn('Record verification','asset-action','primary','verify')}`)}`;else if(V.assetTab==='valuation')body=`${assetFilter()}<div class="v51-grid equal">${panel('Impairment & valuation','Assets flagged by damage, obsolescence or economic under-performance.',`<div class="v51-attention"><div><strong>Boardroom video wall</strong><span>Technology replacement programme may reduce recoverable amount.</span><footer>${btn('Assess','asset-item','','AST-FF-0058')}</footer></div><div><strong>Workshop diagnostic scanner</strong><span>Transfer pending; verify condition and remaining useful life.</span><footer>${btn('Assess','asset-item','','AST-BW-0019')}</footer></div></div>`)}${panel('Valuation controls','Governed effective-dated changes.',`<div class="v51-facts"><div class="v51-fact"><span>Open impairment reviews</span><strong>2</strong></div><div class="v51-fact"><span>Revaluations pending</span><strong>0</strong></div><div class="v51-fact"><span>Residual-value exceptions</span><strong>1</strong></div><div class="v51-fact"><span>Useful-life overrides</span><strong>0</strong></div></div>`)}</div>`;else body=`${assetFilter()}${panel('Disposal register','Approval, proceeds, NBV derecognition and gain/loss evidence.',`<div class="v51-attention"><div><strong>No disposal batches awaiting posting</strong><span>New disposals require asset selection, approval, sale/scrap evidence and a balanced derecognition journal.</span><footer>${btn('Create disposal','asset-action','primary','disposal')}</footer></div></div>`)}`;return `<div class="v51-page">${head('Fixed asset sub-ledger','Fixed Assets','Manage capitalisation, depreciation, custody, impairment and disposal through one controlled lifecycle rather than disconnected registers.',`${btn('Add fixed asset','asset-action','primary','add')}${btn('Run depreciation','asset-action','','depreciation')}`)}${tabs('asset-tab',V.assetTab,[['overview','Overview'],['register','Asset register'],['depreciation','Depreciation'],['additions','Additions & CIP'],['custody','Custody & verification'],['valuation','Impairment & valuation'],['disposals','Disposals']])}${body}</div>`}

function modal(title,desc,body,footer){q('#v51Layer')?.remove();const d=document.createElement('div');d.id='v51Layer';d.className='v51-backdrop';d.innerHTML=`<section class="v51-modal"><header><div><h2>${e(title)}</h2><p>${e(desc)}</p></div><button class="v51-btn" data-v51="close">Close</button></header><div class="v51-modal-body">${body}</div><footer>${footer}</footer></section>`;document.body.appendChild(d)}
function drawer(title,desc,body){q('#v51Layer')?.remove();const d=document.createElement('div');d.id='v51Layer';d.className='v51-backdrop';d.innerHTML=`<aside class="v51-drawer"><header><div><h2>${e(title)}</h2><p>${e(desc)}</p></div><button class="v51-btn" data-v51="close">Close</button></header><div class="v51-drawer-body">${body}</div></aside>`;document.body.appendChild(d)}
function invModal(kind){const names={receipt:'Receive stock',issue:'Issue stock',transfer:'Transfer stock',adjust:'Adjust stock',count:'Capture physical count'};const isTransfer=kind==='transfer';modal(names[kind]||'Inventory action','Update the inventory sub-ledger with source reference, dimensions and an auditable quantity movement.',`<div class="v51-form">${field('SKU',select('v51InvSku',inventory.map(x=>x.sku),inventory[0].sku))}${field('Date',input('v51InvDate','2026-08-14','date'))}${field('Quantity',input('v51InvQty','1','number'))}${field('Reference',input('v51InvRef',`${kind.toUpperCase().slice(0,3)}-${Date.now().toString().slice(-5)}`))}${field('Project / mandate',select('v51InvProject',['None','Corporate','Workshop Service Mandate','Technology Refresh','Growth Fund I'],'None'))}${field(isTransfer?'Destination warehouse':'Counterparty / custodian',input('v51InvCounterparty',''))}${field('Narrative',input('v51InvNote','', 'text','Reason or source document'), 'wide')}</div>`,`${btn('Cancel','close')}${btn('Save movement','save-inv','primary',kind)}`)}
function saveInv(kind){const sku=q('#v51InvSku')?.value,item=inventory.find(x=>x.sku===sku),qty=Math.abs(Number(q('#v51InvQty')?.value||0));if(!item||!qty)return;let delta=qty,type='Receipt';if(kind==='issue'){delta=-qty;type='Issue'}else if(kind==='transfer'){delta=0;type='Transfer'}else if(kind==='adjust'){delta=Number(q('#v51InvQty')?.value||0);type='Adjustment'}else if(kind==='count'){const counted=qty;delta=counted-item.qty;type='Count adjustment'}if(item.qty+delta<0){alert('Quantity cannot become negative.');return}item.qty+=delta;item.value=item.qty*item.unitCost;if(kind==='count')item.countVar=0;V.movements.unshift({id:'MOV-'+Date.now(),date:q('#v51InvDate')?.value||'2026-08-14',sku,type,qty:delta,project:q('#v51InvProject')?.value||'None',counterparty:q('#v51InvCounterparty')?.value||'Internal',ref:q('#v51InvRef')?.value||'Manual',owner:'Current user'});save();q('#v51Layer')?.remove();render()}
function invDrawer(id){const x=inventory.find(v=>v.sku===id);if(!x)return;const mov=V.movements.filter(m=>m.sku===id).slice(0,8);drawer(`${x.sku} · ${x.item}`,'Inventory item · quantity, valuation, usage and movement evidence',`<div class="v51-facts"><div class="v51-fact"><span>Warehouse</span><strong>${e(x.warehouse)}</strong></div><div class="v51-fact"><span>On hand</span><strong>${x.qty}</strong></div><div class="v51-fact"><span>Unit cost</span><strong>${money(x.unitCost)}</strong></div><div class="v51-fact"><span>Carrying value</span><strong>${money(x.qty*x.unitCost)}</strong></div><div class="v51-fact"><span>Count variance</span><strong>${x.countVar}</strong></div><div class="v51-fact"><span>Control status</span><strong>${e(x.status)}</strong></div></div><div class="v51-mini-chart"><svg viewBox="0 0 500 130"><path d="M18 96 C80 82 102 88 150 65 S240 48 285 58 S370 32 480 24" fill="none" stroke="#6d35f2" stroke-width="3"/><path d="M18 108H480" stroke="#dbe3ec"/><text x="18" y="124" font-size="10" fill="#667085">30 days ago</text><text x="430" y="124" font-size="10" fill="#667085">Today</text></svg></div><div style="margin-top:10px">${panel('Recent movements','Source-linked quantity history.',mov.length?movementTable(mov):'<div class="v51-muted">No recent movements.</div>')}</div><div class="v51-actions" style="margin-top:10px">${btn('Issue','inv-action','blue','issue')}${btn('Receive','inv-action','green','receipt')}${btn('Count','inv-action','','count')}</div>`)}
function assetModal(kind){if(kind==='add'){modal('Add fixed asset','Capture acquisition, accounting, tax, custody and evidence before the asset is capitalised.',`<div class="v51-form">${field('Asset description',input('v51AssetDesc','','text','Description'))}${field('Asset class',select('v51AssetCat',['Computer Equipment','Motor Vehicles','Office Equipment','Equipment','Technology'],'Computer Equipment'))}${field('Acquisition date',input('v51AssetDate','2026-08-14','date'))}${field('Supplier',input('v51AssetSupplier','','text','Vendor'))}${field('Cost',input('v51AssetCost','0','number'))}${field('Currency',select('v51AssetCurrency',['USD','ZWG','ZAR'],'USD'))}${field('Location',input('v51AssetLocation','Harare HQ'))}${field('Custodian',input('v51AssetCustodian',''))}${field('Useful life',select('v51AssetLife',['3 years','4 years','5 years','7 years','10 years'],'5 years'))}${field('Depreciation method',select('v51AssetMethod',['Straight line','Reducing balance','Units of production'],'Straight line'))}${field('Residual value',input('v51AssetResidual','0','number'))}${field('Project / funding source',select('v51AssetProject',['Corporate','Growth Fund I','Technology Refresh','Fleet Replacement'],'Corporate'))}${field('Asset GL account',select('v51AssetGL',['1600 · Fixed Assets','1610 · Motor Vehicles','1620 · Computer Equipment'],'1600 · Fixed Assets'))}${field('Depreciation expense GL',select('v51AssetDepGL',['5130 · Depreciation Expense','5131 · Vehicle Depreciation'],'5130 · Depreciation Expense'))}${field('Serial / registration',input('v51AssetSerial',''))}${field('Evidence reference',input('v51AssetEvidence','','text','Invoice / GRN / title / certificate'))}</div>`,`${btn('Cancel','close')}${btn('Create asset','save-asset','primary')}`);return}modal('Fixed asset action','This action will be effective-dated and retained in the asset lifecycle and audit history.',`<div class="v51-form">${field('Asset',select('v51AssetActionId',assets.map(x=>x.id),assets[0].id))}${field('Effective date',input('v51AssetActionDate','2026-08-14','date'))}${field('Reason / evidence',input('v51AssetActionReason','','text','Reason and evidence reference'),'wide')}</div>`,`${btn('Cancel','close')}${btn('Confirm','close','primary')}`)}
function saveAsset(){const cost=Number(q('#v51AssetCost')?.value||0);if(!cost)return;assets.push({id:'AST-'+Date.now().toString().slice(-6),desc:q('#v51AssetDesc')?.value||'New asset',category:q('#v51AssetCat')?.value||'Equipment',location:q('#v51AssetLocation')?.value||'Harare HQ',custodian:q('#v51AssetCustodian')?.value||'Unassigned',cost,accum:0,nbv:cost,life:q('#v51AssetLife')?.value||'5 years',method:q('#v51AssetMethod')?.value||'Straight line',status:'Active'});q('#v51Layer')?.remove();render()}
function assetDrawer(id){const x=assets.find(v=>v.id===id);if(!x)return;const annual=x.cost/Math.max(1,parseInt(x.life)||5);drawer(`${x.id} · ${x.desc}`,'Fixed asset · carrying value, custody, depreciation and lifecycle controls',`<div class="v51-facts"><div class="v51-fact"><span>Asset class</span><strong>${e(x.category)}</strong></div><div class="v51-fact"><span>Location</span><strong>${e(x.location)}</strong></div><div class="v51-fact"><span>Custodian</span><strong>${e(x.custodian)}</strong></div><div class="v51-fact"><span>Gross cost</span><strong>${money(x.cost)}</strong></div><div class="v51-fact"><span>Accumulated depreciation</span><strong>${money(x.accum)}</strong></div><div class="v51-fact"><span>Net book value</span><strong>${money(x.nbv)}</strong></div><div class="v51-fact"><span>Useful life</span><strong>${e(x.life)}</strong></div><div class="v51-fact"><span>Depreciation method</span><strong>${e(x.method)}</strong></div></div><div class="v51-mini-chart"><svg viewBox="0 0 500 130"><path d="M18 22 L110 38 L202 55 L294 72 L386 90 L480 108" fill="none" stroke="#0a66ff" stroke-width="3"/><text x="18" y="16" font-size="10" fill="#334155">${money(x.cost)}</text><text x="420" y="124" font-size="10" fill="#334155">Projected NBV</text></svg></div><div class="v51-grid equal" style="margin-top:10px">${panel('Depreciation profile','Current policy and projected annual charge.',`<div class="v51-facts"><div class="v51-fact"><span>Approx. annual charge</span><strong>${money(annual)}</strong></div><div class="v51-fact"><span>Posting status</span><strong>Scheduled</strong></div></div>`)}${panel('Stewardship controls','Evidence and custody conditions.',`<div class="v51-attention"><div><strong>Physical verification</strong><span>Last verified Jul 2026</span></div><div><strong>Purchase evidence</strong><span>Invoice and approval retained</span></div><div><strong>Insurance / title</strong><span>${/Vehicle/i.test(x.category)?'Policy and registration required':'Not mandatory'}</span></div></div>`)}</div><div class="v51-actions" style="margin-top:10px">${btn('Transfer','asset-action','','transfer')}${btn('Impairment review','asset-action','','impair')}${btn('Dispose','asset-action','danger','disposal')}</div>`)}

function fxPanel(){const root=q('#main');if(!root||!q('#main h1')?.textContent.includes('Financial Reports'))return;qa('.v23-report-currency-strip,.v44-currency-panel,.v45-fund-reporting',root).forEach(x=>x.remove());if(q('.v51-fx-console',root))return;const st=window.MatanhoAccountingV44?.state||{currency:'USD',rateDate:'2026-08-14',display:'translated'};const s8=window.MatanhoAccountingV8?.getState?.()||{};const rates=s8.fxRates||[];const target=q('.v17-filters,.v25-filter-panel,[data-filter="reports"],.v44-filter-toggle',root);const box=document.createElement('section');box.className='v51-fx-console';box.innerHTML=`<header><div><h3>Multi-currency reporting</h3><p>Presentation currency, effective-dated rate evidence and translation method are controlled independently from the underlying ledger currency.</p></div>${btn('Add exchange rate','fx-add','primary')}</header><div class="v51-fx-body"><div class="v51-fx-controls">${field('Functional currency',`<select disabled><option>${e(s8.baseCurrency||'USD')}</option></select>`)}${field('Presentation currency',`<select id="v44ReportCurrency">${['USD','ZWG','ZAR','EUR','GBP'].map(x=>`<option ${x===st.currency?'selected':''}>${x}</option>`).join('')}</select>`)}${field('Rate date',`<input id="v44RateDate" type="date" value="${e(st.rateDate||'2026-08-14')}">`)}${field('Display',`<select id="v44Display"><option value="translated" ${st.display==='translated'?'selected':''}>Presentation currency only</option><option value="dual" ${st.display==='dual'?'selected':''}>Functional + presentation</option></select>`)}${field('Translation policy',`<select id="v51FxMethod"><option>IAS 21 policy</option><option>Closing rate</option><option>Period average</option><option>Custom approved rate</option></select>`,'wide')}<div class="wide v51-actions">${btn('Apply reporting currency','fx-apply','primary')}</div></div><div class="v51-fx-rates"><strong style="font-size:10px">Approved rate register</strong><div class="v51-rate-list">${rates.map(x=>`<div class="v51-rate"><span>${e(x.pair)} · ${e(x.status||'Review')}</span><strong>${Number(x.rate).toFixed(6)}</strong><small>${e(x.date)} · ${e(x.source)}</small></div>`).join('')||'<div class="v51-rate missing"><span>No approved rates</span><strong>—</strong><small>Add the first effective-dated rate.</small></div>'}</div></div></div><div class="v51-fx-foot"><span>Income statement translation may use an average rate; balance-sheet monetary items use the selected closing/effective rate. Source and date remain visible in the controlled report.</span><span>${pill(`${rates.length} rate${rates.length===1?'':'s'}`,'info')}</span></div>`;if(target){const host=target.classList.contains('v44-filter-toggle')?target.parentElement:target;host?.insertAdjacentElement('afterend',box)}else root.prepend(box)}
function enhance(){q('.v45-fund-reporting')?.remove();fxPanel();document.title='Matanho Accounting Operating System · Enterprise Finance v51'}
const oldInv=pages.inventory,oldAssets=pages.assets;pages.inventory=invPage;pages.assets=assetPage;
const prior=typeof render==='function'?render:null;if(prior){render=function(){const out=prior.apply(this,arguments);requestAnimationFrame(enhance);return out}}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-v51]');if(!el)return;const a=el.dataset.v51,id=el.dataset.id||'';if(a==='inv-tab'){V.invTab=id;save();render();return}if(a==='asset-tab'){V.assetTab=id;save();render();return}if(a==='inv-action'){invModal(id);return}if(a==='save-inv'){saveInv(id);return}if(a==='inv-item'){invDrawer(id);return}if(a==='asset-action'){assetModal(id);return}if(a==='save-asset'){saveAsset();return}if(a==='asset-item'){assetDrawer(id);return}if(a==='close'){q('#v51Layer')?.remove();return}if(a==='fx-add'){const b=document.createElement('button');b.dataset.action='v8-add-rate';b.style.display='none';document.body.appendChild(b);b.click();b.remove();return}if(a==='fx-apply'){const b=document.createElement('button');b.dataset.v44='apply-currency';b.style.display='none';document.body.appendChild(b);b.click();b.remove();return}},true);
document.addEventListener('change',ev=>{const id=ev.target.id;if(id==='v51InvWarehouse'){V.invWarehouse=ev.target.value;save();render()}if(id==='v51InvCategory'){V.invCategory=ev.target.value;save();render()}if(id==='v51AssetClass'){V.assetClass=ev.target.value;save();render()}},true);
document.addEventListener('input',ev=>{if(ev.target.id==='v51InvSearch'){V.invSearch=ev.target.value;save()}if(ev.target.id==='v51AssetSearch'){V.assetSearch=ev.target.value;save()}},true);
document.addEventListener('keydown',ev=>{if(ev.key==='Enter'&&['v51InvSearch','v51AssetSearch'].includes(ev.target.id))render();if(ev.key==='Escape')q('#v51Layer')?.remove()}, __ac52Sig);
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>requestAnimationFrame(()=>{if(['inventory','assets'].includes(state.page))render();else enhance()}),{once:true});else requestAnimationFrame(()=>{if(['inventory','assets'].includes(state.page))render();else enhance()});
window.MatanhoAccountingV51={version:'51.0.0',state:V,refresh:enhance,previous:{inventory:oldInv,assets:oldAssets}};
})();


