(()=>{'use strict';
 const q=(s,r=document)=>r.querySelector(s);
 function apply(){
   const root=q('#main'); if(!root)return;
   let page='overview';
   try{page=String(state?.page||'overview')}catch(_){page='overview'}
   root.dataset.v52Page=page;
   root.classList.add('v52-premium');
   // Defensive cleanup: specialist report catalogue belongs only inside Reports, never as page furniture.
   if(page!=='reports') root.querySelectorAll('.v45-fund-reporting').forEach(x=>x.remove());
 }
 const prior=typeof render==='function'?render:null;
 if(prior){render=function(){const out=prior.apply(this,arguments);requestAnimationFrame(apply);return out}}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>requestAnimationFrame(apply),{once:true});else requestAnimationFrame(apply);
 document.title='Matanho Accounting Operating System · Enterprise Finance v52';
 window.MatanhoAccountingV52={version:'52.0.0',refresh:apply};
})();


